    };

    const handleLoadMore = async () => {
        if (!query.trim() || isLoadingMore || !hasMore) return;

        setIsLoadingMore(true);
        setError(null);

        const pageToFetch = currentPage + 1;

        try {
            // Pagination currently only supports the fast API search
            const result = await apiService.search(query, lastUsedOptions, summaryLength, summaryStyle, model, searchSources, pageToFetch);

            // Append basic papers immediately
            setPapers(prev => [...prev, ...result.papers]);
            setCurrentPage(pageToFetch);
            setHasMore(result.hasMore);

            // Score in background
            result.hypotheticalAnswer.then(async (hypo) => {
                 const newPapersScored = await apiService.scorePapers(result.papers, query, hypo, model);

                 setPapers(current => {
                     const scoredMap = new Map(newPapersScored.map(p => [p.id, p]));
                     return current.map(p => scoredMap.get(p.id) || p);
                 });

                 // Update analysis with all papers
                 // Use functional update to get latest state or merge
                 analysisService.analyzePapers([...papers, ...newPapersScored]).then(setAnalysis);
                 triggerBackgroundValidation(newPapersScored);
            });

        } catch (err) {
            setError(err instanceof Error ? err.message : "An unknown error occurred.");
        } finally {
            setIsLoadingMore(false);
        }
    };

