            >
                <div className="flex items-center gap-3">
                    {icon}
                    <h4 className="font-bold text-foreground">{title}</h4>
                    <span className="text-xs font-mono bg-primary/10 text-primary px-2 py-0.5 rounded-full">{count}</span>
