const queryParsingCache = new Map<string, Promise<any>>();


/**
 * Optimized Search Function with Caching.
 * 1. Checks cache.
 * 2. Starts AI tasks (Parsing, Hypothesis) in background.
 * 3. Waits for Parsing.
 * 4. Fetches API results (OpenAlex, Arxiv).
 * 5. Returns results IMMEDIATELY with basic scores.
 * 6. Returns the Hypothesis Promise so the UI can trigger full scoring later.
 */
export const search = async (
    query: string,
    options: AdvancedSearchOptions,
    summaryLength: SummaryLength,
    summaryStyle: SummaryStyle,
    model: ModelDefinition,
    sources: SearchSourceInfo[],
    page: number = 1
): Promise<{ 
    papers: ResearchPaper[], 
    hasMore: boolean, 
    hypotheticalAnswer: Promise<string>, 
    parsedFilters: any 
}> => {

    const cacheKey = JSON.stringify({
        query,
        options,
        summaryLength,
        summaryStyle,
        modelId: model.id,
        page,
        sources: sources.map(s => s.id).sort()
    });

    const cached = searchCache.get(cacheKey);
    if (cached && (Date.now() - cached.timestamp < SEARCH_CACHE_TTL)) {
        console.log("[API Service] Returning cached search results for key:", cacheKey);
        return cached.data;
    }

    // OPTIMIZATION: Always use Gemini Flash for internal "thinking" steps (parsing, hypothesis) regardless of user selection.
    const fastModel: ModelDefinition = { ...model, id: 'gemini-2.5-flash' };

    // 1. Start Hypothesis Generation (Non-blocking)
    const hypotheticalAnswerPromise = geminiService.generateHypotheticalAnswer(query, fastModel);

    // 2. Parse Query (Blocking for fetch, but fast)
    // OPTIMIZATION: Skip LLM parsing for simple keyword queries to speed up response time.
    // We check if the query is complex (long, or contains numbers/operators/keywords) or if advanced options are already used.
    let parsedFilters: any = { core_search_query: query };

    const hasAdvancedOptions = Object.values(options).some(v => !!v && v !== 'any' && v !== false);
    const looksComplex = query.length > 40 || /\d{4}|after|before|since|from|by|author|journal|in\s/i.test(query);

    if (!hasAdvancedOptions && looksComplex) {
        console.log("[Search] Query appears complex, using LLM parsing.");

        if (!queryParsingCache.has(query)) {
             // Cache the promise to handle concurrent identical requests
             queryParsingCache.set(query, geminiService.parseQueryToStructuredFilters(query, fastModel));
        }
        try {
             parsedFilters = await queryParsingCache.get(query);
        } catch(e) {
             console.warn("[Search] Query parsing failed, falling back to raw query.", e);
             parsedFilters = { core_search_query: query };
        }
    } else {
        console.log("[Search] Using fast path (skipping LLM parsing).");
    }

    const finalOptions: AdvancedSearchOptions = {
        ...parsedFilters,
        ...options,
        startYear: options.startYear || parsedFilters.startYear?.toString() || '',
        endYear: options.endYear || parsedFilters.endYear?.toString() || '',
        authors: options.authors || parsedFilters.authors || '',
        authorId: options.authorId, // Explicitly preserve authorId if present
        excludeKeywords: options.excludeKeywords || parsedFilters.excludeKeywords || '',
        journal: options.journal || parsedFilters.journal || '',
        minCitations: options.minCitations || parsedFilters.minCitations?.toString() || '',
        isOpenAccess: options.isOpenAccess || parsedFilters.isOpenAccess || false,
    };

    const retrievalQuery = parsedFilters.core_search_query || query;
    const searchPromises: Promise<ResearchPaper[]>[] = [];
    let openAlexHasMore = false; 

    // Add API-based searches
    if (sources.some(s => s.id === 'openalex')) {
        const promise = openalexService.searchOpenAlex(retrievalQuery, finalOptions, page).then(result => {
            openAlexHasMore = result.hasMore;
            return result.papers;
        });
        searchPromises.push(promise);
    }
    if (sources.some(s => s.id === 'arxiv')) {
        const promise = arxivService.searchArxiv(retrievalQuery, page).then(result => result.papers);
        searchPromises.push(promise);
    }

    const allResults = await Promise.all(searchPromises);
    const allPapers = allResults.flat();

    // Combine and deduplicate immediately
    let papers = mergePapers(allPapers);

    // Client-side text filtering (fast)
    if (finalOptions.titleKeywords) {
        const keywords = finalOptions.titleKeywords.split(',').map(k => k.trim().toLowerCase()).filter(Boolean);
        if (keywords.length > 0) papers = papers.filter(p => keywords.every(kw => p.title.toLowerCase().includes(kw)));
    }
    if (finalOptions.abstractKeywords) {
        const keywords = finalOptions.abstractKeywords.split(',').map(k => k.trim().toLowerCase()).filter(Boolean);
        if (keywords.length > 0) papers = papers.filter(p => keywords.every(kw => p.abstract.toLowerCase().includes(kw)));
    }

    // 4. Basic Scoring (Fast)
    // We do NOT wait for embeddings here. This ensures instant results.
    const scoredPapers = calculateBasicScores(papers, retrievalQuery);

    const result = { papers: scoredPapers, hasMore: openAlexHasMore, hypotheticalAnswer: hypotheticalAnswerPromise, parsedFilters };

    // Cache the result
    searchCache.set(cacheKey, { timestamp: Date.now(), data: result });

    return result;
};

