## utils/toon.ts

```typescript
/**
 * TOON (Type-Object-Object-Notation) Utility
 * 
 * A lightweight schema-based compression utility for arrays of objects.
 * It separates keys (schema) from values to reduce memory footprint
 * and serialization overhead for repetitive data structures like search results.
 */

export class Toon {
    /**
     * Packs an array of objects into a compact format: [keys, [values1], [values2], ...]
     */
    static pack<T extends object>(data: T[]): any[] {
        if (!data || data.length === 0) return [];

        // Extract keys from the first object as the schema
        // We assume all objects in the array share the same shape for maximum efficiency
        const keys = Object.keys(data[0]) as (keyof T)[];

        const packed: any[] = [keys];

        for (const item of data) {
            const row = keys.map(k => item[k]);
            packed.push(row);
        }

        return packed;
    }

    /**
     * Unpacks a TOON-formatted array back into an array of objects.
     */
    static unpack<T>(packed: any[]): T[] {
        if (!packed || packed.length < 2) return [];

        const keys = packed[0] as (keyof T)[];
        const data: T[] = [];

        for (let i = 1; i < packed.length; i++) {
            const row = packed[i];
            const item: any = {};

            keys.forEach((key, idx) => {
                item[key] = row[idx];
            });

            data.push(item as T);
        }

        return data;
    }
}
