export const validatePaper = async (paper: ResearchPaper): Promise<{ validation: ValidationResult, updatedPaperData: Partial<ResearchPaper> }> => {
    const cacheKey = paper.id;
    const cached = validationCache.get(cacheKey);
    if (cached && (Date.now() - cached.timestamp < GENERIC_CACHE_TTL)) {
        return cached.data;
    }

    const result = await validationService.validatePaper(paper);
    validationCache.set(cacheKey, { timestamp: Date.now(), data: result });
    return result;
};

export const generateSearchSummary = async (
    papers: ResearchPaper[],
    length: SummaryLength,
    style: SummaryStyle,
    model: ModelDefinition
): Promise<string> => {
    const validPapers = papers.filter(p => p.abstract && p.abstract.length > 50).slice(0, 5);
    if (validPapers.length === 0) return "Insufficient data to generate a summary.";

    const cacheKey = `${validPapers.map(p => p.id).sort().join(',')}-${length}-${style}-${model.id}`;
    const cached = summaryCache.get(cacheKey);
    if (cached && (Date.now() - cached.timestamp < GENERIC_CACHE_TTL)) {
        return cached.data;
    }

    const result = await geminiService.generateSummaryForPapers(validPapers, length, style, model);
    summaryCache.set(cacheKey, { timestamp: Date.now(), data: result });
    return result;
};

export const searchByDoi = async (doi: string, model: ModelDefinition): Promise<ResearchPaper | null> => {
    // Caching for DOIs could be useful if users repeatedly look up the same DOI
    const paper = await openalexService.searchOpenAlexByDoi(doi);
    if (!paper) return null;
    const { validation, updatedPaperData } = await validationService.validatePaper(paper);
    return { ...paper, ...updatedPaperData, validation, combinedScore: 100, semanticScore: 100 };
};

