export const PaperDetails: React.FC<PaperDetailsProps> = (props) => {
    const { paper, isInWorkspace, onToggleWorkspacePaper, onConceptClick, onFindDoi, logAnalyticsEvent, model } = props;
    const { onFindConnectedPapers, isFindingConnected, onAnalyzePaper, isAnalyzingPaper, onVerifyPaper, onGenerateSuggestions, isGeneratingSuggestions, onCitePaper, onAuthorClick, onFindSimilar, isFindingSimilar } = props;
    const [activeTab, setActiveTab] = useState<'overview' | 'chat' | 'connections' | 'analysis' | 'graph' | 'metadata'>('overview');

    const [abstractContent, setAbstractContent] = useState<{ id: string; text: string } | null>(null);
    const [isAbstractLoading, setIsAbstractLoading] = useState(false);

    const [connectedPapers, setConnectedPapers] = useState<ConnectedPaper[] | null>(null);
    const [isLoadingConnections, setIsLoadingConnections] = useState(false);

    useEffect(() => {
        if (activeTab === 'overview') {
             // Check if we already have data for this paper
             if (abstractContent?.id === paper.id) return;

             setIsAbstractLoading(true);

             const load = async () => {
                 let text = paper.abstract;
                 const isPlaceholder = !text || text.length < 50 || text === 'No abstract available for this paper.';

                 // Lazy fetch: If abstract is missing or short, and we have a DOI, try to get full text from OpenAlex
                 if (isPlaceholder && paper.doi) {
                     try {
                         const fetched = await apiService.fetchMetadataByDOI(paper.doi);
                         if (fetched && fetched.abstract && fetched.abstract.length > 50) {
                             text = fetched.abstract;
                         }
                     } catch(e) {
                         console.warn("Could not fetch enriched abstract:", e);
                     }
                 }

                 setAbstractContent({ id: paper.id, text: text || 'No abstract available.' });
                 setIsAbstractLoading(false);
             };
             load();
        }
    }, [activeTab, paper.id, paper.doi, paper.abstract, abstractContent]);

    // Fetch connections when the tab is activated
    useEffect(() => {
        if (activeTab === 'connections' && !connectedPapers && !isLoadingConnections) {
            setIsLoadingConnections(true);
            apiService.findConnectedPapers(paper, model)
                .then(setConnectedPapers)
                .catch(err => {
                    console.error("Failed to load connections inline:", err);
                    // Optionally set an error state here
                })
                .finally(() => setIsLoadingConnections(false));
        }
        // If paper changes, reset
        if (paper.id !== connectedPapers?.[0]?.title /* hacky check, better to use ref or just rely on array being null on paper change */) {
             // Actually we should reset connectedPapers when paper prop changes.
             // Handled by the key on parent or manual reset.
        }
    }, [activeTab, paper, model]);

    // Reset local state when selected paper changes
    useEffect(() => {
        setConnectedPapers(null);
        setAbstractContent(null);
        setActiveTab('overview');
    }, [paper.id]);


    const googleScholarSearchUrl = `https://scholar.google.com/scholar?hl=en&as_sdt=0,34&q=${encodeURIComponent(`"${paper.title}"`)}`;

    const handleShare = async () => {
        if (!navigator.share) return;
        try {
            await navigator.share({
                title: paper.title,
                text: `Check out this research paper: "${paper.title}"`,
                url: paper.sourceURL || window.location.href,
            });
            logAnalyticsEvent('paper_shared', { title: paper.title });
        } catch (error) {
            console.error('Error sharing paper:', error);
        }
    };

    const renderKeyConcepts = () => {
        if (!paper.keyConceptsState || paper.keyConceptsState === 'idle' || paper.keyConceptsState === 'loading') {
            if (paper.abstract.length < 150) return null;
            return (
                <div className="flex items-center gap-2 text-sm text-muted-foreground">
                    <svg className="animate-spin h-4 w-4" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                    <span>Extracting concepts...</span>
                </div>
            );
        }

        if (paper.keyConceptsState === 'error') {
            return <p className="text-sm text-destructive">Could not extract concepts.</p>;
        }

        if (paper.keyConceptsState === 'loaded' && paper.keyConcepts && paper.keyConcepts.length > 0) {
            return (
                <div className="flex flex-wrap gap-2">
                    {paper.keyConcepts.map((concept) => (
                        <button
                            key={concept}
                            onClick={() => onConceptClick(concept)}
                            className="group flex items-center gap-1.5 px-2.5 py-1 bg-secondary text-secondary-foreground text-xs font-medium rounded-full hover:bg-primary/10 hover:text-primary transition-colors"
                            title={`Search for "${concept}"`}
                        >
                            <span>{concept}</span>
                            <SearchIcon className="w-3 h-3 opacity-0 group-hover:opacity-100 transition-opacity" />
                        </button>
                    ))}
                </div>
            );
        }

        return <p className="text-sm text-muted-foreground italic">No distinct concepts identified.</p>;
    }

    const renderConnections = () => {
        if (isLoadingConnections) {
            return (
                <div className="flex flex-col items-center justify-center py-12 text-muted-foreground space-y-3">
                    <svg className="animate-spin h-8 w-8 text-primary" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                    <p>Mapping citation network via Semantic Scholar...</p>
                </div>
            );
        }

        if (!connectedPapers || connectedPapers.length === 0) {
            return (
                <div className="text-center py-12 text-muted-foreground bg-muted/30 rounded-lg border border-dashed border-border">
                    <NetworkIcon className="w-8 h-8 mx-auto mb-2 opacity-50" />
                    <p>No connected papers found.</p>
                </div>
            );
        }

        const citedBy = connectedPapers.filter(p => p.connection === 'Cited by this paper');
        const references = connectedPapers.filter(p => p.connection === 'This paper cites');
        const others = connectedPapers.filter(p => p.connection !== 'Cited by this paper' && p.connection !== 'This paper cites');

        return (
            <div className="space-y-4">
                {citedBy.length > 0 && (
                    <CollapsibleSection title="Cited By" count={citedBy.length} defaultOpen={true}>
                        <div className="space-y-2">
                            {citedBy.map((p, i) => <ConnectionItem key={i} paper={p} />)}
                        </div>
                    </CollapsibleSection>
                )}
                {references.length > 0 && (
                    <CollapsibleSection title="References" count={references.length}>
                        <div className="space-y-2">
                            {references.map((p, i) => <ConnectionItem key={i} paper={p} />)}
                        </div>
                    </CollapsibleSection>
                )}
                {others.length > 0 && (
                    <CollapsibleSection title="Related Papers" count={others.length}>
                        <div className="space-y-2">
                            {others.map((p, i) => <ConnectionItem key={i} paper={p} />)}
                        </div>
                    </CollapsibleSection>
                )}
            </div>
        );
    };

    return (
        <div className="flex flex-col h-full space-y-4">
             <div>
                <div className="flex justify-between items-start gap-4">
                    <h3 className="text-lg font-bold text-foreground flex-grow pr-2">{paper.title}</h3>
                    <div className="flex-shrink-0 flex items-center gap-2">
                        <button 
                            onClick={() => onCitePaper(paper)}
                            className="flex items-center gap-2 h-9 px-3 rounded-md text-sm font-semibold bg-secondary text-secondary-foreground hover:bg-accent transition-colors border border-transparent hover:border-border"
                            title="Generate Citation"
                        >
                            <CitationIcon className="w-4 h-4" />
                            <span className="hidden sm:inline">Cite</span>
                        </button>
                        <button 
                            onClick={() => onToggleWorkspacePaper(paper)} 
                            aria-label={isInWorkspace ? "Remove from Workspace" : "Add to Workspace"} 
                            className={`flex items-center gap-2 h-9 px-4 rounded-md text-sm font-semibold transition-colors ${
                                isInWorkspace 
                                ? 'bg-green-100 text-green-800 hover:bg-green-200' 
                                : 'bg-secondary text-secondary-foreground hover:bg-accent'
                            }`}
                        >
                            {isInWorkspace ? <CheckIcon className="w-4 h-4" /> : <AddIcon className="w-4 h-4" />}
                            <span>{isInWorkspace ? 'Saved' : 'Save'}</span>
                        </button>
                    </div>
                </div>
            </div>

            <div className="border-b border-border overflow-x-auto">
                <nav className="-mb-px flex space-x-6" aria-label="Tabs">
                    <TabButton isActive={activeTab === 'overview'} onClick={() => setActiveTab('overview')}>Overview</TabButton>
                    <TabButton isActive={activeTab === 'connections'} onClick={() => setActiveTab('connections')}>Connections</TabButton>
                    <TabButton isActive={activeTab === 'graph'} onClick={() => setActiveTab('graph')}>Graph</TabButton>
                    <TabButton isActive={activeTab === 'chat'} onClick={() => setActiveTab('chat')}>Chat</TabButton>
                    <TabButton isActive={activeTab === 'analysis'} onClick={() => setActiveTab('analysis')}>Tools</TabButton>
                    <TabButton isActive={activeTab === 'metadata'} onClick={() => setActiveTab('metadata')}>Metadata</TabButton>
                </nav>
            </div>

            <div className="pt-2">
                {activeTab === 'overview' && (
                    <div className="space-y-4 animate-fade-in">
                        <div>
                            <h4 className="font-semibold text-foreground">Abstract</h4>
                            {isAbstractLoading ? (
                                <div className="flex items-center gap-2 text-sm text-muted-foreground py-2">
                                    <svg className="animate-spin h-4 w-4 text-primary" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                                    <span>Loading abstract...</span>
                                </div>
                            ) : (
                                <p className="mt-1 text-sm text-muted-foreground leading-relaxed">
                                    {abstractContent?.text || paper.abstract}
                                </p>
                            )}
                        </div>
                         <div>
                            <h4 className="font-semibold text-foreground mb-2 flex items-center gap-2">
                                <TagIcon className="w-4 h-4 text-muted-foreground" />
                                Key Concepts
                            </h4>
                            {renderKeyConcepts()}
                        </div>
                    </div>
                )}

                {activeTab === 'connections' && (
                    <div className="animate-fade-in">
                        <div className="mb-4">
                            <h4 className="font-semibold text-foreground flex items-center gap-2">
                                <NetworkIcon className="w-5 h-5 text-primary" />
                                Citation Network
                            </h4>
                            <p className="text-xs text-muted-foreground">Exploring references and citations via Semantic Scholar.</p>
                        </div>
                        {renderConnections()}
                    </div>
                )}

                {activeTab === 'chat' && (
                    <div className="animate-fade-in">
                        <div className="mb-3">
                            <h4 className="font-semibold text-foreground flex items-center gap-2">
                                <ChatIcon className="w-5 h-5 text-primary" />
                                Chat with this Paper
                            </h4>
                            <p className="text-xs text-muted-foreground">Ask questions specifically about "{paper.title}".</p>
                        </div>
                        <PaperChat paper={paper} />
                    </div>
                )}

                {activeTab === 'graph' && (
                    <div className="animate-fade-in">
                        <KnowledgeGraphDisplay 
                            graph={paper.knowledgeGraph}
                            state={paper.knowledgeGraphState}
                        />
                    </div>
                )}

                {activeTab === 'analysis' && (
                     <div className="space-y-6 animate-fade-in">
                        {paper.savedAnalysis && <SavedAnalysis analysis={paper.savedAnalysis} />}
                        <div className="space-y-3">
                             <h3 className="text-base font-bold text-foreground pt-2">Refinement Tools</h3>
                             <ToolCard
                                 icon={<SearchIcon className="w-5 h-5" />}
                                 title="Find Similar Papers (Pivot Search)"
                                 description="Run a new semantic search based on the content of this abstract."
                                 actionText="Find Similar"
                                 onAction={() => onFindSimilar(paper)}
                                 isLoading={isFindingSimilar}
                             />
                             <ToolCard
                                 icon={<NetworkIcon className="w-5 h-5" />}
                                 title="Find Connected Papers"
                                 description="Discover prior work, derivative research, and contrasting studies."
                                 actionText="Find Connections"
                                 onAction={() => onFindConnectedPapers(paper)}
                                 isLoading={isFindingConnected}
                             />
                             <ToolCard
                                 icon={<AnalyzeIcon className="w-5 h-5" />}
                                 title="Structured Analysis"
                                 description="Extract research question, methodology, key findings, and limitations."
                                 actionText="Analyze Paper"
                                 onAction={() => onAnalyzePaper(paper)}
                                 isLoading={isAnalyzingPaper}
                             />
                              <ToolCard
                                 icon={<ShieldCheckIcon className="w-5 h-5" />}
                                 title="Advanced Verification (VACS)"
                                 description="Verify a claim using the paper's text, citations, and metadata."
                                 actionText="Verify Claim"
                                 onAction={() => onVerifyPaper(paper)}
                                 disabled={!paper.doi}
                             />
                             <ToolCard
                                 icon={<LightbulbIcon className="w-5 h-5" />}
                                 title="Generate Search Ideas"
                                 description="Get AI-powered suggestions for new search queries based on this paper."
                                 actionText="Generate Ideas"
                                 onAction={() => onGenerateSuggestions(paper)}
                                 isLoading={isGeneratingSuggestions}
                             />
                             <ToolCard
                                icon={<CitationIcon className="w-5 h-5" />}
                                title="Generate Citation"
                                description="Create a formatted citation in various styles (APA, MLA, etc.)."
                                actionText="Cite Paper"
                                onAction={() => onCitePaper(paper)}
                            />
                            <ToolCard
                                icon={<JournalIcon className="w-5 h-5" />}
                                title="Find Journals"
                                description="Suggest suitable publication venues based on the abstract."
                                actionText="Suggest Journals"
                                onAction={() => props.onFindJournals(paper)}
                                isLoading={props.isFindingJournals}
                            />
                        </div>
                    </div>
                )}

                {activeTab === 'metadata' && (
                     <div className="space-y-6 animate-fade-in">
                        {paper.validation && <ValidationScoreDisplay validation={paper.validation} />}

                        <div className="space-y-3">
                             <div className="flex justify-between items-start">
                                <div>
                                    <h4 className="font-semibold text-foreground text-sm">Authors</h4>
                                    <AuthorList authors={paper.authors} authorList={paper.authorList} onAuthorClick={onAuthorClick} />
                                </div>
                                <div className="text-right">
                                    <h4 className="font-semibold text-foreground text-sm">Year</h4>
                                    <p className="text-sm text-muted-foreground">{paper.year}</p>
                                </div>
                            </div>
                             <div>
                                <h4 className="font-semibold text-foreground text-sm">Journal</h4>
                                <p className="text-sm text-muted-foreground">{paper.journal || 'N/A'}</p>
                            </div>
                            {paper.citations !== undefined && (
                                <div>
                                    <h4 className="font-semibold text-foreground text-sm">Citations</h4>
                                    <p className="text-sm text-muted-foreground">{paper.citations.toLocaleString()}</p>
                                </div>
                            )}
                        </div>

                        <div className="pt-3 border-t border-border flex flex-wrap items-center justify-between gap-x-4 gap-y-2">
                            <div className="flex items-center gap-4">
                                <a href={googleScholarSearchUrl} target="_blank" rel="noopener noreferrer" className="flex items-center gap-1.5 text-sm font-medium text-primary hover:underline">
                                    <ScholarIcon className="w-4 h-4" /> Google Scholar
                                </a>
                                {(paper.pdfURL || paper.openAccessPdfUrl) && (
                                    <a href={paper.pdfURL || paper.openAccessPdfUrl} target="_blank" rel="noopener noreferrer" className="flex items-center gap-1.5 text-sm font-medium text-primary hover:underline">
                                        <PdfIcon className="w-4 h-4" /> PDF
                                    </a>
                                )}
                                {paper.openAccessState === 'loading' && (
                                    <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
                                        <svg className="animate-spin h-3 w-3" viewBox="0 0 24 24">
                                            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" fill="none"/>
                                            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"/>
                                        </svg>
                                        Checking PDF...
                                    </div>
                                )}
                                <DoiDisplay paper={paper} onFindDoi={() => onFindDoi(paper)} />
                            </div>
                            <button
                                onClick={handleShare}
                                className="flex items-center gap-1.5 text-sm font-medium text-muted-foreground hover:text-foreground hover:underline"
                            >
                                <ShareIcon className="w-4 h-4" /> Share
                            </button>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import type { ResearchPaper, AnalysisResult, Project, SearchSourceInfo, ModelDefinition, RagStatus, ChatMessage, AuthorProfile } from '../types';
import { PaperDetails } from './PaperDetails';
import { AnalysisDashboard } from './AnalysisDashboard';
import { LightbulbIcon } from './icons/LightbulbIcon';
import { SearchIcon } from './icons/SearchIcon';
import { BibliographyGenerator } from './BibliographyGenerator';
import { ProjectWorkspace } from './ProjectWorkspace';


interface RefinedQueriesProps {
  queries: string[];
  isLoading: boolean;
  onQueryClick: (query: string) => void;
}

const RefinedQueries: React.FC<RefinedQueriesProps> = ({ queries, isLoading, onQueryClick }) => {
  if (isLoading || queries.length === 0) {
    return null;
  }

  return (
    <div className="mb-6">
      <h3 className="text-lg font-semibold text-foreground mb-3 flex items-center gap-2">
        <LightbulbIcon className="w-6 h-6 text-yellow-500" />
        <span>AI-Generated Query Suggestions</span>
      </h3>
        <div className="space-y-3">
            {queries.map((query, index) => (
            <div
                key={index}
                className="p-3 bg-muted/50 border border-border rounded-lg group"
            >
                <p className="text-sm text-muted-foreground font-mono mb-2" style={{ whiteSpace: 'normal', wordBreak: 'break-all' }}>{query}</p>
                <button
                onClick={() => onQueryClick(query)}
                className="w-full text-center px-3 h-9 bg-secondary text-secondary-foreground text-xs font-semibold rounded-md hover:bg-accent transition-colors flex items-center justify-center gap-2"
                >
                <SearchIcon className="w-4 h-4" />
                <span>Use this query</span>
                </button>
            </div>
            ))}
        </div>
    </div>
  );
};

interface WorkspacePanelProps {
    papers: ResearchPaper[];
    selectedPaper: ResearchPaper | null;
    analysis: AnalysisResult | null;
    summary: string;
    workspacePapers: ResearchPaper[];
    projects: Project[];
    sources: SearchSourceInfo[];
    onToggleWorkspacePaper: (paper: ResearchPaper) => void;
    onFindConnectedPapers: (paper: ResearchPaper) => void;
    isFindingConnected: boolean;
    onAnalyzePaper: (paper: ResearchPaper) => void;
    onCitePaper: (paper: ResearchPaper) => void;
    isAnalyzingPaper: boolean;
    onConceptClick: (concept: string) => void;
    onFindDoi: (paper: ResearchPaper) => void;
    onGenerateSuggestions: (paper: ResearchPaper) => void;
    isGeneratingSuggestions: boolean;
    onVerifyPaper: (paper: ResearchPaper) => void;
    logAnalyticsEvent: (eventName: string, payload: object) => void;
    refinedQueries: string[];
    isGeneratingRefined: boolean;
    onRefinedQuerySearch: (query: string) => void;
    onAnalyzeGaps: (papers: ResearchPaper[], model: ModelDefinition) => void;
    onSynthesizeWorkspace: (papers: ResearchPaper[], model: ModelDefinition) => void;
    onCreateProject: (name: string) => void;
    onDeleteProject: (projectId: string) => void;
    onMovePaperToProject: (paperId: string, projectId: string | null) => void;
    onUpdateProjectColor: (projectId: string, color: string) => void;
    model: ModelDefinition;
    onIndexPaperForRag: (projectId: string, paperId: string) => void;
    projectChats: { [projectId: string]: { history: ChatMessage[], isLoading: boolean } };
    onProjectChat: (projectId: string, message: string) => void;
    isSummaryLoading: boolean;
    onFindJournals: (paper: ResearchPaper) => void;
    isFindingJournals: boolean;
    onAuthorClick: (author: AuthorProfile) => void;
    onFindSimilar: (paper: ResearchPaper) => void;
    isFindingSimilar: boolean; // Add this prop
}

const TabButton: React.FC<{
    onClick: () => void;
    isActive: boolean;
    disabled?: boolean;
    children: React.ReactNode;
}> = ({ onClick, isActive, disabled, children }) => {
    const baseClasses = "inline-flex items-center justify-center whitespace-nowrap rounded-sm px-3 py-1.5 text-sm font-medium ring-offset-background transition-all focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2";
    const activeClasses = "bg-background text-foreground shadow-sm";
    const inactiveClasses = "text-muted-foreground hover:bg-accent/50";
    const disabledClasses = "text-muted-foreground/50 cursor-not-allowed";

    return (
        <button
            onClick={onClick}
            disabled={disabled}
            className={`${baseClasses} ${disabled ? disabledClasses : (isActive ? activeClasses : inactiveClasses)}`}
        >
            {children}
        </button>
    );
};

export const WorkspacePanel: React.FC<WorkspacePanelProps> = (props) => {
    const { 
        papers, selectedPaper, analysis, summary, workspacePapers, projects,
        refinedQueries, isGeneratingRefined, onRefinedQuerySearch, model, isSummaryLoading,
        isFindingSimilar // Destructure new prop
    } = props;
    const [activeTab, setActiveTab] = useState<'details' | 'analysis' | 'workspace' | 'bibliography'>('analysis');

    useEffect(() => {
        if (selectedPaper) {
            setActiveTab('details');
        } else if (analysis || refinedQueries.length > 0 || isGeneratingRefined || isSummaryLoading) {
            setActiveTab('analysis');
        } else {
            setActiveTab('workspace');
        }
    }, [selectedPaper, analysis, refinedQueries, isGeneratingRefined, isSummaryLoading, workspacePapers.length]);

    const renderContent = () => {
        switch (activeTab) {
            case 'details':
                return selectedPaper ? (
                    <PaperDetails
                        paper={selectedPaper}
                        isInWorkspace={workspacePapers.some(p => p.id === selectedPaper.id)}
                        onToggleWorkspacePaper={props.onToggleWorkspacePaper}
                        onConceptClick={props.onConceptClick}
                        onFindDoi={props.onFindDoi}
                        logAnalyticsEvent={props.logAnalyticsEvent}
                        onFindConnectedPapers={props.onFindConnectedPapers}
                        isFindingConnected={props.isFindingConnected}
                        onAnalyzePaper={props.onAnalyzePaper}
                        isAnalyzingPaper={props.isAnalyzingPaper}
                        onVerifyPaper={props.onVerifyPaper}
                        onGenerateSuggestions={props.onGenerateSuggestions}
                        isGeneratingSuggestions={props.isGeneratingSuggestions}
                        onCitePaper={props.onCitePaper}
                        onFindJournals={props.onFindJournals}
                        isFindingJournals={props.isFindingJournals}
                        onAuthorClick={props.onAuthorClick}
                        model={model}
                        onFindSimilar={props.onFindSimilar}
                        isFindingSimilar={isFindingSimilar} // Pass new prop to PaperDetails
                    />
                ) : (
                    <div className="text-center text-muted-foreground py-16">
                        <h2 className="text-lg font-semibold">Select a Paper</h2>
                        <p>Select a paper from the list to view its details and tools here.</p>
                    </div>
                );
            case 'analysis':
                return (analysis || refinedQueries.length > 0 || isGeneratingRefined || isSummaryLoading) ? (
                    <div className="space-y-6">
                        <RefinedQueries
                            queries={refinedQueries}
                            isLoading={isGeneratingRefined}
                            onQueryClick={onRefinedQuerySearch}
                        />
                        {(analysis || isSummaryLoading) && <AnalysisDashboard analysis={analysis} summary={summary} isSummaryLoading={isSummaryLoading} />}
                    </div>
                ) : (
                    <div className="text-center text-muted-foreground py-16">
                        <h2 className="text-lg font-semibold">Search Analysis</h2>
                        <p>Insights about your search results will appear here once a search is complete.</p>
                    </div>
                );
            case 'bibliography':
                return <BibliographyGenerator papers={papers} model={model} />;
            case 'workspace':
                return (
                    <ProjectWorkspace
                        workspacePapers={workspacePapers}
                        projects={projects}
                        onCreateProject={props.onCreateProject}
                        onDeleteProject={props.onDeleteProject}
                        onMovePaperToProject={props.onMovePaperToProject}
                        onSynthesizeWorkspace={props.onSynthesizeWorkspace}
                        onAnalyzeGaps={props.onAnalyzeGaps}
                        onRemovePaperFromWorkspace={props.onToggleWorkspacePaper}
                        onUpdateProjectColor={props.onUpdateProjectColor}
                        model={model}
                        onIndexPaperForRag={props.onIndexPaperForRag}
                        projectChats={props.projectChats}
                        onProjectChat={props.onProjectChat}
                    />
                 )
            default:
                return null;
        }
    };

    return (
        <div className="bg-card rounded-lg shadow-sm border sticky top-24">
            <div className="border-b border-border p-1 flex justify-between items-center">
                <nav className="flex space-x-1 bg-muted p-1 rounded-md" aria-label="Tabs">
                    <TabButton onClick={() => setActiveTab('details')} isActive={activeTab === 'details'} disabled={!selectedPaper}>
                        Paper Details
                    </TabButton>
                    <TabButton onClick={() => setActiveTab('analysis')} isActive={activeTab === 'analysis'}>
                        Search Analysis
                    </TabButton>
                    <TabButton onClick={() => setActiveTab('bibliography')} isActive={activeTab === 'bibliography'} disabled={papers.length === 0}>
                        Bibliography
                    </TabButton>
                    <TabButton onClick={() => setActiveTab('workspace')} isActive={activeTab === 'workspace'}>
                       Workspace
                    </TabButton>
                </nav>
            </div>
            <div className="p-6 overflow-y-auto max-h-[calc(100vh-12rem)]">
                {renderContent()}
            </div>
        </div>
    );
};

import React, { useState, useEffect, useMemo } from 'react';
import ReactDOM from 'react-dom/client';
import type { ResearchPaper, SummaryLength, SummaryStyle, AdvancedSearchOptions, AnalysisResult, Project, VerificationResult, PaperAnalysis, SortConfig, SortKey, SynthesisResult, AppMode, GoldStandardPaper, UserStudyData, TestHarnessResult, ModelDefinition, ChatMessage, SearchSourceInfo, SuggestionsResult, ConnectedPaper, JournalRecommendation, AuthorProfile, Organization } from './types';
import * as apiService from './services/apiService';
import * as agentService from './services/agentService';
import { ResultsDisplay } from './components/ResultsDisplay';
import { LoadingSpinner } from './components/LoadingSpinner';
import { ErrorMessage } from './components/ErrorMessage';
import { InitialSearchScreen } from './components/InitialSearchScreen';
import { ExtensionPromo } from './components/ExtensionPromo';
import { WorkspacePanel } from './components/WorkspacePanel';
import { SuggestionsModal } from './components/SuggestionsModal';
import { VerificationModal } from './components/VerificationModal';
import { SearchForm } from './components/SearchForm';
import { OnboardingModal } from './components/OnboardingModal';
import { InfoModal } from './components/InfoModal';
import { AboutModalContent } from './components/AboutModalContent';
import { ReportModal } from './components/ReportModal';
import { PaperAnalysisModal } from './components/PaperAnalysisModal';
import { SynthesisModal } from './components/SynthesisModal';
import { ResearcherDashboard } from './components/ResearcherDashboard';
import { PaperVerificationApp } from './components/PaperVerificationApp';
import * as verificationService from './services/verificationService';
import { analyticsService } from './services/analyticsService';
import { CitationModal } from './components/CitationModal';
import * as extensionService from './services/extensionService';
import { DatabaseFinderModal } from './components/DatabaseFinderModal';
import * as analysisService from './services/analysisService';
import { Header } from './components/Header';
import { ConnectedPapersModal } from './components/ConnectedPapersModal';
import { JournalFinderModal } from './components/JournalFinderModal';
import { OrganizationFinderModal } from './components/OrganizationFinderModal';


const PROJECT_COLORS = ['sky', 'green', 'yellow', 'red', 'purple', 'pink', 'indigo', 'teal'];

export const AVAILABLE_MODELS: ModelDefinition[] = [
  { id: 'gemini-2.5-flash', name: 'Gemini Flash', provider: 'gemini' },
  { id: 'gemini-2.5-pro', name: 'Gemini Pro', provider: 'gemini' },
  { id: 'gpt-4-turbo', name: 'OpenAI GPT-4 Turbo', provider: 'openai', isMock: true },
  { id: 'claude-3-sonnet', name: 'Anthropic Claude 3 Sonnet', provider: 'anthropic', isMock: true },
];

const App: React.FC = () => {
    // App mode
    const [appMode, setAppMode] = useState<AppMode>('search');

    // Search Mode State
    const [query, setQuery] = useState('');
    const [model, setModel] = useState<ModelDefinition>(AVAILABLE_MODELS[0]);
    const [papers, setPapers] = useState<ResearchPaper[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [isSearchingGrounded, setIsSearchingGrounded] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [summaryLength, setSummaryLength] = useState<SummaryLength>('medium');
    const [summaryStyle, setSummaryStyle] = useState<SummaryStyle>('paragraph');
    const [hasSearched, setHasSearched] = useState(false);
    const [sortConfig, setSortConfig] = useState<SortConfig>({ key: 'relevance', direction: 'desc' });
    const [selectedPaper, setSelectedPaper] = useState<ResearchPaper | null>(null);
    const [workspacePapers, setWorkspacePapers] = useState<ResearchPaper[]>([]);
    const [projects, setProjects] = useState<Project[]>([]);
    const [analysis, setAnalysis] = useState<AnalysisResult | null>(null);
    const [refinedQueries, setRefinedQueries] = useState<string[]>([]);
    const [isScreeningMode, setIsScreeningMode] = useState(false);
    const [isReranking, setIsReranking] = useState(false);
    const [projectChats, setProjectChats] = useState<{ [projectId: string]: { history: ChatMessage[], isLoading: boolean } }>({});
    const [searchSources, setSearchSources] = useState<SearchSourceInfo[]>([{ id: 'openalex', name: 'OpenAlex', description: 'A comprehensive open index of scholarly works.' }]);

    // Live Search Suggestions
    const [searchSuggestions, setSearchSuggestions] = useState<string[]>([]);
    const [isGeneratingSearchSuggestions, setIsGeneratingSearchSuggestions] = useState(false);

    // Pagination state
    const [summary, setSummary] = useState<string>('');
    const [isSummaryLoading, setIsSummaryLoading] = useState(false);
    const [currentPage, setCurrentPage] = useState(1);
    const [isLoadingMore, setIsLoadingMore] = useState(false);
    const [hasMore, setHasMore] = useState(false);
    const [lastUsedOptions, setLastUsedOptions] = useState<AdvancedSearchOptions>({
        startYear: '',
        endYear: '',
        authors: '',
        excludeKeywords: '',
        inclusionCriteria: '',
        exclusionCriteria: '',
        studyDesign: 'any',
        journal: '',
        minCitations: '',
        titleKeywords: '',
        abstractKeywords: '',
        isOpenAccess: false,
    });

    // Modals State
    const [isVerificationModalOpen, setIsVerificationModalOpen] = useState(false);
    const [paperToVerify, setPaperToVerify] = useState<ResearchPaper | null>(null);
    const [isOnboardingOpen, setIsOnboardingOpen] = useState(false);
    const [isAboutModalOpen, setIsAboutModalOpen] = useState(false);
    const [isGapAnalysisModalOpen, setIsGapAnalysisModalOpen] = useState(false);
    const [isAnalyzingGaps, setIsAnalyzingGaps] = useState(false);
    const [gapAnalysisResult, setGapAnalysisResult] = useState<string | null>(null);
    const [gapAnalysisError, setGapAnalysisError] = useState<string | null>(null);
    const [isAnalysisModalOpen, setIsAnalysisModalOpen] = useState(false);
    const [isAnalyzingPaper, setIsAnalyzingPaper] = useState(false);
    const [analysisError, setAnalysisError] = useState<string | null>(null);
    const [analysisResult, setAnalysisResult] = useState<{paper: ResearchPaper, analysis: PaperAnalysis} | null>(null);
    const [isSynthesisModalOpen, setIsSynthesisModalOpen] = useState(false);
    const [isSynthesizing, setIsSynthesizing] = useState(false);
    const [synthesisResult, setSynthesisResult] = useState<SynthesisResult | null>(null);
    const [synthesisError, setSynthesisError] = useState<string | null>(null);
    const [isCitationModalOpen, setIsCitationModalOpen] = useState(false);
    const [paperForCitation, setPaperForCitation] = useState<ResearchPaper | null>(null);
    const [isDbFinderOpen, setIsDbFinderOpen] = useState(false);
    const [isSuggestionsModalOpen, setIsSuggestionsModalOpen] = useState(false);
    const [suggestionsResult, setSuggestionsResult] = useState<SuggestionsResult | null>(null);
    const [isGeneratingSuggestions, setIsGeneratingSuggestions] = useState(false);
    const [suggestionsError, setSuggestionsError] = useState<string | null>(null);
    const [isConnectionsModalOpen, setIsConnectionsModalOpen] = useState(false);
    const [connectionsResult, setConnectionsResult] = useState<{ seedPaper: ResearchPaper; connections: ConnectedPaper[] } | null>(null);
    const [isFindingConnections, setIsFindingConnections] = useState(false);
    const [connectionsError, setConnectionsError] = useState<string | null>(null);
    const [isJournalFinderOpen, setIsJournalFinderOpen] = useState(false);
    const [journalRecommendations, setJournalRecommendations] = useState<JournalRecommendation[]>([]);
    const [isFindingJournals, setIsFindingJournals] = useState(false);
    const [journalFinderError, setJournalFinderError] = useState<string | null>(null);
    const [paperForJournalFinder, setPaperForJournalFinder] = useState<ResearchPaper | null>(null);
    const [isOrgFinderOpen, setIsOrgFinderOpen] = useState(false);
    const [selectedInstitution, setSelectedInstitution] = useState<{ id: string; name: string } | undefined>(undefined);
    const [isFindingSimilar, setIsFindingSimilar] = useState(false); // New state for similar papers loading

    // Dissertation Study State
    const [goldStandardDataset, setGoldStandardDataset] = useState<GoldStandardPaper[]>([]);
    const [testHarnessResults, setTestHarnessResults] = useState<TestHarnessResult[]>([]);
    const [userStudyData, setUserStudyData] = useState<UserStudyData[]>([]);

    useEffect(() => {
        const handlePaperReceived = (paper: ResearchPaper) => {
            setWorkspacePapers(prev => {
                if (prev.some(p => p.id === paper.id)) {
                    return prev; // Already in workspace
                }
                return [paper, ...prev];
            });
        };

        const cleanup = extensionService.listenForExtensionMessages(
            handlePaperReceived, // onPaperSaved (now used for adding to workspace)
            (paperId) => { // onPaperRemoved
                setWorkspacePapers(prev => prev.filter(p => p.id !== paperId));
            }
        );

        return cleanup;
    }, []);

    // Effect for debouncing search suggestions
    useEffect(() => {
        const fetchSearchSuggestions = async (currentQuery: string) => {
            setIsGeneratingSearchSuggestions(true);
            try {
                const suggestions = await apiService.generateSearchSuggestions(currentQuery, model);
                // Only update suggestions if the query hasn't changed while fetching
                setQuery(prevQuery => {
                    if (prevQuery === currentQuery) {
                        setSearchSuggestions(suggestions);
                    }
                    return prevQuery;
                });
            } catch (error) {
                console.error("Failed to fetch search suggestions:", error);
                setSearchSuggestions([]);
            } finally {
                setIsGeneratingSearchSuggestions(false);
            }
        };

        const handler = setTimeout(() => {
            if (query.length > 3 && !isLoading && !hasSearched) {
                fetchSearchSuggestions(query);
            } else {
                setSearchSuggestions([]);
            }
        }, 500); // 500ms debounce

        return () => {
            clearTimeout(handler);
        };
    }, [query, isLoading, hasSearched, model]);


    // Helper to trigger background validation
    const triggerBackgroundValidation = (papersToValidate: ResearchPaper[]) => {
        // Process validation in the background to populate badges
        papersToValidate.forEach(async (paper) => {
            // Avoid validating if we already have a 'validated' or 'validating' status
            if (paper.validation?.status === 'validated' || paper.validation?.status === 'validating') return;

            // Optimistic update to 'validating'
            const currentValidation = paper.validation || { 
                score: 0, 
                status: 'unvalidated', 
                checks: { crossref_match: false, title_match: false, author_match: false, open_access: false, doaj_indexed: false, source_enriched: false, has_citations: false }, 
                log: [] 
            };
            updatePaperState(paper.id, { validation: { ...currentValidation, status: 'validating' } });

            try {
                const { validation, updatedPaperData } = await apiService.validatePaper(paper);
                updatePaperState(paper.id, { ...updatedPaperData, validation });
            } catch (e) {
                console.warn(`Background validation failed for paper ${paper.id}`, e);
                 updatePaperState(paper.id, { validation: { ...currentValidation, status: 'error' } });
            }
        });
    };


    const handleSearch = async (searchQuery: string, options: AdvancedSearchOptions) => {
        // Use DOI from options if provided, otherwise check if the search query itself is a DOI
        const specificDoi = options.doi?.trim();
        if (!searchQuery.trim() && !specificDoi) return;

        const doiRegex = /^10.\d{4,9}\/[-._;()/:A-Z0-9]+$/i;
        const queryIsDoi = doiRegex.test(searchQuery.trim());
        const effectiveDoi = specificDoi || (queryIsDoi ? searchQuery.trim() : null);

        setSearchSuggestions([]);
        setIsGeneratingSearchSuggestions(false);
        setIsLoading(true);
        setIsSearchingGrounded(false);
        setError(null);
        setPapers([]);
        setSummary(''); // Clear summary to show loading state in UI if needed
        setIsSummaryLoading(false);
        setHasSearched(true);
        setSelectedPaper(null);
        setAnalysis(null);
        setIsScreeningMode(false);
        setSortConfig({ key: 'relevance', direction: 'desc' });
        setCurrentPage(1);
        setLastUsedOptions(options);
        setIsFindingSimilar(false); // Reset this loading state

        if (effectiveDoi) {
            try {
                const result = await apiService.searchByDoi(effectiveDoi, model);
                if (result) {
                    setPapers([result]);
                    setHasMore(false);
                    handleSelectPaper(result);
                } else {
                    setError(`No paper found for DOI: ${effectiveDoi}`);
                }
            } catch (err) {
                setError(err instanceof Error ? err.message : "An unknown error occurred while searching by DOI.");
            } finally {
                setIsLoading(false);
            }
        } else {
            try {
                // 1. Fast Search (API-based) - Returns immediately after API response
                // The promise for hypotheticalAnswer is returned to allow background processing
                const { papers: fastPapers, hasMore, hypotheticalAnswer: hypoPromise, parsedFilters } = await apiService.search(searchQuery, options, summaryLength, summaryStyle, model, searchSources, 1);

                setPapers(fastPapers);
                setHasMore(hasMore);
                setIsLoading(false); // Stop main spinner immediately

                // 2. Background: Semantic Scoring & Refinement
                // We wait for the hypothesis to be generated, then score the papers
                hypoPromise.then(async (hypotheticalAnswer) => {
                    if (fastPapers.length > 0) {
                        const scoredPapers = await apiService.scorePapers(fastPapers, searchQuery, hypotheticalAnswer, model);

                        // Update papers with scores
                        setPapers(current => {
                            const scoredMap = new Map(scoredPapers.map(p => [p.id, p]));
                            return current.map(p => scoredMap.get(p.id) || p);
                        });

                        // 3. Background: Analysis & Summary (using scored papers for better quality)
                        analysisService.analyzePapers(scoredPapers).then(setAnalysis);
                        setIsSummaryLoading(true);
                        apiService.generateSearchSummary(scoredPapers, summaryLength, summaryStyle, model)
                            .then(setSummary)
                            .catch(e => console.warn("Summary generation failed", e))
                            .finally(() => setIsSummaryLoading(false));
                        triggerBackgroundValidation(scoredPapers);
                    }

                    // 4. Background: Deep AI Search (Grounded)
                    // Only run if this is the first page search and we have context
                    setIsSearchingGrounded(true);
                    apiService.searchGrounded(searchQuery, hypotheticalAnswer, model, parsedFilters).then(groundedPapers => {
                        if (groundedPapers.length > 0) {
                             // Score grounded papers before merging
                             apiService.scorePapers(groundedPapers, searchQuery, hypotheticalAnswer, model).then(scoredGrounded => {
                                setPapers(prev => {
                                    const merged = apiService.mergePapers([...prev, ...scoredGrounded]);
                                    return merged;
                                });
                                triggerBackgroundValidation(groundedPapers);
                             });
                        }
                    }).finally(() => {
                        setIsSearchingGrounded(false);
                    });
                });

            } catch (err) {
                setError(err instanceof Error ? err.message : "An unknown error occurred.");
                setIsLoading(false);
            }
        }
    };

    const handleSuggestionSearch = (suggestion: string) => {
        setQuery(suggestion);
        handleSearch(suggestion, lastUsedOptions);
    };

    const handleLoadMore = async () => {
        if (!query.trim() || isLoadingMore || !hasMore) return;

        setIsLoadingMore(true);
        setError(null);

        const pageToFetch = currentPage + 1;

        try {
            // Pagination currently only supports the fast API search
            const result = await apiService.search(query, lastUsedOptions, summaryLength, summaryStyle, model, searchSources, pageToFetch);

            // Append basic papers immediately
            setPapers(prev => [...prev, ...result.papers]);
            setCurrentPage(pageToFetch);
            setHasMore(result.hasMore);

            // Score in background
            result.hypotheticalAnswer.then(async (hypo) => {
                 const newPapersScored = await apiService.scorePapers(result.papers, query, hypo, model);

                 setPapers(current => {
                     const scoredMap = new Map(newPapersScored.map(p => [p.id, p]));
                     return current.map(p => scoredMap.get(p.id) || p);
                 });

                 // Update analysis with all papers
                 // Use functional update to get latest state or merge
                 analysisService.analyzePapers([...papers, ...newPapersScored]).then(setAnalysis);
                 triggerBackgroundValidation(newPapersScored);
            });

        } catch (err) {
            setError(err instanceof Error ? err.message : "An unknown error occurred.");
        } finally {
            setIsLoadingMore(false);
        }
    };

    const updatePaperState = (paperId: string, updates: Partial<ResearchPaper>) => {
        const updater = (p: ResearchPaper) => p.id === paperId ? { ...p, ...updates } : p;
        setPapers(prev => prev.map(updater));
        setWorkspacePapers(prev => prev.map(updater));
        if (selectedPaper?.id === paperId) {
            setSelectedPaper(prev => prev ? { ...prev, ...updates } : null);
        }
    };

    // Asynchronously classify study designs for new papers without blocking the UI
    useEffect(() => {
        const papersToClassify = papers.filter(p => p.detectedStudyDesign === undefined);

        if (papersToClassify.length > 0) {
            // Mark papers as "classification in progress" to avoid re-triggering on re-renders.
            papersToClassify.forEach(p => updatePaperState(p.id, { detectedStudyDesign: '...' as any }));

            papersToClassify.forEach(paper => {
                apiService.classifyStudyDesign(paper, model)
                    .then(design => {
                        updatePaperState(paper.id, { detectedStudyDesign: design });
                    })
                    .catch(error => {
                        console.error(`Failed to classify study design for paper ${paper.id}`, error);
                        updatePaperState(paper.id, { detectedStudyDesign: 'N/A' });
                    });
            });
        }
    }, [papers, model]);

    const handleSelectPaper = async (paper: ResearchPaper) => {
        setSelectedPaper(paper);

        // Fetch open access PDF if DOI is available and not yet fetched
        if (paper.doi && !paper.openAccessState) {
            updatePaperState(paper.id, { openAccessState: 'loading' });
            try {
                const url = await apiService.findOpenAccessPdf(paper.doi);
                updatePaperState(paper.id, { openAccessPdfUrl: url || undefined, openAccessState: 'loaded' });
            } catch (error) {
                console.error("Failed to find open access PDF:", error);
                updatePaperState(paper.id, { openAccessState: 'error' });
            }
        }

        // Fetch Key Concepts if not already fetched
        if (!paper.keyConceptsState || paper.keyConceptsState === 'idle') {
            updatePaperState(paper.id, { keyConceptsState: 'loading' });
            try {
                // Pass title and abstract for better extraction
                const concepts = await apiService.extractKeyConcepts(paper.title, paper.abstract, model);
                updatePaperState(paper.id, { keyConcepts: concepts, keyConceptsState: 'loaded' });
            } catch (error) {
                console.error("Failed to extract key concepts:", error);
                updatePaperState(paper.id, { keyConceptsState: 'error' });
            }
        }

        // Fetch Knowledge Graph if not already fetched
        if (!paper.knowledgeGraphState || paper.knowledgeGraphState === 'idle') {
            if (paper.abstract.length < 150) {
                 updatePaperState(paper.id, { knowledgeGraph: { entities: [], relationships: [] }, knowledgeGraphState: 'loaded' });
            } else {
                updatePaperState(paper.id, { knowledgeGraphState: 'loading' });
                try {
                    const graph = await apiService.extractKnowledgeGraph(paper.abstract, model);
                    updatePaperState(paper.id, { knowledgeGraph: graph, knowledgeGraphState: 'loaded' });
                } catch (error) {
                    console.error("Failed to extract knowledge graph:", error);
                    updatePaperState(paper.id, { knowledgeGraphState: 'error' });
                }
            }
        }
    };

    const handleToggleWorkspacePaper = (paper: ResearchPaper) => {
        setWorkspacePapers(prev => {
            const exists = prev.some(p => p.id === paper.id);
            if (exists) {
                // If removing, also remove from any project it's in
                setProjects(projs => projs.map(p => ({...p, paperIds: p.paperIds.filter(id => id !== paper.id) })));
                return prev.filter(p => p.id !== paper.id);
            } else {
                return [...prev, paper];
            }
        });
    };

    const handleOpenVerificationModal = (paper: ResearchPaper) => {
        analyticsService.logEvent('tool_used', { tool: 'verify_paper_modal_opened', paperId: paper.id });
        setPaperToVerify(paper);
        setIsVerificationModalOpen(true);
    };

    const handleVerificationComplete = (doi: string, result: VerificationResult) => {
        setPapers(prev => prev.map(p => p.doi === doi ? { ...p, verificationResult: result } : p));
        setWorkspacePapers(prev => prev.map(p => p.doi === doi ? { ...p, verificationResult: result } : p));
        if (selectedPaper?.doi === doi) {
            setSelectedPaper(prev => prev ? { ...prev, verificationResult: result } : null);
        }
    };

    const handleAnalyzeGaps = async (papersToAnalyze: ResearchPaper[], modelToUse: ModelDefinition) => {
        analyticsService.logEvent('tool_used', { tool: 'analyze_gaps', paperCount: papersToAnalyze.length });
        setIsGapAnalysisModalOpen(true);
        setIsAnalyzingGaps(true);
        setGapAnalysisError(null);
        setGapAnalysisResult(null);

        try {
            const result = await apiService.analyzeGaps(papersToAnalyze, modelToUse);
            setGapAnalysisResult(result);
        } catch (err) {
            const message = err instanceof Error ? err.message : "An unknown error occurred.";
            setGapAnalysisError(message);
        } finally {
            setIsAnalyzingGaps(false);
        }
    };

    const handleAnalyzePaper = async (paper: ResearchPaper) => {
        analyticsService.logEvent('tool_used', { tool: 'analyze_single_paper', paperId: paper.id });
        setIsAnalysisModalOpen(true);
        setIsAnalyzingPaper(true);
        setAnalysisError(null);
        // Set paper immediately for the modal header, but analysis will be fetched.
        setAnalysisResult({ paper, analysis: paper.savedAnalysis || {} as PaperAnalysis });

        try {
            const analysis = await apiService.analyzeSinglePaper(paper, model);
            setAnalysisResult({ paper, analysis });
        } catch (err) {
            const message = err instanceof Error ? err.message : "An unknown error occurred.";
            setAnalysisError(message);
        } finally {
            setIsAnalyzingPaper(false);
        }
    };

    const handleSaveAnalysis = (paper: ResearchPaper, analysis: PaperAnalysis) => {
        const updatePaper = (p: ResearchPaper) => p.id === paper.id ? { ...p, savedAnalysis: analysis } : p;
        setPapers(prev => prev.map(updatePaper));
        setWorkspacePapers(prev => prev.map(updatePaper));
        if (selectedPaper?.id === paper.id) {
            setSelectedPaper(prev => prev ? { ...prev, savedAnalysis: analysis } : null);
        }
        setAnalysisResult(prev => prev ? { ...prev, paper: { ...prev.paper, savedAnalysis: analysis }} : null);
    };

    const handleConceptSearch = (concept: string) => {
        const currentQuery = query;
        setQuery(concept);
        handleSearch(concept, { ...lastUsedOptions, inclusionCriteria: `"${concept}" OR "${currentQuery}"` });
    };

    const handleOpenCitationModal = (paper: ResearchPaper) => {
        analyticsService.logEvent('tool_used', { tool: 'open_citation_modal', paperId: paper.id });
        setPaperForCitation(paper);
        setIsCitationModalOpen(true);
    };

    const handleSortChange = (key: SortKey) => {
        setSortConfig(current => {
            if (current.key === key) {
                return { ...current, direction: current.direction === 'asc' ? 'desc' : 'asc' };
            }
            return { key, direction: 'desc' };
        });
    };

    const handleSetScreeningMode = (enabled: boolean) => {
        setIsScreeningMode(enabled);
        if (enabled) {
            // Initialize screening status for all papers
            setPapers(prev => prev.map(p => ({ ...p, screeningStatus: p.screeningStatus || 'none' })));
            // Switch to sorting by screening fit score by default
            setSortConfig({ key: 'screeningFitScore', direction: 'desc' });
        }
    };

    const handleScreenPaper = (paperId: string, status: 'include' | 'exclude' | 'none') => {
        setPapers(prev => prev.map(p => p.id === paperId ? { ...p, screeningStatus: status } : p));
    };

    const handleAiRerank = async () => {
        setIsReranking(true);
        try {
            const includedExplicit = papers.filter(p => p.screeningStatus === 'include');
            const allIncluded = [...new Map([...includedExplicit, ...workspacePapers].map(item => [item.id, item])).values()];
            const excluded = papers.filter(p => p.screeningStatus === 'exclude');
            const unscreened = papers.filter(p => !p.screeningStatus || p.screeningStatus === 'none');

            const rerankedResults = await apiService.rerankForScreening(allIncluded, excluded, unscreened, model);

            const rerankedMap = new Map(rerankedResults.map(r => [r.paperId, { score: r.score, rationale: r.rationale }]));

            setPapers(prev => prev.map(p => {
                const rerankedData = rerankedMap.get(p.id);
                if (rerankedData) {
                    return {
                        ...p,
                        screeningFitScore: rerankedData.score,
                        screeningRationale: rerankedData.rationale,
                    };
                }
                return p;
            }));

        } catch (err) {
            setError(err instanceof Error ? err.message : "An error occurred during AI re-ranking.");
        } finally {
            setIsReranking(false);
        }
    };

    const handleGenerateSuggestions = async (paper: ResearchPaper) => {
        analyticsService.logEvent('tool_used', { tool: 'generate_suggestions', paperId: paper.id });
        setIsGeneratingSuggestions(true);
        setSuggestionsError(null);
        setIsSuggestionsModalOpen(true);
        setSuggestionsResult({ seedPaper: paper, suggestions: [] });

        try {
            const suggestions = await apiService.generateSuggestions(paper, model);
            setSuggestionsResult({ seedPaper: paper, suggestions });
        } catch (err) {
            const message = err instanceof Error ? err.message : "An unknown error occurred.";
            setSuggestionsError(message);
        } finally {
            setIsGeneratingSuggestions(false);
        }
    };

    const handleSuggestionClick = (newQuery: string) => {
        setIsSuggestionsModalOpen(false);
        setQuery(newQuery);
        handleSearch(newQuery, lastUsedOptions);
    };

    const handleFindDoi = async (paperToUpdate: ResearchPaper) => {
        analyticsService.logEvent('tool_used', { tool: 'find_doi', paperId: paperToUpdate.id });
        updatePaperState(paperToUpdate.id, { doiState: 'loading' });
        try {
            const doi = await apiService.findDoiForPaper(paperToUpdate);
            if (doi) {
                updatePaperState(paperToUpdate.id, { doi: doi, doiState: 'loaded' });
            } else {
                updatePaperState(paperToUpdate.id, { doiState: 'error' });
            }
        } catch (error) {
            console.error("Failed to find DOI:", error);
            updatePaperState(paperToUpdate.id, { doiState: 'error' });
        }
    };

    const handleFindConnectedPapers = async (paper: ResearchPaper) => {
        analyticsService.logEvent('tool_used', { tool: 'find_connected_papers', paperId: paper.id });
        setIsConnectionsModalOpen(true);
        setIsFindingConnections(true);
        setConnectionsError(null);
        setConnectionsResult({ seedPaper: paper, connections: [] });

        try {
            const connections = await apiService.findConnectedPapers(paper, model);
            setConnectionsResult({ seedPaper: paper, connections });
        } catch (err) {
            setConnectionsError(err instanceof Error ? err.message : "An unknown error occurred.");
        } finally {
            setIsFindingConnections(false);
        }
    };

    const handleFindJournals = async (paper: ResearchPaper) => {
        analyticsService.logEvent('tool_used', { tool: 'find_journals', paperId: paper.id });
        setIsJournalFinderOpen(true);
        setIsFindingJournals(true);
        setJournalFinderError(null);
        setPaperForJournalFinder(paper);
        setJournalRecommendations([]);

        try {
            const recommendations = await apiService.suggestJournals(paper, model);
            setJournalRecommendations(recommendations);
        } catch (err) {
            setJournalFinderError(err instanceof Error ? err.message : "An unknown error occurred.");
        } finally {
            setIsFindingJournals(false);
        }
    };

    const handleAuthorSearch = (author: AuthorProfile) => {
        // Use the author name for display query
        setQuery(author.name);

        // Use author ID for precise search if available, otherwise name
        // Reset other filters to ensure clean search
        const options: AdvancedSearchOptions = {
            startYear: '',
            endYear: '',
            authors: '', // We use authorId or specific author filter logic
            authorId: author.id,
            excludeKeywords: '',
            inclusionCriteria: '',
            exclusionCriteria: '',
            studyDesign: 'any',
            journal: '',
            minCitations: '',
            titleKeywords: '',
            abstractKeywords: '',
            isOpenAccess: false,
        };

        // If no ID, pass name to authors field
        if (!author.id) {
            options.authors = author.name;
        }

        handleSearch(author.name, options);
    };

    const handleSelectOrganization = (org: Organization) => {
        setSelectedInstitution(org);
        setIsOrgFinderOpen(false);
    };

    const handleFindSimilar = async (paper: ResearchPaper) => {
        analyticsService.logEvent('tool_used', { tool: 'find_similar_papers', paperId: paper.id });
        setIsFindingSimilar(true); // Set loading state

        try {
            // 1. Generate an optimized search query from the paper's content
            const similarQuery = await apiService.generateSimilaritySearchQuery(paper, model);

            // 2. Update the UI search bar to reflect this new "Pivot Search"
            setQuery(similarQuery);

            // 3. Execute the search using standard options, but reset filters that might be too specific
            const newOptions: AdvancedSearchOptions = {
                ...lastUsedOptions,
                authors: '', // Don't restrict to same authors
                journal: '', // Don't restrict to same journal
                titleKeywords: '', 
                abstractKeywords: '',
                doi: '', // Clear specific DOI
            };

            handleSearch(similarQuery, newOptions);

        } catch (err) {
            console.error("Failed to find similar papers:", err);
            setError("Failed to find similar papers. Please try again."); // Provide user feedback
        } finally {
            setIsFindingSimilar(false); // Clear loading state
        }
    };


    const sortedPapers = useMemo(() => {
        return [...papers].sort((a, b) => {
            const { key, direction } = sortConfig;
            const dir = direction === 'asc' ? 1 : -1;

            const getVal = (p: ResearchPaper, k: SortKey) => {
                switch(k) {
                    case 'relevance': return p.combinedScore;
                    case 'year': return p.year;
                    case 'citations': return p.citations;
                    case 'validationScore': return p.validation?.score;
                    case 'screeningFitScore': return p.screeningFitScore;
                    default: return 0;
                }
            };

            const aVal = getVal(a, key) ?? -1;
            const bVal = getVal(b, key) ?? -1;

            if (aVal < bVal) return -1 * dir;
            if (aVal > bVal) return 1 * dir;
            return 0;
        });
    }, [papers, sortConfig]);

    const handleCreateProject = (name: string) => {
        const newProject: Project = {
            id: `proj_${Date.now()}`,
            name,
            paperIds: [],
            createdAt: Date.now(),
            color: PROJECT_COLORS[projects.length % PROJECT_COLORS.length],
            paperStatuses: {},
        };
        setProjects(prev => [...prev, newProject]);
    };

    const handleDeleteProject = (projectId: string) => {
        setProjects(prev => prev.filter(p => p.id !== projectId));
        // Also remove any chat history associated with the project
        setProjectChats(prev => {
            const newChats = {...prev};
            delete newChats[projectId];
            return newChats;
        });
    };

    const handleMovePaperToProject = (paperId: string, projectId: string | null) => {
        setProjects(prevProjects => {
            const newProjects = prevProjects.map(p => ({
                ...p,
                paperIds: p.paperIds.filter(id => id !== paperId),
            }));

            if (projectId) {
                const targetProjectIndex = newProjects.findIndex(p => p.id === projectId);
                if (targetProjectIndex > -1) {
                    newProjects[targetProjectIndex].paperIds.push(paperId);
                }
            }
            return newProjects;
        });
    };

    const handleUpdateProjectColor = (projectId: string, color: string) => {
        setProjects(prev => prev.map(p => p.id === projectId ? { ...p, color } : p));
    };

    const handleSynthesizeWorkspace = async (papersToSynthesize: ResearchPaper[], modelToUse: ModelDefinition) => {
        analyticsService.logEvent('tool_used', { tool: 'synthesize_workspace', paperCount: papersToSynthesize.length });
        setIsSynthesisModalOpen(true);
        setIsSynthesizing(true);
        setSynthesisError(null);
        setSynthesisResult(null);
        try {
            const result = await apiService.synthesizePapers(papersToSynthesize, modelToUse);
            setSynthesisResult(result);
        } catch (err) {
            const message = err instanceof Error ? err.message : "An unknown error occurred.";
            setSynthesisError(message);
        } finally {
            setIsSynthesizing(false);
        }
    };

     const handleIndexPaperForRag = (projectId: string, paperId: string) => {
        setProjects(prev => prev.map(p => {
            if (p.id === projectId) {
                const newStatuses = { ...p.paperStatuses, [paperId]: 'indexing' as const };
                return { ...p, paperStatuses: newStatuses };
            }
            return p;
        }));

        // Simulate indexing delay
        setTimeout(() => {
            setProjects(prev => prev.map(p => {
                if (p.id === projectId) {
                    // 10% chance of error for simulation purposes
                    const status = Math.random() > 0.9 ? 'error' : 'indexed';
                    const newStatuses = { ...p.paperStatuses, [paperId]: status };
                    return { ...p, paperStatuses: newStatuses };
                }
                return p;
            }));
        }, 2000 + Math.random() * 1000);
    };

    const handleProjectChat = async (projectId: string, message: string) => {
        const project = projects.find(p => p.id === projectId);
        if (!project) return;

        const userMessage: ChatMessage = { role: 'user', parts: [{ text: message }] };

        setProjectChats(prev => ({
            ...prev,
            [projectId]: {
                history: [...(prev[projectId]?.history || []), userMessage],
                isLoading: true,
            }
        }));

        try {
            const projectPapers: ResearchPaper[] = project.paperIds.map(id => workspacePapers.find(p => p.id === id)).filter((p): p is ResearchPaper => !!p);

            // The agent service now streams updates. We'll handle them one by one.
            const agentStream = agentService.runAgentTask(message, project, projectPapers, model);

            for await (const update of agentStream) {
                setProjectChats(prev => {
                    const currentHistory = prev[projectId]?.history || [];
                    let newHistory = [...currentHistory];

                    if (update.type === 'tool-start') {
                        newHistory.push({ role: 'tool', parts: [{ toolCall: update.toolCall }] });
                    } else if (update.type === 'tool-end') {
                        // Find the corresponding tool-start message and add the result
                        const lastMsgIndex = newHistory.length - 1;
                        if (newHistory[lastMsgIndex]?.role === 'tool' && newHistory[lastMsgIndex].parts[0].toolCall?.name === update.toolResponse.name) {
                            newHistory[lastMsgIndex].parts[0].toolResponse = update.toolResponse;
                        }
                    } else if (update.type === 'final-answer') {
                        newHistory.push({ role: 'model', parts: [{ text: update.text }] });
                    }

                    return {
                        ...prev,
                        [projectId]: {
                            ...prev[projectId],
                            history: newHistory,
                        },
                    };
                });
            }

        } catch (error) {
            const errorMessage = error instanceof Error ? error.message : "An error occurred.";
            const modelMessage: ChatMessage = { role: 'model', parts: [{ text: `Error: ${errorMessage}` }] };
            setProjectChats(prev => ({
                ...prev,
                [projectId]: {
                    history: [...(prev[projectId]?.history || []), modelMessage],
                    isLoading: false,
                }
            }));
        } finally {
            setProjectChats(prev => ({
                ...prev,
                [projectId]: {
                    ...prev[projectId],
                    isLoading: false,
                }
            }));
        }
    };

    const handleAddSource = (source: SearchSourceInfo) => {
        setSearchSources(prev => {
            if (!prev.some(s => s.id === source.id)) {
                return [...prev, source];
            }
            return prev;
        });
    };


    // --- Dissertation Feature Handlers ---

    const handleUpdateGoldStandardPaper = (updatedPaper: GoldStandardPaper) => {
        setGoldStandardDataset(prev => prev.map(p => p.paper_id === updatedPaper.paper_id ? updatedPaper : p));
    };

    const handleRunTestHarness = async () => {
        analyticsService.logEvent('test_harness_run_started', { datasetSize: goldStandardDataset.length });
        const results: TestHarnessResult[] = [];
        for (const paper of goldStandardDataset) {
            try {
                // Reconstruct a partial ResearchPaper for verification
                const paperForVerification: ResearchPaper = {
                    id: paper.paper_id, // Use ID or create a stable one
                    title: paper.title,
                    authors: paper.authors,
                    year: paper.year,
                    abstract: paper.abstract,
                    doi: paper.paper_id,
                    // Fill other required fields with defaults or empty
                    citations: 0,
                    sourceURL: `https://doi.org/${paper.paper_id}`,
                };

                const vacsResult = await verificationService.verifyPaper(paperForVerification, paper.title);

                // Map VACS verdict to our label system for comparison
                const vacsLabel = vacsResult.verdict === 'Verified' ? 'verified' 
                                : vacsResult.verdict === 'Questionable' ? 'refuted' 
                                : 'inconclusive';

                const isCorrect = vacsLabel === paper.label;

                results.push({
                    paperId: paper.paper_id,
                    vacsResult,
                    groundTruth: paper,
                    isCorrect,
                    precisionAt1: isCorrect ? 1 : 0,
                });
            } catch (error) {
                console.error(`Failed to verify paper ${paper.paper_id}`, error);
            }
        }
        setTestHarnessResults(results);
        const accuracy = results.length > 0 ? (results.filter(r => r.isCorrect).length / results.length) * 100 : 0;
        analyticsService.logEvent('test_harness_run_completed', { 
            testCount: results.length, 
            accuracy: parseFloat(accuracy.toFixed(2)) 
        });
    };

    const handleSaveUserStudyData = (data: UserStudyData) => {
        analyticsService.logEvent('user_study_task_completed', { studyData: data });
        setUserStudyData(prev => [...prev, data]);
    };


    const renderAppMode = () => {
        switch (appMode) {
            case 'dashboard':
                return <ResearcherDashboard 
                            dataset={goldStandardDataset}
                            setDataset={handleUpdateGoldStandardPaper}
                            testResults={testHarnessResults}
                            runTestHarness={handleRunTestHarness}
                            userStudyData={userStudyData}
                            onStartUserStudy={() => setAppMode('evaluation')}
                        />;
            case 'evaluation':
                return <PaperVerificationApp 
                            dataset={goldStandardDataset} 
                            onComplete={(data) => {
                                handleSaveUserStudyData(data);
                                alert('Study task complete! Thank you.');
                                // In a real study, you might show a new task or end the session.
                                // For now, we return to the dashboard.
                                setAppMode('dashboard');
                            }}
                        />;
            case 'search':
            default:
                return (
                    <div className="container mx-auto px-4 sm:px-6 lg:px-8 py-6">
                        <div className="grid grid-cols-1 lg:grid-cols-5 gap-8">
                            <main className={hasSearched ? "lg:col-span-3" : "lg:col-span-5"}>
                                {!hasSearched ? (
                                    <InitialSearchScreen 
                                        query={query} 
                                        onQueryChange={setQuery} 
                                        onSearch={handleSearch} 
                                        isLoading={isLoading} 
                                        summaryLength={summaryLength} 
                                        onLengthChange={setSummaryLength} 
                                        summaryStyle={summaryStyle} 
                                        onStyleChange={setSummaryStyle} 
                                        model={model} 
                                        onModelChange={setModel} 
                                        availableModels={AVAILABLE_MODELS} 
                                        logAnalyticsEvent={() => {}} 
                                        onOpenDbFinder={() => setIsDbFinderOpen(true)} 
                                        searchSources={searchSources}
                                        suggestions={searchSuggestions}
                                        isSuggestionsLoading={isGeneratingSearchSuggestions}
                                        onSuggestionClick={handleSuggestionSearch}
                                        onOpenOrgFinder={() => setIsOrgFinderOpen(true)}
                                    >
                                        <ExtensionPromo />
                                    </InitialSearchScreen>
                                ) : (
                                    <div className="space-y-6">
                                        <SearchForm 
                                            query={query} 
                                            onQueryChange={setQuery} 
                                            onSearch={handleSearch} 
                                            isLoading={isLoading} 
                                            summaryLength={summaryLength} 
                                            onLengthChange={setSummaryLength} 
                                            summaryStyle={summaryStyle} 
                                            onStyleChange={setSummaryStyle} 
                                            model={model} 
                                            onModelChange={setModel} 
                                            availableModels={AVAILABLE_MODELS} 
                                            logAnalyticsEvent={() => {}}
                                            suggestions={searchSuggestions}
                                            isSuggestionsLoading={isGeneratingSearchSuggestions}
                                            onSuggestionClick={handleSuggestionSearch}
                                            onOpenOrgFinder={() => setIsOrgFinderOpen(true)}
                                            selectedInstitution={selectedInstitution}
                                            onClearInstitution={() => setSelectedInstitution(undefined)}
                                        />
                                        {isLoading && <LoadingSpinner message={"Searching..."} />}
                                        {error && <ErrorMessage message={error} />}
                                        {!isLoading && !error && hasSearched && (
                                            <>
                                                <ResultsDisplay 
                                                    papers={sortedPapers} 
                                                    selectedPaperId={selectedPaper?.id || null} 
                                                    onSelectPaper={handleSelectPaper} 
                                                    sortConfig={sortConfig} 
                                                    onSortChange={handleSortChange}
                                                    isScreeningMode={isScreeningMode}
                                                    onSetScreeningMode={handleSetScreeningMode}
                                                    onScreenPaper={handleScreenPaper}
                                                    onAiRerank={handleAiRerank}
                                                    isReranking={isReranking}
                                                    onLoadMore={handleLoadMore}
                                                    hasMore={hasMore}
                                                    isLoadingMore={isLoadingMore}
                                                    isSearchingGrounded={isSearchingGrounded}
                                                />
                                            </>
                                        )}
                                    </div>
                                )}
                            </main>

                            {hasSearched && (
                                <aside className="lg:col-span-2">
                                <WorkspacePanel 
                                    papers={papers} 
                                    selectedPaper={selectedPaper} 
                                    analysis={analysis} 
                                    summary={summary} 
                                    workspacePapers={workspacePapers} 
                                    projects={projects} 
                                    sources={[]} 
                                    onToggleWorkspacePaper={handleToggleWorkspacePaper} 
                                    onFindConnectedPapers={handleFindConnectedPapers} 
                                    isFindingConnected={isFindingConnections} 
                                    onAnalyzePaper={handleAnalyzePaper} 
                                    onCitePaper={handleOpenCitationModal} 
                                    isAnalyzingPaper={isAnalyzingPaper} 
                                    onConceptClick={handleConceptSearch} 
                                    onFindDoi={handleFindDoi} 
                                    onGenerateSuggestions={handleGenerateSuggestions} 
                                    isGeneratingSuggestions={isGeneratingSuggestions} 
                                    onVerifyPaper={handleOpenVerificationModal} 
                                    logAnalyticsEvent={() => {}} 
                                    refinedQueries={refinedQueries} 
                                    isGeneratingRefined={false} 
                                    onRefinedQuerySearch={() => {}} 
                                    onAnalyzeGaps={handleAnalyzeGaps} 
                                    onSynthesizeWorkspace={handleSynthesizeWorkspace} 
                                    onCreateProject={handleCreateProject} 
                                    onDeleteProject={handleDeleteProject} 
                                    onMovePaperToProject={handleMovePaperToProject} 
                                    onUpdateProjectColor={handleUpdateProjectColor} 
                                    model={model} 
                                    onIndexPaperForRag={handleIndexPaperForRag} 
                                    projectChats={projectChats} 
                                    onProjectChat={handleProjectChat} 
                                    isSummaryLoading={isSummaryLoading} 
                                    onFindJournals={handleFindJournals}
                                    isFindingJournals={isFindingJournals}
                                    onAuthorClick={handleAuthorSearch}
                                    onFindSimilar={handleFindSimilar}
                                    isFindingSimilar={isFindingSimilar} // Pass new prop to WorkspacePanel
                                />
                                </aside>
                            )}
                        </div>
                    </div>
                );
        }
    }

    return (
        <div className="min-h-screen bg-background text-foreground flex flex-col">
            <Header
                onOpenAbout={() => setIsAboutModalOpen(true)}
                onOpenHelp={() => setIsOnboardingOpen(true)}
                appMode={appMode}
                onModeChange={setAppMode}
            />
            <div className="flex-grow">
                {renderAppMode()}
            </div>

            {/* Modals are kept at the top level to be accessible from any mode */}
            {isOnboardingOpen && <OnboardingModal onComplete={() => setIsOnboardingOpen(false)} onSkip={() => setIsOnboardingOpen(false)} />}
            {isAboutModalOpen && <InfoModal isOpen={isAboutModalOpen} onClose={() => setIsAboutModalOpen(false)} title="About AI Research Explorer"> <AboutModalContent /> </InfoModal>}
            <VerificationModal isOpen={isVerificationModalOpen} onClose={() => setIsVerificationModalOpen(false)} paper={paperToVerify} onVerificationComplete={handleVerificationComplete} />
            <ReportModal isOpen={isGapAnalysisModalOpen} onClose={() => setIsGapAnalysisModalOpen(false)} isLoading={isAnalyzingGaps} content={gapAnalysisResult} error={gapAnalysisError} />
            <PaperAnalysisModal isOpen={isAnalysisModalOpen} onClose={() => setIsAnalysisModalOpen(false)} isLoading={isAnalyzingPaper} error={analysisError} result={analysisResult} onSaveAnalysis={handleSaveAnalysis} isAnalysisSaved={!!analysisResult?.paper.savedAnalysis} />
            <SynthesisModal isOpen={isSynthesisModalOpen} onClose={() => setIsSynthesisModalOpen(false)} isLoading={isSynthesizing} result={synthesisResult} error={synthesisError} />
            <CitationModal isOpen={isCitationModalOpen} onClose={() => setIsCitationModalOpen(false)} paper={paperForCitation} model={model} />
            <DatabaseFinderModal isOpen={isDbFinderOpen} onClose={() => setIsDbFinderOpen(false)} onAddSource={handleAddSource} existingSources={searchSources} />
            <SuggestionsModal isOpen={isSuggestionsModalOpen} result={suggestionsResult} onClose={() => setIsSuggestionsModalOpen(false)} error={suggestionsError} isLoading={isGeneratingSuggestions} onSuggestionClick={handleSuggestionClick} />
            <ConnectedPapersModal isOpen={isConnectionsModalOpen} result={connectionsResult} onClose={() => setIsConnectionsModalOpen(false)} error={connectionsError} isLoading={isFindingConnections} />
            <JournalFinderModal isOpen={isJournalFinderOpen} onClose={() => setIsJournalFinderOpen(false)} paper={paperForJournalFinder} recommendations={journalRecommendations} isLoading={isFindingJournals} error={journalFinderError} />
            <OrganizationFinderModal isOpen={isOrgFinderOpen} onClose={() => setIsOrgFinderOpen(false)} onSelectOrganization={handleSelectOrganization} />
        </div>
    );
};

