                        <p><strong>{screeningStats.none}</strong> Unscreened</p>
                    </div>
                    <div className="flex items-center gap-3 pt-2">
                        <button
                            onClick={onAiRerank}
                            disabled={isReranking || screenedCount < 3}
                            className="h-9 px-4 text-sm font-semibold rounded-md bg-primary text-primary-foreground hover:bg-primary/90 disabled:opacity-50 flex items-center gap-2"
                        >
                            <SparklesIcon className="w-4 h-4" />
                            {isReranking ? 'Re-ranking...' : 'AI Re-rank Unscreened'}
                        </button>
                        {screenedCount < 3 && <p className="text-xs text-muted-foreground">Screen at least 3 papers to enable AI re-ranking.</p>}
                    </div>
                </div>
            )}
            <div className="space-y-3">
                {papers.map((paper) => (
                    <PaperCard
                        key={paper.id}
                        paper={paper}
                        isSelected={paper.id === selectedPaperId}
                        onSelect={() => onSelectPaper(paper)}
                        isScreeningMode={isScreeningMode}
                        onScreenPaper={onScreenPaper}
                    />
                ))}
            </div>

            {(isSearchingGrounded || isRefiningAI) && ( // Show message during any AI refinement
                 <div className="flex items-center justify-center gap-2 py-6 text-sm text-muted-foreground animate-pulse">
                     <SparklesIcon className="w-4 h-4 text-primary" />
                     <span>AI refining search results...</span>
                 </div>
            )}

            {hasMore && !isSearchingGrounded && !isRefiningAI && ( // Only show Load More if no AI refinement is ongoing
                <div className="flex justify-center pt-4">
                    <button
                        onClick={onLoadMore}
                        disabled={isLoadingMore}
                        className="h-10 px-6 font-semibold rounded-md bg-secondary text-secondary-foreground hover:bg-accent disabled:opacity-50"
                    >
                        {isLoadingMore ? 'Loading...' : 'Load More Results'}
                    </button>
                </div>
            )}
        </div>
    );
};

