// --- HELPER FUNCTIONS ---

const stopWords = new Set(['a', 'an', 'the', 'in', 'on', 'at', 'for', 'to', 'of', 'and', 'or', 'but', 'is', 'are', 'was', 'were', 'what', 'when', 'where', 'who', 'how', 'which', 'what', 'is', 'the', 'impact', 'of', 'on']);

const calculateTitleMatchScore = (queryWords: Set<string>, title: string): number => {
    if (!title || queryWords.size === 0) return 0;
    const titleLower = title.toLowerCase();
    let matchCount = 0;

    queryWords.forEach(word => {
        if (titleLower.includes(word)) {
            matchCount++;
        }
    });
    return (matchCount / queryWords.size) * 100;
};

export function mergePapers(allPapers: ResearchPaper[]): ResearchPaper[] {
    const paperGroups = new Map<string, ResearchPaper[]>();

    allPapers.forEach(paper => {
        const id = createPaperId(paper);
        if (!paperGroups.has(id)) {
            paperGroups.set(id, []);
        }
        paperGroups.get(id)!.push(paper);
    });

    const mergedPapers: ResearchPaper[] = [];

    paperGroups.forEach((papers, id) => {
        // Simple merge strategy: start with the first paper and fill in missing fields from others.
        const merged = papers.reduce((acc, current) => {
            return {
                ...acc,
                // Prioritize longer abstracts
                abstract: (current.abstract && current.abstract.length > (acc.abstract?.length || 0) && current.abstract !== 'No abstract available for this paper.') ? current.abstract : acc.abstract,
                // Prioritize available citations
                citations: current.citations ?? acc.citations,
                // Prioritize available PDF URLs
                pdfURL: current.pdfURL ?? acc.pdfURL,
                // Prioritize more specific source URLs
                sourceURL: current.sourceURL?.includes('doi.org') ? current.sourceURL : (acc.sourceURL || current.sourceURL),
                journal: current.journal ?? acc.journal,
                enrichmentSource: current.enrichmentSource ?? acc.enrichmentSource,
                // Prioritize known OA status
                isOpenAccess: current.isOpenAccess || acc.isOpenAccess,
                // Merge structured author list if available
                authorList: current.authorList && current.authorList.length > 0 ? current.authorList : acc.authorList
            };
        }, { ...papers[0], id });

        mergedPapers.push(merged);
    });

    return mergedPapers;
}

/**
 * Internal function to calculate full semantic scores.
 * This includes generating embeddings which can be slow.
 */
export async function calculatePaperScores( // Exported for use in App.tsx handleLoadMore
    papers: ResearchPaper[],
    query: string,
    hypotheticalAnswer: string,
    model: ModelDefinition,
    options: AdvancedSearchOptions // Added options for consistency, though not strictly used in current scoring
): Promise<ResearchPaper[]> {
    if (papers.length === 0) return [];

    // Semantic scoring
    const semanticallyRankedPapers = await embeddingService.calculateSemanticScores(hypotheticalAnswer, papers);
    let processedPapers = semanticallyRankedPapers;

    // --- Semantic Impact Score Calculation ---
    const papersWithAbstracts = processedPapers.filter(p => p.abstract && p.abstract.trim().length > 50);

    if (papersWithAbstracts.length > 1) {
        // We perform a mini-centrality analysis on the top results
        const abstracts = papersWithAbstracts.map(p => p.abstract);
        const allPaperEmbeddings = await batchEmbedText(abstracts);

        const embeddingMap = new Map<string, number[]>();
        papersWithAbstracts.forEach((paper, index) => {
            embeddingMap.set(paper.id, allPaperEmbeddings[index]);
        });

        const centralityScores = new Map<string, number>();
        papersWithAbstracts.forEach(paperA => {
            const embeddingA = embeddingMap.get(paperA.id);
            if (!embeddingA || embeddingA.length === 0) {
                centralityScores.set(paperA.id, 0); return;
            }
            let totalSimilarity = 0;
            let count = 0;
            papersWithAbstracts.forEach(paperB => {
                if (paperA.id === paperB.id) return;
                const embeddingB = embeddingMap.get(paperB.id);
                if (embeddingB && embeddingB.length > 0) {
                    totalSimilarity += cosineSimilarity(embeddingA, embeddingB);
                    count++;
                }
            });
            const avgSimilarity = count > 0 ? totalSimilarity / count : 0;
            centralityScores.set(paperA.id, ((avgSimilarity + 1) / 2) * 100);
        });

        const currentYear = new Date().getFullYear();
        const papersWithCitationsPerYear = papersWithAbstracts.map(paper => {
            const age = Math.max(1, currentYear - paper.year);
            const citationsPerYear = (paper.citations || 0) / age;
            return { id: paper.id, citationsPerYear };
        });
        const maxCitationsPerYear = Math.max(...papersWithCitationsPerYear.map(p => p.citationsPerYear), 1);

        processedPapers = processedPapers.map(paper => {
            const centrality = centralityScores.get(paper.id) || 0;
            const cpyData = papersWithCitationsPerYear.find(p => p.id === paper.id);
            const citationImpact = cpyData ? (cpyData.citationsPerYear / maxCitationsPerYear) * 100 : 0;

            const newImpactScore = (citationImpact * 0.6) + (centrality * 0.4);
            return { ...paper, newImpactScore };
        });
    } else {
        // Fallback for single result
        const currentYear = new Date().getFullYear();
        processedPapers = processedPapers.map(paper => {
            const age = Math.max(1, currentYear - currentYear); // Use currentYear for consistency
            const citationsPerYear = (paper.citations || 0) / (age > 0 ? age : 1);
            const impactScore = citationsPerYear > 0 ? 50 : 0; 
            return { ...paper, impactScore };
        });
    }

    const queryWords = query.toLowerCase().replace(/[^a-z0-9\s]/g, '').split(/\s+/).filter(word => word && !stopWords.has(word));
    const querySet = new Set(queryWords);

    const papersWithCombinedScore = processedPapers.map(paper => {
        const semanticScore = paper.semanticScore || 0;
        const impactScore = paper.impactScore || 0;
        const currentYear = new Date().getFullYear();
        const recencyScore = Math.max(0, 100 - ((currentYear - paper.year) * 5));
        const titleMatchScore = calculateTitleMatchScore(querySet, paper.title);

        const combinedScore = (semanticScore * 0.60) + (impactScore * 0.20) + (titleMatchScore * 0.15) + (recencyScore * 0.05);

        return { ...paper, combinedScore };
    });

    return papersWithCombinedScore.sort((a, b) => (b.combinedScore || 0) - (a.combinedScore || 0));
}

/**
 * Calculates fast, heuristic-based scores for instant feedback.
 * Does NOT use embeddings.
 */
const calculateBasicScores = (papers: ResearchPaper[], query: string): ResearchPaper[] => {
    const currentYear = new Date().getFullYear();
    // Tokenize query once
    const queryTokens = query.toLowerCase().replace(/[^a-z0-9\s]/g, '').split(/\s+/).filter(word => word && !stopWords.has(word));
    const querySet = new Set(queryTokens);

    return papers.map(paper => {
        const titleMatchScore = calculateTitleMatchScore(querySet, paper.title);
        const age = Math.max(1, currentYear - paper.year);
        const citationsPerYear = (paper.citations || 0) / age;
        // Heuristic: 50 cites/year is 'high impact' (100 score)
        const impactScore = Math.min(100, citationsPerYear * 2); 
        const recencyScore = Math.max(0, 100 - ((currentYear - paper.year) * 5));

        // Basic combined score: Heavily weight title match for initial results
        const combinedScore = (impactScore * 0.3) + (titleMatchScore * 0.5) + (recencyScore * 0.2);

        return { ...paper, impactScore, combinedScore, semanticScore: 0 }; 
    }).sort((a, b) => (b.combinedScore || 0) - (a.combinedScore || 0));
};

// --- API SERVICE IMPLEMENTATION ---

// Client-side caching
const SEARCH_CACHE_TTL = 1000 * 60 * 5; // 5 minutes
const GENERIC_CACHE_TTL = 1000 * 60 * 30; // 30 minutes

interface FullSearchResultCacheEntry {
    timestamp: number;
    data: {
        refinedPapers: ResearchPaper[]; // The set of papers from API search, now with semantic scores
        newSummary: string;
        newAnalysis: AnalysisResult | null;
        newGroundedPapers: ResearchPaper[];
        finalParsedFilters: Partial<AdvancedSearchOptions> & { core_search_query: string };
        finalHypotheticalAnswer: string;
    };
}

const fullSearchResultCache = new Map<string, FullSearchResultCacheEntry>();
const validationCache = new Map<string, { timestamp: number, data: { validation: ValidationResult, updatedPaperData: Partial<ResearchPaper> } }>();
const summaryCache = new Map<string, { timestamp: number, data: string }>();
const paperAnalysisCache = new Map<string, { timestamp: number, data: PaperAnalysis }>();
const connectedPapersCache = new Map<string, { timestamp: number, data: ConnectedPaper[] }>();
// New cache for query parsing to avoid repeated LLM calls for the same query string
const queryParsingCache = new Map<string, Promise<Partial<AdvancedSearchOptions> & { core_search_query: string }>>();
const hypotheticalAnswerCache = new Map<string, Promise<string>>();


/**
 * Performs a fast, API-only search to quickly display initial results.
 * This function does NOT involve LLM calls for parsing or hypothetical answers.
 * @param query The raw user query.
 * @param options Advanced search options.
 * @param sources Search sources (e.g., OpenAlex, arXiv).
 * @param page The page number.
 * @returns Initial papers with basic scores, and pagination info.
 */
export const searchFast = async (
    query: string,
    options: AdvancedSearchOptions,
    sources: SearchSourceInfo[],
    page: number = 1
): Promise<{ papers: ResearchPaper[], hasMore: boolean, rawQueryUsed: string }> => {

    // For fast search, we use the raw query directly for API calls.
    const retrievalQuery = query;
    const finalOptions: AdvancedSearchOptions = { ...options }; // Use provided options directly

    const searchPromises: Promise<ResearchPaper[]>[] = [];
    let openAlexHasMore = false; 

    // Add API-based searches
    if (sources.some(s => s.id === 'openalex')) {
        const promise = openalexService.searchOpenAlex(retrievalQuery, finalOptions, page).then(result => {
            openAlexHasMore = result.hasMore;
            return result.papers;
        });
        searchPromises.push(promise);
    }
    if (sources.some(s => s.id === 'arxiv')) {
        const promise = arxivService.searchArxiv(retrievalQuery, page).then(result => result.papers);
        searchPromises.push(promise);
    }

    const results = await Promise.allSettled(searchPromises);
    const allPapers = results
        .filter(r => r.status === 'fulfilled')
        .flatMap(r => (r as PromiseFulfilledResult<ResearchPaper[]>).value);

    let papers = mergePapers(allPapers);

    // Client-side text filtering (fast)
    if (finalOptions.titleKeywords) {
        const keywords = finalOptions.titleKeywords.split(',').map(k => k.trim().toLowerCase()).filter(Boolean);
        if (keywords.length > 0) papers = papers.filter(p => keywords.every(kw => p.title.toLowerCase().includes(kw)));
    }
    if (finalOptions.abstractKeywords) {
        const keywords = finalOptions.abstractKeywords.split(',').map(k => k.trim().toLowerCase()).filter(Boolean);
        if (keywords.length > 0) papers = papers.filter(p => keywords.every(kw => p.abstract.toLowerCase().includes(kw)));
    }

    const scoredPapers = calculateBasicScores(papers, retrievalQuery);

    return { papers: scoredPapers, hasMore: openAlexHasMore, rawQueryUsed: retrievalQuery };
};

/**
 * Runs all background AI analysis tasks after initial search results are displayed.
 * This includes LLM parsing, hypothetical answer generation, semantic scoring,
 * deep AI grounded search, and summary generation.
 * @param initialQuery The original user query.
 * @param initialOptions The original advanced search options.
 * @param initialPapers The papers obtained from the fast search.
 * @param model The AI model to use.
 * @param summaryLength Preferred summary length.
 * @param summaryStyle Preferred summary style.
 * @param sources Search sources (for potentially refined API calls).
 * @param setAiParsedFilters Callback to update AI-parsed filters in App.tsx state.
 * @param setAiHypotheticalAnswer Callback to update AI-hypothetical answer in App.tsx state.
 * @returns An object containing refined papers, new summary, analysis, and grounded papers.
 */
export const runBackgroundAIAnalysis = async (
    initialQuery: string,
    initialOptions: AdvancedSearchOptions,
    initialPapers: ResearchPaper[],
    model: ModelDefinition,
    summaryLength: SummaryLength,
    summaryStyle: SummaryStyle,
    sources: SearchSourceInfo[],
    setAiParsedFilters: (filters: Partial<AdvancedSearchOptions> & { core_search_query: string }) => void,
    setAiHypotheticalAnswer: (answer: string) => void,
): Promise<{
    refinedPapers: ResearchPaper[];
    newSummary: string;
    newAnalysis: AnalysisResult | null;
    newGroundedPapers: ResearchPaper[];
    finalParsedFilters: Partial<AdvancedSearchOptions> & { core_search_query: string };
    finalHypotheticalAnswer: string;
}> => {
    const fastModel: ModelDefinition = { ...model, id: 'gemini-2.5-flash' };

    // Generate a consistent cache key for the full AI analysis
    const cacheKey = JSON.stringify({
        query: initialQuery,
        options: initialOptions,
        modelId: model.id,
        summaryLength,
        summaryStyle,
        sources: sources.map(s => s.id).sort(),
    });

    // Check cache first
    const cachedEntry = fullSearchResultCache.get(cacheKey);
    if (cachedEntry && (Date.now() - cachedEntry.timestamp < SEARCH_CACHE_TTL)) {
        console.log("[API Service] Returning cached full AI analysis for key:", cacheKey);
        setAiParsedFilters(cachedEntry.data.finalParsedFilters);
        setAiHypotheticalAnswer(cachedEntry.data.finalHypotheticalAnswer);
        return cachedEntry.data;
    }

    // 1. Start AI tasks (Parsing and Hypothesis) in parallel
    if (!queryParsingCache.has(initialQuery)) {
        const parsePromise = geminiService.parseQueryToStructuredFilters(initialQuery, fastModel);
        queryParsingCache.set(initialQuery, parsePromise);
    }
    const parsedFiltersPromise = queryParsingCache.get(initialQuery)!;

    if (!hypotheticalAnswerCache.has(initialQuery)) {
        const hypoPromise = geminiService.generateHypotheticalAnswer(initialQuery, fastModel);
        hypotheticalAnswerCache.set(initialQuery, hypoPromise);
    }
    const hypotheticalAnswerPromise = hypotheticalAnswerCache.get(initialQuery)!;

    const [parsedFilters, hypotheticalAnswer] = await Promise.all([
        parsedFiltersPromise,
        hypotheticalAnswerPromise
    ]);

    setAiParsedFilters(parsedFilters);
    setAiHypotheticalAnswer(hypotheticalAnswer);

    // 2. Decide if a refined API search is needed
    // Compare parsedFilters with initialOptions to avoid unnecessary re-fetches
    let refinedPapers = initialPapers;
    let retrievalQuery = initialQuery; // Start with initialQuery

    const hasLLMRefinements = parsedFilters.core_search_query !== initialQuery ||
                              parsedFilters.authors !== initialOptions.authors ||
                              parsedFilters.startYear !== initialOptions.startYear ||
                              parsedFilters.endYear !== initialOptions.endYear ||
                              parsedFilters.journal !== initialOptions.journal ||
                              parsedFilters.excludeKeywords !== initialOptions.excludeKeywords;

    // Only re-fetch if LLM parsing provided substantially different filters AND user didn't provide them initially
    if (hasLLMRefinements) {
        console.log("[API Service] LLM parsing provided refinements, attempting a refined API search.");
        const refinedOptions: AdvancedSearchOptions = {
            ...initialOptions, // Keep user's explicit options
            ...parsedFilters, // Overlay AI-parsed values
            // Ensure year values are strings as expected by searchOpenAlex
            startYear: parsedFilters.startYear?.toString() || initialOptions.startYear,
            endYear: parsedFilters.endYear?.toString() || initialOptions.endYear,
            authors: parsedFilters.authors || initialOptions.authors,
            journal: parsedFilters.journal || initialOptions.journal,
            excludeKeywords: parsedFilters.excludeKeywords || initialOptions.excludeKeywords,
            doi: initialOptions.doi, // Preserve DOI if present
        };
        retrieralQuery = parsedFilters.core_search_query;
        try {
            const { papers: apiRefinedPapers } = await searchFast(retrievalQuery, refinedOptions, sources, 1);
            refinedPapers = apiRefinedPapers;
            console.log(`[API Service] Refined API search yielded ${refinedPapers.length} papers.`);
        } catch (e) {
            console.warn("[API Service] Refined API search failed, sticking with initial papers.", e);
        }
    } else {
        console.log("[API Service] LLM parsing did not provide significant new filters, skipping refined API search.");
    }

    // 3. Semantic Scoring for refined/initial papers
    const scoredRefinedPapers = await calculatePaperScores(refinedPapers, retrievalQuery, hypotheticalAnswer, model, initialOptions);

    // 4. Deep AI Grounded Search
    const newGroundedPapers = await searchGrounded(retrievalQuery, hypotheticalAnswer, model, parsedFilters);

    // 5. Generate Summary and Analysis using the comprehensive set of papers (scored, refined, and grounded)
    const allPapersForSummary = mergePapers([...scoredRefinedPapers, ...newGroundedPapers]);

    const newSummary = await generateSearchSummary(allPapersForSummary, summaryLength, summaryStyle, model);
    const newAnalysis = await analysisService.analyzePapers(allPapersForSummary);

    const result = { 
        refinedPapers: scoredRefinedPapers, // This is the set of papers from API search, now with semantic scores
        newSummary, 
        newAnalysis, 
        newGroundedPapers: newGroundedPapers, 
        finalParsedFilters: parsedFilters, 
        finalHypotheticalAnswer: hypotheticalAnswer 
    };

    // Store the result in cache
    fullSearchResultCache.set(cacheKey, { timestamp: Date.now(), data: result });

    return result;
};

/**
 * Secondary "Deep Search" using AI Grounding.
 */
export const searchGrounded = async (
    query: string,
    hypotheticalAnswer: string,
    model: ModelDefinition,
    parsedFilters: any 
): Promise<ResearchPaper[]> => {
    // OPTIMIZATION: Use Gemini Flash for faster search results.
    const fastModel: ModelDefinition = { ...model, id: 'gemini-2.5-flash' };

    try {
        const foundPapers = await geminiService.findPapersWithGoogleSearch(query, fastModel);

        const papers = foundPapers.map(p => {
            const paperData: Omit<ResearchPaper, 'id'> = {
                title: p.title,
                authors: p.authors,
                year: p.year,
                abstract: p.abstract,
                sourceURL: p.sourceURL,
                pdfURL: undefined,
                citations: undefined, 
            };
            return { ...paperData, id: createPaperId(paperData) };
        });

        const retrievalQuery = parsedFilters?.core_search_query || query;
        // We use the full scoring here because grounded results are few (max 10)
        return await calculatePaperScores(papers, retrievalQuery, hypotheticalAnswer, model, {} as any);

    } catch (err) {
        console.warn("AI Grounded search failed (non-critical):", err);
        return []; 
    }
};


