export const findConnectedPapers = async (paper: ResearchPaper, model: ModelDefinition): Promise<ConnectedPaper[]> => {
    const cacheKey = `${paper.id}-${model.id}`;
    const cached = connectedPapersCache.get(cacheKey);
    if (cached && (Date.now() - cached.timestamp < GENERIC_CACHE_TTL)) {
        return cached.data;
    }

    let result: ConnectedPaper[];
    if (!paper.doi) {
        result = await geminiService.findConnectedPapers(paper, model);
    } else {
        try {
            const { references, citations } = await semanticScholarService.getCitationGraph(paper.doi);
            result = [...citations, ...references];
        } catch (error) {
            console.error("Failed to get citation graph, falling back to AI search.", error);
            result = await geminiService.findConnectedPapers(paper, model);
        }
    }

    connectedPapersCache.set(cacheKey, { timestamp: Date.now(), data: result });
    return result;
};

