interface WorkspaceAnalysisDashboardProps {
    isOpen: boolean;
    onClose: () => void;
    workspacePapers: ResearchPaper[];
    analysisResult: AnalysisResult | null; // For bibliometrics, clusters
    synthesisResult: SynthesisResult | null; // For comparative summary
    gapAnalysisReport: string | null; // For research gap report
    isAnalysisLoading: boolean; // For bibliometrics, clusters
    isSynthesisLoading: boolean; // For comparative summary
    isGapAnalysisLoading: boolean; // For research gap report
}

// Helper for rendering sections within the dashboard
const DashboardSection: React.FC<{
    title: string;
    icon: React.ReactNode;
    isLoading: boolean;
    error?: string | null; // Not currently used but good for future extension
    children: React.ReactNode;
    isEmpty?: boolean;
    emptyMessage?: string;
}> = ({ title, icon, isLoading, error, children, isEmpty, emptyMessage = "No data available." }) => (
    <div className="bg-card p-4 rounded-lg border space-y-3">
        <h3 className="text-lg font-bold text-foreground flex items-center gap-2">
            {icon} {title}
        </h3>
        {isLoading ? (
            <div className="py-4">
                <LoadingSpinner message={`Loading ${title.toLowerCase()}...`} />
            </div>
        ) : error ? ( // Error handling, though currently logic is in App.tsx to avoid passing error directly here.
            <ErrorMessage message={error} />
        ) : isEmpty ? (
            <p className="text-muted-foreground italic text-center py-4">{emptyMessage}</p>
        ) : (
            children
        )}
    </div>
);


export const WorkspaceAnalysisDashboard: React.FC<WorkspaceAnalysisDashboardProps> = ({
    isOpen,
    onClose,
    workspacePapers,
    analysisResult,
    synthesisResult,
    gapAnalysisReport,
    isAnalysisLoading,
    isSynthesisLoading,
    isGapAnalysisLoading,
}) => {
    const totalPapers = workspacePapers.length;

    if (!isOpen) {
        return null;
    }

    // Combine all loading states for the main spinner at the top
    const overallLoading = isAnalysisLoading || isSynthesisLoading || isGapAnalysisLoading;

    return (
        <div
            className="fixed inset-0 z-50 overflow-hidden"
            aria-labelledby="workspace-analysis-title"
            role="dialog"
            aria-modal="true"
        >
            {/* Backdrop */}
            <div
                className="absolute inset-0 bg-background/80 backdrop-blur-sm transition-opacity"
                aria-hidden="true"
                onClick={onClose}
            ></div>

            {/* Drawer Panel */}
            <div
                className="fixed inset-y-0 right-0 w-full md:w-3/4 lg:w-2/3 xl:w-1/2 bg-card shadow-2xl flex flex-col transform transition-transform duration-300 ease-in-out"
                style={{ transform: isOpen ? 'translateX(0%)' : 'translateX(100%)' }}
                onClick={(e) => e.stopPropagation()} // Prevent closing when clicking inside
            >
                <header className="flex items-center justify-between p-4 border-b border-border flex-shrink-0">
                    <div className="flex items-center gap-3">
                        <AnalyzeIcon className="w-7 h-7 text-primary" />
                        <div>
                            <h2 id="workspace-analysis-title" className="text-xl font-bold text-foreground">
                                Workspace Analysis Dashboard
                            </h2>
                            <p className="text-sm text-muted-foreground">Insights from {totalPapers} paper(s) in your workspace.</p>
                        </div>
                    </div>
                    <button
                        onClick={onClose}
                        className="p-2 text-muted-foreground hover:bg-accent rounded-full focus:outline-none focus:ring-2 focus:ring-ring"
                        aria-label="Close"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                        </svg>
                    </button>
                </header>

                <main className="flex-grow overflow-y-auto p-6 space-y-6">
                    {overallLoading && (
                        <LoadingSpinner message="Generating comprehensive insights..." />
                    )}

                    {/* Synthesis Summary */}
                    <DashboardSection
                        title="Comparative Synthesis"
                        icon={<SynthesisIcon className="w-5 h-5 text-teal-600" />}
                        isLoading={isSynthesisLoading}
                        isEmpty={!synthesisResult || synthesisResult.length === 0}
                        emptyMessage="Not enough papers (min 2) or no synthesis generated."
                    >
                        {synthesisResult && synthesisResult.length > 0 && (
                            <div className="overflow-x-auto border rounded-lg">
                                <table className="min-w-full divide-y divide-border">
                                    <thead className="bg-muted/50">
                                        <tr>
                                            <th scope="col" className="px-4 py-2 text-left text-xs font-medium text-muted-foreground uppercase tracking-wider w-1/4">Paper Title</th>
                                            <th scope="col" className="px-4 py-2 text-left text-xs font-medium text-muted-foreground uppercase tracking-wider w-1/4">Main Finding</th>
                                            <th scope="col" className="px-4 py-2 text-left text-xs font-medium text-muted-foreground uppercase tracking-wider w-1/4">Methodology</th>
                                            <th scope="col" className="px-4 py-2 text-left text-xs font-medium text-muted-foreground uppercase tracking-wider w-1/4">Context / Sample</th>
                                        </tr>
                                    </thead>
                                    <tbody className="bg-card divide-y divide-border">
                                        {synthesisResult.map((paper, index) => (
                                            <tr key={index}>
                                                <td className="px-4 py-3 whitespace-normal text-sm font-medium text-foreground">{paper.title}</td>
                                                <td className="px-4 py-3 whitespace-normal text-sm text-muted-foreground">{paper.mainFinding}</td>
                                                <td className="px-4 py-3 whitespace-normal text-sm text-muted-foreground">{paper.methodology}</td>
                                                <td className="px-4 py-3 whitespace-normal text-sm text-muted-foreground">{paper.context}</td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        )}
                    </DashboardSection>

                    {/* Gap Analysis Report */}
                    <DashboardSection
                        title="Research Gap Analysis"
                        icon={<ReportIcon className="w-5 h-5 text-red-600" />}
                        isLoading={isGapAnalysisLoading}
                        isEmpty={!gapAnalysisReport}
                        emptyMessage="Not enough papers (min 2) or no gap analysis generated."
                    >
                        {gapAnalysisReport && (
                            <div className="prose prose-slate max-w-none text-foreground prose-p:text-muted-foreground prose-h3:text-foreground prose-li:text-muted-foreground">
                                <FormattedReport text={gapAnalysisReport} />
                            </div>
                        )}
                    </DashboardSection>

                    {/* Bibliometric and Thematic Insights */}
                    <DashboardSection
                        title="Bibliometric & Thematic Insights"
                        icon={<AnalyzeIcon className="w-5 h-5 text-purple-600" />}
                        isLoading={isAnalysisLoading}
                        isEmpty={!analysisResult || (analysisResult.clusters.length === 0 && analysisResult.publicationYears.length === 0 && analysisResult.topAuthors.length === 0)}
                        emptyMessage="No bibliometric or thematic insights generated for this selection."
                    >
                        {analysisResult && (
                            <div className="space-y-6">
                                {analysisResult.clusters.length > 0 && (
                                    <div>
                                        <h4 className="font-semibold text-foreground mb-3">Thematic Clusters</h4>
                                        <div className="space-y-3">
                                            {analysisResult.clusters.map(cluster => (
                                                <div key={cluster.clusterName} className="bg-muted/50 border border-border p-3 rounded-lg">
                                                    <h5 className="font-bold text-primary text-sm">{cluster.clusterName}</h5>
                                                    <p className="text-xs text-muted-foreground mt-1 mb-2">{cluster.description}</p>
                                                    {cluster.keywords && cluster.keywords.length > 0 && (
                                                        <div className="flex flex-wrap gap-1.5">
                                                            {cluster.keywords.map(keyword => (
                                                                <span key={keyword} className="px-2 py-0.5 bg-primary/10 text-primary text-xs font-medium rounded-full">
                                                                    {keyword}
                                                                </span>
                                                            ))}
                                                        </div>
                                                    )}
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                )}

                                {analysisResult.publicationYears.length > 0 && (
                                    <PublicationYearChart data={analysisResult.publicationYears} />
                                )}
                                {analysisResult.topAuthors.length > 0 && (
                                    <TopAuthorsChart data={analysisResult.topAuthors} />
                                )}
                            </div>
                        )}
                    </DashboardSection>
                </main>

                <footer className="flex-shrink-0 p-4 border-t border-border flex justify-end gap-2 bg-muted/50">
                    <button
                        onClick={onClose}
                        className="h-9 px-4 text-sm font-semibold rounded-md bg-secondary text-secondary-foreground hover:bg-accent"
                    >
                        Close Dashboard
                    </button>
                    {/* Optional: Add an export all data button */}
                    {/* <button
                        onClick={() => {}}
                        className="h-9 px-4 text-sm font-semibold rounded-md bg-primary text-primary-foreground hover:bg-primary/90 flex items-center gap-2"
                    >
                        <ExportIcon className="w-4 h-4" /> Export All Data
                    </button> */}
                </footer>
            </div>
        </div>
    );
};

