export const PaperDetails: React.FC<PaperDetailsProps> = (props) => {
    const { paper, isInWorkspace, onToggleWorkspacePaper, onConceptClick, onFindDoi, logAnalyticsEvent, model } = props;
    const { onFindConnectedPapers, isFindingConnected, onAnalyzePaper, isAnalyzingPaper, onVerifyPaper, onGenerateSuggestions, isGeneratingSuggestions, onCitePaper, onFindJournals, isFindingJournals, onAuthorClick, onFindSimilar, isFindingSimilar } = props;
    const [activeTab, setActiveTab] = useState<'overview' | 'chat' | 'connections' | 'analysis' | 'graph' | 'metadata'>('overview');

    const [abstractContent, setAbstractContent] = useState<{ id: string; text: string } | null>(null);
    const [isAbstractLoading, setIsAbstractLoading] = useState(false);

    const [connectedPapers, setConnectedPapers] = useState<ConnectedPaper[] | null>(null);
    const [isLoadingConnections, setIsLoadingConnections] = useState(false);

    useEffect(() => {
        if (activeTab === 'overview') {
             // Check if we already have data for this paper
             if (abstractContent?.id === paper.id) return;

             setIsAbstractLoading(true);

             const load = async () => {
                 let text = paper.abstract;
                 const isPlaceholder = !text || text.length < 50 || text === 'No abstract available for this paper.';

                 // Lazy fetch: If abstract is missing or short, and we have a DOI, try to get full text from OpenAlex
                 if (isPlaceholder && paper.doi) {
                     try {
                         const fetched = await apiService.fetchMetadataByDOI(paper.doi);
                         if (fetched && fetched.abstract && fetched.abstract.length > 50) {
                             text = fetched.abstract;
                         }
                     } catch(e) {
                         console.warn("Could not fetch enriched abstract:", e);
                     }
                 }

                 setAbstractContent({ id: paper.id, text: text || 'No abstract available.' });
                 setIsAbstractLoading(false);
             };
             load();
        }
    }, [activeTab, paper.id, paper.doi, paper.abstract, abstractContent]);

    // Fetch connections when the tab is activated
    useEffect(() => {
        if (activeTab === 'connections' && !connectedPapers && !isLoadingConnections) {
            setIsLoadingConnections(true);
            apiService.findConnectedPapers(paper, model)
                .then(setConnectedPapers)
                .catch(err => {
                    console.error("Failed to load connections inline:", err);
                    // Optionally set an error state here
                })
                .finally(() => setIsLoadingConnections(false));
        }
        // If paper changes, reset
        if (paper.id !== connectedPapers?.[0]?.title /* hacky check, better to use ref or just rely on array being null on paper change */) {
             // Actually we should reset connectedPapers when paper prop changes.
             // Handled by the key on parent or manual reset.
        }
    }, [activeTab, paper, model]);

    // Reset local state when selected paper changes
    useEffect(() => {
        setConnectedPapers(null);
        setAbstractContent(null);
        setActiveTab('overview');
    }, [paper.id]);


    const googleScholarSearchUrl = `https://scholar.google.com/scholar?hl=en&as_sdt=0,34&q=${encodeURIComponent(`"${paper.title}"`)}`;

    const handleShare = async () => {
        if (!navigator.share) return;
        try {
            await navigator.share({
                title: paper.title,
                text: `Check out this research paper: "${paper.title}"`,
                url: paper.sourceURL || window.location.href,
            });
            logAnalyticsEvent('paper_shared', { title: paper.title });
        } catch (error) {
            console.error('Error sharing paper:', error);
        }
    };

    const renderKeyConcepts = () => {
        if (!paper.keyConceptsState || paper.keyConceptsState === 'idle') {
            if (paper.abstract.length < 150) return null; // Only show spinner if abstract is substantial enough for extraction
            return (
                <div className="py-2">
                    <LoadingSpinner message="Extracting concepts..." />
                </div>
            );
        }

        if (paper.keyConceptsState === 'loading') {
            return (
                <div className="py-2">
                    <LoadingSpinner message="Extracting concepts..." />
                </div>
            );
        }

        if (paper.keyConceptsState === 'error') {
            return <p className="text-sm text-destructive">Could not extract concepts.</p>;
        }

        if (paper.keyConceptsState === 'loaded' && paper.keyConcepts && paper.keyConcepts.length > 0) {
            return (
                <div className="flex flex-wrap gap-2">
                    {paper.keyConcepts.map((concept) => (
                        <button
                            key={concept}
                            onClick={() => onConceptClick(concept)}
                            className="group flex items-center gap-1.5 px-2.5 py-1 bg-secondary text-secondary-foreground text-xs font-medium rounded-full hover:bg-primary/10 hover:text-primary transition-colors"
                            title={`Search for "${concept}"`}
                        >
                            <span>{concept}</span>
                            <SearchIcon className="w-3 h-3 opacity-0 group-hover:opacity-100 transition-opacity" />
                        </button>
                    ))}
                </div>
            );
        }

        return <p className="text-sm text-muted-foreground italic">No distinct concepts identified.</p>;
    }

    const renderConnections = () => {
        if (isLoadingConnections) {
            return (
                <div className="py-8">
                    <LoadingSpinner message="Mapping citation network via Semantic Scholar..." />
                </div>
            );
        }

        if (!connectedPapers || connectedPapers.length === 0) {
            return (
                <div className="text-center py-12 text-muted-foreground bg-muted/30 rounded-lg border border-dashed border-border">
                    <NetworkIcon className="w-8 h-8 mx-auto mb-2 opacity-50" />
                    <p>No connected papers found.</p>
                </div>
            );
        }

        const citedBy = connectedPapers.filter(p => p.connection === 'Cited by this paper');
        const references = connectedPapers.filter(p => p.connection === 'This paper cites');
        const others = connectedPapers.filter(p => p.connection !== 'Cited by this paper' && p.connection !== 'This paper cites');

        return (
            <div className="space-y-4">
                {citedBy.length > 0 && (
                    <CollapsibleSection title="Cited By" count={citedBy.length} defaultOpen={true}>
                        <div className="space-y-2">
                            {citedBy.map((p, i) => <ConnectionItem key={i} paper={p} />)}
                        </div>
                    </CollapsibleSection>
                )}
                {references.length > 0 && (
                    <CollapsibleSection title="References" count={references.length}>
                        <div className="space-y-2">
                            {references.map((p, i) => <ConnectionItem key={i} paper={p} />)}
                        </div>
                    </CollapsibleSection>
                )}
                {others.length > 0 && (
                    <CollapsibleSection title="Related Papers" count={others.length}>
                        <div className="space-y-2">
                            {others.map((p, i) => <ConnectionItem key={i} paper={p} />)}
                        </div>
                    </CollapsibleSection>
                )}
            </div>
        );
    };

    return (
        <div className="flex flex-col h-full space-y-4">
             <div>
                <div className="flex justify-between items-start gap-4">
                    <h3 className="text-lg font-bold text-foreground flex-grow pr-2">{paper.title}</h3>
                    <div className="flex-shrink-0 flex items-center gap-2">
                        <button 
                            onClick={() => onCitePaper(paper)}
                            className="flex items-center gap-2 h-9 px-3 rounded-md text-sm font-semibold bg-secondary text-secondary-foreground hover:bg-accent transition-colors border border-transparent hover:border-border"
                            title="Generate Citation"
                        >
                            <CitationIcon className="w-4 h-4" />
                            <span className="hidden sm:inline">Cite</span>
                        </button>
                        <button 
                            onClick={() => onToggleWorkspacePaper(paper)} 
                            aria-label={isInWorkspace ? "Remove from Workspace" : "Add to Workspace"} 
                            className={`flex items-center gap-2 h-9 px-4 rounded-md text-sm font-semibold transition-colors ${
                                isInWorkspace 
                                ? 'bg-green-100 text-green-800 hover:bg-green-200' 
                                : 'bg-secondary text-secondary-foreground hover:bg-accent'
                            }`}
                        >
                            {isInWorkspace ? <CheckIcon className="w-4 h-4" /> : <AddIcon className="w-4 h-4" />}
                            <span>{isInWorkspace ? 'Saved' : 'Save'}</span>
                        </button>
                    </div>
                </div>
            </div>

            <div className="border-b border-border overflow-x-auto">
                <nav className="-mb-px flex space-x-6" aria-label="Tabs">
                    <TabButton isActive={activeTab === 'overview'} onClick={() => setActiveTab('overview')}>Overview</TabButton>
                    <TabButton isActive={activeTab === 'connections'} onClick={() => setActiveTab('connections')}>Connections</TabButton>
                    <TabButton isActive={activeTab === 'graph'} onClick={() => setActiveTab('graph')}>Graph</TabButton>
                    <TabButton isActive={activeTab === 'chat'} onClick={() => setActiveTab('chat')}>Chat</TabButton>
                    <TabButton isActive={activeTab === 'analysis'} onClick={() => setActiveTab('analysis')}>Tools</TabButton>
                    <TabButton isActive={activeTab === 'metadata'} onClick={() => setActiveTab('metadata')}>Metadata</TabButton>
                </nav>
            </div>

            <div className="pt-2">
                {activeTab === 'overview' && (
                    <div className="space-y-4 animate-fade-in">
                        <div>
                            <h4 className="font-semibold text-foreground">Abstract</h4>
                            {isAbstractLoading ? (
                                <div className="py-4">
                                    <LoadingSpinner message="Loading abstract..." />
                                </div>
                            ) : (
                                <p className="mt-1 text-sm text-muted-foreground leading-relaxed">
                                    {abstractContent?.text || paper.abstract}
                                </p>
                            )}
                        </div>
                         <div>
                            <h4 className="font-semibold text-foreground mb-2 flex items-center gap-2">
                                <TagIcon className="w-4 h-4 text-muted-foreground" />
                                Key Concepts
                            </h4>
                            {renderKeyConcepts()}
                        </div>
                    </div>
                )}

                {activeTab === 'connections' && (
                    <div className="animate-fade-in">
                        <div className="mb-4">
                            <h4 className="font-semibold text-foreground flex items-center gap-2">
                                <NetworkIcon className="w-5 h-5 text-primary" />
                                Citation Network
                            </h4>
                            <p className="text-xs text-muted-foreground">Exploring references and citations via Semantic Scholar.</p>
                        </div>
                        {renderConnections()}
                    </div>
                )}

                {activeTab === 'chat' && (
                    <div className="animate-fade-in">
                        <div className="mb-3">
                            <h4 className="font-semibold text-foreground flex items-center gap-2">
                                <ChatIcon className="w-5 h-5 text-primary" />
                                Chat with this Paper
                            </h4>
                            <p className="text-xs text-muted-foreground">Ask questions specifically about "{paper.title}".</p>
                        </div>
                        <PaperChat paper={paper} />
                    </div>
                )}

                {activeTab === 'graph' && (
                    <div className="animate-fade-in">
                        <KnowledgeGraphDisplay 
                            graph={paper.knowledgeGraph}
                            state={paper.knowledgeGraphState}
                        />
                    </div>
                )}

                {activeTab === 'analysis' && (
                     <div className="space-y-6 animate-fade-in">
                        {paper.savedAnalysis && <SavedAnalysis analysis={paper.savedAnalysis} />}
                        <div className="space-y-3">
                             <h3 className="text-base font-bold text-foreground pt-2">Refinement Tools</h3>
                             <ToolCard
                                 icon={<SearchIcon className="w-5 h-5" />}
                                 title="Find Similar Papers (Pivot Search)"
                                 description="Run a new semantic search based on the content of this abstract."
                                 actionText="Find Similar"
                                 onAction={() => onFindSimilar(paper)}
                                 isLoading={isFindingSimilar}
                             />
                             <ToolCard
                                 icon={<NetworkIcon className="w-5 h-5" />}
                                 title="Find Connected Papers"
                                 description="Discover prior work, derivative research, and contrasting studies."
                                 actionText="Find Connections"
                                 onAction={() => onFindConnectedPapers(paper)}
                                 isLoading={isFindingConnected}
                             />
                             <ToolCard
                                 icon={<AnalyzeIcon className="w-5 h-5" />}
                                 title="Structured Analysis"
                                 description="Extract research question, methodology, key findings, and limitations."
                                 actionText="Analyze Paper"
                                 onAction={() => onAnalyzePaper(paper)}
                                 isLoading={isAnalyzingPaper}
                             />
                              <ToolCard
                                 icon={<ShieldCheckIcon className="w-5 h-5" />}
                                 title="Advanced Verification (VACS)"
                                 description="Verify a claim using the paper's text, citations, and metadata."
                                 actionText="Verify Claim"
                                 onAction={() => onVerifyPaper(paper)}
                                 disabled={!paper.doi}
                             />
                             <ToolCard
                                 icon={<LightbulbIcon className="w-5 h-5" />}
                                 title="Generate Search Ideas"
                                 description="Get AI-powered suggestions for new search queries based on this paper."
                                 actionText="Generate Ideas"
                                 onAction={() => onGenerateSuggestions(paper)}
                                 isLoading={isGeneratingSuggestions}
                             />
                             <ToolCard
                                icon={<CitationIcon className="w-5 h-5" />}
                                title="Generate Citation"
                                description="Create a formatted citation in various styles (APA, MLA, etc.)."
                                actionText="Cite Paper"
                                onAction={() => onCitePaper(paper)}
                            />
                            <ToolCard
                                icon={<JournalIcon className="w-5 h-5" />}
                                title="Find Journals"
                                description="Suggest suitable publication venues based on the abstract."
                                actionText="Suggest Journals"
                                onAction={() => props.onFindJournals(paper)}
                                isLoading={props.isFindingJournals}
                            />
                        </div>
                    </div>
                )}

                {activeTab === 'metadata' && (
                     <div className="space-y-6 animate-fade-in">
                        {paper.validation && <ValidationScoreDisplay validation={paper.validation} />}

                        <div className="space-y-3">
                             <div className="flex justify-between items-start">
                                <div>
                                    <h4 className="font-semibold text-foreground text-sm">Authors</h4>
                                    <AuthorList authors={paper.authors} authorList={paper.authorList} onAuthorClick={onAuthorClick} />
                                </div>
                                <div className="text-right">
                                    <h4 className="font-semibold text-foreground text-sm">Year</h4>
                                    <p className="text-sm text-muted-foreground">{paper.year}</p>
                                </div>
                            </div>
                             <div>
                                <h4 className="font-semibold text-foreground text-sm">Journal</h4>
                                <p className="text-sm text-muted-foreground">{paper.journal || 'N/A'}</p>
                            </div>
                            {paper.citations !== undefined && (
                                <div>
                                    <h4 className="font-semibold text-foreground text-sm">Citations</h4>
                                    <p className="text-sm text-muted-foreground">{paper.citations.toLocaleString()}</p>
                                </div>
                            )}
                        </div>

                        <div className="pt-3 border-t border-border flex flex-wrap items-center justify-between gap-x-4 gap-y-2">
                            <div className="flex items-center gap-4">
                                <a href={googleScholarSearchUrl} target="_blank" rel="noopener noreferrer" className="flex items-center gap-1.5 text-sm font-medium text-primary hover:underline">
                                    <ScholarIcon className="w-4 h-4" /> Google Scholar
                                </a>
                                {(paper.pdfURL || paper.openAccessPdfUrl) && (
                                    <a href={paper.pdfURL || paper.openAccessPdfUrl} target="_blank" rel="noopener noreferrer" className="flex items-center gap-1.5 text-sm font-medium text-primary hover:underline">
                                        <PdfIcon className="w-4 h-4" /> PDF
                                    </a>
                                )}
                                {paper.openAccessState === 'loading' && (
                                    <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
                                        <svg className="animate-spin h-3 w-3" viewBox="0 0 24 24">
                                            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" fill="none"/>
                                            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"/>
                                        </svg>
                                        Checking PDF...
                                    </div>
                                )}
                                <DoiDisplay paper={paper} onFindDoi={() => onFindDoi(paper)} />
                            </div>
                            <button
                                onClick={handleShare}
                                className="flex items-center gap-1.5 text-sm font-medium text-muted-foreground hover:text-foreground hover:underline"
                            >
                                <ShareIcon className="w-4 h-4" /> Share
                            </button>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

import React from 'react';
import type { AnalysisResult } from '../types';
import { PublicationYearChart } from './PublicationYearChart';
import { TopAuthorsChart } from './TopAuthorsChart';
import { FormattedSummary } from './FormattedSummary';
import { SparklesIcon } from './icons/SparklesIcon';

interface SearchResultsAnalysisProps {
  analysis: AnalysisResult | null;
  summary: string;
  isSummaryLoading: boolean;
}

export const SearchResultsAnalysis: React.FC<SearchResultsAnalysisProps> = ({ analysis, summary, isSummaryLoading }) => {
  return (
    <div className="space-y-6">
        {isSummaryLoading ? (
            <div className="bg-accent/50 border-l-4 border-primary/50 p-4 rounded-r-lg shadow-sm animate-pulse">
                 <div className="flex items-center gap-2 mb-2">
                     <div className="w-6 h-6 bg-primary/20 rounded-full"></div>
                     <div className="h-5 bg-primary/20 rounded w-1/3"></div>
                 </div>
                 <div className="space-y-2">
                     <div className="h-4 bg-primary/10 rounded w-full"></div>
                     <div className="h-4 bg-primary/10 rounded w-5/6"></div>
                     <div className="h-4 bg-primary/10 rounded w-4/6"></div>
                 </div>
            </div>
        ) : summary && (
            <div className="bg-accent/50 border-l-4 border-primary p-4 rounded-r-lg shadow-sm">
                <h3 className="text-lg font-semibold text-foreground mb-2 flex items-center gap-2">
                    <SparklesIcon className="w-6 h-6 text-primary" />
                    AI-Generated Search Overview
                </h3>
                <FormattedSummary text={summary} />
            </div>
        )}

        {analysis && (
            <>
                {analysis.clusters.length > 0 && <div>
                    <h3 className="text-lg font-semibold text-foreground mb-3">Thematic Clusters</h3>
                    <div className="space-y-3">
                        {analysis.clusters.map(cluster => (
                            <div key={cluster.clusterName} className="bg-muted/50 border border-border p-3 rounded-lg">
                                <h4 className="font-bold text-primary text-sm">{cluster.clusterName}</h4>
                                <p className="text-xs text-muted-foreground mt-1 mb-2">{cluster.description}</p>
                                {cluster.keywords && cluster.keywords.length > 0 && (
                                    <div className="flex flex-wrap gap-1.5">
                                        {cluster.keywords.map(keyword => (
                                            <span key={keyword} className="px-2 py-0.5 bg-primary/10 text-primary text-xs font-medium rounded-full">
                                                {keyword}
                                            </span>
                                        ))}
                                    </div>
                                )}
                            </div>
                        ))}
                    </div>
                </div>}

                {(analysis.publicationYears.length > 0 || analysis.topAuthors.length > 0) &&
                    <div className="space-y-6 pt-4">
                        <h3 className="text-xl font-bold text-foreground border-b border-border pb-2">Bibliometric Insights</h3>
