const safeJsonParse = (jsonString: string) => {
  if (!jsonString || !jsonString.trim()) return null;
  try {
    const cleanedString = jsonString.replace(/```json/g, '').replace(/```/g, '').trim();
    return JSON.parse(cleanedString);
  } catch (e) {
    console.error("Failed to parse JSON:", e);
    console.error("Original string:", jsonString);
    return null;
  }
};

// Helper for exponential backoff
const retryWithBackoff = async <T>(operation: () => Promise<T>, retries: number = 3, delay: number = 2000): Promise<T> => {
    try {
        return await operation();
    } catch (error: any) {
        // Check for 429 (Resource Exhausted) or 503 (Service Unavailable)
        // The error object structure can vary, so we check status, code, and message.
        const isRateLimit = error?.status === 429 || error?.code === 429 || error?.message?.includes('429') || error?.message?.includes('RESOURCE_EXHAUSTED');
        const isServerOverload = error?.status === 503 || error?.code === 503;

        if (retries > 0 && (isRateLimit || isServerOverload)) {
            console.warn(`[Gemini API] Rate limit or server overload hit. Retrying in ${delay}ms... (Retries left: ${retries})`);
            await new Promise(resolve => setTimeout(resolve, delay));
            return retryWithBackoff(operation, retries - 1, delay * 2);
        }
        throw error;
    }
};

