import type { ResearchPaper, AdvancedSearchOptions, AuthorProfile } from '../types';
import { createPaperId } from './extensionService';

// Client-side cache for OpenAlex search results
interface CacheEntry {
    result: {
        papers: ResearchPaper[];
        hasMore: boolean;
    };
    timestamp: number;
}
const openAlexCache = new Map<string, CacheEntry>();

// Client-side cache for individual OpenAlex papers (by DOI)
interface SinglePaperCacheEntry {
    result: ResearchPaper | null;
    timestamp: number;
}
const singlePaperCache = new Map<string, SinglePaperCacheEntry>();

const CACHE_TTL_MS = 5 * 60 * 1000; // 5 minutes

/**
 * Reconstructs a readable abstract string from OpenAlex's inverted index format.
 * @param invertedAbstract - The inverted index object from the OpenAlex API.
 * @returns A string representing the paper's abstract.
 */
function deinvertAbstract(invertedAbstract: { [key: string]: number[] }): string {
    if (!invertedAbstract) return '';

    const abstractArray: string[] = [];
    let maxIndex = -1;

    // First, determine the size of the array needed
    for (const word in invertedAbstract) {
        for (const pos of invertedAbstract[word]) {
            if (pos > maxIndex) {
                maxIndex = pos;
            }
        }
    }

    // Initialize the array with empty strings
    if(maxIndex > -1){
        abstractArray.length = maxIndex + 1;
        abstractArray.fill('');
    }

    // Populate the array with words at their correct positions
    for (const word in invertedAbstract) {
        for (const pos of invertedAbstract[word]) {
            abstractArray[pos] = word;
        }
    }
    return abstractArray.join(' ').trim();
}


const mapOpenAlexWorkToResearchPaper = (work: any): ResearchPaper | null => {
    const abstract = work.abstract_inverted_index 
        ? deinvertAbstract(work.abstract_inverted_index) 
        : 'No abstract available for this paper.';

    // Filter out papers with no abstract for better summary quality
    if (!abstract || abstract.length < 50) {
        return null;
    }

    const authorList: AuthorProfile[] = (work.authorships || []).map((a: any) => ({
        id: a.author?.id?.replace('https://openalex.org/', '') || undefined,
        name: a.author?.display_name || 'Unknown Author',
        orcid: a.author?.orcid?.replace('https://orcid.org/', '') || undefined
    }));

    const doi = work.doi ? work.doi.replace('https://doi.org/', '') : undefined;

    // Updated journal mapping from primary_location.source.display_name instead of host_venue
    const journal = work.primary_location?.source?.display_name || undefined;

    const paperData: Omit<ResearchPaper, 'id'> = {
        title: work.title || work.display_name,
        authors: authorList.map(a => a.name).join(', '),
        authorList,
        year: work.publication_year,
        abstract,
        sourceURL: work.doi ? `https://doi.org/${work.doi.replace('https://doi.org/', '')}` : work.id,
        pdfURL: work.primary_location?.pdf_url || undefined,
        citations: work.cited_by_count,
        doi,
        journal,
        isOpenAccess: work.open_access?.is_oa || false, // Map OA status directly
        isInDoaj: work.primary_location?.source?.is_in_doaj || false, // Map DOAJ status directly
    };

    return {
        ...paperData,
        id: createPaperId(paperData),
    };
};

/**
 * Searches the OpenAlex database for research papers.
 * @param query - The user's search query string.
 * @param options - Advanced search options including year range and authors.
 * @returns A promise that resolves to an object containing an array of ResearchPaper objects and a boolean indicating if more results are available.
 */
export const searchOpenAlex = async (query: string, options: AdvancedSearchOptions, page: number = 1): Promise<{ papers: ResearchPaper[], hasMore: boolean }> => {
    // 1. Create a consistent cache key
    const cacheKey = JSON.stringify({ query, ...options, page });

    // 2. Check the cache
    const cachedEntry = openAlexCache.get(cacheKey);
    if (cachedEntry && (Date.now() - cachedEntry.timestamp < CACHE_TTL_MS)) {
        console.log("Serving from OpenAlex cache:", cacheKey);
        return cachedEntry.result;
    }

    const PER_PAGE = 15;
    const BASE_URL = 'https://api.openalex.org/works';
    const params = new URLSearchParams({
        search: query,
        'per-page': PER_PAGE.toString(),
        'page': page.toString(),
        // Optimize response size by selecting only necessary fields
        // Removed 'host_venue' as it is no longer valid.
        'select': 'id,doi,title,display_name,publication_year,abstract_inverted_index,authorships,cited_by_count,primary_location,open_access,type',
        // Use a more specific, yet still example, email for the polite pool.
        mailto: 'contact@ai-research-explorer.com'
    });

    // Build the filter string for the OpenAlex API
    const filters: string[] = [];
    if (options.startYear || options.endYear) {
        const start = options.startYear || '';
        const end = options.endYear || '';
        // Only add the filter if at least one year is specified.
        // OpenAlex API supports open-ended ranges like "2020-" or "-2020".
        if (start || end) {
            filters.push(`publication_year:${start}-${end}`);
        }
    }

    // Prefer Author ID if available for precise disambiguation
    if (options.authorId) {
        filters.push(`authorships.author.id:${options.authorId}`);
    } else if (options.authors) {
        // Use the .search field to find authors by name
        filters.push(`authorships.author.display_name.search:${options.authors}`);
    }

    // Institution filtering (ROR)
    if (options.institutionId) {
        filters.push(`authorships.institutions.ror:${options.institutionId}`);
    } else if (options.institutionName) {
        // Fallback to text search if ID isn't present (less precise)
        filters.push(`authorships.institutions.display_name.search:${options.institutionName}`);
    }

    if (options.journal) {
        // Use primary_location.source.display_name instead of host_venue.display_name
        filters.push(`primary_location.source.display_name.search:${options.journal}`);
    }
    if (options.minCitations && parseInt(options.minCitations, 10) > 0) {
        filters.push(`cited_by_count:>${parseInt(options.minCitations, 10)}`);
    }

    // Apply Open Access filter directly in API call if requested
    if (options.isOpenAccess) {
        filters.push(`open_access.is_oa:true`);
    }

    if (filters.length > 0) {
        params.append('filter', filters.join(','));
    }

    const url = `${BASE_URL}?${params.toString()}`;
    let response: Response | null = null; // To access response in catch block

    try {
        response = await fetch(url);
        if (!response.ok) {
            const errorData = await response.json().catch(() => ({ message: `HTTP error! Status: ${response?.status}` }));
            throw new Error(`OpenAlex API error: ${errorData.message || response.statusText}`);
        }
        const data = await response.json();

        const papers = (data.results || []).map(mapOpenAlexWorkToResearchPaper).filter((p): p is ResearchPaper => p !== null);
        const totalCount = data.meta?.count || 0;
        const hasMore = (page * PER_PAGE) < totalCount;

        // 3. Store the result in the cache
        console.log("Caching OpenAlex result:", cacheKey);
        openAlexCache.set(cacheKey, { result: { papers, hasMore }, timestamp: Date.now() });

        return { papers, hasMore };
    } catch (error) {
        console.error("Error searching OpenAlex. Request URL:", url);
        if (response) {
            console.error("Response Status:", response.status, response.statusText);
        }
        if (error instanceof Error) {
            console.error("Original Error Message:", error.message);
        }

        throw new Error("Failed to fetch results from OpenAlex. Please check your network connection and try again later.");
    }
};

/**
 * Fetches a single paper from OpenAlex using its DOI.
 * @param doi The Digital Object Identifier of the paper.
 * @returns A promise that resolves to a ResearchPaper object or null if not found.
 */
export const searchOpenAlexByDoi = async (doi: string): Promise<ResearchPaper | null> => {
    // 1. Check cache
    const cachedEntry = singlePaperCache.get(doi);
    if (cachedEntry && (Date.now() - cachedEntry.timestamp < CACHE_TTL_MS)) {
        console.log("Serving from OpenAlex single paper cache:", doi);
        return cachedEntry.result;
    }

    // Removed host_venue from select list here as well
    const url = `https://api.openalex.org/works/https://doi.org/${encodeURIComponent(doi)}?select=id,doi,title,display_name,publication_year,abstract_inverted_index,authorships,cited_by_count,primary_location,open_access,type`;
    try {
        const response = await fetch(url);
        if (!response.ok) {
            if (response.status === 404) return null;
            throw new Error(`OpenAlex API error! Status: ${response.status}`);
        }
        const work = await response.json();
        const result = mapOpenAlexWorkToResearchPaper(work);

        // 2. Cache result
        singlePaperCache.set(doi, { result, timestamp: Date.now() });

        return result;
    } catch (error) {
        console.error(`Error fetching from OpenAlex by DOI (${doi}):`, error);
        throw new Error(`Failed to fetch metadata for DOI ${doi} from OpenAlex.`);
    }
};

import type { ResearchPaper } from '../types';

// A simple regex to extract arXiv IDs from various URL formats (e.g., /abs/..., /pdf/...).
const ARXIV_ID_REGEX = /(?:abs|pdf)\/(\d{4}\.\d{4,5}(v\d+)?)/;

// Caching configuration
const CACHE_TTL_MS = 5 * 60 * 1000; // 5 minutes

interface SearchCacheEntry {
    result: { papers: ResearchPaper[], hasMore: boolean };
    timestamp: number;
}
const searchCache = new Map<string, SearchCacheEntry>();

interface EnrichmentCacheEntry {
    result: Partial<ResearchPaper> | null;
    timestamp: number;
}
const enrichmentCache = new Map<string, EnrichmentCacheEntry>();


/**
 * Extracts a clean arXiv ID from a given URL.
 * @param url The URL of the arXiv paper.
 * @returns The arXiv ID string if found, otherwise null.
 */
const extractArxivId = (url?: string): string | null => {
    if (!url) return null;
    const match = url.match(ARXIV_ID_REGEX);
    return match ? match[1] : null;
};

/**
 * Fetches and parses paper metadata from the official arXiv API.
 * @param paper The initial ResearchPaper object, used to check for an arXiv source URL.
 * @returns A promise that resolves to a `Partial<ResearchPaper>` object with high-quality data if found, otherwise null.
 */
export const enrichFromArxiv = async (paper: ResearchPaper): Promise<Partial<ResearchPaper> | null> => {
    const arxivId = extractArxivId(paper.sourceURL);
    if (!arxivId) {
        return null;
    }

    // Check cache
    const cached = enrichmentCache.get(arxivId);
    if (cached && (Date.now() - cached.timestamp < CACHE_TTL_MS)) {
        return cached.result;
    }

    const apiUrl = `https://export.arxiv.org/api/query?id_list=${arxivId}`;

    try {
        const response = await fetch(apiUrl);
        if (!response.ok) {
            console.warn(`arXiv API returned status ${response.status} for ID ${arxivId}`);
            return null;
        }

        const xmlText = await response.text();
        const parser = new DOMParser();
        const xmlDoc = parser.parseFromString(xmlText, "application/xml");

        const entry = xmlDoc.querySelector("entry");
        if (!entry) {
            return null;
        }

        const title = entry.querySelector("title")?.textContent?.trim().replace(/\s+/g, ' ') || undefined;
        const abstract = entry.querySelector("summary")?.textContent?.trim().replace(/\s+/g, ' ') || undefined;
        const publishedDate = entry.querySelector("published")?.textContent;
        const year = publishedDate ? new Date(publishedDate).getFullYear() : undefined;

        const authors = Array.from(entry.querySelectorAll("author > name")).map(node => node.textContent?.trim()).filter(Boolean).join(', ');

        const pdfLinkNode = Array.from(entry.querySelectorAll("link")).find(link => link.getAttribute('title') === 'pdf');
        const pdfURL = pdfLinkNode?.getAttribute('href') || undefined;

        const sourceURL = entry.querySelector("id")?.textContent?.trim() || undefined;

        // Construct the enriched data object, only including fields that were successfully parsed.
        const enrichedData: Partial<ResearchPaper> = {};
        if (title) enrichedData.title = title;
        if (abstract) enrichedData.abstract = abstract;
        if (year) enrichedData.year = year;
        if (authors) enrichedData.authors = authors;
        if (pdfURL) enrichedData.pdfURL = pdfURL;
        if (sourceURL) enrichedData.sourceURL = sourceURL;
        enrichedData.enrichmentSource = 'arXiv'; // Mark the source of enrichment

        // Store in cache
        enrichmentCache.set(arxivId, { result: enrichedData, timestamp: Date.now() });

        return enrichedData;

    } catch (error) {
        console.error(`Failed to fetch or parse arXiv data for ID ${arxivId}:`, error);
        return null; // Fail gracefully, allowing the app to use the original data.
    }
};

/**
 * Searches the arXiv API for papers matching a query.
 * @param query The search query string.
 * @param page The page number for pagination.
 * @returns A promise that resolves to an object containing an array of ResearchPaper objects and a boolean indicating if more results are available.
 */
export const searchArxiv = async (query: string, page: number = 1): Promise<{ papers: ResearchPaper[], hasMore: boolean }> => {
    const cacheKey = JSON.stringify({ query, page });

    // Check cache
    const cached = searchCache.get(cacheKey);
    if (cached && (Date.now() - cached.timestamp < CACHE_TTL_MS)) {
        console.log("Serving from arXiv search cache:", cacheKey);
        return cached.result;
    }

    const resultsPerPage = 15;
    const start = (page - 1) * resultsPerPage;
    const apiUrl = `https://export.arxiv.org/api/query?search_query=all:${encodeURIComponent(query)}&max_results=${resultsPerPage}&start=${start}`;

    try {
        const response = await fetch(apiUrl);
        if (!response.ok) {
            throw new Error(`arXiv API error: ${response.status}`);
        }
        const xmlText = await response.text();
        const parser = new DOMParser();
        const xmlDoc = parser.parseFromString(xmlText, "application/xml");

        const totalResultsNode = xmlDoc.querySelector("opensearch\\:totalResults");
        const totalResults = totalResultsNode ? parseInt(totalResultsNode.textContent || '0', 10) : 0;

        const hasMore = (start + resultsPerPage) < totalResults;

        const entries = Array.from(xmlDoc.querySelectorAll("entry"));
        const papers: ResearchPaper[] = entries.map(entry => {
            const title = entry.querySelector("title")?.textContent?.trim().replace(/\s+/g, ' ') || 'Untitled';
            const abstract = entry.querySelector("summary")?.textContent?.trim().replace(/\s+/g, ' ') || 'No abstract available.';
            const publishedDate = entry.querySelector("published")?.textContent;
            const year = publishedDate ? new Date(publishedDate).getFullYear() : new Date().getFullYear();
            const authors = Array.from(entry.querySelectorAll("author > name")).map(node => node.textContent?.trim()).filter(Boolean).join(', ');
            const pdfLinkNode = Array.from(entry.querySelectorAll("link")).find(link => link.getAttribute('title') === 'pdf');
            const sourceURL = entry.querySelector("id")?.textContent?.trim();

            const paperData: Omit<ResearchPaper, 'id'> = {
                title,
                authors,
                year,
                abstract,
                sourceURL: sourceURL,
                pdfURL: pdfLinkNode?.getAttribute('href') || undefined,
                citations: undefined, // arXiv API doesn't provide this directly
                enrichmentSource: 'arXiv',
            };
            // ID will be created later in apiService after de-duplication
            return { ...paperData, id: '' };
        });

        const result = { papers, hasMore };

        // Cache result
        searchCache.set(cacheKey, { result, timestamp: Date.now() });

        return result;

    } catch (error) {
        console.error("Error searching arXiv:", error);
        // Return empty array on error to not break the entire search process
        return { papers: [], hasMore: false };
    }
};

import type { ResearchPaper, ConnectedPaper } from '../types';

const S2_API_BASE = 'https://api.semanticscholar.org/graph/v1/paper/';

// Cache
const CACHE_TTL_MS = 5 * 60 * 1000; // 5 minutes
interface CacheEntry {
    result: { references: ConnectedPaper[], citations: ConnectedPaper[] };
    timestamp: number;
}
const cache = new Map<string, CacheEntry>();

// Helper to map S2 paper data to our internal ConnectedPaper type
const mapS2Paper = (s2paper: any, connection: string): ConnectedPaper => {
    return {
        title: s2paper.title || 'Title not available',
        authors: (s2paper.authors || []).map((a: any) => a.name).join(', '),
        year: s2paper.year || 0,
        summary: s2paper.abstract || 'Abstract not available.',
        sourceURL: s2paper.url,
        connection: connection,
    };
};

export const getCitationGraph = async (doi: string): Promise<{ references: ConnectedPaper[], citations: ConnectedPaper[] }> => {
    const cacheKey = doi;

    // Check cache
    const cached = cache.get(cacheKey);
    if (cached && (Date.now() - cached.timestamp < CACHE_TTL_MS)) {
        return cached.result;
    }

    // Request fields for both the papers referenced by the given DOI, and the papers that cite the DOI.
    const url = `${S2_API_BASE}DOI:${doi}?fields=references.title,references.authors,references.year,references.abstract,references.url,citations.title,citations.authors,citations.year,citations.abstract,citations.url`;

    try {
        const response = await fetch(url);
        if (!response.ok) {
            throw new Error(`Semantic Scholar API error: ${response.status}`);
        }
        const data = await response.json();

        const references = (data.references || []).map((p: any) => mapS2Paper(p, 'This paper cites'));
        const citations = (data.citations || []).map((p: any) => mapS2Paper(p, 'Cited by this paper'));

        const result = { references, citations };

        // Cache result
        cache.set(cacheKey, { result, timestamp: Date.now() });

        return result;
    } catch (error) {
        console.error("Error fetching citation graph from Semantic Scholar:", error);
        // Return empty arrays to not break the UI in case of an API failure
        return { references: [], citations: [] };
    }
};

// Cache for Unpaywall results
const CACHE_TTL_MS = 5 * 60 * 1000; // 5 minutes
const cache = new Map<string, { url: string | null, timestamp: number }>();

/**
 * Finds a direct URL to a legal, open-access PDF version of a paper using the Unpaywall API.
 * Unpaywall is an open database of open access content.
 * @param doi The Digital Object Identifier of the paper.
 * @returns A promise that resolves to the PDF URL string if found, otherwise null.
 */
export const findOpenAccessPdf = async (doi: string): Promise<string | null> => {
    // Check cache
    if (cache.has(doi)) {
        const entry = cache.get(doi)!;
        if (Date.now() - entry.timestamp < CACHE_TTL_MS) {
            return entry.url;
        }
    }

    // Unpaywall requires an email for their "polite pool" of users.
    const email = 'contact@ai-research-explorer.com';
    const url = `https://api.unpaywall.org/v2/${encodeURIComponent(doi)}?email=${email}`;

    try {
        const response = await fetch(url);
        if (!response.ok) {
            // This is expected for DOIs not in their database, so we don't throw an error.
            console.log(`Unpaywall: No record found for DOI ${doi}. Status: ${response.status}`);
            return null;
        }

        const data = await response.json();

        // The 'best_oa_location' provides the direct link to the best available Open Access version.
        // We specifically check for 'application/pdf' to ensure it's a direct PDF link.
        const pdfLocation = data?.best_oa_location;
        let result: string | null = null;

        if (pdfLocation && pdfLocation.url_for_pdf) {
            result = pdfLocation.url_for_pdf;
        }

        // Cache the result (whether it's a URL or null)
        cache.set(doi, { url: result, timestamp: Date.now() });

        return result;

    } catch (error) {
        console.error(`Error querying Unpaywall for DOI ${doi}:`, error);
        // We don't throw an error here to allow the verification process to continue to other methods.
        return null;
    }
};

