import { GoogleGenAI } from "@google/genai";
import type { ResearchPaper } from '../types';
import { cosineSimilarity } from '../utils/math';
import { embedText as embedTextUtil, batchEmbedText as batchEmbedTextUtil } from '../utils/embeddings';

const apiKey = typeof process !== 'undefined' ? process.env.API_KEY : '';
const ai = new GoogleGenAI({ apiKey });
const model = "text-embedding-004";

// Helper for exponential backoff (duplicated here to avoid circular dependency issues, or could be extracted to utils)
const retryWithBackoff = async <T>(operation: () => Promise<T>, retries: number = 5, delay: number = 2000): Promise<T> => {
    try {
        return await operation();
    } catch (error: any) {
        const isRateLimit = error?.status === 429 || error?.code === 429 || error?.message?.includes('429') || error?.message?.includes('RESOURCE_EXHAUSTED');
        const isServerOverload = error?.status === 503 || error?.code === 503;

        if (retries > 0 && (isRateLimit || isServerOverload)) {
            console.warn(`[Embedding API] Rate limit hit. Retrying in ${delay}ms... (Retries left: ${retries})`);
            await new Promise(resolve => setTimeout(resolve, delay));
            return retryWithBackoff(operation, retries - 1, delay * 2);
        }
        throw error;
    }
};

/**
 * Generates an embedding for a single piece of text.
 */
export const calculateSemanticScores = async (queryOrHypotheticalAnswer: string, papers: ResearchPaper[]): Promise<ResearchPaper[]> => {
    if (papers.length === 0) return [];

    try {
        // Use the util function but wrapped in retry logic if it wasn't already (util uses ai.models.embedContent directly)
        // Ideally utils/embeddings.ts should have the retry logic, but let's implement it here or rely on utils.
        // Actually, let's just use the utils which we will update to include retries.

        const queryEmbedding = await embedTextUtil(queryOrHypotheticalAnswer);

        const papersToEmbed = papers.filter(p => 
            p.abstract && 
            typeof p.abstract === 'string' && 
            p.abstract.trim() !== ''
        );

        if (papersToEmbed.length === 0) {
            return papers.map(p => ({ ...p, semanticScore: 0 }));
        }

        const abstractsToEmbed = papersToEmbed.map(p => p.abstract);

        const paperEmbeddings = await batchEmbedTextUtil(abstractsToEmbed);

        const embeddingMap = new Map<string, number[]>();
        papersToEmbed.forEach((paper, index) => {
            // Use the paper's actual ID for mapping
            embeddingMap.set(paper.id, paperEmbeddings[index]);
        });

        return papers.map((paper) => {
            const paperEmbedding = embeddingMap.get(paper.id);
            if (!paperEmbedding || paperEmbedding.length === 0) {
                return { ...paper, semanticScore: 0 };
            }

            const similarity = cosineSimilarity(queryEmbedding, paperEmbedding);
            // Convert similarity from [-1, 1] to a score from 0-100
            const score = Math.round(((similarity + 1) / 2) * 100); 
            return {
                ...paper,
                semanticScore: score,
            };
        });

    } catch (error) {
        console.error("Error calculating semantic scores:", error);
        return papers.map(p => ({ ...p, semanticScore: 0 }));
    }
};

import { GoogleGenAI } from "@google/genai";

const apiKey = typeof process !== 'undefined' ? process.env.API_KEY : '';
const ai = new GoogleGenAI({ apiKey });
const model = "text-embedding-004";

// Helper for exponential backoff
const retryWithBackoff = async <T>(operation: () => Promise<T>, retries: number = 5, delay: number = 2000): Promise<T> => {
    try {
        return await operation();
    } catch (error: any) {
        const isRateLimit = error?.status === 429 || error?.code === 429 || error?.message?.includes('429') || error?.message?.includes('RESOURCE_EXHAUSTED');
        const isServerOverload = error?.status === 503 || error?.code === 503;

        if (retries > 0 && (isRateLimit || isServerOverload)) {
            console.warn(`[Embedding API] Rate limit hit. Retrying in ${delay}ms... (Retries left: ${retries})`);
            await new Promise(resolve => setTimeout(resolve, delay));
            return retryWithBackoff(operation, retries - 1, delay * 2);
        }
        throw error;
    }
};

/**
 * Generates an embedding for a single piece of text.
 */
export const embedText = async (text: string): Promise<number[]> => {
    if (!text || text.trim() === '') {
        return [];
    }
    try {
        // Use 'contents' as the parameter for the text content
        const response = await retryWithBackoff(() => ai.models.embedContent({ 
            model, 
            contents: text
        }));
        return response.embedding?.values || [];
    } catch (e) {
        console.error(`Error embedding text: "${text.substring(0, 50)}..."`, e);
        return [];
    }
};

/**
 * Generates embeddings for multiple pieces of text.
 * Falls back to parallel single requests since batchEmbedContents is not reliably available.
 */
export const batchEmbedText = async (texts: string[]): Promise<number[][]> => {
    if (!texts || texts.length === 0) {
        return [];
    }

    // Create a map to restore original order and handle empty texts
    const textMap = new Map<number, string>();
    texts.forEach((text, i) => {
        if (text && text.trim() !== '') {
            textMap.set(i, text);
        }
    });

    const validTexts = Array.from(textMap.values());
    if (validTexts.length === 0) {
        return texts.map(() => []);
    }

    try {
        // Execute embeddings in parallel
        // Note: For very large batches (e.g. > 100), one might want to chunk this 
        // to avoid hitting rate limits, but for typical UI usage, Promise.all is sufficient.
        const embeddings = await Promise.all(validTexts.map(text => embedText(text)));

        const resultMap = new Map<string, number[]>();
        validTexts.forEach((text, index) => {
            resultMap.set(text, embeddings[index]);
        });

        // Reconstruct the original array order
        const finalResults: number[][] = new Array(texts.length).fill([]);
        for (const [originalIndex, text] of textMap.entries()) {
            finalResults[originalIndex] = resultMap.get(text) || [];
        }
        return finalResults;

    } catch (error) {
        console.error("Error during batch embedding.", error);
        return texts.map(() => []);
    }
};

