    const handleProjectChat = async (projectId: string, message: string) => {
        const project = projects.find(p => p.id === projectId);
        if (!project) return;

        const userMessage: ChatMessage = { role: 'user', parts: [{ text: message }] };

        setProjectChats(prev => ({
            ...prev,
            [projectId]: {
                history: [...(prev[projectId]?.history || []), userMessage],
                isLoading: true,
            }
        }));

        try {
            const projectPapers: ResearchPaper[] = project.paperIds.map(id => workspacePapers.find(p => p.id === id)).filter((p): p is ResearchPaper => !!p);

            // The agent service now streams updates. We'll handle them one by one.
            const agentStream = agentService.runAgentTask(message, project, projectPapers, model);

            for await (const update of agentStream) {
                setProjectChats(prev => {
                    const currentHistory = prev[projectId]?.history || [];
                    let newHistory = [...currentHistory];

                    if (update.type === 'tool-start') {
                        newHistory.push({ role: 'tool', parts: [{ toolCall: update.toolCall }] });
                    } else if (update.type === 'tool-end') {
                        // Find the corresponding tool-start message and add the result
                        const lastMsgIndex = newHistory.length - 1;
                        if (newHistory[lastMsgIndex]?.role === 'tool' && newHistory[lastMsgIndex].parts[0].toolCall?.name === update.toolResponse.name) {
                            newHistory[lastMsgIndex].parts[0].toolResponse = update.toolResponse;
                        }
                    } else if (update.type === 'final-answer') {
                        newHistory.push({ role: 'model', parts: [{ text: update.text }] });
                    }

                    return {
                        ...prev,
                        [projectId]: {
                            ...prev[projectId],
                            history: newHistory,
                        },
                    };
                });
            }

        } catch (error) {
            const errorMessage = error instanceof Error ? error.message : "An error occurred.";
            const modelMessage: ChatMessage = { role: 'model', parts: [{ text: `Error: ${errorMessage}` }] };
            setProjectChats(prev => ({
                ...prev,
                [projectId]: {
                    history: [...(prev[projectId]?.history || []), modelMessage],
                    isLoading: false,
                }
            }));
        } finally {
            setProjectChats(prev => ({
                ...prev,
                [projectId]: {
                    ...prev[projectId],
                    isLoading: false,
                }
            }));
        }
    };

    const handleWorkspaceChat = async (message: string) => {
        if (!workspacePapers.length) return;

        const userMessage: ChatMessage = { role: 'user', parts: [{ text: message }] };
        setWorkspaceChatHistory(prev => [...prev, userMessage]);
        setIsWorkspaceChatLoading(true);

        try {
            // Create a pseudo-project for the entire workspace
            const workspaceProject: Project = {
                id: 'workspace_all',
                name: 'All Workspace Papers',
                paperIds: workspacePapers.map(p => p.id),
                createdAt: Date.now(),
                color: 'sky',
                paperStatuses: {}
            };

            const agentStream = agentService.runAgentTask(message, workspaceProject, workspacePapers, model);

            for await (const update of agentStream) {
                setWorkspaceChatHistory(prev => {
                    const currentHistory = [...prev];
                    if (update.type === 'tool-start') {
                        currentHistory.push({ role: 'tool', parts: [{ toolCall: update.toolCall }] });
                    } else if (update.type === 'tool-end') {
                        const lastMsgIndex = currentHistory.length - 1;
                        if (currentHistory[lastMsgIndex]?.role === 'tool' && currentHistory[lastMsgIndex].parts[0].toolCall?.name === update.toolResponse.name) {
                            currentHistory[lastMsgIndex].parts[0].toolResponse = update.toolResponse;
                        }
                    } else if (update.type === 'final-answer') {
                        currentHistory.push({ role: 'model', parts: [{ text: update.text }] });
                    }
                    return currentHistory;
                });
            }
        } catch (error) {
            const errorMessage = error instanceof Error ? error.message : "An error occurred.";
            const modelMessage: ChatMessage = { role: 'model', parts: [{ text: `Error: ${errorMessage}` }] };
            setWorkspaceChatHistory(prev => [...prev, modelMessage]);
