    title: string;
    icon: React.ReactNode;
    count: number;
    children: React.ReactNode;
    actions?: React.ReactNode;
    defaultExpanded?: boolean;
    color?: string;
    onGenerateInsights?: () => void;
    isGeneratingInsights?: boolean;
    hasInsights?: boolean;
    isExpandedView?: boolean;
    onToggleView?: () => void;
}> = ({ title, icon, count, children, actions, defaultExpanded = true, color, onGenerateInsights, isGeneratingInsights, hasInsights, isExpandedView, onToggleView }) => {
    const [isExpanded, setIsExpanded] = useState(defaultExpanded);
    const borderColorClass = color ? (colorClassMap[color]?.border || 'border-border') : 'border-border';

    return (
        <div className={`bg-muted/50 border rounded-lg border-l-4 ${borderColorClass}`}>
            <header 
                className="flex items-center justify-between p-3 cursor-pointer hover:bg-accent/50 transition-colors"
                onClick={() => setIsExpanded(!isExpanded)}
            >
                <div className="flex items-center gap-3">
                    {icon}
                    <h4 className="font-bold text-foreground">{title}</h4>
                    <span className="text-xs font-mono bg-primary/10 text-primary px-2 py-0.5 rounded-full">{count}</span>
                </div>
                <div className="flex items-center gap-2">
                    <div onClick={e => e.stopPropagation()}>{actions}</div>
                    <ChevronDownIcon className={`w-5 h-5 text-muted-foreground transition-transform ${isExpanded ? 'rotate-180' : ''}`} />
                </div>
            </header>

            {isExpanded && onGenerateInsights && (
                <div className="px-3 pb-3 border-b border-border/50 bg-background/50 flex items-center justify-between">
                    <p className="text-xs text-muted-foreground">
                        {isExpandedView ? "Viewing Session Insights" : "Compact View"}
                    </p>
                    <div className="flex gap-2">
                        <button
                            onClick={onGenerateInsights}
                            disabled={isGeneratingInsights}
                            className={`flex items-center gap-1.5 h-7 px-3 text-xs font-semibold rounded-full border transition-colors ${
                                hasInsights && !isGeneratingInsights
                                ? 'bg-secondary text-secondary-foreground hover:bg-accent border-border'
                                : 'bg-primary text-primary-foreground hover:bg-primary/90 border-transparent'
                            } disabled:opacity-50`}
                        >
                            <SparklesIcon className="w-3 h-3" />
                            {isGeneratingInsights ? 'Generating...' : hasInsights ? 'Regenerate Insights' : 'Generate Insights'}
                        </button>
                        {hasInsights && (
                            <button
                                onClick={onToggleView}
                                className="flex items-center gap-1.5 h-7 px-3 text-xs font-semibold rounded-full bg-background border border-input hover:bg-accent text-foreground transition-colors"
                            >
                                {isExpandedView ? 'Compact View' : 'Expand View'}
                            </button>
                        )}
                    </div>
                </div>
            )}

            {isExpanded && (
                <div className={`border-t border-border p-2 ${isExpandedView ? 'space-y-4' : 'space-y-1'}`}>
                    {children}
                </div>
            )}
        </div>
    );
};

export const ProjectWorkspace: React.FC<ProjectWorkspaceProps> = (props) => {
    const { 
        workspacePapers, projects, onCreateProject, 
        onAnalyzeWorkspace, onRemovePaperFromWorkspace, 
        onUpdateProjectColor, model, onIndexPaperForRag,
        isWorkspaceAnalysisLoading
    } = props;
    const [newProjectName, setNewProjectName] = useState('');
    const [projectToDelete, setProjectToDelete] = useState<Project | null>(null);
    const [generatingProjectId, setGeneratingProjectId] = useState<string | null>(null);
    const [expandedProjects, setExpandedProjects] = useState<Set<string>>(new Set());

    // Local state for paper highlights to avoid lifting it all the way up for now
    // In a real app, this should be in the main app state or a robust store.
    const [localPaperHighlights, setLocalPaperHighlights] = useState<{ [paperId: string]: { category: string; text: string }[] }>({});

    // Merge workspace papers with local highlights
    const enrichedPapers = useMemo(() => {
        return workspacePapers.map(p => ({
            ...p,
            highlights: localPaperHighlights[p.id] || p.highlights
        }));
    }, [workspacePapers, localPaperHighlights]);

    const paperMap = useMemo(() => new Map(enrichedPapers.map(p => [p.id, p])), [enrichedPapers]);
    const allProjectPaperIds = useMemo(() => new Set(projects.flatMap(p => p.paperIds)), [projects]);
    const unsortedPapers = useMemo(() => enrichedPapers.filter(p => !allProjectPaperIds.has(p.id)), [enrichedPapers, allProjectPaperIds]);

    const handleCreateProject = (e: React.FormEvent) => {
        e.preventDefault();
        if (newProjectName.trim()) {
            onCreateProject(newProjectName.trim());
            setNewProjectName('');
        }
    };

    const confirmDeleteProject = () => {
        if (projectToDelete) {
            props.onDeleteProject(projectToDelete.id);
            setProjectToDelete(null);
        }
    };

    const handleGenerateInsights = async (project: Project) => {
        const projectPapers = project.paperIds.map(id => paperMap.get(id)).filter((p): p is ResearchPaper => !!p);
        if (projectPapers.length === 0) return;

        setGeneratingProjectId(project.id);

        // Ensure this project is expanded
        setExpandedProjects(prev => new Set(prev).add(project.id));

        try {
            const results = await apiService.generateSessionHighlights(projectPapers, project.name, model);

            const newHighlights: { [id: string]: any[] } = {};
            results.forEach(r => {
                newHighlights[r.paperId] = r.highlights;
            });

            setLocalPaperHighlights(prev => ({ ...prev, ...newHighlights }));
        } catch (error) {
            console.error("Failed to generate insights:", error);
        } finally {
            setGeneratingProjectId(null);
        }
    };

    const toggleProjectView = (projectId: string) => {
        setExpandedProjects(prev => {
            const newSet = new Set(prev);
            if (newSet.has(projectId)) {
                newSet.delete(projectId);
            } else {
                newSet.add(projectId);
            }
            return newSet;
        });
    };

    return (
        <div className="space-y-6">
            <div className="bg-primary/5 rounded-lg border border-primary/20 p-5 text-center space-y-4">
                <div>
                    <h3 className="text-xl font-bold text-foreground">Workspace Analysis</h3>
                    <p className="text-sm text-muted-foreground mt-1">
                        Ready to process your collection? Launch the dashboard to find research gaps, synthesize findings, and chat with your papers.
                    </p>
                </div>
                <button 
                    onClick={() => onAnalyzeWorkspace(workspacePapers, model)}
                    disabled={workspacePapers.length === 0 || isWorkspaceAnalysisLoading}
                    className="w-full h-12 px-6 text-base font-bold rounded-lg bg-primary text-primary-foreground hover:bg-primary/90 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-3 transition-all shadow-md hover:shadow-lg hover:-translate-y-0.5"
                >
                    <AnalyzeIcon className="w-5 h-5"/>
                    <span>{isWorkspaceAnalysisLoading ? 'Preparing Dashboard...' : 'Open Analysis Dashboard'}</span>
                </button>
            </div>

            <div>
                <h3 className="text-lg font-bold text-foreground mb-3 flex items-center gap-2">
                    <FolderIcon className="w-5 h-5 text-muted-foreground" />
                    Projects
                </h3>
                <form onSubmit={handleCreateProject} className="flex items-center gap-2 mb-6">
                    <input 
                        type="text"
                        value={newProjectName}
                        onChange={(e) => setNewProjectName(e.target.value)}
                        placeholder="Create a new project (e.g. 'Thesis Chapter 1')..."
                        className="w-full h-10 px-3 bg-background border border-input rounded-md focus:ring-2 focus:ring-ring"
                    />
                    <button type="submit" className="h-10 px-4 bg-secondary text-secondary-foreground font-semibold rounded-md hover:bg-accent disabled:opacity-50 flex items-center gap-2 flex-shrink-0" disabled={!newProjectName.trim()}>
                        <AddIcon className="w-4 h-4"/> Create
                    </button>
                </form>
            </div>

            <div className="space-y-4">
                {projects.sort((a,b) => b.createdAt - a.createdAt).map(project => {
                    const projectPapers = project.paperIds.map(id => paperMap.get(id)).filter((p): p is ResearchPaper => !!p);
                    const hasInsights = projectPapers.some(p => p.highlights && p.highlights.length > 0);
                    const isExpanded = expandedProjects.has(project.id);

                    return (
                        <CollapsibleSection
                            key={project.id}
                            title={project.name}
                            icon={<FolderIcon className={`w-5 h-5 ${colorClassMap[project.color]?.text || 'text-primary'}`} />}
                            count={project.paperIds.length}
                            color={project.color}
                            actions={
                                <div className="flex items-center gap-2">
                                    <ColorPickerTrigger project={project} onUpdateColor={onUpdateProjectColor} />
                                    <button 
                                        onClick={() => setProjectToDelete(project)} 
                                        className="p-1.5 text-destructive/80 hover:bg-destructive/10 rounded-full"
                                        title={`Delete project "${project.name}"`}
                                    >
                                        <RemoveIcon className="w-4 h-4" />
                                    </button>
                                </div>
                            }
                            onGenerateInsights={() => handleGenerateInsights(project)}
                            isGeneratingInsights={generatingProjectId === project.id}
                            hasInsights={hasInsights}
                            isExpandedView={isExpanded}
                            onToggleView={() => toggleProjectView(project.id)}
                        >
                            {projectPapers.length > 0 ? projectPapers.map(paper => (
                            <PaperListItem
                                    key={paper.id}
                                    paper={paper}
                                    allProjects={projects}
                                    currentProjectId={project.id}
                                    onMove={props.onMovePaperToProject}
                                    onRemove={onRemovePaperFromWorkspace}
                                    ragStatus={project.paperStatuses?.[paper.id] || 'unindexed'}
                                    onIndex={() => onIndexPaperForRag(project.id, paper.id)}
                                    isDetailedView={isExpanded}
                            />
                            )) : <p className="text-sm text-muted-foreground italic text-center p-4">This project is empty.</p>}
                        </CollapsibleSection>
                    );
                })}

                <CollapsibleSection
                    title="Unsorted Papers"
                    icon={<InboxIcon className="w-5 h-5 text-primary" />}
                    count={unsortedPapers.length}
                    defaultExpanded={unsortedPapers.length > 0 || projects.length === 0}
                >
                    {unsortedPapers.length > 0 ? unsortedPapers.map(paper => (
                        <PaperListItem
                           key={paper.id}
                           paper={paper}
                           allProjects={projects}
                           currentProjectId={null}
                           onMove={props.onMovePaperToProject}
                           onRemove={onRemovePaperFromWorkspace}
                           ragStatus="unindexed"
                           onIndex={() => {}} // No indexing in unsorted
                        />
                    )) : <p className="text-sm text-muted-foreground italic text-center p-4">Add papers to your workspace to see them here.</p>}
                </CollapsibleSection>
            </div>

            {projectToDelete && (
                 <div className="fixed inset-0 bg-background/80 backdrop-blur-sm flex items-center justify-center z-50">
                    <div className="bg-card p-6 rounded-lg shadow-lg border max-w-sm w-full">
                        <h4 className="text-lg font-bold text-foreground">Confirm Deletion</h4>
                        <p className="text-sm text-muted-foreground mt-2">
                            Are you sure you want to delete the project "<strong>{projectToDelete.name}</strong>"? 
                            All papers within this project will be moved to "Unsorted". This action cannot be undone.
                        </p>
                        <div className="flex justify-end gap-2 mt-6">
                            <button onClick={() => setProjectToDelete(null)} className="h-9 px-4 text-sm font-semibold rounded-md bg-secondary text-secondary-foreground hover:bg-accent">
                                Cancel
                            </button>
                            <button onClick={confirmDeleteProject} className="h-9 px-4 text-sm font-semibold rounded-md bg-destructive text-destructive-foreground hover:bg-destructive/90">
                                Delete Project
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

import type { AdvancedSearchOptions, ResearchPaper, SummaryLength, SummaryStyle, ModelDefinition, SearchSourceInfo, KnowledgeGraph, PaperAnalysis, SynthesisResult, ConnectedPaper, ValidationResult, AuthorProfile, AnalysisResult } from '../types';
import * as validationService from './validationService';
import { createPaperId } from './extensionService';
import * as unpaywallService from './unpaywallService';
import * as openalexService from './openalexService';
import * as arxivService from './arxivService';
import * as geminiService from './geminiService';
import * as embeddingService from './embeddingService';
import { cosineSimilarity } from '../utils/math';
import { batchEmbedText } from '../utils/embeddings';
import * as crossrefService from './crossrefService';
import * as semanticScholarService from './semanticScholarService';
import * as analysisService from './analysisService';

// Caches
const GENERIC_CACHE_TTL = 10 * 60 * 1000; // 10 minutes
const paperAnalysisCache = new Map<string, { timestamp: number; data: PaperAnalysis }>();
const connectedPapersCache = new Map<string, { timestamp: number; data: ConnectedPaper[] }>();

export const searchFast = async (
    query: string, 
    options: AdvancedSearchOptions, 
    sources: SearchSourceInfo[], 
    page: number
): Promise<{ papers: ResearchPaper[], hasMore: boolean, rawQueryUsed: string }> => {
    // Primary source is OpenAlex for fast retrieval
    const { papers, hasMore } = await openalexService.searchOpenAlex(query, options, page);
    return { papers, hasMore, rawQueryUsed: query };
};

export const searchByDoi = async (doi: string, model: ModelDefinition): Promise<ResearchPaper | null> => {
    return await openalexService.searchOpenAlexByDoi(doi);
};

export const calculatePaperScores = async (
    papers: ResearchPaper[], 
    query: string, 
    hypotheticalAnswer: string,
    model: ModelDefinition,
    options: AdvancedSearchOptions
): Promise<ResearchPaper[]> => {
    // 1. Semantic Scoring
    const textToEmbed = hypotheticalAnswer || query;
    const scoredPapers = await embeddingService.calculateSemanticScores(textToEmbed, papers);

    // 2. Screening Fit (if criteria exist)
    if (options.inclusionCriteria || options.exclusionCriteria) {
        const screenedPapers = await Promise.all(scoredPapers.map(async (p) => {
            const { score, rationale } = await geminiService.evaluateScreeningFit(p, options.inclusionCriteria, options.exclusionCriteria, model);
            return { ...p, screeningFitScore: score, screeningRationale: rationale };
        }));
        return screenedPapers;
    }

    return scoredPapers;
};

export const mergePapers = (papers: ResearchPaper[]): ResearchPaper[] => {
    const uniquePapers = new Map<string, ResearchPaper>();
    papers.forEach(p => {
        const existing = uniquePapers.get(p.id);
        if (!existing) {
            uniquePapers.set(p.id, p);
        } else {
            // Merge strategy: prefer non-null values, prefer DOI presence
            const merged = { ...existing, ...p };
            // Ensure essential fields don't get overwritten by empty ones if existing had them
            if (existing.abstract && (!p.abstract || p.abstract.length < existing.abstract.length)) {
                merged.abstract = existing.abstract;
            }
             if (existing.doi && !p.doi) {
                merged.doi = existing.doi;
            }
            uniquePapers.set(p.id, merged);
        }
    });
    return Array.from(uniquePapers.values());
};

export const runBackgroundAIAnalysis = async (
    query: string,
    options: AdvancedSearchOptions,
    initialPapers: ResearchPaper[],
    model: ModelDefinition,
    summaryLength: SummaryLength,
    summaryStyle: SummaryStyle,
    sources: SearchSourceInfo[],
    setAiParsedFilters: (filters: any) => void,
    setAiHypotheticalAnswer: (answer: string) => void
): Promise<{
    refinedPapers: ResearchPaper[];
    newGroundedPapers: ResearchPaper[];
    newSummary: string;
    newAnalysis: AnalysisResult | null;
    finalParsedFilters: any;
    finalHypotheticalAnswer: string;
}> => {

    // 1. Parse Query & Generate Hypothesis (Parallel)
    const [parsedFilters, hypotheticalAnswer] = await Promise.all([
        geminiService.parseQueryToStructuredFilters(query, model),
        geminiService.generateHypotheticalAnswer(query, model)
    ]);

    setAiParsedFilters(parsedFilters);
    setAiHypotheticalAnswer(hypotheticalAnswer);

    // 2. Score Initial Papers
    const scoredInitialPapers = await calculatePaperScores(initialPapers, query, hypotheticalAnswer, model, options);

    // 3. Grounded Search (Google Search) - to supplement OpenAlex results
    let groundedPapers: ResearchPaper[] = [];
    try {
        const groundedResults = await geminiService.findPapersWithGoogleSearch(query, model);
        groundedPapers = groundedResults.map(p => ({
            ...p,
            id: createPaperId(p), 
            citations: 0, 
            semanticScore: 0 
        } as ResearchPaper));
    } catch (e) {
        console.warn("Grounded search failed:", e);
    }

    // Score grounded papers
    const scoredGroundedPapers = await calculatePaperScores(groundedPapers, query, hypotheticalAnswer, model, options);

    // Combine for summary/analysis - prioritize high semantic score for the summary context
    const allPapers = [...scoredInitialPapers, ...scoredGroundedPapers]
        .sort((a, b) => (b.semanticScore || 0) - (a.semanticScore || 0));

    const topPapers = allPapers.slice(0, 10);

    // 4. Generate Summary & Analysis (Parallel)
    const [summary, analysis] = await Promise.all([
        geminiService.generateSummaryForPapers(topPapers, summaryLength, summaryStyle, model),
        analysisService.analyzePapers(topPapers)
    ]);

    return {
        refinedPapers: scoredInitialPapers,
        newGroundedPapers: scoredGroundedPapers,
        newSummary: summary,
        newAnalysis: analysis,
        finalParsedFilters: parsedFilters,
        finalHypotheticalAnswer: hypotheticalAnswer
    };
};

export const validatePaper = async (paper: ResearchPaper) => {
    return await validationService.validatePaper(paper);
};

export const generateSearchSuggestions = async (query: string, model: ModelDefinition) => geminiService.generateSearchSuggestions(query, model);
export const analyzeGaps = async (papers: ResearchPaper[], model: ModelDefinition) => geminiService.analyzeResearchGaps(papers, model);

// Export the analyzePapers function from analysisService via apiService
export const analyzePapers = async (papers: ResearchPaper[]) => analysisService.analyzePapers(papers);

export const analyzeSinglePaper = async (paper: ResearchPaper, model: ModelDefinition): Promise<PaperAnalysis> => {
    const cacheKey = `${paper.id}-${model.id}`;
    const cached = paperAnalysisCache.get(cacheKey);
    if (cached && (Date.now() - cached.timestamp < GENERIC_CACHE_TTL)) {
        return cached.data;
    }

    const result = await geminiService.analyzeSinglePaper(paper, model);
    paperAnalysisCache.set(cacheKey, { timestamp: Date.now(), data: result });
    return result;
};

export const extractKeyConcepts = async (title: string, abstract: string, model: ModelDefinition) => geminiService.extractKeyConcepts(title, abstract, model);
export const extractKnowledgeGraph = async (abstract: string, model: ModelDefinition) => geminiService.extractKnowledgeGraph(abstract, model);
export const synthesizePapers = async (papers: ResearchPaper[], model: ModelDefinition) => geminiService.synthesizePapers(papers, model);
export const findOpenAccessPdf = async (doi: string) => unpaywallService.findOpenAccessPdf(doi);
export const fetchMetadataByDOI = async (doi: string) => openalexService.searchOpenAlexByDoi(doi);
export const findDoiForPaper = async (paper: ResearchPaper) => crossrefService.findDoiForPaper(paper);
export const rerankForScreening = async (included: ResearchPaper[], excluded: ResearchPaper[], unscreened: ResearchPaper[], model: ModelDefinition) => {
    if (unscreened.length === 0) return [];
    const rerankingPromises = unscreened.map(async (paper) => {
        const result = await geminiService.rerankByScreeningExample(included, excluded, paper, model);
        return { paperId: paper.id, score: result.score, rationale: result.rationale };
    });
    return await Promise.all(rerankingPromises);
};
export const generateSuggestions = async (paper: ResearchPaper, model: ModelDefinition) => geminiService.generatePaperBasedSuggestions(paper, model);

export const findConnectedPapers = async (paper: ResearchPaper, model: ModelDefinition): Promise<ConnectedPaper[]> => {
    const cacheKey = `${paper.id}-${model.id}`;
    const cached = connectedPapersCache.get(cacheKey);
    if (cached && (Date.now() - cached.timestamp < GENERIC_CACHE_TTL)) {
        return cached.data;
    }

    let result: ConnectedPaper[];
    if (!paper.doi) {
        result = await geminiService.findConnectedPapers(paper, model);
    } else {
        try {
            const { references, citations } = await semanticScholarService.getCitationGraph(paper.doi);
            result = [...citations, ...references];
        } catch (error) {
            console.error("Failed to get citation graph, falling back to AI search.", error);
            result = await geminiService.findConnectedPapers(paper, model);
        }
    }

    connectedPapersCache.set(cacheKey, { timestamp: Date.now(), data: result });
    return result;
};

export const classifyStudyDesign = async (paper: ResearchPaper, model: ModelDefinition) => geminiService.classifyStudyDesign(paper, model);
export const suggestJournals = async (paper: ResearchPaper, model: ModelDefinition) => geminiService.suggestJournals(paper, model);
export const generateSimilaritySearchQuery = async (paper: ResearchPaper, model: ModelDefinition) => geminiService.generateSimilaritySearchQuery(paper, model);
export const generateSessionHighlights = async (papers: ResearchPaper[], topic: string, model: ModelDefinition) => geminiService.generateSessionHighlights(papers, topic, model);

