export const extractCitationMetadata = async (paper: ResearchPaper, model: ModelDefinition): Promise<object> => {
    const prompt = `From the provided paper metadata, extract the necessary fields to create a CSL JSON object for citation.
    - The author names MUST be split into "family" and "given" names. If only a full name is available, split it. If only one name, treat as family.
    - The date MUST be represented in the 'date-parts' format (e.g., [[2023]]). Use the year if a full date is not available.
    - Set 'type' to 'article-journal'. If journal is missing, set 'container-title' to 'N/A'.

    **Paper Metadata:**
    Title: "${paper.title}"
    Authors: "${paper.authors}"
    Year: ${paper.year}
    Journal: "${paper.journal || 'Unknown Journal'}"
    URL: "${paper.sourceURL || ''}"
    DOI: "${paper.doi || ''}"

    Return a single CSL JSON object.`;

    try {
        const result = await generateJsonWithModel(prompt, model, cslSchema);
        if (!result) {
            // Simple fallback structure if model fails
            return { 
                type: 'article-journal',
                title: paper.title, 
                author: [{ literal: paper.authors }],
                issued: { 'date-parts': [[paper.year || new Date().getFullYear()]] }
            };
        }
        // Ensure type is set correctly for Citation.js
        if (!result.type) result.type = 'article-journal';
        return result;
    } catch (error) {
        console.error("Error extracting citation metadata:", error);
        // Safe fallback that definitely works with Citation.js
        return {
            type: 'article-journal',
            title: paper.title,
            author: [{ literal: paper.authors }],
            issued: { 'date-parts': [[paper.year || new Date().getFullYear()]] },
        };
    }
};

