const suggestionsCache = new Map<string, string[]>();

export const generateSearchSuggestions = async (partialQuery: string, model: ModelDefinition): Promise<string[]> => {
    if (suggestionsCache.has(partialQuery)) {
        return suggestionsCache.get(partialQuery)!;
    }

    const prompt = `You are an expert academic librarian. A user is typing a search query. Based on their partial input, generate 3-5 distinct and insightful search query suggestions that would help them find relevant academic papers. The suggestions should be alternative phrasings, more specific queries, or related concepts.

