import { GoogleGenAI, Type } from "@google/genai";
import type { ModelDefinition, ResearchPaper, DeepResearchStep, DeepResearchReport } from "../types";
import * as openalexService from "./openalexService";
import { createPaperId } from "./extensionService";

const apiKey = typeof process !== 'undefined' ? process.env.API_KEY : '';
const ai = new GoogleGenAI({ apiKey });

// Helper to sanitize JSON
const safeJsonParse = (jsonString: string) => {
    try {
        const cleanedString = jsonString.replace(/```json/g, '').replace(/```/g, '').trim();
        return JSON.parse(cleanedString);
    } catch (e) {
        console.error("Failed to parse JSON:", e);
        return null;
    }
};

/**
 * Step 1: Generate a Research Plan
 * Deconstructs the user's broad topic into specific search queries.
 */
const planSchema = {
    type: Type.OBJECT,
    properties: {
        sub_queries: {
            type: Type.ARRAY,
            items: { type: Type.STRING },
            description: "A list of 3-5 specific search queries to cover different aspects of the topic."
        }
    },
    required: ["sub_queries"]
};

export const generateResearchPlan = async (topic: string, model: ModelDefinition): Promise<DeepResearchStep[]> => {
    const prompt = `You are a Lead Researcher planning a comprehensive literature review.

    Topic: "${topic}"

    Task: Break this topic down into 3-5 distinct, targeted search queries that will help gather a complete picture.
    - One query should be broad.
    - One should focus on recent developments (e.g., "since 2020").
    - One should focus on challenges or limitations.
    - One should focus on a specific sub-niche or methodology if applicable.

    Return a JSON object with a "sub_queries" array of strings.`;

    try {
        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: planSchema,
            }
        });

        const result = safeJsonParse(response.text || '');
        if (!result || !result.sub_queries) return [];

        return result.sub_queries.map((q: string, i: number) => ({
            id: `step_${i}`,
            query: q,
            status: 'pending',
            papersFound: 0
        }));
    } catch (e) {
        console.error("Deep Research Plan Error:", e);
        // Fallback plan
        return [
            { id: 'step_0', query: topic, status: 'pending', papersFound: 0 },
            { id: 'step_1', query: `${topic} challenges`, status: 'pending', papersFound: 0 }
        ];
    }
};

/**
 * Step 2: Execute Search
 * Runs a search for a single step.
 */
export const executeSearchStep = async (step: DeepResearchStep): Promise<ResearchPaper[]> => {
    try {
        // We use a broader search here
        const { papers } = await openalexService.searchOpenAlex(step.query, {
            startYear: '', endYear: '', authors: '', excludeKeywords: '', inclusionCriteria: '', exclusionCriteria: '', studyDesign: 'any',
            isOpenAccess: false
        });

        // Return top 5 most relevant per query to avoid overwhelming context
        return papers.slice(0, 5); 
    } catch (e) {
        console.error(`Search failed for ${step.query}:`, e);
        return [];
    }
};

/**
 * Step 3: Synthesize Report
 * Reads all gathered papers and writes a report.
 */
const reportSchema = {
    type: Type.OBJECT,
    properties: {
        title: { type: Type.STRING, description: "A formal academic title for the report." },
        summary: { type: Type.STRING, description: "An executive summary of the findings." },
        sections: {
            type: Type.ARRAY,
            items: {
                type: Type.OBJECT,
                properties: {
                    heading: { type: Type.STRING },
                    content: { type: Type.STRING, description: "Detailed content for this section, using markdown." }
                },
                required: ["heading", "content"]
            }
        }
    },
    required: ["title", "summary", "sections"]
};

export const synthesizeReport = async (topic: string, papers: ResearchPaper[], model: ModelDefinition): Promise<DeepResearchReport> => {
    // Create a context string from the papers
    const context = papers.map((p, i) => 
        `[${i+1}] Title: ${p.title}\nAuthors: ${p.authors} (${p.year})\nAbstract: ${p.abstract}\n`
    ).join('\n---\n');

    const prompt = `You are an expert academic writer. Write a comprehensive research report on the topic: "${topic}".

    Use the following ${papers.length} research papers as your source material.

    **Source Material:**
    ${context}

    **Instructions:**
    1.  Synthesize the findings from the papers. Do not just list them.
    2.  Identify common themes, conflicts, and gaps.
    3.  Structure the report with a clear Title, Executive Summary, and several thematic Sections (Introduction, Methodologies, Key Findings, Conclusion).
    4.  IMPORTANT: Cite your sources using the bracket notation [1], [2], etc., corresponding to the provided source list order.
    5.  The tone should be formal and academic.

    Return the result as a JSON object matching the schema.`;

    try {
        // Use Pro model for better writing if available, else Flash
        const modelId = model.id.includes('pro') ? model.id : 'gemini-2.5-flash';

        const response = await ai.models.generateContent({
            model: modelId,
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: reportSchema,
            }
        });

        const result = safeJsonParse(response.text || '');
        if (!result) throw new Error("Failed to parse report.");

        return {
            title: result.title,
            summary: result.summary,
            sections: result.sections,
            references: papers // Pass papers back to link citations [1] -> paper
        };

    } catch (e) {
        console.error("Report Synthesis Error:", e);
        throw new Error("Failed to generate research report.");
    }
};

import React, { useState, useEffect, useRef } from 'react';
import type { ModelDefinition, DeepResearchStep, DeepResearchReport, ResearchPaper } from '../types';
import * as deepResearchService from '../services/deepResearchService';
import { AnalyzeIcon } from './icons/AnalyzeIcon';
import { LoadingSpinner } from './LoadingSpinner';
import { CheckIcon } from './icons/CheckIcon';
import { SearchIcon } from './icons/SearchIcon';
import { ScholarIcon } from './icons/ScholarIcon';
import { AddIcon } from './icons/AddIcon';

interface DeepResearchModalProps {
    isOpen: boolean;
    onClose: () => void;
    initialTopic: string;
    model: ModelDefinition;
    onAddPapersToWorkspace: (papers: ResearchPaper[]) => void;
}

export const DeepResearchModal: React.FC<DeepResearchModalProps> = ({ isOpen, onClose, initialTopic, model, onAddPapersToWorkspace }) => {
    const [topic, setTopic] = useState(initialTopic);
    const [status, setStatus] = useState<'idle' | 'planning' | 'researching' | 'synthesizing' | 'completed'>('idle');
    const [steps, setSteps] = useState<DeepResearchStep[]>([]);
    const [allPapers, setAllPapers] = useState<ResearchPaper[]>([]);
    const [report, setReport] = useState<DeepResearchReport | null>(null);
    const [progress, setProgress] = useState(0);
    const [isSaved, setIsSaved] = useState(false);

    // Reset when opened
    useEffect(() => {
        if (isOpen) {
            setTopic(initialTopic);
            setStatus('idle');
            setSteps([]);
            setAllPapers([]);
            setReport(null);
            setProgress(0);
            setIsSaved(false);
        }
    }, [isOpen, initialTopic]);

    const startDeepResearch = async () => {
        if (!topic.trim()) return;

        setStatus('planning');
        setProgress(5);

        try {
            // 1. Plan
            const plan = await deepResearchService.generateResearchPlan(topic, model);
            setSteps(plan);
            setStatus('researching');
            setProgress(20);

            // 2. Execute searches in parallel
            const papersMap = new Map<string, ResearchPaper>(); // Dedup by ID

            // Execute sequentially to update UI nicely, or parallel for speed? 
            // Let's do sequential for better "agent watching" UX
            let completedSteps = 0;
            const totalSteps = plan.length;

            for (const step of plan) {
                // Update step status to searching
                setSteps(prev => prev.map(s => s.id === step.id ? { ...s, status: 'searching' } : s));

                const foundPapers = await deepResearchService.executeSearchStep(step);

                foundPapers.forEach(p => papersMap.set(p.id, p));

                // Update step status to completed
                setSteps(prev => prev.map(s => s.id === step.id ? { ...s, status: 'completed', papersFound: foundPapers.length } : s));

                completedSteps++;
                setProgress(20 + (completedSteps / totalSteps) * 50); // Scale up to 70%
            }

            const uniquePapers = Array.from(papersMap.values());
            setAllPapers(uniquePapers);

            // 3. Synthesize
            setStatus('synthesizing');
            setProgress(80);

            const finalReport = await deepResearchService.synthesizeReport(topic, uniquePapers, model);
            setReport(finalReport);

            setStatus('completed');
            setProgress(100);

        } catch (error) {
            console.error("Deep Research Failed:", error);
            alert("Deep research encountered an error. Please try again.");
            setStatus('idle');
        }
    };

    const handleSaveToWorkspace = () => {
        onAddPapersToWorkspace(allPapers);
        setIsSaved(true);
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-background/90 backdrop-blur-sm z-50 flex items-center justify-center p-4">
            <div className="bg-card rounded-xl shadow-2xl w-full max-w-5xl h-[85vh] flex flex-col border border-border overflow-hidden">
                {/* Header */}
                <header className="p-5 border-b border-border bg-muted/30 flex justify-between items-center">
                    <div className="flex items-center gap-3">
                        <div className="bg-purple-100 text-purple-700 p-2 rounded-lg">
                            <AnalyzeIcon className="w-6 h-6" />
                        </div>
                        <div>
                            <h2 className="text-xl font-bold text-foreground">Deep Research Agent</h2>
                            <p className="text-sm text-muted-foreground">Autonomous multi-step literature review.</p>
                        </div>
                    </div>
                    <button onClick={onClose} className="text-muted-foreground hover:text-foreground">
                        Close
                    </button>
                </header>

                <div className="flex flex-grow overflow-hidden">
                    {/* Sidebar: Agent Status & Steps */}
                    <aside className="w-1/3 border-r border-border bg-muted/10 flex flex-col">
                        <div className="p-4 border-b border-border">
                            {status === 'idle' ? (
                                <div className="space-y-4">
                                    <div>
                                        <label className="block text-sm font-medium mb-2">Research Topic</label>
                                        <textarea 
                                            value={topic}
                                            onChange={(e) => setTopic(e.target.value)}
                                            className="w-full p-3 rounded-md border bg-background text-sm"
                                            rows={4}
                                            placeholder="e.g., The impact of Generative AI on software engineering productivity..."
                                        />
                                    </div>
                                    <button 
                                        onClick={startDeepResearch}
                                        disabled={!topic.trim()}
                                        className="w-full py-2 bg-primary text-primary-foreground font-semibold rounded-md hover:bg-primary/90 disabled:opacity-50"
                                    >
                                        Start Research
                                    </button>
                                </div>
                            ) : (
                                <div>
                                    <div className="flex justify-between text-xs font-semibold uppercase tracking-wider text-muted-foreground mb-2">
                                        <span>Progress</span>
                                        <span>{Math.round(progress)}%</span>
                                    </div>
                                    <div className="w-full bg-muted rounded-full h-2 mb-4">
                                        <div className="bg-purple-600 h-2 rounded-full transition-all duration-500" style={{ width: `${progress}%` }}></div>
                                    </div>
                                    <p className="font-semibold text-foreground animate-pulse">
                                        {status === 'planning' && "Generating research plan..."}
                                        {status === 'researching' && "Executing search queries..."}
                                        {status === 'synthesizing' && "Writing final report..."}
                                        {status === 'completed' && "Research Completed"}
                                    </p>
                                </div>
                            )}
                        </div>

                        <div className="flex-grow overflow-y-auto p-4 space-y-3">
                            {steps.map((step, idx) => (
                                <div key={step.id} className={`p-3 rounded-lg border text-sm transition-colors ${
                                    step.status === 'completed' ? 'bg-green-50 border-green-200' :
                                    step.status === 'searching' ? 'bg-blue-50 border-blue-200' :
                                    'bg-card border-border'
                                }`}>
                                    <div className="flex items-start justify-between gap-2">
                                        <div className="flex items-center gap-2">
                                            {step.status === 'completed' ? <CheckIcon className="w-4 h-4 text-green-600" /> :
                                             step.status === 'searching' ? <div className="w-4 h-4 rounded-full border-2 border-blue-600 border-t-transparent animate-spin" /> :
                                             <SearchIcon className="w-4 h-4 text-muted-foreground" />}
                                            <span className="font-medium text-foreground">{step.query}</span>
                                        </div>
                                        {step.papersFound > 0 && (
                                            <span className="text-xs bg-white px-2 py-0.5 rounded-full border shadow-sm">
                                                {step.papersFound} papers
                                            </span>
                                        )}
                                    </div>
                                </div>
                            ))}
                            {allPapers.length > 0 && status !== 'idle' && (
                                <div className="mt-6 pt-4 border-t border-border">
                                    <h4 className="font-bold text-sm text-foreground mb-2">Total Sources Found: {allPapers.length}</h4>
                                    <div className="max-h-40 overflow-y-auto space-y-1">
                                        {allPapers.map((p, i) => (
                                            <div key={i} className="text-xs text-muted-foreground truncate pl-2 border-l-2 border-muted">
                                                [{i+1}] {p.title}
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            )}
                        </div>
                    </aside>

                    {/* Main Content: Report */}
                    <main className="w-2/3 bg-background flex flex-col">
                        {status === 'completed' && report ? (
                            <div className="flex-grow overflow-y-auto p-8">
                                <div className="max-w-3xl mx-auto prose prose-slate">
                                    <h1 className="text-3xl font-bold text-foreground mb-2">{report.title}</h1>
                                    <div className="p-4 bg-purple-50 rounded-lg border border-purple-100 mb-8 not-prose">
                                        <h3 className="text-sm font-bold text-purple-800 uppercase tracking-wide mb-2">Executive Summary</h3>
                                        <p className="text-purple-900 leading-relaxed">{report.summary}</p>
                                    </div>

                                    {report.sections.map((section, idx) => (
                                        <div key={idx} className="mb-8">
                                            <h2 className="text-xl font-bold text-foreground border-b pb-2 mb-4">{section.heading}</h2>
                                            <div className="text-foreground leading-relaxed whitespace-pre-line">
                                                {section.content}
                                            </div>
                                        </div>
                                    ))}

                                    <div className="mt-12 pt-8 border-t border-border">
                                        <h2 className="text-xl font-bold text-foreground mb-4">References</h2>
                                        <ul className="list-decimal list-outside pl-5 space-y-2 text-sm text-muted-foreground">
                                            {report.references.map((p, i) => (
                                                <li key={i}>
                                                    <span className="font-medium text-foreground">{p.authors}</span> ({p.year}). 
                                                    <a href={p.sourceURL} target="_blank" rel="noopener noreferrer" className="text-primary hover:underline ml-1">
                                                        {p.title}
                                                    </a>. {p.journal || ''}
                                                </li>
                                            ))}
                                        </ul>
                                    </div>
                                </div>
                            </div>
                        ) : (
                            <div className="flex-grow flex flex-col items-center justify-center text-muted-foreground p-8">
                                {status === 'idle' ? (
                                    <>
                                        <div className="w-16 h-16 bg-muted rounded-full flex items-center justify-center mb-4">
                                            <ScholarIcon className="w-8 h-8 text-muted-foreground" />
                                        </div>
                                        <p className="text-lg font-medium">Ready to research.</p>
                                        <p className="text-sm">Enter a topic on the left to begin the agent loop.</p>
                                    </>
                                ) : (
                                    <>
                                        <LoadingSpinner />
                                        <p className="mt-4 font-medium">
                                            {status === 'synthesizing' ? 'Synthesizing final report...' : 'Agent is working...'}
                                        </p>
                                    </>
                                )}
                            </div>
                        )}

                        {/* Footer Actions */}
                        {status === 'completed' && (
                            <div className="p-4 border-t border-border bg-card flex justify-end gap-3">
                                <button 
                                    onClick={handleSaveToWorkspace}
                                    disabled={isSaved}
                                    className={`px-4 py-2 rounded-md font-semibold flex items-center gap-2 transition-colors ${
                                        isSaved 
                                        ? 'bg-green-100 text-green-700 cursor-default' 
                                        : 'bg-primary text-primary-foreground hover:bg-primary/90'
                                    }`}
                                >
                                    {isSaved ? <CheckIcon className="w-4 h-4" /> : <AddIcon className="w-4 h-4" />}
                                    {isSaved ? "Saved to Workspace" : "Save All Sources to Workspace"}
                                </button>
                            </div>
                        )}
                    </main>
                </div>
            </div>
        </div>
    );
};

