import type { ResearchPaper, CrossrefWork } from '../types';

// Helper to normalize strings for comparison by removing case and non-alphanumeric characters.
const normalizeString = (str: string) => str.toLowerCase().replace(/[^a-z0-9]/g, '');

// Headers for "Polite" pool usage to avoid rate limits
const HEADERS = {
    'User-Agent': 'AI-Research-Explorer/1.0 (mailto:contact@ai-research-explorer.com)'
};

// Caching configuration
const CACHE_TTL_MS = 15 * 60 * 1000; // 15 minutes cache for Crossref data

interface CacheEntry<T> {
    data: T;
    timestamp: number;
}

const doiCache = new Map<string, CacheEntry<CrossrefWork | null>>();
const searchCache = new Map<string, CacheEntry<CrossrefWork | null>>();
const cslCache = new Map<string, CacheEntry<object | null>>();

/**
 * Robust fetch wrapper with timeout and graceful error handling.
 */
const safeFetch = async (url: string): Promise<Response | null> => {
    try {
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 8000); // 8 second timeout
        const response = await fetch(url, { headers: HEADERS, signal: controller.signal });
        clearTimeout(timeoutId);
        return response;
    } catch (error) {
        // Log as warning instead of error to handle expected network/CORS issues gracefully
        const msg = error instanceof Error ? error.message : String(error);
        console.warn(`Crossref request failed (${msg}):`, url);
        return null;
    }
};

/**
 * Checks if the first author of the local paper matches any of the authors from the Crossref result.
 * @param paperAuthors The author string from the local ResearchPaper object.
 * @param crossrefAuthors The array of author objects from the Crossref API response.
 * @returns A boolean indicating if a likely match was found.
 */
const checkAuthorMatch = (paperAuthors: string, crossrefAuthors: CrossrefWork['author']): boolean => {
    if (!crossrefAuthors || crossrefAuthors.length === 0) return false;

    // Get the last name of the first author from the local paper data.
    const firstPaperAuthorLastName = paperAuthors.split(',')[0].trim().split(' ').pop()?.toLowerCase();
    if (!firstPaperAuthorLastName) return false;

    // Check if any author in the Crossref data has a matching family name or a full name containing the last name.
    return crossrefAuthors.some(author => {
        const familyName = author.family?.toLowerCase();
        const fullName = author.name?.toLowerCase();
        return familyName === firstPaperAuthorLastName || fullName?.includes(firstPaperAuthorLastName);
    });
};

/**
 * Fetches paper metadata directly by DOI from Crossref.
 * This is significantly faster and more reliable than searching by title.
 * @param doi The DOI of the paper.
 * @returns A promise that resolves to a `CrossrefWork` object if found, otherwise null.
 */
export const fetchWorkByDoi = async (doi: string): Promise<CrossrefWork | null> => {
    const cacheKey = doi.toLowerCase();
    const cached = doiCache.get(cacheKey);
    if (cached && (Date.now() - cached.timestamp < CACHE_TTL_MS)) {
        return cached.data;
    }

    const url = `https://api.crossref.org/works/${encodeURIComponent(doi)}`;

    const response = await safeFetch(url);
    if (!response || !response.ok) {
        if (response) console.warn(`Crossref DOI fetch returned status: ${response.status}`);
        return null;
    }

    try {
        const data = await response.json();
        const result = data.message as CrossrefWork;
        doiCache.set(cacheKey, { data: result, timestamp: Date.now() });
        return result;
    } catch (error) {
        console.warn(`Error parsing Crossref JSON for DOI ${doi}:`, error);
        return null;
    }
};

/**
 * Fetches paper metadata from the Crossref API to find a high-confidence match.
 * @param paper The `ResearchPaper` object to verify.
 * @returns A promise that resolves to a `CrossrefWork` object if a match is found, otherwise null.
 */
export const fetchPaperFromCrossref = async (paper: ResearchPaper): Promise<CrossrefWork | null> => {
    // Generate a simple cache key based on title and first author to handle repeated lookups for the same paper object
    const cacheKey = `${normalizeString(paper.title)}|${normalizeString(paper.authors.split(',')[0])}`;
    const cached = searchCache.get(cacheKey);
    if (cached && (Date.now() - cached.timestamp < CACHE_TTL_MS)) {
        return cached.data;
    }

    // Construct the API URL. Querying by title is generally effective. We fetch 3 results to increase our chances of a match.
    const url = `https://api.crossref.org/works?query.bibliographic=${encodeURIComponent(paper.title)}&rows=3`;

    const response = await safeFetch(url);
    if (!response || !response.ok) {
        return null;
    }

    try {
        const data = await response.json();
        const items = data.message?.items;

        if (!items || items.length === 0) {
            searchCache.set(cacheKey, { data: null, timestamp: Date.now() });
            return null; // No results from Crossref.
        }

        // Iterate through the top results to find the best match.
        const normalizedPaperTitle = normalizeString(paper.title);

        let bestMatch: CrossrefWork | null = null;

        for (const item of items) {
            const apiTitle = item.title?.[0];
            if (!apiTitle) continue;

            const normalizedApiTitle = normalizeString(apiTitle);

            // A match is considered high-confidence if the titles are very similar AND an author name matches.
            const titleIsSimilar = normalizedApiTitle.includes(normalizedPaperTitle) || normalizedPaperTitle.includes(normalizedApiTitle);

            if (titleIsSimilar && checkAuthorMatch(paper.authors, item.author)) {
                bestMatch = item as CrossrefWork; // Found a confident match.
                break;
            }
        }

        searchCache.set(cacheKey, { data: bestMatch, timestamp: Date.now() });
        return bestMatch;
    } catch (error) {
        console.warn("Error parsing Crossref search response:", error);
        return null;
    }
};

/**
 * Finds the DOI for a given paper using the Crossref API.
 * It first attempts a highly specific query with title and author, and falls back to a broader search if needed.
 * @param paper The `ResearchPaper` object to search for.
 * @returns A promise that resolves to the DOI string if found, otherwise null.
 */
export const findDoiForPaper = async (paper: ResearchPaper): Promise<string | null> => {
    try {
        // Attempt 1: Highly specific query using title and first author's last name.
        const firstAuthorLastName = paper.authors.split(',')[0].trim().split(' ').pop();

        if (firstAuthorLastName) {
            const url = `https://api.crossref.org/works?query.title=${encodeURIComponent(paper.title)}&query.author=${encodeURIComponent(firstAuthorLastName)}&rows=1&select=DOI,title,author`;

            const response = await safeFetch(url);
            if (response && response.ok) {
                const data = await response.json();
                const item = data.message?.items?.[0];

                if (item) {
                    // Perform a confidence check on the result.
                    const apiTitle = item.title?.[0];
                    if (apiTitle) {
                        const normalizedPaperTitle = normalizeString(paper.title);
                        const normalizedApiTitle = normalizeString(apiTitle);
                        const titleIsSimilar = normalizedApiTitle.includes(normalizedPaperTitle) || normalizedPaperTitle.includes(normalizedApiTitle);

                        if (titleIsSimilar && checkAuthorMatch(paper.authors, item.author) && item.DOI) {
                            return item.DOI; // High-confidence match from specific query.
                        }
                    }
                }
            }
        }

        // Attempt 2: Fallback to the broader verification-style search if the specific query fails or yields no confident match.
        const crossrefResult = await fetchPaperFromCrossref(paper);
        if (crossrefResult && crossrefResult.DOI) {
            return crossrefResult.DOI;
        }

        return null; // No DOI found through either method.
    } catch (error) {
        console.warn("Error finding DOI:", error);
        return null;
    }
};

/**
 * Fetches a perfectly formatted CSL-JSON object directly from the Crossref API.
 * This is the most reliable way to get citation data for a paper with a DOI.
 * @param doi The Digital Object Identifier of the paper.
 * @returns A promise that resolves to a CSL-JSON object or null if not found.
 */
export const fetchCslFromCrossref = async (doi: string): Promise<object | null> => {
    const cacheKey = doi.toLowerCase();
    const cached = cslCache.get(cacheKey);
    if (cached && (Date.now() - cached.timestamp < CACHE_TTL_MS)) {
        return cached.data;
    }

    const url = `https://api.crossref.org/works/${encodeURIComponent(doi)}/transform/application/vnd.citationstyles.csl+json`;

    const response = await safeFetch(url);
    if (!response || !response.ok) {
        if (response) console.warn(`Crossref CSL fetch failed for DOI ${doi}: Status ${response.status}`);
        return null;
    }

    try {
        const cslData = await response.json();
        cslCache.set(cacheKey, { data: cslData, timestamp: Date.now() });
        return cslData;
    } catch (error) {
        console.warn(`Error parsing CSL JSON for DOI ${doi}:`, error);
        return null;
    }
};

export interface DoajArticle {
    bibjson: {
        title: string;
        identifier: { type: string; id: string }[];
        journal: {
            in_doaj: boolean;
            title: string;
        };
    };
}

// Client-side cache for DOAJ results
interface CacheEntry {
    result: DoajArticle | null;
    timestamp: number;
}
const doajCache = new Map<string, CacheEntry>();
const CACHE_TTL_MS = 24 * 60 * 60 * 1000; // 24 hours

/**
 * Searches the DOAJ API for an article by its DOI.
 * A successful find indicates the article is published in a vetted open access journal.
 * @param doi The Digital Object Identifier of the paper.
 * @returns A promise that resolves to the DOAJ article object if found, otherwise null.
 */
export const searchByDoi = async (doi: string): Promise<DoajArticle | null> => {
    // Check cache first
    const cacheKey = doi.toLowerCase();
    const cached = doajCache.get(cacheKey);
    if (cached && (Date.now() - cached.timestamp < CACHE_TTL_MS)) {
        return cached.result;
    }

    // The DOAJ API is public and doesn't require an API key.
    const url = `https://doaj.org/api/v4/articles/doi/${encodeURIComponent(doi)}`;

    try {
        const controller = new AbortController();
        // Set a short timeout to avoid hanging on failed requests
        const timeoutId = setTimeout(() => controller.abort(), 5000);

        const response = await fetch(url, { signal: controller.signal });
        clearTimeout(timeoutId);

        if (!response.ok) {
            if (response.status === 404) {
                // This is expected if the DOI is not in DOAJ.
                doajCache.set(cacheKey, { result: null, timestamp: Date.now() });
                return null;
            }
            // For other errors (500s), log a warning but don't fail hard.
            console.warn(`DOAJ API returned status ${response.status} for DOI ${doi}`);
            return null;
        }

        const data = await response.json();

        // Check if the journal is actually in DOAJ, as a sanity check.
        if (data?.bibjson?.journal?.in_doaj) {
            const result = data as DoajArticle;
            doajCache.set(cacheKey, { result, timestamp: Date.now() });
            return result;
        }

        doajCache.set(cacheKey, { result: null, timestamp: Date.now() });
        return null;

    } catch (error) {
        // Handle network errors (e.g. CORS) gracefully to avoid "Failed to fetch" console errors.
        const msg = error instanceof Error ? error.message : String(error);
        if (msg.includes('Failed to fetch') || msg.includes('NetworkError') || msg.includes('aborted')) {
             console.warn(`Skipping DOAJ check for ${doi} due to network/CORS restriction.`);
        } else {
             console.warn(`Error querying DOAJ for DOI ${doi}:`, msg);
        }
        return null;
    }
};

import { GoogleGenAI } from "@google/genai";

const apiKey = typeof process !== 'undefined' ? process.env.API_KEY : '';
const ai = new GoogleGenAI({ apiKey });
const model = "text-embedding-004";

// Caching for embeddings
const embeddingCache = new Map<string, { embedding: number[], timestamp: number }>();
const CACHE_TTL = 24 * 60 * 60 * 1000; // 24 hours

// Helper for exponential backoff
const retryWithBackoff = async <T>(operation: () => Promise<T>, retries: number = 5, delay: number = 2000): Promise<T> => {
    try {
        return await operation();
    } catch (error: any) {
        const isRateLimit = error?.status === 429 || error?.code === 429 || error?.message?.includes('429') || error?.message?.includes('RESOURCE_EXHAUSTED');
        const isServerOverload = error?.status === 503 || error?.code === 503;

        if (retries > 0 && (isRateLimit || isServerOverload)) {
            console.warn(`[Embedding API] Rate limit hit. Retrying in ${delay}ms... (Retries left: ${retries})`);
            await new Promise(resolve => setTimeout(resolve, delay));
            return retryWithBackoff(operation, retries - 1, delay * 2);
        }
        throw error;
    }
};

/**
 * Generates an embedding for a single piece of text.
 */
export const embedText = async (text: string): Promise<number[]> => {
    if (!text || text.trim() === '') {
        return [];
    }

    // Check cache
    const cacheKey = text.trim();
    if (embeddingCache.has(cacheKey)) {
        const entry = embeddingCache.get(cacheKey)!;
        if (Date.now() - entry.timestamp < CACHE_TTL) {
            return entry.embedding;
        }
    }

    try {
        // Use 'contents' as the parameter for the text content
        const response = await retryWithBackoff(() => ai.models.embedContent({ 
            model, 
            contents: text
        })) as any;

        const embedding = response.embedding?.values || [];

        // Update cache
        if (embedding.length > 0) {
            embeddingCache.set(cacheKey, { embedding, timestamp: Date.now() });
        }

        return embedding;
    } catch (e) {
        console.error(`Error embedding text: "${text.substring(0, 50)}..."`, e);
        return [];
    }
};

/**
 * Generates embeddings for multiple pieces of text.
 * Falls back to parallel single requests since batchEmbedContents is not reliably available.
 */
export const batchEmbedText = async (texts: string[]): Promise<number[][]> => {
    if (!texts || texts.length === 0) {
        return [];
    }

    // Create a map to restore original order and handle empty texts
    const textMap = new Map<number, string>();
    texts.forEach((text, i) => {
        if (text && text.trim() !== '') {
            textMap.set(i, text);
        }
    });

    const validTexts = Array.from(textMap.values());
    if (validTexts.length === 0) {
        return texts.map(() => []);
    }

    try {
        // Execute embeddings in parallel
        // Note: For very large batches (e.g. > 100), one might want to chunk this 
        // to avoid hitting rate limits, but for typical UI usage, Promise.all is sufficient.
        const embeddings = await Promise.all(validTexts.map(text => embedText(text)));

        const resultMap = new Map<string, number[]>();
        validTexts.forEach((text, index) => {
            resultMap.set(text, embeddings[index]);
        });

        // Reconstruct the original array order
        const finalResults: number[][] = new Array(texts.length).fill([]);
        for (const [originalIndex, text] of textMap.entries()) {
            finalResults[originalIndex] = resultMap.get(text) || [];
        }
        return finalResults;

    } catch (error) {
        console.error("Error during batch embedding.", error);
        return texts.map(() => []);
    }
};

