import { GoogleGenAI, Type } from "@google/genai";
import type { ModelDefinition, ResearchPaper, DeepResearchStep, DeepResearchReport } from "../types";
import * as openalexService from "./openalexService";
import { createPaperId } from "./extensionService";

const apiKey = typeof process !== 'undefined' ? process.env.API_KEY : '';
const ai = new GoogleGenAI({ apiKey });

// Helper to sanitize JSON
const safeJsonParse = (jsonString: string) => {
    try {
        const cleanedString = jsonString.replace(/```json/g, '').replace(/```/g, '').trim();
        return JSON.parse(cleanedString);
    } catch (e) {
        console.error("Failed to parse JSON:", e);
        return null;
    }
};

/**
 * TOKEN OPTIMIZATION:
 * Compresses the list of papers into a token-efficient string format for the LLM.
 */
const compressPapersForContext = (papers: ResearchPaper[], maxPapers: number = 15): string => {
    const uniquePapers = Array.from(new Map(papers.map(p => [p.id, p])).values());
    uniquePapers.sort((a, b) => (b.citations || 0) - (a.citations || 0));
    const topPapers = uniquePapers.slice(0, maxPapers);

    return topPapers.map((p, i) => {
        const cleanAbstract = (p.abstract || "No abstract.").replace(/\s+/g, ' ').substring(0, 1200);
        return `[${i + 1}] DOI: ${p.doi || 'N/A'}
TITLE: ${p.title}
YEAR: ${p.year}
ABSTRACT: ${cleanAbstract}`;
    }).join('\n\n');
};

const planSchema = {
    type: Type.OBJECT,
    properties: {
        sub_queries: {
            type: Type.ARRAY,
            items: { type: Type.STRING },
            description: "A list of exactly 3 distinct, targeted search queries."
        }
    },
    required: ["sub_queries"]
};

export const generateResearchPlan = async (topic: string, model: ModelDefinition): Promise<DeepResearchStep[]> => {
    const isTechnical = /implement|architecture|code|system|agent|software|algorithm/i.test(topic);

    const prompt = `Plan a comprehensive literature review on: "${topic}".
    ${isTechnical ? "This is a technical implementation query. Focus queries on system architectures, methodologies, and technical challenges." : ""}
    Generate exactly 3 distinct search queries to cover:
    1. The core theoretical concept.
    2. State-of-the-art methodologies and technical implementations.
    3. Recent (post-2021) evaluations and comparative studies.

    Return JSON with "sub_queries".`;

    try {
        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview", 
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: planSchema,
            }
        });

        const result = safeJsonParse(response.text || '');
        if (!result || !result.sub_queries) return [];

        return result.sub_queries.map((q: string, i: number) => ({
            id: `step_${i}`,
            query: q,
            status: 'pending',
            papersFound: 0
        }));
    } catch (e) {
        console.error("Deep Research Plan Error:", e);
        return [{ id: 'step_0', query: topic, status: 'pending', papersFound: 0 }];
    }
};

export const executeSearchStep = async (step: DeepResearchStep): Promise<ResearchPaper[]> => {
    try {
        const { papers } = await openalexService.searchOpenAlex(step.query, {
            startYear: '', endYear: '', authors: '', excludeKeywords: '', inclusionCriteria: '', exclusionCriteria: '', studyDesign: 'any',
            isOpenAccess: false
        });
        return papers.slice(0, 8); 
    } catch (e) {
        console.error(`Search failed for ${step.query}:`, e);
        return [];
    }
};

const reportSchema = {
    type: Type.OBJECT,
    properties: {
        title: { type: Type.STRING },
        summary: { type: Type.STRING },
        sections: {
            type: Type.ARRAY,
            items: {
                type: Type.OBJECT,
                properties: {
                    heading: { type: Type.STRING },
                    content: { type: Type.STRING, description: "Markdown content for this section." }
                },
                required: ["heading", "content"]
            }
        }
    },
    required: ["title", "summary", "sections"]
};

export const synthesizeReport = async (topic: string, papers: ResearchPaper[], model: ModelDefinition): Promise<DeepResearchReport> => {
    const context = compressPapersForContext(papers, 18);
    const isTechnical = /implement|architecture|code|system|agent|software|algorithm/i.test(topic);

    const prompt = `Act as a Senior Research Lead. Write a comprehensive literature review report on: "${topic}".

    Source Material (Abstracts of Top Papers):
    ${context}

    Instructions:
    1. Synthesize the findings across all sources. Identify consistent patterns and notable disagreements.
    2. Cite sources using [1], [2] notation strictly matching the list provided.
    ${isTechnical ? "3. Include a section on 'Technical Implementation Strategies' or 'System Architectures' described in the literature." : "3. Focus on methodological trends and empirical outcomes."}
    4. Structure: Title, Executive Summary, 3-5 Detailed Thematic Sections.
    5. Tone: Academic, rigorous, and highly informative.

    Return a JSON object matching the report schema. Use Markdown for section contents.`;

    try {
        const response = await ai.models.generateContent({
            model: "gemini-3-pro-preview",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: reportSchema,
                thinkingConfig: { thinkingBudget: 16000 }
            }
        });

        const result = safeJsonParse(response.text || '');
        if (!result) throw new Error("Failed to parse report.");

        const uniquePapers = Array.from(new Map(papers.map(p => [p.id, p])).values());
        uniquePapers.sort((a, b) => (b.citations || 0) - (a.citations || 0));
        const references = uniquePapers.slice(0, 18);

        return {
            title: result.title,
            summary: result.summary,
            sections: result.sections,
            references: references
        };
    } catch (e) {
        console.error("Report Synthesis Error:", e);
        throw new Error("Failed to generate research report.");
    }
};

import React, { useState, useEffect } from 'react';
import type { ModelDefinition, DeepResearchStep, DeepResearchReport, ResearchPaper } from '../types';
import * as deepResearchService from '../services/deepResearchService';
import { AnalyzeIcon } from './icons/AnalyzeIcon';
import { LoadingSpinner } from './LoadingSpinner';
import { CheckIcon } from './icons/CheckIcon';
import { SearchIcon } from './icons/SearchIcon';
import { ScholarIcon } from './icons/ScholarIcon';
import { AddIcon } from './icons/AddIcon';
import { ExportIcon } from './icons/ExportIcon';

interface DeepResearchModalProps {
    isOpen: boolean;
    onClose: () => void;
    initialTopic: string;
    model: ModelDefinition;
    onAddPapersToWorkspace: (papers: ResearchPaper[]) => void;
}

export const DeepResearchModal: React.FC<DeepResearchModalProps> = ({ isOpen, onClose, initialTopic, model, onAddPapersToWorkspace }) => {
    const [topic, setTopic] = useState(initialTopic);
    const [status, setStatus] = useState<'idle' | 'planning' | 'researching' | 'synthesizing' | 'completed'>('idle');
    const [steps, setSteps] = useState<DeepResearchStep[]>([]);
    const [report, setReport] = useState<DeepResearchReport | null>(null);
    const [progress, setProgress] = useState(0);
    const [isSaved, setIsSaved] = useState(false);

    useEffect(() => {
        if (isOpen) {
            setTopic(initialTopic);
            setStatus('idle');
            setSteps([]);
            setReport(null);
            setProgress(0);
            setIsSaved(false);
        }
    }, [isOpen, initialTopic]);

    const startDeepResearch = async () => {
        if (!topic.trim()) return;

        setStatus('planning');
        setProgress(5);

        try {
            const plan = await deepResearchService.generateResearchPlan(topic, model);
            setSteps(plan);
            setStatus('researching');
            setProgress(15);

            let completedSteps = 0;
            const totalSteps = plan.length;

            const searchPromises = plan.map(async (step) => {
                setSteps(prev => prev.map(s => s.id === step.id ? { ...s, status: 'searching' } : s));

                try {
                    const foundPapers = await deepResearchService.executeSearchStep(step);
                    setSteps(prev => prev.map(s => s.id === step.id ? { ...s, status: 'completed', papersFound: foundPapers.length } : s));
                    completedSteps++;
                    setProgress(prev => Math.max(prev, 15 + (completedSteps / totalSteps) * 60));
                    return foundPapers;
                } catch (e) {
                    console.error(`Error in search step ${step.id}:`, e);
                    setSteps(prev => prev.map(s => s.id === step.id ? { ...s, status: 'error' } : s));
                    completedSteps++;
                    setProgress(prev => Math.max(prev, 15 + (completedSteps / totalSteps) * 60));
                    return [];
                }
            });

            const results = await Promise.all(searchPromises);
            const allFoundPapers = results.flat();

            setStatus('synthesizing');
            setProgress(80);

            const finalReport = await deepResearchService.synthesizeReport(topic, allFoundPapers, model);
            setReport(finalReport);

            setStatus('completed');
            setProgress(100);

        } catch (error) {
            console.error("Deep Research Failed:", error);
            alert("Deep research encountered an error. Please try again.");
            setStatus('idle');
        }
    };

    const handleSaveToWorkspace = () => {
        if (report?.references) {
            onAddPapersToWorkspace(report.references);
            setIsSaved(true);
        }
    };

    const handleExportMarkdown = () => {
        if (!report) return;

        let md = `# ${report.title}\n\n`;
        md += `## Executive Summary\n\n${report.summary}\n\n`;

        report.sections.forEach(s => {
            md += `## ${s.heading}\n\n${s.content}\n\n`;
        });

        md += `## References\n\n`;
        report.references.forEach((p, i) => {
            md += `[${i + 1}] ${p.authors} (${p.year}). **${p.title}**. ${p.journal || ''} [Link](${p.sourceURL})\n\n`;
        });

        const blob = new Blob([md], { type: 'text/markdown' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `${report.title.replace(/\s+/g, '_')}_Report.md`;
        a.click();
        URL.revokeObjectURL(url);
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-background/90 backdrop-blur-sm z-50 flex items-center justify-center p-4">
            <div className="bg-card rounded-xl shadow-2xl w-full max-w-6xl h-[90vh] flex flex-col border border-border overflow-hidden">
                <header className="p-5 border-b border-border bg-muted/30 flex justify-between items-center">
                    <div className="flex items-center gap-3">
                        <div className="bg-purple-600 text-white p-2 rounded-lg">
                            <AnalyzeIcon className="w-6 h-6" />
                        </div>
                        <div>
                            <h2 className="text-xl font-bold text-foreground">Deep Research Agent</h2>
                            <p className="text-sm text-muted-foreground font-medium">Autonomous Technical & Academic Literature Synthesis</p>
                        </div>
                    </div>
                    <button onClick={onClose} className="p-2 text-muted-foreground hover:bg-accent rounded-full">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                </header>

                <div className="flex flex-grow overflow-hidden">
                    <aside className="w-80 border-r border-border bg-muted/10 flex flex-col shrink-0">
                        <div className="p-4 border-b border-border">
                            {status === 'idle' ? (
                                <div className="space-y-4">
                                    <div>
                                        <label className="block text-xs font-bold uppercase tracking-wider text-muted-foreground mb-2">Research Topic</label>
                                        <textarea 
                                            value={topic}
                                            onChange={(e) => setTopic(e.target.value)}
                                            className="w-full p-3 rounded-md border bg-background text-sm min-h-[100px] focus:ring-2 focus:ring-primary"
                                            placeholder="e.g., Implementing efficient RAG architectures for multi-agent systems..."
                                        />
                                    </div>
                                    <button 
                                        onClick={startDeepResearch}
                                        disabled={!topic.trim()}
                                        className="w-full py-2 bg-primary text-primary-foreground font-semibold rounded-md hover:bg-primary/90 disabled:opacity-50 transition-all shadow-sm"
                                    >
                                        Start Agentic Research
                                    </button>
                                </div>
                            ) : (
                                <div>
                                    <div className="flex justify-between text-xs font-semibold uppercase tracking-wider text-muted-foreground mb-2">
                                        <span>Agent Progress</span>
                                        <span>{Math.round(progress)}%</span>
                                    </div>
                                    <div className="w-full bg-muted rounded-full h-2 mb-4">
                                        <div className="bg-purple-600 h-2 rounded-full transition-all duration-500 shadow-sm" style={{ width: `${progress}%` }}></div>
                                    </div>
                                    <div className="flex items-center gap-2 text-xs font-medium text-foreground">
                                        <div className="w-2 h-2 bg-purple-600 rounded-full animate-ping" />
                                        <span>
                                            {status === 'planning' && "Generating search strategy..."}
                                            {status === 'researching' && "Parallel retrieval active..."}
                                            {status === 'synthesizing' && "Reasoning across papers (Pro)..."}
                                            {status === 'completed' && "Report Ready"}
                                        </span>
                                    </div>
                                </div>
                            )}
                        </div>

                        <div className="flex-grow overflow-y-auto p-4 space-y-3">
                            <h3 className="text-[10px] font-bold text-muted-foreground uppercase tracking-widest mb-2">Search Steps</h3>
                            {steps.map((step) => (
                                <div key={step.id} className={`p-3 rounded-lg border text-xs transition-all ${
                                    step.status === 'completed' ? 'bg-green-50 border-green-200' :
                                    step.status === 'searching' ? 'bg-blue-50 border-blue-200 ring-1 ring-blue-100' :
                                    'bg-card border-border'
                                }`}>
                                    <div className="flex items-start justify-between gap-2">
                                        <div className="flex items-center gap-2">
                                            {step.status === 'completed' ? <CheckIcon className="w-3 h-3 text-green-600" /> :
                                             step.status === 'searching' ? <div className="w-3 h-3 rounded-full border-2 border-blue-600 border-t-transparent animate-spin" /> :
                                             <SearchIcon className="w-3 h-3 text-muted-foreground" />}
                                            <span className="font-medium text-foreground truncate max-w-[180px]">{step.query}</span>
                                        </div>
                                        {step.papersFound > 0 && (
