                                                <section key={idx} className="animate-fade-in" style={{ animationDelay: `${idx * 150}ms` }}>
                                                    <h2 className="text-2xl font-bold text-foreground border-b border-border pb-3 mb-5 flex items-center gap-3">
                                                        <span className="text-muted-foreground/30 font-mono text-lg">0{idx + 1}</span>
