}

export const DeepResearchModal: React.FC<DeepResearchModalProps> = ({ isOpen, onClose, initialTopic, model, onAddPapersToWorkspace }) => {
    const [topic, setTopic] = useState(initialTopic);
    const [status, setStatus] = useState<'idle' | 'planning' | 'researching' | 'synthesizing' | 'completed'>('idle');
