    useEffect(() => {
        if (isOpen) {
            setTopic(initialTopic);
            setStatus('idle');
            setSteps([]);
            setReport(null);
            setProgress(0);
            setIsSaved(false);
        }
    }, [isOpen, initialTopic]);

    const startDeepResearch = async () => {
        if (!topic.trim()) return;

        setStatus('planning');
        setProgress(5);

        try {
            const plan = await deepResearchService.generateResearchPlan(topic, model);
            setSteps(plan);
            setStatus('researching');
            setProgress(15);

            let completedSteps = 0;
            const totalSteps = plan.length;

            const searchPromises = plan.map(async (step) => {
                setSteps(prev => prev.map(s => s.id === step.id ? { ...s, status: 'searching' } : s));

                try {
                    const foundPapers = await deepResearchService.executeSearchStep(step);
                    setSteps(prev => prev.map(s => s.id === step.id ? { ...s, status: 'completed', papersFound: foundPapers.length } : s));
                    completedSteps++;
                    setProgress(prev => Math.max(prev, 15 + (completedSteps / totalSteps) * 60));
                    return foundPapers;
                } catch (e) {
                    console.error(`Error in search step ${step.id}:`, e);
                    setSteps(prev => prev.map(s => s.id === step.id ? { ...s, status: 'error' } : s));
                    completedSteps++;
                    setProgress(prev => Math.max(prev, 15 + (completedSteps / totalSteps) * 60));
                    return [];
                }
            });

            const results = await Promise.all(searchPromises);
            const allFoundPapers = results.flat();

            setStatus('synthesizing');
            setProgress(80);

            const finalReport = await deepResearchService.synthesizeReport(topic, allFoundPapers, model);
            setReport(finalReport);

            setStatus('completed');
            setProgress(100);

        } catch (error) {
            console.error("Deep Research Failed:", error);
            alert("Deep research encountered an error. Please try again.");
            setStatus('idle');
        }
    };

