export const generateSessionHighlights = async (papers: ResearchPaper[], topic: string, model: ModelDefinition): Promise<{ paperId: string; highlights: { category: string; text: string }[] }[]> => {
    if (papers.length === 0) return [];

    const papersContext = papers.map(p => `Paper ID: ${p.id}\nTitle: "${p.title}"\nAbstract: "${p.abstract}"`).join('\n\n---\n\n');

    const prompt = `You are a research assistant organizing a session on the topic: "${topic}".

    For each of the following papers, generate 2-3 specific, high-value insights or highlights relevant to this topic.

    **Instructions:**
    1. Focus on what makes each paper unique or valuable for the topic "${topic}".
    2. Format each highlight with a short 'category' label (e.g., **Novelty**, **Data**, **Outcome**, **Limitation**) and a 'text' description.
    3. Keep the descriptions concise (1 sentence).

    **Papers:**
    ${papersContext}

    Return a JSON array where each object corresponds to a paper (matched by Paper ID) and contains its highlights.`;

    try {
        const result = await generateJsonWithModel(prompt, model, highlightSchema);
        return result || [];
    } catch (error) {
        console.error("Error generating session highlights:", error);
        return [];
    }
};

