import { GoogleGenAI } from "@google/genai";
import type { ResearchPaper } from '../types';
import { cosineSimilarity } from '../utils/math';
import { embedText as embedTextUtil, batchEmbedText as batchEmbedTextUtil } from '../utils/embeddings';

// Fixed: Correct initialization of GoogleGenAI using process.env.API_KEY directly
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
const model = "text-embedding-004";

// Helper for exponential backoff (duplicated here to avoid circular dependency issues, or could be extracted to utils)
const retryWithBackoff = async <T>(operation: () => Promise<T>, retries: number = 5, delay: number = 2000): Promise<T> => {
    try {
        return await operation();
    } catch (error: any) {
        const isRateLimit = error?.status === 429 || error?.code === 429 || error?.message?.includes('429') || error?.message?.includes('RESOURCE_EXHAUSTED');
        const isServerOverload = error?.status === 503 || error?.code === 503;

        if (retries > 0 && (isRateLimit || isServerOverload)) {
            console.warn(`[Embedding API] Rate limit hit. Retrying in ${delay}ms... (Retries left: ${retries})`);
            await new Promise(resolve => setTimeout(resolve, delay));
            return retryWithBackoff(operation, retries - 1, delay * 2);
        }
        throw error;
    }
};

/**
 * Generates an embedding for a single piece of text.
 */
export const calculateSemanticScores = async (queryOrHypotheticalAnswer: string, papers: ResearchPaper[]): Promise<ResearchPaper[]> => {
    if (papers.length === 0) return [];

    try {
        // Use the util function but wrapped in retry logic if it wasn't already (util uses ai.models.embedContent directly)
        // Ideally utils/embeddings.ts should have the retry logic, but let's implement it here or rely on utils.
        // Actually, let's just use the utils which we will update to include retries.

        const queryEmbedding = await embedTextUtil(queryOrHypotheticalAnswer);

        const papersToEmbed = papers.filter(p => 
            p.abstract && 
            typeof p.abstract === 'string' && 
            p.abstract.trim() !== ''
        );

        if (papersToEmbed.length === 0) {
            return papers.map(p => ({ ...p, semanticScore: 0 }));
        }

        const abstractsToEmbed = papersToEmbed.map(p => p.abstract);

        const paperEmbeddings = await batchEmbedTextUtil(abstractsToEmbed);

        const embeddingMap = new Map<string, number[]>();
        papersToEmbed.forEach((paper, index) => {
            // Use the paper's actual ID for mapping
            embeddingMap.set(paper.id, paperEmbeddings[index]);
        });

        return papers.map((paper) => {
            const paperEmbedding = embeddingMap.get(paper.id);
            if (!paperEmbedding || paperEmbedding.length === 0) {
                return { ...paper, semanticScore: 0 };
            }

            const similarity = cosineSimilarity(queryEmbedding, paperEmbedding);
            // Convert similarity from [-1, 1] to a score from 0-100
            const score = Math.round(((similarity + 1) / 2) * 100); 
            return {
                ...paper,
                semanticScore: score,
            };
        });

    } catch (error) {
        console.error("Error calculating semantic scores:", error);
        return papers.map(p => ({ ...p, semanticScore: 0 }));
    }
};

import { GoogleGenAI } from "@google/genai";

// Fixed: Correct initialization of GoogleGenAI using process.env.API_KEY directly
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
const model = "text-embedding-004";

// Caching for embeddings
const embeddingCache = new Map<string, { embedding: number[], timestamp: number }>();
const CACHE_TTL = 24 * 60 * 60 * 1000; // 24 hours

// Helper for exponential backoff
const retryWithBackoff = async <T>(operation: () => Promise<T>, retries: number = 5, delay: number = 2000): Promise<T> => {
    try {
        return await operation();
    } catch (error: any) {
        const isRateLimit = error?.status === 429 || error?.code === 429 || error?.message?.includes('429') || error?.message?.includes('RESOURCE_EXHAUSTED');
        const isServerOverload = error?.status === 503 || error?.code === 503;

        if (retries > 0 && (isRateLimit || isServerOverload)) {
            console.warn(`[Embedding API] Rate limit hit. Retrying in ${delay}ms... (Retries left: ${retries})`);
            await new Promise(resolve => setTimeout(resolve, delay));
            return retryWithBackoff(operation, retries - 1, delay * 2);
        }
        throw error;
    }
};

/**
 * Generates an embedding for a single piece of text.
 */
export const embedText = async (text: string): Promise<number[]> => {
    if (!text || text.trim() === '') {
        return [];
    }

    // Check cache
    const cacheKey = text.trim();
    if (embeddingCache.has(cacheKey)) {
        const entry = embeddingCache.get(cacheKey)!;
        if (Date.now() - entry.timestamp < CACHE_TTL) {
            return entry.embedding;
        }
    }

    try {
        // Use 'contents' as the parameter for the text content
        const response = await retryWithBackoff(() => ai.models.embedContent({ 
            model, 
            contents: text
        })) as any;

        const embedding = response.embedding?.values || [];

        // Update cache
        if (embedding.length > 0) {
            embeddingCache.set(cacheKey, { embedding, timestamp: Date.now() });
        }

        return embedding;
    } catch (e) {
        console.error(`Error embedding text: "${text.substring(0, 50)}..."`, e);
        return [];
    }
};

/**
 * Generates embeddings for multiple pieces of text.
 * Falls back to parallel single requests since batchEmbedContents is not reliably available.
 */
export const batchEmbedText = async (texts: string[]): Promise<number[][]> => {
    if (!texts || texts.length === 0) {
        return [];
    }

    // Create a map to restore original order and handle empty texts
    const textMap = new Map<number, string>();
    texts.forEach((text, i) => {
        if (text && text.trim() !== '') {
            textMap.set(i, text);
        }
    });

    const validTexts = Array.from(textMap.values());
    if (validTexts.length === 0) {
        return texts.map(() => []);
    }

    try {
        // Execute embeddings in parallel
        // Note: For very large batches (e.g. > 100), one might want to chunk this 
        // to avoid hitting rate limits, but for typical UI usage, Promise.all is sufficient.
        const embeddings = await Promise.all(validTexts.map(text => embedText(text)));

        const resultMap = new Map<string, number[]>();
        validTexts.forEach((text, index) => {
            resultMap.set(text, embeddings[index]);
        });

        // Reconstruct the original array order
        const finalResults: number[][] = new Array(texts.length).fill([]);
        for (const [originalIndex, text] of textMap.entries()) {
            finalResults[originalIndex] = resultMap.get(text) || [];
        }
        return finalResults;

    } catch (error) {
        console.error("Error during batch embedding.", error);
        return texts.map(() => []);
    }
};

import { GoogleGenAI, FunctionDeclaration, Type, Chat } from "@google/genai";
import type { ResearchPaper, ModelDefinition, Project, ChatMessage, ConnectedPaper } from '../types';
import * as apiService from './apiService';

// Fixed: Correct initialization of GoogleGenAI using process.env.API_KEY directly
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// --- AGENT TOOL DEFINITIONS ---

const getPapersInProjectTool: FunctionDeclaration = {
    name: "get_papers_in_project",
    description: "Lists all the papers currently saved in the user's project.",
    parameters: { type: Type.OBJECT, properties: {} }
};

const getPaperDetailsTool: FunctionDeclaration = {
    name: "get_paper_details",
    description: "Retrieves the full details (title, authors, abstract, citations) for a specific paper using its ID.",
    parameters: {
        type: Type.OBJECT,
        properties: {
            paper_id: { type: Type.STRING, description: "The unique ID of the paper." }
        },
        required: ["paper_id"]
    }
};

const findConnectedPapersTool: FunctionDeclaration = {
    name: "find_connected_papers",
    description: "Finds papers that are connected to a given paper, either by citing it or being cited by it.",
    parameters: {
        type: Type.OBJECT,
        properties: {
            paper_id: { type: Type.STRING, description: "The unique ID of the paper to find connections for." }
        },
        required: ["paper_id"]
    }
};

const availableTools = [
    getPapersInProjectTool,
    getPaperDetailsTool,
    findConnectedPapersTool,
];

// --- AGENT EXECUTION LOGIC ---

type AgentUpdate = 
    | { type: 'tool-start'; toolCall: { name: string; args: any; thinking: string; } }
    | { type: 'tool-end'; toolResponse: { name: string; result: any; } }
    | { type: 'final-answer'; text: string };


export async function* runAgentTask(
    query: string,
    project: Project,
    projectPapers: ResearchPaper[],
    modelDef: ModelDefinition
): AsyncGenerator<AgentUpdate> {

    // Updated: Use gemini-3-pro-preview for agentic reasoning tasks
    const modelId = 'gemini-3-pro-preview'; 

    const toolImplementations = {
        get_papers_in_project: () => projectPapers.map(p => ({ id: p.id, title: p.title, year: p.year })),
        get_paper_details: (args: { paper_id: string }) => {
            const paper = projectPapers.find(p => p.id === args.paper_id);
            if (!paper) return { error: "Paper not found." };
            return {
                id: paper.id,
                title: paper.title,
                authors: paper.authors,
                year: paper.year,
                abstract: paper.abstract,
                citations: paper.citations,
            };
        },
        find_connected_papers: async (args: { paper_id: string }): Promise<ConnectedPaper[] | { error: string }> => {
            const paper = projectPapers.find(p => p.id === args.paper_id);
            if (!paper) return { error: "Paper not found." };
            try {
                return await apiService.findConnectedPapers(paper, modelDef);
            } catch (e) {
                return { error: e instanceof Error ? e.message : "Failed to find connected papers." };
            }
        },
    };

    const chat: Chat = ai.chats.create({
        model: modelId,
        config: {
            systemInstruction: `You are an expert AI research assistant.
- You have access to a set of tools to answer questions about the user's current research project.
- The project is named "${project.name}".
- First, understand the user's request. Then, devise a plan and use the available tools step-by-step to gather the necessary information.
- If you need to list papers first to get an ID, do so.
- When calling a tool, explain your reasoning in the 'thinking' field.
- Once you have gathered enough information, synthesize it and provide a final, comprehensive answer to the user.
- Do not invent information. If the tools do not provide the answer, state that.`,
            tools: [{ functionDeclarations: availableTools }],
        },
    });

    let response = await chat.sendMessage({ message: query });

    while (response.functionCalls && response.functionCalls.length > 0) {
        for (const fnCall of response.functionCalls) {

            const { name, args, id } = fnCall;
            const thinking = `Calling tool '${name}' to gather information.`;

            yield { type: 'tool-start', toolCall: { name, args, thinking } };

            const toolImplementation = (toolImplementations as any)[name];
            if (!toolImplementation) {
                throw new Error(`Unknown tool called by the model: ${name}`);
            }

            const toolResult = await Promise.resolve(toolImplementation(args));

            yield { type: 'tool-end', toolResponse: { name, result: toolResult } };

            response = await chat.sendMessage({
                message: {
                    functionResponses: { id, name, response: { result: toolResult } }
                }
            });
        }
    }

    yield { type: 'final-answer', text: response.text };
}

import { GoogleGenAI, Type } from "@google/genai";
import type { ModelDefinition, ResearchPaper, DeepResearchStep, DeepResearchReport } from "../types";
import * as openalexService from "./openalexService";
import { createPaperId } from "./extensionService";

// Fixed: Correct initialization of GoogleGenAI using process.env.API_KEY directly
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Helper to sanitize JSON
const safeJsonParse = (jsonString: string) => {
    try {
        const cleanedString = jsonString.replace(/```json/g, '').replace(/```/g, '').trim();
        return JSON.parse(cleanedString);
    } catch (e) {
        console.error("Failed to parse JSON:", e);
        return null;
    }
};

/**
 * TOKEN OPTIMIZATION:
 * Compresses the list of papers into a token-efficient string format for the LLM.
 */
const compressPapersForContext = (papers: ResearchPaper[], maxPapers: number = 15): string => {
    const uniquePapers = Array.from(new Map(papers.map(p => [p.id, p])).values());
    uniquePapers.sort((a, b) => (b.citations || 0) - (a.citations || 0));
    const topPapers = uniquePapers.slice(0, maxPapers);

    return topPapers.map((p, i) => {
        const cleanAbstract = (p.abstract || "No abstract.").replace(/\s+/g, ' ').substring(0, 1200);
        return `[${i + 1}] DOI: ${p.doi || 'N/A'}
TITLE: ${p.title}
YEAR: ${p.year}
ABSTRACT: ${cleanAbstract}`;
    }).join('\n\n');
};

const planSchema = {
    type: Type.OBJECT,
    properties: {
        sub_queries: {
            type: Type.ARRAY,
            items: { type: Type.STRING },
            description: "A list of exactly 3 distinct, targeted search queries."
        }
    },
    required: ["sub_queries"]
};

export const generateResearchPlan = async (topic: string, model: ModelDefinition): Promise<DeepResearchStep[]> => {
    const isTechnical = /implement|architecture|code|system|agent|software|algorithm/i.test(topic);

    const prompt = `Plan a comprehensive literature review on: "${topic}".
    ${isTechnical ? "This is a technical implementation query. Focus queries on system architectures, methodologies, and technical challenges." : ""}
    Generate exactly 3 distinct search queries to cover:
    1. The core theoretical concept.
    2. State-of-the-art methodologies and technical implementations.
    3. Recent (post-2021) evaluations and comparative studies.

    Return JSON with "sub_queries".`;

    try {
        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview", 
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: planSchema,
            }
        });

        const result = safeJsonParse(response.text || '');
        if (!result || !result.sub_queries) return [];

        return result.sub_queries.map((q: string, i: number) => ({
            id: `step_${i}`,
            query: q,
            status: 'pending',
            papersFound: 0
        }));
    } catch (e) {
        console.error("Deep Research Plan Error:", e);
        return [{ id: 'step_0', query: topic, status: 'pending', papersFound: 0 }];
    }
};

export const executeSearchStep = async (step: DeepResearchStep): Promise<ResearchPaper[]> => {
    try {
        const { papers } = await openalexService.searchOpenAlex(step.query, {
            startYear: '', endYear: '', authors: '', excludeKeywords: '', inclusionCriteria: '', exclusionCriteria: '', studyDesign: 'any',
            isOpenAccess: false
        });
        return papers.slice(0, 8); 
    } catch (e) {
        console.error(`Search failed for ${step.query}:`, e);
        return [];
    }
};

const reportSchema = {
    type: Type.OBJECT,
    properties: {
        title: { type: Type.STRING },
        summary: { type: Type.STRING },
        sections: {
            type: Type.ARRAY,
            items: {
                type: Type.OBJECT,
                properties: {
                    heading: { type: Type.STRING },
                    content: { type: Type.STRING, description: "Markdown content for this section." }
                },
                required: ["heading", "content"]
            }
        }
    },
    required: ["title", "summary", "sections"]
};

export const synthesizeReport = async (topic: string, papers: ResearchPaper[], model: ModelDefinition): Promise<DeepResearchReport> => {
    const context = compressPapersForContext(papers, 18);
    const isTechnical = /implement|architecture|code|system|agent|software|algorithm/i.test(topic);

    const prompt = `Act as a Senior Research Lead. Write a comprehensive literature review report on: "${topic}".

    Source Material (Abstracts of Top Papers):
    ${context}

    Instructions:
    1. Synthesize the findings across all sources. Identify consistent patterns and notable disagreements.
    2. Cite sources using [1], [2] notation strictly matching the list provided.
    ${isTechnical ? "3. Include a section on 'Technical Implementation Strategies' or 'System Architectures' described in the literature." : "3. Focus on methodological trends and empirical outcomes."}
    4. Structure: Title, Executive Summary, 3-5 Detailed Thematic Sections.
    5. Tone: Academic, rigorous, and highly informative.

    Return a JSON object matching the report schema. Use Markdown for section contents.`;

    try {
        const response = await ai.models.generateContent({
            model: "gemini-3-pro-preview",
            contents: prompt,
            config: {
                // responseMimeType is correct for gemini-3 models
                responseMimeType: "application/json",
                responseSchema: reportSchema,
                // thinkingConfig is recommended for gemini-3 series complex tasks
                thinkingConfig: { thinkingBudget: 16000 }
            }
        });

        const result = safeJsonParse(response.text || '');
        if (!result) throw new Error("Failed to parse report.");

        const uniquePapers = Array.from(new Map(papers.map(p => [p.id, p])).values());
        uniquePapers.sort((a, b) => (b.citations || 0) - (a.citations || 0));
        const references = uniquePapers.slice(0, 18);

        return {
            title: result.title,
            summary: result.summary,
            sections: result.sections,
            references: references
        };
    } catch (e) {
        console.error("Report Synthesis Error:", e);
        throw new Error("Failed to generate research report.");
    }
};

