        setProjects(prev => [...prev, newProject]);
    };

    const handleDeleteProject = (projectId: string) => {
        setProjects(prev => prev.filter(p => p.id !== projectId));
        // Also remove any chat history associated with the project
        setProjectChats(prev => {
            const newChats = {...prev};
            delete newChats[projectId];
            return newChats;
        });
    };

    const handleMovePaperToProject = (paperId: string, projectId: string | null) => {
        setProjects(prevProjects => {
            const newProjects = prevProjects.map(p => ({
                ...p,
                paperIds: p.paperIds.filter(id => id !== paperId),
            }));

            if (projectId) {
                const targetProjectIndex = newProjects.findIndex(p => p.id === projectId);
                if (targetProjectIndex > -1) {
                    newProjects[targetProjectIndex].paperIds.push(paperId);
                }
            }
            return newProjects;
        });
    };

    const handleUpdateProjectColor = (projectId: string, color: string) => {
        setProjects(prev => prev.map(p => p.id === projectId ? { ...p, color } : p));
    };

    const handleSynthesizeWorkspace = async (papersToSynthesize: ResearchPaper[], modelToUse: ModelDefinition, isWorkspaceContext: boolean = false) => {
        analyticsService.logEvent('tool_used', { tool: 'synthesize_workspace', paperCount: papersToSynthesize.length, context: isWorkspaceContext ? 'workspace' : 'search_results' });
        if (isWorkspaceContext) {
            setShowWorkspaceAnalysisDrawer(true); // Open the drawer
            setIsWorkspaceSynthesisLoading(true);
            setWorkspaceSynthesisSummary(null);
        } else {
            setIsSynthesisModalOpen(true);
            setIsSynthesizing(true);
            setSynthesisError(null);
            setSynthesisResult(null);
        }
        try {
            const result = await apiService.synthesizePapers(papersToSynthesize, modelToUse);
            if (isWorkspaceContext) {
                setWorkspaceSynthesisSummary(result);
            } else {
                setSynthesisResult(result);
            }
        } catch (err) {
            const message = err instanceof Error ? err.message : "An unknown error occurred.";
            if (isWorkspaceContext) {
                setWorkspaceSynthesisSummary([{ title: "Error", mainFinding: message, methodology: "", context: "" }]); // Display error
            } else {
                setSynthesisError(message);
            }
        } finally {
            if (isWorkspaceContext) {
                setIsWorkspaceSynthesisLoading(false);
            } else {
                setIsSynthesizing(false);
            }
        }
    };

    const handleAnalyzeWorkspace = async (papersToAnalyze: ResearchPaper[], modelToUse: ModelDefinition) => {
        analyticsService.logEvent('tool_used', { tool: 'analyze_workspace_dashboard', paperCount: papersToAnalyze.length });
        setShowWorkspaceAnalysisDrawer(true);
        setIsWorkspaceAnalysisLoading(true);
        setWorkspaceAnalysisResult(null); // Clear previous results
        setWorkspaceSynthesisSummary(null); // Clear previous synthesis
        setWorkspaceGapAnalysisReport(null); // Clear previous gap report
        setIsWorkspaceSynthesisLoading(false); // Reset specific loadings
        setIsWorkspaceGapAnalysisLoading(false);

        try {
            const analysisData = await apiService.analyzePapers(papersToAnalyze);
            setWorkspaceAnalysisResult(analysisData);
            // Trigger synthesis and gap analysis in background for the dashboard
            handleSynthesizeWorkspace(papersToAnalyze, modelToUse, true); // Pass true for workspace context
            handleAnalyzeGaps(papersToAnalyze, modelToUse, true); // Pass true for workspace context
        } catch (err) {
            console.error("Failed to perform workspace analysis:", err);
            // Set an error state in the dashboard if needed
        } finally {
            setIsWorkspaceAnalysisLoading(false);
        }
    };

     const handleIndexPaperForRag = (projectId: string, paperId: string) => {
        setProjects(prev => prev.map(p => {
            if (p.id === projectId) {
                const newStatuses = { ...p.paperStatuses, [paperId]: 'indexing' as const };
                return { ...p, paperStatuses: newStatuses };
            }
            return p;
        }));

        // Simulate indexing delay
        setTimeout(() => {
            setProjects(prev => prev.map(p => {
                if (p.id === projectId) {
                    // 10% chance of error for simulation purposes
                    const status = Math.random() > 0.9 ? 'error' : 'indexed';
                    const newStatuses = { ...p.paperStatuses, [paperId]: status };
                    return { ...p, paperStatuses: newStatuses };
                }
                return p;
            }));
        }, 2000 + Math.random() * 1000);
    };

    const handleProjectChat = async (projectId: string, message: string) => {
        const project = projects.find(p => p.id === projectId);
        if (!project) return;

        const userMessage: ChatMessage = { role: 'user', parts: [{ text: message }] };

        setProjectChats(prev => ({
            ...prev,
            [projectId]: {
                history: [...(prev[projectId]?.history || []), userMessage],
                isLoading: true,
            }
        }));

        try {
            const projectPapers: ResearchPaper[] = project.paperIds.map(id => workspacePapers.find(p => p.id === id)).filter((p): p is ResearchPaper => !!p);

            // The agent service now streams updates. We'll handle them one by one.
            const agentStream = agentService.runAgentTask(message, project, projectPapers, model);

            for await (const update of agentStream) {
                setProjectChats(prev => {
                    const currentHistory = prev[projectId]?.history || [];
                    let newHistory = [...currentHistory];

                    if (update.type === 'tool-start') {
                        newHistory.push({ role: 'tool', parts: [{ toolCall: update.toolCall }] });
                    } else if (update.type === 'tool-end') {
                        // Find the corresponding tool-start message and add the result
                        const lastMsgIndex = newHistory.length - 1;
                        if (newHistory[lastMsgIndex]?.role === 'tool' && newHistory[lastMsgIndex].parts[0].toolCall?.name === update.toolResponse.name) {
                            newHistory[lastMsgIndex].parts[0].toolResponse = update.toolResponse;
                        }
                    } else if (update.type === 'final-answer') {
                        newHistory.push({ role: 'model', parts: [{ text: update.text }] });
                    }

                    return {
                        ...prev,
                        [projectId]: {
                            ...prev[projectId],
                            history: newHistory,
                        },
                    };
                });
            }

        } catch (error) {
            const errorMessage = error instanceof Error ? error.message : "An error occurred.";
            const modelMessage: ChatMessage = { role: 'model', parts: [{ text: `Error: ${errorMessage}` }] };
            setProjectChats(prev => ({
                ...prev,
                [projectId]: {
                    history: [...(prev[projectId]?.history || []), modelMessage],
                    isLoading: false,
                }
            }));
        } finally {
            setProjectChats(prev => ({
                ...prev,
                [projectId]: {
                    ...prev[projectId],
                    isLoading: false,
                }
            }));
        }
    };

    const handleWorkspaceChat = async (message: string) => {
        if (!workspacePapers.length) return;

        const userMessage: ChatMessage = { role: 'user', parts: [{ text: message }] };
        setWorkspaceChatHistory(prev => [...prev, userMessage]);
        setIsWorkspaceChatLoading(true);

        try {
            // Create a pseudo-project for the entire workspace
            const workspaceProject: Project = {
                id: 'workspace_all',
                name: 'All Workspace Papers',
                paperIds: workspacePapers.map(p => p.id),
                createdAt: Date.now(),
                color: 'sky',
                paperStatuses: {}
            };

            const agentStream = agentService.runAgentTask(message, workspaceProject, workspacePapers, model);

            for await (const update of agentStream) {
                setWorkspaceChatHistory(prev => {
                    const currentHistory = [...prev];
                    if (update.type === 'tool-start') {
                        currentHistory.push({ role: 'tool', parts: [{ toolCall: update.toolCall }] });
                    } else if (update.type === 'tool-end') {
                        const lastMsgIndex = currentHistory.length - 1;
                        if (currentHistory[lastMsgIndex]?.role === 'tool' && currentHistory[lastMsgIndex].parts[0].toolCall?.name === update.toolResponse.name) {
                            currentHistory[lastMsgIndex].parts[0].toolResponse = update.toolResponse;
                        }
                    } else if (update.type === 'final-answer') {
                        currentHistory.push({ role: 'model', parts: [{ text: update.text }] });
                    }
                    return currentHistory;
                });
            }
        } catch (error) {
            const errorMessage = error instanceof Error ? error.message : "An error occurred.";
            const modelMessage: ChatMessage = { role: 'model', parts: [{ text: `Error: ${errorMessage}` }] };
            setWorkspaceChatHistory(prev => [...prev, modelMessage]);
        } finally {
            setIsWorkspaceChatLoading(false);
        }
    };

    const handleAddSource = (source: SearchSourceInfo) => {
        setSearchSources(prev => {
            if (!prev.some(s => s.id === source.id)) {
                return [...prev, source];
            }
            return prev;
        });
    };


    // --- Dissertation Feature Handlers ---

    const handleUpdateGoldStandardPaper = (updatedPaper: GoldStandardPaper) => {
        setGoldStandardDataset(prev => prev.map(p => p.paper_id === updatedPaper.paper_id ? updatedPaper : p));
    };

    const handleRunTestHarness = async () => {
        analyticsService.logEvent('test_harness_run_started', { datasetSize: goldStandardDataset.length });
        const results: TestHarnessResult[] = [];
        for (const paper of goldStandardDataset) {
            try {
                // Reconstruct a partial ResearchPaper for verification
                const paperForVerification: ResearchPaper = {
                    id: paper.paper_id, // Use ID or create a stable one
                    title: paper.title,
                    authors: paper.authors,
                    year: paper.year,
                    abstract: paper.abstract,
                    doi: paper.paper_id,
                    // Fill other required fields with defaults or empty
                    citations: 0,
                    sourceURL: `https://doi.org/${paper.paper_id}`,
                };

                const vacsResult = await verificationService.verifyPaper(paperForVerification, paper.title);

                // Map VACS verdict to our label system for comparison
                const vacsLabel = vacsResult.verdict === 'Verified' ? 'verified' 
                                : vacsResult.verdict === 'Questionable' ? 'refuted' 
                                : 'inconclusive';

                const isCorrect = vacsLabel === paper.label;

                results.push({
                    paperId: paper.paper_id,
                    vacsResult,
                    groundTruth: paper,
                    isCorrect,
                    precisionAt1: isCorrect ? 1 : 0,
                });
            } catch (error) {
                console.error(`Failed to verify paper ${paper.paper_id}`, error);
            }
        }
        setTestHarnessResults(results);
        const accuracy = results.length > 0 ? (results.filter(r => r.isCorrect).length / results.length) * 100 : 0;
        analyticsService.logEvent('test_harness_run_completed', { 
            testCount: results.length, 
            accuracy: parseFloat(accuracy.toFixed(2)) 
        });
    };

    const handleSaveUserStudyData = (data: UserStudyData) => {
        analyticsService.logEvent('user_study_task_completed', { studyData: data });
        setUserStudyData(prev => [...prev, data]);
    };


    const renderAppMode = () => {
        switch (appMode) {
            case 'dashboard':
                return <ResearcherDashboard 
                            dataset={goldStandardDataset}
                            setDataset={handleUpdateGoldStandardPaper}
                            testResults={testHarnessResults}
                            runTestHarness={handleRunTestHarness}
                            userStudyData={userStudyData}
                            onStartUserStudy={() => setAppMode('evaluation')}
                        />;
            case 'evaluation':
                return <PaperVerificationApp 
                            dataset={goldStandardDataset} 
                            onComplete={(data) => {
                                handleSaveUserStudyData(data);
                                alert('Study task complete! Thank you.');
                                // In a real study, you might show a new task or end the session.
                                // For now, we return to the dashboard.
                                setAppMode('dashboard');
                            }}
                        />;
            case 'search':
            default:
                return (
                    <div className="container mx-auto px-4 sm:px-6 lg:px-8 py-6">
                        <div className="grid grid-cols-1 lg:grid-cols-5 gap-8">
                            <main className={hasSearched ? "lg:col-span-3" : "lg:col-span-5"}>
                                {!hasSearched ? (
                                    <InitialSearchScreen 
                                        query={query} 
                                        onQueryChange={setQuery} 
                                        onSearch={handleSearch} 
                                        isLoading={isLoading} 
                                        summaryLength={summaryLength} 
                                        onLengthChange={setSummaryLength} 
                                        summaryStyle={summaryStyle} 
                                        onStyleChange={setSummaryStyle} 
                                        model={model} 
                                        onModelChange={setModel} 
                                        availableModels={AVAILABLE_MODELS} 
                                        logAnalyticsEvent={() => {}} 
                                        onOpenDbFinder={() => setIsDbFinderOpen(true)} 
                                        searchSources={searchSources}
                                        suggestions={searchSuggestions}
                                        isSuggestionsLoading={isGeneratingSearchSuggestions}
                                        onSuggestionClick={handleSuggestionSearch}
                                        onOpenOrgFinder={() => setIsOrgFinderOpen(true)}
                                        onOpenDeepResearch={() => setIsDeepResearchOpen(true)}
                                    >
                                        <ExtensionPromo />
                                    </InitialSearchScreen>
                                ) : (
                                    <div className="space-y-6">
                                        <SearchForm 
                                            query={query} 
                                            onQueryChange={setQuery} 
                                            onSearch={handleSearch} 
                                            isLoading={isLoading} 
                                            summaryLength={summaryLength} 
                                            onLengthChange={setSummaryLength} 
                                            summaryStyle={summaryStyle} 
                                            onStyleChange={setSummaryStyle} 
                                            model={model} 
                                            onModelChange={setModel} 
                                            availableModels={AVAILABLE_MODELS} 
                                            logAnalyticsEvent={() => {}}
                                            suggestions={searchSuggestions}
                                            isSuggestionsLoading={isGeneratingSearchSuggestions}
                                            onSuggestionClick={handleSuggestionSearch}
                                            onOpenOrgFinder={() => setIsOrgFinderOpen(true)}
                                            selectedInstitution={selectedInstitution}
                                            onClearInstitution={() => setSelectedInstitution(undefined)}
                                            onOpenDeepResearch={() => setIsDeepResearchOpen(true)}
                                        />
                                        {isLoading && <LoadingSpinner message={"Searching..."} />}
                                        {error && <ErrorMessage message={error} />}
                                        {!isLoading && !error && hasSearched && (
                                            <>
                                                <ResultsDisplay 
                                                    papers={sortedPapers} 
                                                    selectedPaperId={selectedPaper?.id || null} 
                                                    onSelectPaper={handleSelectPaper} 
                                                    sortConfig={sortConfig} 
                                                    onSortChange={handleSortChange}
                                                    isScreeningMode={isScreeningMode}
                                                    onSetScreeningMode={handleSetScreeningMode}
                                                    onScreenPaper={handleScreenPaper}
                                                    onAiRerank={handleAiRerank}
                                                    isReranking={isReranking}
                                                    onLoadMore={handleLoadMore}
                                                    hasMore={hasMore}
                                                    isLoadingMore={isLoadingMore}
                                                    isSearchingGrounded={isSearchingGrounded}
                                                    isRefiningAI={isRefiningAI} // Pass new state
                                                />
                                            </>
                                        )}
                                    </div>
                                )}
                            </main>

                            {hasSearched && (
                                <aside className="lg:col-span-2">
                                <WorkspacePanel 
                                    papers={papers} 
                                    selectedPaper={selectedPaper} 
                                    analysis={analysis} 
                                    summary={summary} 
                                    workspacePapers={workspacePapers} 
                                    projects={projects} 
                                    sources={[]} 
                                    onToggleWorkspacePaper={handleToggleWorkspacePaper} 
                                    onFindConnectedPapers={handleFindConnectedPapers} 
                                    isFindingConnected={isFindingConnections} 
                                    onAnalyzePaper={handleAnalyzePaper} 
                                    onCitePaper={handleOpenCitationModal} 
                                    isAnalyzingPaper={isAnalyzingPaper} 
                                    onConceptClick={handleConceptSearch} 
                                    onFindDoi={handleFindDoi} 
                                    onGenerateSuggestions={handleGenerateSuggestions} 
                                    isGeneratingSuggestions={isGeneratingSuggestions} 
                                    onVerifyPaper={handleOpenVerificationModal} 
                                    logAnalyticsEvent={() => {}} 
                                    refinedQueries={refinedQueries} 
                                    isGeneratingRefined={false} 
                                    onRefinedQuerySearch={() => {}} 
                                    onAnalyzeGaps={(papers, model) => handleAnalyzeGaps(papers, model, true)} 
                                    onSynthesizeWorkspace={(papers, model) => handleSynthesizeWorkspace(papers, model, true)}
                                    onAnalyzeWorkspace={handleAnalyzeWorkspace} // New prop for opening dashboard
                                    onCreateProject={handleCreateProject} 
                                    onDeleteProject={handleDeleteProject} 
                                    onMovePaperToProject={handleMovePaperToProject} 
                                    onUpdateProjectColor={handleUpdateProjectColor} 
                                    model={model} 
                                    onIndexPaperForRag={handleIndexPaperForRag} 
                                    projectChats={projectChats} 
                                    onProjectChat={handleProjectChat} 
                                    isSummaryLoading={isSummaryLoading} 
                                    onFindJournals={handleFindJournals}
                                    isFindingJournals={isFindingJournals}
                                    onAuthorClick={handleAuthorSearch}
                                    onFindSimilar={handleFindSimilar}
                                    isFindingSimilar={isFindingSimilar}
                                    showWorkspaceAnalysisDrawer={showWorkspaceAnalysisDrawer}
                                    onCloseWorkspaceAnalysisDrawer={() => setShowWorkspaceAnalysisDrawer(false)}
                                    workspaceAnalysisResult={workspaceAnalysisResult}
                                    workspaceSynthesisSummary={workspaceSynthesisSummary}
                                    workspaceGapAnalysisReport={workspaceGapAnalysisReport}
                                    isWorkspaceAnalysisLoading={isWorkspaceAnalysisLoading}
                                    isWorkspaceSynthesisLoading={isWorkspaceSynthesisLoading}
                                    isWorkspaceGapAnalysisLoading={isWorkspaceGapAnalysisLoading}
                                    // New Chat Props
                                    workspaceChatHistory={workspaceChatHistory}
                                    isWorkspaceChatLoading={isWorkspaceChatLoading}
                                    onWorkspaceChat={handleWorkspaceChat}
                                />
                                </aside>
                            )}
                        </div>
                    </div>
                );
        }
    }

    return (
        <div className="min-h-screen bg-background text-foreground flex flex-col">
            <Header
                onOpenAbout={() => setIsAboutModalOpen(true)}
                onOpenHelp={() => setIsOnboardingOpen(true)}
                appMode={appMode}
                onModeChange={setAppMode}
            />
            <div className="flex-grow">
                {renderAppMode()}
            </div>

            {/* Modals are kept at the top level to be accessible from any mode */}
            {isOnboardingOpen && <OnboardingModal onComplete={() => setIsOnboardingOpen(false)} onSkip={() => setIsOnboardingOpen(false)} />}
            {isAboutModalOpen && <InfoModal isOpen={isAboutModalOpen} onClose={() => setIsAboutModalOpen(false)} title="About AI Research Explorer"> <AboutModalContent /> </InfoModal>}
            <VerificationModal isOpen={isVerificationModalOpen} onClose={() => setIsVerificationModalOpen(false)} paper={paperToVerify} onVerificationComplete={handleVerificationComplete} />
            <ReportModal isOpen={isGapAnalysisModalOpen} onClose={() => setIsGapAnalysisModalOpen(false)} isLoading={isAnalyzingGaps} content={gapAnalysisResult} error={gapAnalysisError} />
            <PaperAnalysisModal isOpen={isAnalysisModalOpen} onClose={() => setIsAnalysisModalOpen(false)} isLoading={isAnalyzingPaper} error={analysisError} result={analysisResult} onSaveAnalysis={handleSaveAnalysis} isAnalysisSaved={!!analysisResult?.paper.savedAnalysis} />
            <SynthesisModal isOpen={isSynthesisModalOpen} onClose={() => setIsSynthesisModalOpen(false)} isLoading={isSynthesizing} result={synthesisResult} error={synthesisError} />
            <CitationModal isOpen={isCitationModalOpen} onClose={() => setIsCitationModalOpen(false)} paper={paperForCitation} model={model} />
            <DatabaseFinderModal isOpen={isDbFinderOpen} onClose={() => setIsDbFinderOpen(false)} onAddSource={handleAddSource} existingSources={searchSources} />
            <SuggestionsModal isOpen={isSuggestionsModalOpen} result={suggestionsResult} onClose={() => setIsSuggestionsModalOpen(false)} error={suggestionsError} isLoading={isGeneratingSuggestions} onSuggestionClick={handleSuggestionClick} />
            <ConnectedPapersModal isOpen={isConnectionsModalOpen} result={connectionsResult} onClose={() => setIsConnectionsModalOpen(false)} error={connectionsError} isLoading={isFindingConnections} />
            <JournalFinderModal isOpen={isJournalFinderOpen} onClose={() => setIsJournalFinderOpen(false)} paper={paperForJournalFinder} recommendations={journalRecommendations} isLoading={isFindingJournals} error={journalFinderError} />
            <OrganizationFinderModal isOpen={isOrgFinderOpen} onClose={() => setIsOrgFinderOpen(false)} onSelectOrganization={handleSelectOrganization} />
            <DeepResearchModal isOpen={isDeepResearchOpen} onClose={() => setIsDeepResearchOpen(false)} initialTopic={query} model={model} onAddPapersToWorkspace={handleAddPapersToWorkspace} />
        </div>
    );
};

export default App;

import React, { useState, useEffect } from 'react';
import { SearchIcon } from './icons/SearchIcon';
import type { SummaryLength, AdvancedSearchOptions, SummaryStyle, ModelDefinition } from '../types';
import { ChevronDownIcon } from './icons/ChevronDownIcon';
import { RefineIcon } from './icons/RefineIcon';
import { SearchSuggestions } from './SearchSuggestions';
import { BuildingIcon } from './icons/BuildingIcon';
import { RemoveIcon } from './icons/RemoveIcon';
import { RobotIcon } from './icons/RobotIcon';
import { DoiIcon } from './icons/DoiIcon';

interface SearchFormProps {
  query: string;
  onQueryChange: (query: string) => void;
  onSearch: (query: string, options: AdvancedSearchOptions) => void;
  isLoading: boolean;
  summaryLength: SummaryLength;
  onLengthChange: (length: SummaryLength) => void;
  summaryStyle: SummaryStyle;
  onStyleChange: (style: SummaryStyle) => void;
  model: ModelDefinition;
  onModelChange: (model: ModelDefinition) => void;
  availableModels: ModelDefinition[];
  logAnalyticsEvent: (eventName: string, payload: object) => void;
  suggestions: string[];
  isSuggestionsLoading: boolean;
  onSuggestionClick: (suggestion: string) => void;
  onOpenOrgFinder: () => void;
  selectedInstitution?: { id: string; name: string };
  onClearInstitution: () => void;
  onOpenDeepResearch: () => void;
}

const summaryStyles: { id: SummaryStyle; name: string }[] = [
    { id: 'paragraph', name: 'Paragraph' },
    { id: 'bullets', name: 'Bullets' },
    { id: 'qa', name: 'Q&A' },
];

const studyDesigns = [
    { id: 'any', name: 'Any Study Design' },
    { id: 'randomized_controlled_trial', name: 'Randomized Controlled Trial' },
    { id: 'systematic_review', name: 'Systematic Review' },
    { id: 'observational_study', name: 'Observational Study' },
    { id: 'qualitative_study', name: 'Qualitative Study' },
];

export const SearchForm: React.FC<SearchFormProps> = ({ 
    query,
    onQueryChange,
    onSearch, 
    isLoading, 
    summaryLength, 
    onLengthChange,
    summaryStyle,
    onStyleChange,
    model,
    onModelChange,
    availableModels,
    suggestions,
    isSuggestionsLoading,
    onSuggestionClick,
    onOpenOrgFinder,
    selectedInstitution,
    onClearInstitution,
    onOpenDeepResearch
}) => {
  const [isRefineOpen, setIsRefineOpen] = useState(false);
  const [localQuery, setLocalQuery] = useState(query);
  const [advancedOptions, setAdvancedOptions] = useState<AdvancedSearchOptions>({
    startYear: '',
    endYear: '',
    authors: '',
    excludeKeywords: '',
    inclusionCriteria: '',
    exclusionCriteria: '',
    studyDesign: 'any',
    journal: '',
    minCitations: '',
    titleKeywords: '',
    abstractKeywords: '',
    isOpenAccess: false,
    doi: '',
  });

  useEffect(() => {
    setLocalQuery(query);
  }, [query]);

  useEffect(() => {
      if (selectedInstitution) {
          setAdvancedOptions(prev => ({
              ...prev,
              institutionName: selectedInstitution.name,
              institutionId: selectedInstitution.id
          }));
      } else {
          setAdvancedOptions(prev => {
              const { institutionName, institutionId, ...rest } = prev;
              return rest as AdvancedSearchOptions;
          });
      }
  }, [selectedInstitution]);

  useEffect(() => {
    const handler = setTimeout(() => {
      if (localQuery !== query) {
        onQueryChange(localQuery);
      }
    }, 300);
    return () => clearTimeout(handler);
  }, [localQuery, query, onQueryChange]);

  const handleAdvancedChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    if (type === 'checkbox') {
        setAdvancedOptions(prev => ({ ...prev, [name]: (e.target as HTMLInputElement).checked }));
    } else {
        setAdvancedOptions(prev => ({ ...prev, [name]: value }));
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (localQuery !== query) {
        onQueryChange(localQuery);
    }
    onSearch(localQuery, advancedOptions);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setLocalQuery(e.target.value);
  };

  const handleDoiChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setAdvancedOptions(prev => ({ ...prev, doi: e.target.value }));
  };

  const placeholderText = `Ask a research question...`;

  return (
    <div className="relative">
      <form onSubmit={handleSubmit} className="flex flex-col gap-4">
        <div className="flex flex-col md:flex-row items-stretch md:items-center gap-2">
          <div className="relative flex-grow min-w-0">
            <input
              type="text"
              value={localQuery}
              onChange={handleInputChange}
              placeholder={placeholderText}
              className="w-full pl-4 pr-12 h-12 bg-background border border-input rounded-md focus:ring-2 focus:ring-ring focus:ring-offset-1 transition-shadow duration-200 text-base text-foreground"
              disabled={isLoading}
              autoComplete="off"
            />
            <div className="absolute inset-y-0 right-0 flex items-center pr-4">
                <SearchIcon className="w-5 h-5 text-muted-foreground" />
            </div>
          </div>

          <div className="relative md:w-64 flex-shrink-0">
            <input
              type="text"
              name="doi"
              value={advancedOptions.doi || ''}
              onChange={handleDoiChange}
              placeholder="Or enter DOI directly..."
              className="w-full pl-10 pr-4 h-12 bg-blue-50/30 border border-blue-200/50 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all text-sm text-foreground placeholder:text-blue-400/70"
              disabled={isLoading}
              title="Search by Digital Object Identifier"
            />
            <div className="absolute inset-y-0 left-0 flex items-center pl-3">
                <DoiIcon className="w-4 h-4 text-blue-500" />
            </div>
          </div>

           <div className="relative hidden lg:block">
              <select
