    const handleLoadMore = async () => {
        if (!query.trim() || isLoadingMore || !hasMore) return;

        setIsLoadingMore(true);
        setError(null);

        const pageToFetch = currentPage + 1;

        try {
            // Pagination uses the fast API search
            const { papers: newPapers, hasMore: newHasMore, rawQueryUsed } = await apiService.searchFast(query, lastUsedOptions, searchSources, pageToFetch);

            // Append basic papers immediately
            setPapers(prev => [...prev, ...newPapers]);
            setCurrentPage(pageToFetch);
            setHasMore(newHasMore);

            // Trigger background AI refinement for the new set of papers
            // This is a simpler version, only applying semantic scoring and validation to new papers.
            // Full re-analysis/summary would be too heavy for pagination.
            if (aiHypotheticalAnswer) {
                apiService.calculatePaperScores(newPapers, rawQueryUsed, aiHypotheticalAnswer, model, lastUsedOptions).then(scoredNewPapers => {
                    setPapers(current => {
                        const scoredMap = new Map(scoredNewPapers.map(p => [p.id, p]));
                        return current.map(p => scoredMap.get(p.id) || p);
                    });
                    triggerBackgroundValidation(scoredNewPapers);
                }).catch(e => console.warn("Semantic scoring for loaded more papers failed", e));
            } else {
                 triggerBackgroundValidation(newPapers); // Just basic validation if no hypothesis is ready
            }

        } catch (err) {
            setError(err instanceof Error ? err.message : "An unknown error occurred.");
        } finally {
            setIsLoadingMore(false);
        }
    };

