/**
 * TOON (Text-Oriented Object Notation) Utility
 * 
 * Inspired by toon-format, this utility provides a compact way to serialize 
 * Research Paper metadata for LLM context windows. 
 * It reduces token overhead by removing redundant JSON keys and whitespace.
 */

import type { ResearchPaper } from '../types';

export const paperToToon = (paper: ResearchPaper, index: number): string => {
    // We use a compact, key-value pair format with unique delimiters
    // [ID] T: Title | A: Authors | Y: Year | S: Summary/Abstract
    const cleanAbstract = (paper.abstract || "").replace(/\s+/g, ' ').substring(0, 800);
    const cleanAuthors = (paper.authors || "").substring(0, 100);

    return `[${index}] T:${paper.title}\nAU:${cleanAuthors}\nY:${paper.year}\nAB:${cleanAbstract}\n---`;
};

export const papersToToonCollection = (papers: ResearchPaper[]): string => {
    return papers.map((p, i) => paperToToon(p, i + 1)).join('\n');
};

/**
 * Estimation of token savings compared to standard JSON stringify
 * Standard JSON (pretty): ~1.2 tokens per 4 characters
 * TOON: ~1.1 tokens per 4 characters + ~20-30% fewer characters due to key removal
 */

// This file handles direct AI model interactions, optimized for speed and token usage.

