const safeJsonParse = (jsonString: string) => {
  if (!jsonString || !jsonString.trim()) return null;
  try {
    const cleanedString = jsonString.replace(/```json/g, '').replace(/```/g, '').trim();
    return JSON.parse(cleanedString);
  } catch (e) {
    console.error("Failed to parse JSON:", jsonString, e);
    return null;
  }
};

const retryWithBackoff = async <T>(operation: () => Promise<T>, retries: number = 3, delay: number = 1000): Promise<T> => {
    try {
        return await operation();
    } catch (error: any) {
        const isRateLimit = error?.status === 429 || error?.message?.includes('429') || error?.message?.includes('RESOURCE_EXHAUSTED');
        if (retries > 0 && isRateLimit) {
            await new Promise(resolve => setTimeout(resolve, delay));
            return retryWithBackoff(operation, retries - 1, delay * 2);
        }
        throw error;
    }
};

/**
 * OPTIMIZATION: Unified Search Strategy
 * Combines parsing and hypothetical answer generation into one call to save 2-4s.
 */
const unifiedStrategySchema = {
    type: Type.OBJECT,
    properties: {
        parsedFilters: {
            type: Type.OBJECT,
            properties: {
                core_search_query: { type: Type.STRING },
                startYear: { type: Type.NUMBER },
                endYear: { type: Type.NUMBER },
                authors: { type: Type.STRING },
                isOpenAccess: { type: Type.BOOLEAN }
            },
            required: ["core_search_query"]
        },
        hypotheticalAbstract: { 
            type: Type.STRING,
            description: "A compact hypothetical abstract to guide semantic search."
        }
    },
    required: ["parsedFilters", "hypotheticalAbstract"]
};

export const getUnifiedSearchStrategy = async (userQuery: string, model: ModelDefinition): Promise<{ filters: any, hypothesis: string }> => {
    const prompt = `Task: Prepare a research retrieval strategy for: "${userQuery}".

    1. Parse the query into structured filters (years, authors, core keywords).
    2. Generate a 150-word hypothetical abstract that perfectly answers the query to use for semantic embedding matches.

    Return JSON with "parsedFilters" and "hypotheticalAbstract".`;

    try {
        const response = await retryWithBackoff(() => ai.models.generateContent({
            model: "gemini-3-flash-preview", 
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: unifiedStrategySchema,
            }
        }));

        const result = safeJsonParse(response.text ?? '');
        return {
            filters: result?.parsedFilters || { core_search_query: userQuery },
            hypothesis: result?.hypotheticalAbstract || userQuery
        };
    } catch (e) {
        return { filters: { core_search_query: userQuery }, hypothesis: userQuery };
    }
};

const overallSummarySchema = {
    type: Type.OBJECT,
    properties: {
        summary: { type: Type.STRING },
    },
    required: ["summary"],
};

export const generateSummaryForPapers = async (
    papers: ResearchPaper[],
    summaryLength: SummaryLength,
    summaryStyle: SummaryStyle,
    model: ModelDefinition
): Promise<string> => {
    if (papers.length === 0) return "";

    // TOKEN OPTIMIZATION: Use TOON format for context
    const context = papersToToonCollection(papers.slice(0, 15));

    const prompt = `Synthesize an overview from these sources:
    ${context}

    Style: ${summaryStyle}, Length: ${summaryLength}. 
    Focus on common findings and methodology trends. Use [1], [2] citations.`;

    try {
        const result = await retryWithBackoff(() => ai.models.generateContent({
            model: model.id,
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: overallSummarySchema,
            }
        }));
        const parsed = safeJsonParse(result.text ?? '');
        return parsed?.summary || "Summary generation failed.";
    } catch (error) {
        return "An error occurred while generating the summary.";
    }
};

