// Persistent Cache for cross-session optimization
const SESSION_CACHE_KEY = 'are_ai_session_cache_v2';
const getStoredCache = () => {
    try {
        const stored = localStorage.getItem(SESSION_CACHE_KEY);
        return stored ? JSON.parse(stored) : {};
    } catch { return {}; }
};
const setStoredCache = (data: any) => {
    try {
        localStorage.setItem(SESSION_CACHE_KEY, JSON.stringify(data));
    } catch {}
};

