interface PaperChatProps {
    paper: ResearchPaper;
}

export const PaperChat: React.FC<PaperChatProps> = ({ paper }) => {
    const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const chatSessionRef = useRef<Chat | null>(null);

    // Initialize chat session when paper changes
    useEffect(() => {
        try {
            // FIX: Added 'createPaperChatSession' implementation to geminiService.
            chatSessionRef.current = geminiService.createPaperChatSession(paper, 'gemini-3-flash-preview');
            setChatHistory([]); 
            setError(null);

            // Add initial welcome message
            setChatHistory([{
                role: 'model',
                parts: [{ text: `Hello! I've read "${paper.title}". Ask me anything about its methodology, findings, or implications.` }]
            }]);
        } catch (e) {
            setError("Failed to initialize chat session.");
        }
    }, [paper]);

    const handleSendMessage = async (message: string) => {
        if (!chatSessionRef.current) return;

        const userMsg: ChatMessage = { role: 'user', parts: [{ text: message }] };
        setChatHistory(prev => [...prev, userMsg]);
        setIsLoading(true);
        setError(null);

        try {
            const result = await chatSessionRef.current.sendMessage({ message });
            const modelMsg: ChatMessage = { role: 'model', parts: [{ text: result.text }] };
            setChatHistory(prev => [...prev, modelMsg]);
        } catch (err) {
            setError(err instanceof Error ? err.message : "Failed to send message.");
            // Remove user message on failure or show error state? 
            // Better to keep it but show error.
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="h-[500px] border rounded-lg overflow-hidden flex flex-col">
            <ChatPanel 
                history={chatHistory} 
                isLoading={isLoading} 
                error={error} 
                onSendMessage={handleSendMessage} 
            />
        </div>
    );
};

/**
 * TOON (Text-Oriented Object Notation) Utility
 * 
 * A hyper-compact serialization format designed to minimize token usage 
 * in LLM context windows. It removes all non-essential formatting and keys.
 */

import type { ResearchPaper } from '../types';

export const paperToToon = (paper: ResearchPaper, index: number): string => {
    // Format: #[Index]|T:{Title}|A:{Authors}|Y:{Year}|C:{Citations}|S:{Snippet}
    // We strip newlines and extra spaces from title and snippet.
    const t = (paper.title || "").replace(/[\n\r]/g, ' ').replace(/\s+/g, ' ').trim();
    const a = (paper.authors || "").split(',')[0].trim() + " et al";
    const y = paper.year || "0000";
    const c = paper.citations || 0;
    const s = (paper.abstract || "").replace(/[\n\r]/g, ' ').replace(/\s+/g, ' ').substring(0, 600).trim();

    return `#${index}|T:${t}|A:${a}|Y:${y}|C:${c}|S:${s}`;
};

export const papersToToonCollection = (papers: ResearchPaper[]): string => {
    // Delimit papers with a single newline to save tokens
    return papers.map((p, i) => paperToToon(p, i + 1)).join('\n');
};

import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
const EMBEDDING_MODEL = "text-embedding-004";

// Persistent Cache using localStorage (simple string-key store)
const PERSISTENT_CACHE_KEY = 'are_embeddings_index_v1';
const getStoredEmbeddings = (): Record<string, number[]> => {
    try {
        const stored = localStorage.getItem(PERSISTENT_CACHE_KEY);
        return stored ? JSON.parse(stored) : {};
    } catch { return {}; }
};

const saveEmbeddingsToStore = (newEmbeddings: Record<string, number[]>) => {
    try {
        const current = getStoredEmbeddings();
        const updated = { ...current, ...newEmbeddings };
        // Basic eviction: if cache > 1MB, clear old entries
        if (JSON.stringify(updated).length > 1024 * 1024) {
            localStorage.removeItem(PERSISTENT_CACHE_KEY);
            localStorage.setItem(PERSISTENT_CACHE_KEY, JSON.stringify(newEmbeddings));
        } else {
            localStorage.setItem(PERSISTENT_CACHE_KEY, JSON.stringify(updated));
        }
    } catch {}
};

export const embedText = async (text: string): Promise<number[]> => {
    if (!text || text.trim() === '') return [];

    const cacheKey = text.trim().substring(0, 500); // Index by truncated text
    const store = getStoredEmbeddings();

    if (store[cacheKey]) return store[cacheKey];

    try {
        const response = await ai.models.embedContent({ 
            model: EMBEDDING_MODEL, 
            contents: text
        }) as any;

        const embedding = response.embedding?.values || [];
        if (embedding.length > 0) {
            saveEmbeddingsToStore({ [cacheKey]: embedding });
        }
        return embedding;
    } catch (e) {
        console.error("Embedding failed:", e);
        return [];
    }
};

export const batchEmbedText = async (texts: string[]): Promise<number[][]> => {
    if (!texts || texts.length === 0) return [];

    // Efficiently separate cached vs new items
    const store = getStoredEmbeddings();
    const results: number[][] = new Array(texts.length);
    const indicesToFetch: number[] = [];
    const textsToFetch: string[] = [];

    texts.forEach((text, i) => {
        const key = text.substring(0, 500);
        if (store[key]) {
            results[i] = store[key];
        } else {
            indicesToFetch.push(i);
            textsToFetch.push(text);
        }
    });

    if (textsToFetch.length > 0) {
        // Fetch remaining in parallel
        const fetched = await Promise.all(textsToFetch.map(t => embedText(t)));
        indicesToFetch.forEach((originalIndex, fetchIndex) => {
            results[originalIndex] = fetched[fetchIndex];
        });
    }

    return results;
};

