/**
 * Normalizes metrics and combines them into a single relevance score.
 */
const computeCombinedScore = (semanticScore: number, citations: number = 0): number => {
    // 0-100 semantic score
    // 0-100 citation score (log scale, 500 citations approx 80 pts)
    const citationScore = citations === 0 ? 0 : Math.min(100, Math.round((Math.log10(citations) / 2.7) * 100));
    // Weighing: 75% semantic relevance, 25% academic impact
    return Math.round((semanticScore * 0.75) + (citationScore * 0.25));
};

