export const runBackgroundAIAnalysis = async (
    query: string,
    options: AdvancedSearchOptions,
    initialPapers: ResearchPaper[],
    model: ModelDefinition,
    summaryLength: SummaryLength,
    summaryStyle: SummaryStyle,
    sources: SearchSourceInfo[],
    setAiParsedFilters: (filters: any) => void,
    setAiHypotheticalAnswer: (answer: string) => void
): Promise<{
    refinedPapers: ResearchPaper[];
    newGroundedPapers: ResearchPaper[];
    newSummary: string;
    newAnalysis: AnalysisResult | null;
    finalParsedFilters: any;
    finalHypotheticalAnswer: string;
}> => {

    const cacheKey = `${query}_${summaryLength}_${summaryStyle}_${model.id}`;
    const cache = getStoredCache();
    if (cache[cacheKey]) {
        const data = cache[cacheKey];
        setAiParsedFilters(data.finalParsedFilters);
        setAiHypotheticalAnswer(data.finalHypotheticalAnswer);
        return data;
    }

    // A. Strategy & Initial Fetch (Parallel)
    const [strategy, groundedResults] = await Promise.all([
        geminiService.getUnifiedSearchStrategy(query, model),
        geminiService.findPapersWithGoogleSearch(query, model).catch(() => [])
    ]);

    const { filters: parsedFilters, hypothesis: hypotheticalAnswer } = strategy;
    setAiParsedFilters(parsedFilters);
    setAiHypotheticalAnswer(hypotheticalAnswer);

    // B. Scoring & Grounding
    const groundedPapers = groundedResults.map(p => ({
        ...p,
        id: createPaperId(p), 
        citations: p.citations || 0, 
        semanticScore: 0 
    } as ResearchPaper));

    // Calculate Combined Scores (Semantic + Impact)
    const [scoredInitial, scoredGrounded] = await Promise.all([
        calculatePaperScores(initialPapers, query, hypotheticalAnswer, model, options),
        calculatePaperScores(groundedPapers, query, hypotheticalAnswer, model, options)
    ]);

    // C. Final Synthesis
    const combinedTop = [...scoredInitial, ...scoredGrounded]
        .sort((a, b) => (b.combinedScore || 0) - (a.combinedScore || 0))
        .slice(0, 20); // Process more papers thanks to TOON token savings

    const [summary, analysis] = await Promise.all([
        geminiService.generateSummaryForPapers(combinedTop, summaryLength, summaryStyle, model),
        analysisService.analyzePapers(combinedTop)
    ]);

    const result = {
        refinedPapers: scoredInitial,
        newGroundedPapers: scoredGrounded,
        newSummary: summary,
        newAnalysis: analysis,
        finalParsedFilters: parsedFilters,
        finalHypotheticalAnswer: hypotheticalAnswer
    };

    cache[cacheKey] = result;
    setStoredCache(cache);
    return result;
};

