/**
 * Persistent Cache Utility
 * Provides a localStorage-backed cache with TTL support and automatic size management.
 */

interface CacheItem<T> {
    data: T;
    expiry: number;
}

export const getCache = <T>(key: string): T | null => {
    try {
        const itemStr = localStorage.getItem(key);
        if (!itemStr) return null;

        const item: CacheItem<T> = JSON.parse(itemStr);
        const now = new Date().getTime();

        if (now > item.expiry) {
            localStorage.removeItem(key);
            return null;
        }
        return item.data;
    } catch (e) {
        console.warn(`Cache read error for key: ${key}`, e);
        return null;
    }
};

export const setCache = <T>(key: string, data: T, ttlMs: number): void => {
    try {
        const expiry = new Date().getTime() + ttlMs;
        const item: CacheItem<T> = { data, expiry };
        const serialized = JSON.stringify(item);

        // Simple size management: if local storage is getting full, clear old research items
        // Standard limit is 5MB. If this item is huge or storage is full, we handle it.
        try {
            localStorage.setItem(key, serialized);
        } catch (e) {
            console.warn("LocalStorage full, clearing academic cache...");
            clearAcademicCache();
            localStorage.setItem(key, serialized);
        }
    } catch (e) {
        console.error(`Cache write error for key: ${key}`, e);
    }
};

const clearAcademicCache = () => {
    // Only clear keys starting with our prefixes to avoid breaking other app state
    const prefixes = ['openalex_', 'arxiv_', 'single_paper_'];
    for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);
        if (key && prefixes.some(p => key.startsWith(p))) {
            localStorage.removeItem(key);
        }
    }
};

