const computeCombinedScore = (semanticScore: number, citations: number = 0): number => {
    const citationScore = citations === 0 ? 0 : Math.min(100, Math.round((Math.log10(citations) / 2.7) * 100));
    return Math.round((semanticScore * 0.75) + (citationScore * 0.25));
};

export const searchFast = async (
    query: string, 
    options: AdvancedSearchOptions, 
    sources: SearchSourceInfo[], 
    page: number
): Promise<{ papers: ResearchPaper[], hasMore: boolean, rawQueryUsed: string }> => {
    // Parallelize OpenAlex and arXiv for better coverage
    const [oaResult, arxivResult] = await Promise.all([
        openalexService.searchOpenAlex(query, options, page),
        arxivService.searchArxiv(query, page).catch(() => ({ papers: [], hasMore: false }))
    ]);

    const combinedPapers = mergePapers([...oaResult.papers, ...arxivResult.papers]);

    return { 
        papers: combinedPapers.map(p => ({ ...p, combinedScore: p.combinedScore || 0 })), 
        hasMore: oaResult.hasMore || arxivResult.hasMore, 
        rawQueryUsed: query 
    };
};

