const S2_API_BASE = 'https://api.semanticscholar.org/graph/v1';
const CACHE_TTL_MS = 5 * 60 * 1000;

export const searchSemanticScholar = async (query: string, options: AdvancedSearchOptions, page: number = 1): Promise<{ papers: ResearchPaper[], hasMore: boolean }> => {
    const cacheKey = `s2_search_${query}_${page}`;
    const cached = getCache<any>(cacheKey);
    if (cached) return cached;

    const limit = 15;
    const offset = (page - 1) * limit;
    const fields = 'title,authors,year,abstract,url,citationCount,influentialCitationCount,openAccessPdf,venue,externalIds';

    const url = `${S2_API_BASE}/paper/search?query=${encodeURIComponent(query)}&limit=${limit}&offset=${offset}&fields=${fields}`;

    try {
        const response = await fetch(url);
        if (!response.ok) throw new Error("S2 API Error");
        const data = await response.json();

        const papers: ResearchPaper[] = (data.data || []).map((p: any) => ({
            id: `s2:${p.paperId}`,
            title: p.title,
            authors: (p.authors || []).map((a: any) => a.name).join(', '),
            year: p.year,
            abstract: p.abstract || 'No abstract available.',
            sourceURL: p.url,
            pdfURL: p.openAccessPdf?.url || undefined,
            citations: p.citationCount,
            influentialCitationCount: p.influentialCitationCount,
            doi: p.externalIds?.DOI,
            journal: p.venue,
            isOpenAccess: !!p.openAccessPdf,
            enrichmentSource: 'Semantic Scholar'
        }));

        const result = { papers, hasMore: !!data.next };
        setCache(cacheKey, result, CACHE_TTL_MS);
        return result;
    } catch (e) {
        console.error("Semantic Scholar search failed:", e);
        return { papers: [], hasMore: false };
    }
};

export const getPaperInfluenceData = async (doi: string): Promise<Partial<ResearchPaper> | null> => {
    const url = `${S2_API_BASE}/paper/DOI:${doi}?fields=citationCount,influentialCitationCount,openAccessPdf`;
    try {
        const response = await fetch(url);
        if (!response.ok) return null;
        const p = await response.json();
        return {
            citations: p.citationCount,
            influentialCitationCount: p.influentialCitationCount,
            pdfURL: p.openAccessPdf?.url || undefined
        };
    } catch { return null; }
};

import type { ResearchPaper, AdvancedSearchOptions } from '../types';
import { getCache, setCache } from '../utils/cache';

const CORE_API_BASE = 'https://api.core.ac.uk/v3';
const CACHE_TTL_MS = 10 * 60 * 1000;

/**
 * CORE Integration focuses on finding repository-hosted versions 
 * of papers that might be paywalled on official sites.
 */
export const searchCORE = async (query: string, page: number = 1): Promise<{ papers: ResearchPaper[], hasMore: boolean }> => {
    const cacheKey = `core_search_${query}_${page}`;
    const cached = getCache<any>(cacheKey);
    if (cached) return cached;

    // CORE API usually requires a key for high volume, 
    // but they offer a limited public tier for search.
    const url = `${CORE_API_BASE}/search/works?q=${encodeURIComponent(query)}&limit=10&offset=${(page-1)*10}`;

    try {
        const response = await fetch(url);
        if (!response.ok) return { papers: [], hasMore: false };
        const data = await response.json();

        const papers: ResearchPaper[] = (data.results || []).map((p: any) => ({
            id: `core:${p.id}`,
            coreId: p.id.toString(),
            title: p.title,
            authors: (p.authors || []).map((a: any) => a.name).join(', '),
            year: p.publishedDate ? new Date(p.publishedDate).getFullYear() : 0,
            abstract: p.abstract || 'No abstract.',
            sourceURL: p.downloadUrl || p.fullTextUrl || undefined,
            pdfURL: p.downloadUrl || undefined,
            repositoryURL: p.publisher || undefined,
            doi: p.doi,
            isOpenAccess: true, // CORE mostly indexes OA
            enrichmentSource: 'CORE'
        }));

        const result = { papers, hasMore: data.totalHits > (page * 10) };
        setCache(cacheKey, result, CACHE_TTL_MS);
        return result;
    } catch { return { papers: [], hasMore: false }; }
};

