import { getCache, setCache } from '../utils/cache';

const SESSION_CACHE_KEY_PREFIX = 'are_session_v5_';

/**
 * AUTHORITATIVE SCORING ENGINE
 * Normalizes metrics from multiple sources.
 */
const computeCombinedScore = (semanticScore: number, citations: number = 0, influentialCitations: number = 0): number => {
    // 1. Semantic Match (0-100) - Weight 0.4
    // 2. Global Citations (Log scale, 0-100) - Weight 0.2
    // 3. Authority/Influence (Influential Citations count heavily) - Weight 0.4

    const citationScore = citations === 0 ? 0 : Math.min(100, Math.round((Math.log10(citations) / 2.7) * 100));
    const influenceScore = influentialCitations === 0 ? 0 : Math.min(100, Math.round((Math.log10(influentialCitations * 5) / 2.5) * 100));

    return Math.round(
        (semanticScore * 0.4) + 
        (citationScore * 0.2) + 
        (influenceScore * 0.4)
    );
};

export const searchFast = async (
    query: string, 
    options: AdvancedSearchOptions, 
    sources: SearchSourceInfo[], 
    page: number
): Promise<{ papers: ResearchPaper[], hasMore: boolean, rawQueryUsed: string }> => {

    // AGGRESSIVE PARALLEL RETRIEVAL
    // We hit all three major indices to ensure we have:
    // - Breadth (OpenAlex)
    // - Authority Data (Semantic Scholar)
    // - Repository Full Text (CORE)
    const [oaResult, s2Result, coreResult, arxivResult] = await Promise.all([
        openalexService.searchOpenAlex(query, options, page),
        semanticScholarService.searchSemanticScholar(query, options, page).catch(() => ({ papers: [], hasMore: false })),
        coreService.searchCORE(query, page).catch(() => ({ papers: [], hasMore: false })),
        arxivService.searchArxiv(query, page).catch(() => ({ papers: [], hasMore: false }))
    ]);

    // Merge and deduplicate by DOI or normalized Title
    const merged = mergePapers([
        ...oaResult.papers, 
        ...s2Result.papers, 
        ...coreResult.papers, 
        ...arxivResult.papers
    ]);

    return { 
        papers: merged.map(p => ({ ...p, combinedScore: p.combinedScore || 0 })), 
        hasMore: oaResult.hasMore || s2Result.hasMore, 
        rawQueryUsed: query 
    };
};

export const calculatePaperScores = async (
    papers: ResearchPaper[], 
    query: string, 
    hypotheticalAnswer: string,
    model: ModelDefinition,
    options: AdvancedSearchOptions
): Promise<ResearchPaper[]> => {
    const textToEmbed = hypotheticalAnswer || query;
    const scoredPapers = await embeddingService.calculateSemanticScores(textToEmbed, papers);

    return scoredPapers.map(p => ({
        ...p,
        combinedScore: computeCombinedScore(p.semanticScore || 0, p.citations, p.influentialCitationCount)
    }));
};

export const runBackgroundAIAnalysis = async (
    query: string,
    options: AdvancedSearchOptions,
    initialPapers: ResearchPaper[],
    model: ModelDefinition,
    summaryLength: SummaryLength,
    summaryStyle: SummaryStyle,
    sources: SearchSourceInfo[],
    setAiParsedFilters: (filters: any) => void,
    setAiHypotheticalAnswer: (answer: string) => void
): Promise<{
    refinedPapers: ResearchPaper[];
    newGroundedPapers: ResearchPaper[];
    newSummary: string;
    newAnalysis: AnalysisResult | null;
    finalParsedFilters: any;
    finalHypotheticalAnswer: string;
}> => {

    const cacheKey = `${SESSION_CACHE_KEY_PREFIX}${query}_${summaryLength}_${summaryStyle}_${model.id}`;
    const cached = getCache<any>(cacheKey);
    if (cached) {
        setAiParsedFilters(cached.finalParsedFilters);
        setAiHypotheticalAnswer(cached.finalHypotheticalAnswer);
        return cached;
    }

    const [strategy, groundedResults] = await Promise.all([
        geminiService.getUnifiedSearchStrategy(query, model),
        geminiService.findPapersWithGoogleSearch(query, model).catch(() => [])
    ]);

    const { filters: parsedFilters, hypothesis: hypotheticalAnswer } = strategy;
    setAiParsedFilters(parsedFilters);
    setAiHypotheticalAnswer(hypotheticalAnswer);

    // Score all initial and grounded papers
    const groundedPapers = groundedResults.map(p => ({
        ...p,
        id: createPaperId(p), 
        citations: p.citations || 0, 
        semanticScore: 0 
    } as ResearchPaper));

    const [scoredInitial, scoredGrounded] = await Promise.all([
        calculatePaperScores(initialPapers, query, hypotheticalAnswer, model, options),
        calculatePaperScores(groundedPapers, query, hypotheticalAnswer, model, options)
    ]);

    // Top authoritative selection for the summary
    const combinedTop = [...scoredInitial, ...scoredGrounded]
        .sort((a, b) => (b.combinedScore || 0) - (a.combinedScore || 0))
        .slice(0, 20); 

    const [summary, analysis] = await Promise.all([
        geminiService.generateSummaryForPapers(combinedTop, summaryLength, summaryStyle, model),
        analysisService.analyzePapers(combinedTop)
    ]);

    const result = {
        refinedPapers: scoredInitial,
        newGroundedPapers: scoredGrounded,
        newSummary: summary,
        newAnalysis: analysis,
        finalParsedFilters: parsedFilters,
        finalHypotheticalAnswer: hypotheticalAnswer
    };

    setCache(cacheKey, result, 10 * 60 * 1000); 
    return result;
};

export const mergePapers = (papers: ResearchPaper[]): ResearchPaper[] => {
    const unique = new Map<string, ResearchPaper>();
    papers.forEach(p => {
        // Use DOI as primary key, fallback to normalized title ID
        const key = p.doi?.toLowerCase() || p.id;
        const existing = unique.get(key);

        if (!existing) {
            unique.set(key, p);
        } else {
            // Merge properties, keeping the most "enriched" data
            unique.set(key, {
                ...existing,
                ...p,
                // Combine scores if they exist
                citations: Math.max(existing.citations || 0, p.citations || 0),
                influentialCitationCount: Math.max(existing.influentialCitationCount || 0, p.influentialCitationCount || 0),
                pdfURL: existing.pdfURL || p.pdfURL,
                abstract: existing.abstract.length > p.abstract.length ? existing.abstract : p.abstract
            });
        }
    });
    return Array.from(unique.values());
};

