const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const safeJsonParse = (jsonString: string) => {
  if (!jsonString || !jsonString.trim()) return null;
  try {
    const cleanedString = jsonString.replace(/```json/g, '').replace(/```/g, '').trim();
    return JSON.parse(cleanedString);
  } catch (e) {
    console.error("Failed to parse JSON:", jsonString, e);
    return null;
  }
};

/**
 * NEW: Multimodal PDF Metadata Extraction
 * Uses vision/multimodal capabilities to read a raw PDF.
 */
export const extractMetadataFromPdf = async (base64Pdf: string): Promise<Partial<ResearchPaper>> => {
    const prompt = `Act as an academic librarian. Extract the following from this PDF document:
    1. Title
    2. Authors (comma separated)
    3. Publication Year
    4. A concise 300-word abstract
    5. DOI (if present)

    Return as a JSON object with keys: title, authors, year, abstract, doi.`;

    try {
        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: {
                parts: [
                    { inlineData: { mimeType: "application/pdf", data: base64Pdf } },
                    { text: prompt }
                ]
            },
            config: { responseMimeType: "application/json" }
        });
        return safeJsonParse(response.text ?? '') || {};
    } catch (e) {
        console.error("PDF Extraction failed:", e);
        throw new Error("Failed to parse PDF content.");
    }
};

/**
 * NEW: Structured Literature Review Drafting
 * Uses the Pro model for high-reasoning synthesis.
 */
export const draftLiteratureReview = async (papers: ResearchPaper[], topic: string): Promise<LiteratureReviewDraft> => {
    const context = papersToToonCollection(papers);
    const prompt = `Topic: "${topic}"

    Using these ${papers.length} sources:
    ${context}

    Task: Draft a formal academic literature review.
    1. Synthesize themes across papers.
    2. Critically evaluate methodologies.
    3. Identify gaps in current literature.

    Structure:
    - Introduction & Theoretical Framework
    - Thematic Synthesis
    - Methodological Trends
    - Critical Gaps & Conclusion

    Use [1], [2] citations. Return JSON with "title" and a "sections" array of {heading, content}.`;

    try {
        const response = await ai.models.generateContent({
            model: "gemini-3-pro-preview",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                thinkingConfig: { thinkingBudget: 16000 }
            }
        });
        return safeJsonParse(response.text ?? '') || { title: "Draft", sections: [] };
    } catch (e) {
        console.error("Drafting failed:", e);
        throw new Error("Failed to generate literature review draft.");
    }
};

