export const getUnifiedSearchStrategy = async (userQuery: string, model: ModelDefinition): Promise<{ filters: any, hypothesis: string }> => {
    const prompt = `Task: Prepare a research retrieval strategy for: "${userQuery}".
    1. Parse the query into structured filters (years, authors, core keywords).
    2. Generate a 150-word hypothetical abstract that perfectly answers the query for semantic matching.
    Return JSON with "parsedFilters" and "hypotheticalAbstract".`;
    try {
        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview", 
            contents: prompt,
            config: { responseMimeType: "application/json" }
        });
        const result = safeJsonParse(response.text ?? '');
        return { filters: result?.parsedFilters || { core_search_query: userQuery }, hypothesis: result?.hypotheticalAbstract || userQuery };
    } catch (e) { return { filters: { core_search_query: userQuery }, hypothesis: userQuery }; }
};

export const generateSummaryForPapers = async (papers: ResearchPaper[], length: SummaryLength, style: SummaryStyle, model: ModelDefinition): Promise<string> => {
    if (papers.length === 0) return "";
    const context = papersToToonCollection(papers.slice(0, 15));
    const prompt = `Synthesize an overview from: ${context}\nStyle: ${style}, Length: ${length}. Use [1], [2] citations.`;
    try {
        const result = await ai.models.generateContent({ model: model.id, contents: prompt });
        return result.text || "";
    } catch { return "Summary failed."; }
};

