const SESSION_CACHE_KEY_PREFIX = 'are_session_v6_';

export const handlePdfUpload = async (base64Pdf: string): Promise<ResearchPaper> => {
    const metadata = await geminiService.extractMetadataFromPdf(base64Pdf);
    const paper: ResearchPaper = {
        id: `local_${Date.now()}`,
        title: metadata.title || "Untitled Document",
        authors: metadata.authors || "Unknown Authors",
        year: metadata.year || new Date().getFullYear(),
        abstract: metadata.abstract || "No abstract extracted.",
        doi: metadata.doi,
        enrichmentSource: 'Local Upload',
        localFileBase64: base64Pdf
    };
    return paper;
};

export const draftLiteratureReview = async (papers: ResearchPaper[], topic: string): Promise<LiteratureReviewDraft> => {
    return geminiService.draftLiteratureReview(papers, topic);
};

export const searchFast = async (query: string, options: AdvancedSearchOptions, sources: SearchSourceInfo[], page: number): Promise<{ papers: ResearchPaper[], hasMore: boolean, rawQueryUsed: string }> => {
    const { papers, hasMore } = await openalexService.searchOpenAlex(query, options, page);
    return { papers, hasMore, rawQueryUsed: query };
};

export const runBackgroundAIAnalysis = async (query: string, options: AdvancedSearchOptions, initialPapers: ResearchPaper[], model: ModelDefinition, length: SummaryLength, style: SummaryStyle, sources: SearchSourceInfo[], setAiParsedFilters: (f: any) => void, setAiHypotheticalAnswer: (a: string) => void) => {
    const cacheKey = `${SESSION_CACHE_KEY_PREFIX}${query}_${length}_${style}_${model.id}`;
    const cached = getCache<any>(cacheKey);
    if (cached) {
        setAiParsedFilters(cached.finalParsedFilters);
        setAiHypotheticalAnswer(cached.finalHypotheticalAnswer);
        return cached;
    }

    const [strategy, groundedResults] = await Promise.all([
        geminiService.getUnifiedSearchStrategy(query, model),
        geminiService.findPapersWithGoogleSearch(query, model).catch(() => [])
    ]);

    const { filters: parsedFilters, hypothesis: hypotheticalAnswer } = strategy;
    setAiParsedFilters(parsedFilters);
    setAiHypotheticalAnswer(hypotheticalAnswer);

    const groundedPapers = groundedResults.map(p => ({ ...p, id: createPaperId(p) } as ResearchPaper));
    const combined = [...initialPapers, ...groundedPapers];

    const [summary, analysis] = await Promise.all([
        geminiService.generateSummaryForPapers(combined, length, style, model),
        analysisService.analyzePapers(combined)
    ]);

    const result = { refinedPapers: initialPapers, newGroundedPapers: groundedPapers, newSummary: summary, newAnalysis: analysis, finalParsedFilters: parsedFilters, finalHypotheticalAnswer: hypotheticalAnswer };
    setCache(cacheKey, result, 10 * 60 * 1000);
    return result;
};

