                                {isSynthesisLoading ? <LoadingSpinner /> : (
                                    <div className="border rounded-lg overflow-hidden bg-card">
                                        <table className="min-w-full divide-y divide-border text-sm">
                                            <thead className="bg-muted/50">
                                                <tr><th className="p-3 text-left">Paper</th><th className="p-3 text-left">Methodology</th><th className="p-3 text-left">Key Finding</th></tr>
                                            </thead>
                                            <tbody className="divide-y">
                                                {synthesisResult?.map((r, i) => (
                                                    <tr key={i}><td className="p-3 font-medium">{r.title}</td><td className="p-3 text-muted-foreground">{r.methodology}</td><td className="p-3">{r.mainFinding}</td></tr>
                                                ))}
                                            </tbody>
                                        </table>
                                    </div>
                                )}
                            </section>
                            <section>
                                <h3 className="text-lg font-bold mb-4 flex items-center gap-2"><ReportIcon className="w-5 h-5 text-primary"/> Research Gaps</h3>
                                {isGapAnalysisLoading ? <LoadingSpinner /> : <div className="bg-card p-6 rounded-lg border prose prose-sm max-w-none"><FormattedReport text={gapAnalysisReport || "Not enough data."}/></div>}
                            </section>
                        </div>
                    )}

                    {activeTab === 'drafting' && (
                        <div className="space-y-6">
                            <div className="bg-purple-50 border border-purple-100 p-6 rounded-xl">
                                <h3 className="text-lg font-bold text-purple-900 mb-2 flex items-center gap-2"><SparklesIcon className="w-5 h-5"/> Review Assistant</h3>
                                <p className="text-sm text-purple-700 mb-4">Define a topic to generate a structured literature review draft using your saved papers.</p>
                                <div className="flex gap-2">
                                    <input 
                                        type="text" 
                                        value={draftTopic} 
                                        onChange={e => setDraftTopic(e.target.value)} 
                                        placeholder="e.g. Current trends in federated learning architectures..." 
                                        className="flex-grow h-10 px-3 rounded-md border border-purple-200 focus:ring-2 focus:ring-purple-500"
                                    />
                                    <button 
                                        onClick={handleDraftReview}
                                        disabled={isDrafting || !draftTopic.trim()}
                                        className="h-10 px-6 bg-purple-600 text-white font-bold rounded-md hover:bg-purple-700 disabled:opacity-50"
                                    >
                                        {isDrafting ? 'Drafting (Pro)...' : 'Generate Draft'}
                                    </button>
                                </div>
                            </div>

                            {currentDraft && (
                                <div className="space-y-8 animate-fade-in">
                                    <div className="flex justify-between items-center border-b pb-2">
                                        <h1 className="text-2xl font-extrabold">{currentDraft.title}</h1>
                                        <button className="flex items-center gap-2 text-sm font-bold text-primary hover:underline"><ExportIcon className="w-4 h-4"/> Export .md</button>
                                    </div>
                                    {currentDraft.sections.map((s, i) => (
                                        <section key={i}>
                                            <h2 className="text-lg font-bold mb-3 border-l-4 border-primary pl-3">{s.heading}</h2>
                                            <p className="text-muted-foreground leading-relaxed whitespace-pre-wrap">{s.content}</p>
                                        </section>
                                    ))}
                                </div>
                            )}
                        </div>
                    )}

                    {activeTab === 'assistant' && (
                        <div className="h-[600px] border rounded-lg overflow-hidden bg-card">
                            <ChatPanel history={chatHistory} isLoading={isChatLoading} error={null} onSendMessage={onChat} />
                        </div>
                    )}
                </main>
            </div>
        </div>
    );
};

