interface SearchFormProps {
  query: string;
  onQueryChange: (query: string) => void;
  onSearch: (query: string, options: AdvancedSearchOptions) => void;
  isLoading: boolean;
  summaryLength: SummaryLength;
  onLengthChange: (length: SummaryLength) => void;
  summaryStyle: SummaryStyle;
  onStyleChange: (style: SummaryStyle) => void;
  model: ModelDefinition;
  onModelChange: (model: ModelDefinition) => void;
  availableModels: ModelDefinition[];
  logAnalyticsEvent: (eventName: string, payload: object) => void;
  suggestions: string[];
  isSuggestionsLoading: boolean;
  onSuggestionClick: (suggestion: string) => void;
  onOpenOrgFinder: () => void;
  selectedInstitution?: { id: string; name: string };
  onClearInstitution: () => void;
  onOpenDeepResearch: () => void;
}

type SearchMode = 'topic' | 'doi';

const summaryStyles: { id: SummaryStyle; name: string }[] = [
    { id: 'paragraph', name: 'Paragraph' },
    { id: 'bullets', name: 'Bullets' },
    { id: 'qa', name: 'Q&A' },
];

const studyDesigns = [
    { id: 'any', name: 'Any Study Design' },
    { id: 'randomized_controlled_trial', name: 'Randomized Controlled Trial' },
    { id: 'systematic_review', name: 'Systematic Review' },
    { id: 'observational_study', name: 'Observational Study' },
    { id: 'qualitative_study', name: 'Qualitative Study' },
];

export const SearchForm: React.FC<SearchFormProps> = ({ 
    query,
    onQueryChange,
    onSearch, 
    isLoading, 
    summaryLength, 
    onLengthChange,
    summaryStyle,
    onStyleChange,
    model,
    onModelChange,
    availableModels,
    suggestions,
    isSuggestionsLoading,
    onSuggestionClick,
    onOpenOrgFinder,
    selectedInstitution,
    onClearInstitution,
    onOpenDeepResearch
}) => {
  const [isRefineOpen, setIsRefineOpen] = useState(false);
  const [searchMode, setSearchMode] = useState<SearchMode>('topic');

  // We maintain separate local states to preserve context when switching modes
  const [localQuery, setLocalQuery] = useState(query);
  const [localDoi, setLocalDoi] = useState('');

  const [advancedOptions, setAdvancedOptions] = useState<AdvancedSearchOptions>({
    startYear: '',
    endYear: '',
    authors: '',
    excludeKeywords: '',
    inclusionCriteria: '',
    exclusionCriteria: '',
    studyDesign: 'any',
    journal: '',
    minCitations: '',
    titleKeywords: '',
    abstractKeywords: '',
    isOpenAccess: false,
    doi: '',
  });

  useEffect(() => {
    setLocalQuery(query);
  }, [query]);

  useEffect(() => {
      if (selectedInstitution) {
          setAdvancedOptions(prev => ({
              ...prev,
              institutionName: selectedInstitution.name,
              institutionId: selectedInstitution.id
          }));
      } else {
          setAdvancedOptions(prev => {
              const { institutionName, institutionId, ...rest } = prev;
              return rest as AdvancedSearchOptions;
          });
      }
  }, [selectedInstitution]);

  useEffect(() => {
    const handler = setTimeout(() => {
      if (searchMode === 'topic' && localQuery !== query) {
        onQueryChange(localQuery);
      }
    }, 300);
    return () => clearTimeout(handler);
  }, [localQuery, query, onQueryChange, searchMode]);

  const handleAdvancedChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    if (type === 'checkbox') {
        setAdvancedOptions(prev => ({ ...prev, [name]: (e.target as HTMLInputElement).checked }));
    } else {
        setAdvancedOptions(prev => ({ ...prev, [name]: value }));
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (searchMode === 'topic') {
        if (localQuery !== query) {
            onQueryChange(localQuery);
        }
        onSearch(localQuery, { ...advancedOptions, doi: '' });
    } else {
        onSearch('', { ...advancedOptions, doi: localDoi });
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (searchMode === 'topic') {
        setLocalQuery(e.target.value);
    } else {
        setLocalDoi(e.target.value);
    }
  };

  const currentInputValue = searchMode === 'topic' ? localQuery : localDoi;
  const currentPlaceholder = searchMode === 'topic' 
    ? "Search by topic, keywords, or full research question..." 
    : "Enter DOI (e.g. 10.1101/2023.01.01.123456)";

  return (
    <div className="relative">
      <form onSubmit={handleSubmit} className="flex flex-col gap-4">
        <div className="flex flex-col md:flex-row items-stretch md:items-center gap-2">
          {/* Unified Search Group */}
          <div className="flex-grow flex items-stretch shadow-sm rounded-md overflow-hidden border border-input focus-within:ring-2 focus-within:ring-ring focus-within:ring-offset-1 transition-all">
            {/* Mode Selector */}
            <div className="relative flex-shrink-0">
                <select
                    value={searchMode}
                    onChange={(e) => setSearchMode(e.target.value as SearchMode)}
                    className={`h-12 pl-4 pr-10 text-sm font-bold appearance-none cursor-pointer border-r border-input bg-muted/30 hover:bg-muted/50 transition-colors focus:outline-none ${searchMode === 'doi' ? 'text-blue-700' : 'text-foreground'}`}
                    aria-label="Search Type"
                >
                    <option value="topic">Topic</option>
                    <option value="doi">DOI</option>
                </select>
                <div className="absolute inset-y-0 right-3 flex items-center pointer-events-none">
                    <ChevronDownIcon className="w-3.5 h-3.5 text-muted-foreground" />
                </div>
            </div>

            {/* Main Input Field */}
            <div className="relative flex-grow min-w-0">
                <input
                    type="text"
                    value={currentInputValue}
                    onChange={handleInputChange}
                    placeholder={currentPlaceholder}
                    className="w-full pl-4 pr-12 h-12 bg-background border-none focus:ring-0 text-base text-foreground placeholder:text-muted-foreground/60"
                    disabled={isLoading}
                    autoComplete="off"
                />
                <div className="absolute inset-y-0 right-0 flex items-center pr-4">
                    {searchMode === 'topic' ? (
                        <SearchIcon className="w-5 h-5 text-muted-foreground" />
                    ) : (
                        <DoiIcon className="w-5 h-5 text-blue-500" />
                    )}
                </div>
            </div>
          </div>

           <div className="relative hidden lg:block">
              <select
                id="model-select"
                value={model.id}
                onChange={(e) => {
                    const selectedModel = availableModels.find(m => m.id === e.target.value);
                    if (selectedModel) {
                        onModelChange(selectedModel);
                    }
                }}
                disabled={isLoading}
                className="h-12 pl-3 pr-8 bg-background border border-input rounded-md appearance-none focus:ring-2 focus:ring-ring transition-shadow duration-200 text-sm font-medium"
                aria-label="Select AI Model"
              >
                {availableModels.map(m => <option key={m.id} value={m.id}>{m.name}{m.isMock ? ' (Mock)' : ''}</option>)}
              </select>
              <div className="absolute inset-y-0 right-0 flex items-center pr-2 pointer-events-none">
                <ChevronDownIcon className="w-4 h-4 text-muted-foreground" />
              </div>
            </div>

            <div className="flex items-center gap-2">
                <button
                    type="button"
                    onClick={() => setIsRefineOpen(!isRefineOpen)}
                    aria-pressed={isRefineOpen}
                    title="Advanced Filters"
                    className={`h-12 px-4 flex-shrink-0 flex items-center justify-center font-semibold rounded-md border border-input focus:outline-none focus:ring-2 focus:ring-offset-1 focus:ring-ring disabled:cursor-not-allowed transition-colors duration-200 ${
                    isRefineOpen ? 'bg-primary/10 text-primary ring-1 ring-ring' : 'bg-secondary text-secondary-foreground hover:bg-accent'
                    }`}
                    disabled={isLoading}
                >
                    <RefineIcon className="w-5 h-5" />
                </button>
                <button
                    type="submit"
                    disabled={isLoading || !currentInputValue.trim()}
                    className="flex-grow md:flex-grow-0 px-8 h-12 bg-primary text-primary-foreground font-bold rounded-md hover:bg-primary/90 focus:outline-none focus:ring-2 focus:ring-offset-1 focus:ring-ring disabled:bg-primary/50 disabled:cursor-not-allowed transition-all shadow-sm active:scale-95"
                >
                    {isLoading ? 'Searching...' : 'Search'}
                </button>
            </div>
        </div>

        {isRefineOpen && (
          <div className="p-4 bg-muted/50 border border-border rounded-lg mt-2 animate-fade-in space-y-4">
            <h3 className="text-sm font-semibold text-foreground">Advanced Search Filters</h3>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="grid grid-cols-2 gap-2">
                <div>
                  <label htmlFor="startYear" className="block text-xs font-medium text-muted-foreground mb-1">Start Year</label>
                  <input type="number" name="startYear" id="startYear" value={advancedOptions.startYear} onChange={handleAdvancedChange} placeholder="e.g., 2018" className="w-full h-9 px-3 text-sm bg-background border border-input rounded-md"/>
                </div>
                <div>
                  <label htmlFor="endYear" className="block text-xs font-medium text-muted-foreground mb-1">End Year</label>
                  <input type="number" name="endYear" id="endYear" value={advancedOptions.endYear} onChange={handleAdvancedChange} placeholder="e.g., 2023" className="w-full h-9 px-3 text-sm bg-background border border-input rounded-md"/>
                </div>
              </div>
               <div>
                  <label htmlFor="authors" className="block text-xs font-medium text-muted-foreground mb-1">Authors</label>
                  <input type="text" name="authors" id="authors" value={advancedOptions.authors} onChange={handleAdvancedChange} placeholder="e.g., Smith J" className="w-full h-9 px-3 text-sm bg-background border border-input rounded-md"/>
                </div>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label htmlFor="journal" className="block text-xs font-medium text-muted-foreground mb-1">Journal / Venue</label>
