              </div>
              <div>
                <label htmlFor="institution" className="block text-xs font-medium text-muted-foreground mb-1">Institution</label>
                {selectedInstitution ? (
                    <div className="flex items-center justify-between h-9 px-3 bg-background border border-input rounded-md">
                        <span className="text-sm text-foreground truncate">{selectedInstitution.name}</span>
                        <button type="button" onClick={onClearInstitution} className="text-muted-foreground hover:text-destructive">
                            <RemoveIcon className="w-3 h-3" />
