import React, { useState, useEffect } from 'react';
import { SearchIcon } from './icons/SearchIcon';
import type { SummaryLength, AdvancedSearchOptions, SummaryStyle, ModelDefinition } from '../types';
import { ChevronDownIcon } from './icons/ChevronDownIcon';
import { RefineIcon } from './icons/RefineIcon';
import { SearchSuggestions } from './SearchSuggestions';
import { BuildingIcon } from './icons/BuildingIcon';
import { RemoveIcon } from './icons/RemoveIcon';
import { RobotIcon } from './icons/RobotIcon';
import { DoiIcon } from './icons/DoiIcon';

interface SearchFormProps {
  query: string;
  onQueryChange: (query: string) => void;
  onSearch: (query: string, options: AdvancedSearchOptions) => void;
  isLoading: boolean;
  summaryLength: SummaryLength;
  onLengthChange: (length: SummaryLength) => void;
  summaryStyle: SummaryStyle;
  onStyleChange: (style: SummaryStyle) => void;
  model: ModelDefinition;
  onModelChange: (model: ModelDefinition) => void;
  availableModels: ModelDefinition[];
  logAnalyticsEvent: (eventName: string, payload: object) => void;
  suggestions: string[];
  isSuggestionsLoading: boolean;
  onSuggestionClick: (suggestion: string) => void;
  onOpenOrgFinder: () => void;
  selectedInstitution?: { id: string; name: string };
  onClearInstitution: () => void;
  onOpenDeepResearch: () => void;
}

type SearchMode = 'topic' | 'doi';

const summaryStyles: { id: SummaryStyle; name: string }[] = [
    { id: 'paragraph', name: 'Paragraph' },
    { id: 'bullets', name: 'Bullets' },
    { id: 'qa', name: 'Q&A' },
];

const studyDesigns = [
    { id: 'any', name: 'Any Study Design' },
    { id: 'randomized_controlled_trial', name: 'Randomized Controlled Trial' },
    { id: 'systematic_review', name: 'Systematic Review' },
    { id: 'observational_study', name: 'Observational Study' },
    { id: 'qualitative_study', name: 'Qualitative Study' },
];

export const SearchForm: React.FC<SearchFormProps> = ({ 
    query,
    onQueryChange,
    onSearch, 
    isLoading, 
    summaryLength, 
    onLengthChange,
    summaryStyle,
    onStyleChange,
    model,
    onModelChange,
    availableModels,
    suggestions,
    isSuggestionsLoading,
    onSuggestionClick,
    onOpenOrgFinder,
    selectedInstitution,
    onClearInstitution,
    onOpenDeepResearch
}) => {
  const [isRefineOpen, setIsRefineOpen] = useState(false);
  const [searchMode, setSearchMode] = useState<SearchMode>('topic');

  const [localQuery, setLocalQuery] = useState(query);
  const [localDoi, setLocalDoi] = useState('');

  const [advancedOptions, setAdvancedOptions] = useState<AdvancedSearchOptions>({
    startYear: '',
    endYear: '',
    authors: '',
    excludeKeywords: '',
    inclusionCriteria: '',
    exclusionCriteria: '',
    studyDesign: 'any',
    journal: '',
    minCitations: '',
    titleKeywords: '',
    abstractKeywords: '',
    isOpenAccess: false,
    doi: '',
  });

  useEffect(() => {
    setLocalQuery(query);
  }, [query]);

  useEffect(() => {
      if (selectedInstitution) {
          setAdvancedOptions(prev => ({
              ...prev,
              institutionName: selectedInstitution.name,
              institutionId: selectedInstitution.id
          }));
      } else {
          setAdvancedOptions(prev => {
              const { institutionName, institutionId, ...rest } = prev;
              return rest as AdvancedSearchOptions;
          });
      }
  }, [selectedInstitution]);

  useEffect(() => {
    const handler = setTimeout(() => {
      if (searchMode === 'topic' && localQuery !== query) {
        onQueryChange(localQuery);
      }
    }, 300);
    return () => clearTimeout(handler);
  }, [localQuery, query, onQueryChange, searchMode]);

  const handleAdvancedChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    if (type === 'checkbox') {
        setAdvancedOptions(prev => ({ ...prev, [name]: (e.target as HTMLInputElement).checked }));
    } else {
        setAdvancedOptions(prev => ({ ...prev, [name]: value }));
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (searchMode === 'topic') {
        if (localQuery !== query) onQueryChange(localQuery);
        onSearch(localQuery, { ...advancedOptions, doi: '' });
    } else {
        onSearch('', { ...advancedOptions, doi: localDoi });
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (searchMode === 'topic') setLocalQuery(e.target.value);
    else setLocalDoi(e.target.value);
  };

  const currentInputValue = searchMode === 'topic' ? localQuery : localDoi;
  const currentPlaceholder = searchMode === 'topic' 
    ? "Ask a research question or enter keywords..." 
    : "Enter DOI for direct retrieval...";

  return (
    <div className="relative w-full">
      <form onSubmit={handleSubmit} className="flex flex-col gap-6">
        <div className="flex flex-col md:flex-row items-center gap-3">

          {/* Main Pill Search Bar - Expanded width */}
          <div className="relative flex-grow flex items-center bg-background border border-input rounded-full px-2 py-1.5 shadow-sm hover:shadow-md focus-within:shadow-md focus-within:ring-1 focus-within:ring-primary/20 transition-all duration-300 w-full">
            {/* Mode Selector - Sleek and subtle */}
            <div className="relative flex-shrink-0 pl-3 mr-1">
                <select
                    value={searchMode}
                    onChange={(e) => setSearchMode(e.target.value as SearchMode)}
                    className="h-9 pr-6 text-xs font-bold appearance-none cursor-pointer bg-transparent border-none focus:ring-0 text-muted-foreground hover:text-foreground transition-colors uppercase tracking-wider"
                    aria-label="Search Type"
                >
                    <option value="topic">Topic</option>
                    <option value="doi">DOI</option>
                </select>
                <div className="absolute inset-y-0 right-1 flex items-center pointer-events-none">
                    <ChevronDownIcon className="w-3 h-3 text-muted-foreground/50" />
                </div>
                <div className="absolute right-0 top-1/2 -translate-y-1/2 h-4 w-px bg-border" />
            </div>

            {/* Main Input Field */}
            <div className="relative flex-grow min-w-0">
                <input
                    type="text"
                    value={currentInputValue}
                    onChange={handleInputChange}
                    placeholder={currentPlaceholder}
                    className="w-full pl-3 pr-4 h-11 bg-transparent border-none focus:ring-0 text-lg text-foreground placeholder:text-muted-foreground/40 font-medium"
                    disabled={isLoading}
                    autoComplete="off"
                />
            </div>

            {/* Actions Inside Pill */}
            <div className="flex items-center gap-1.5 pr-2">
                <button
                    type="button"
                    onClick={() => setIsRefineOpen(!isRefineOpen)}
                    className={`p-2.5 rounded-full transition-all duration-200 ${
                        isRefineOpen ? 'bg-primary/10 text-primary' : 'text-muted-foreground hover:bg-muted'
                    }`}
                    title="Filters"
                >
                    <RefineIcon className="w-5 h-5" />
                </button>

                <button
                    type="submit"
                    disabled={isLoading || !currentInputValue.trim()}
                    className="flex items-center justify-center h-10 w-10 md:w-auto md:px-5 bg-primary text-primary-foreground rounded-full hover:bg-primary/90 disabled:opacity-50 transition-all shadow-sm"
                >
                    <SearchIcon className="w-5 h-5 md:mr-2" />
                    <span className="hidden md:inline font-bold">Search</span>
                </button>
            </div>
          </div>

          {/* Model Selector - Compact Version */}
          <div className="relative w-full md:w-44 lg:w-48">
              <select
                id="model-select"
                value={model.id}
                onChange={(e) => {
                    const selectedModel = availableModels.find(m => m.id === e.target.value);
                    if (selectedModel) onModelChange(selectedModel);
                }}
                disabled={isLoading}
                className="w-full h-11 pl-4 pr-10 bg-muted/40 border border-border rounded-full appearance-none focus:ring-2 focus:ring-primary/20 transition-all text-xs font-bold text-muted-foreground hover:text-foreground cursor-pointer"
                aria-label="Select AI Model"
              >
                {availableModels.map(m => <option key={m.id} value={m.id}>{m.name.split(' ')[0]}</option>)}
              </select>
              <div className="absolute inset-y-0 right-4 flex items-center pointer-events-none">
                <ChevronDownIcon className="w-3 h-3 text-muted-foreground" />
              </div>
          </div>
        </div>

        {isRefineOpen && (
          <div className="p-5 bg-muted/30 border border-border rounded-2xl animate-fade-in space-y-5">
            <div className="flex items-center justify-between mb-2">
                <h3 className="text-xs font-bold uppercase tracking-widest text-muted-foreground">Advanced Search Filters</h3>
                <button onClick={() => setIsRefineOpen(false)} className="text-xs font-medium hover:underline">Close</button>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label htmlFor="startYear" className="block text-[10px] font-bold uppercase text-muted-foreground mb-1.5 ml-1">Start Year</label>
                  <input type="number" name="startYear" id="startYear" value={advancedOptions.startYear} onChange={handleAdvancedChange} placeholder="2018" className="w-full h-10 px-3 text-sm bg-background border border-input rounded-xl focus:ring-primary/20"/>
                </div>
                <div>
                  <label htmlFor="endYear" className="block text-[10px] font-bold uppercase text-muted-foreground mb-1.5 ml-1">End Year</label>
                  <input type="number" name="endYear" id="endYear" value={advancedOptions.endYear} onChange={handleAdvancedChange} placeholder="2024" className="w-full h-10 px-3 text-sm bg-background border border-input rounded-xl focus:ring-primary/20"/>
                </div>
              </div>
               <div>
                  <label htmlFor="authors" className="block text-[10px] font-bold uppercase text-muted-foreground mb-1.5 ml-1">Authors</label>
                  <input type="text" name="authors" id="authors" value={advancedOptions.authors} onChange={handleAdvancedChange} placeholder="e.g., Bengio Y" className="w-full h-10 px-3 text-sm bg-background border border-input rounded-xl focus:ring-primary/20"/>
                </div>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
              <div>
                <label htmlFor="journal" className="block text-[10px] font-bold uppercase text-muted-foreground mb-1.5 ml-1">Journal / Conference</label>
                <input type="text" name="journal" id="journal" value={advancedOptions.journal || ''} onChange={handleAdvancedChange} placeholder="e.g., Nature, NeurIPS" className="w-full h-10 px-3 text-sm bg-background border border-input rounded-xl focus:ring-primary/20"/>
              </div>
              <div>
                <label htmlFor="institution" className="block text-[10px] font-bold uppercase text-muted-foreground mb-1.5 ml-1">Institution</label>
                {selectedInstitution ? (
                    <div className="flex items-center justify-between h-10 px-3 bg-background border border-input rounded-xl">
                        <span className="text-sm text-foreground truncate font-medium">{selectedInstitution.name}</span>
                        <button type="button" onClick={onClearInstitution} className="p-1 text-muted-foreground hover:text-destructive">
                            <RemoveIcon className="w-4 h-4" />
                        </button>
                    </div>
                ) : (
                    <button
                        type="button"
                        onClick={onOpenOrgFinder}
                        className="w-full h-10 px-3 text-sm bg-background border border-input rounded-xl text-left text-muted-foreground hover:border-primary/50 flex items-center gap-2 transition-colors"
                    >
                        <BuildingIcon className="w-4 h-4" /> <span>Find Institution (ROR)</span>
                    </button>
                )}
              </div>
            </div>
             <div className="flex items-center gap-2 py-1">
                <input type="checkbox" name="isOpenAccess" id="isOpenAccess" checked={advancedOptions.isOpenAccess || false} onChange={handleAdvancedChange} className="h-4 w-4 rounded border-input text-primary focus:ring-primary"/>
                <label htmlFor="isOpenAccess" className="text-xs font-bold text-muted-foreground uppercase tracking-wider">Open Access Only</label>
            </div>
            <hr className="border-border/50" />
             <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                <div>
                  <label htmlFor="inclusionCriteria" className="block text-[10px] font-bold uppercase text-muted-foreground mb-1.5 ml-1">Inclusion Logic</label>
                  <textarea name="inclusionCriteria" id="inclusionCriteria" value={advancedOptions.inclusionCriteria} onChange={handleAdvancedChange} rows={2} placeholder="Must focus on..." className="w-full p-3 text-sm bg-background border border-input rounded-xl focus:ring-primary/20"/>
                </div>
                <div>
                  <label htmlFor="exclusionCriteria" className="block text-[10px] font-bold uppercase text-muted-foreground mb-1.5 ml-1">Exclusion Logic</label>
                  <textarea name="exclusionCriteria" id="exclusionCriteria" value={advancedOptions.exclusionCriteria} onChange={handleAdvancedChange} rows={2} placeholder="Ignore studies on..." className="w-full p-3 text-sm bg-background border border-input rounded-xl focus:ring-primary/20"/>
                </div>
            </div>
          </div>
        )}

        {/* Action Row - Clean and Centered */}
        <div className="flex flex-col sm:flex-row justify-center items-center gap-6">
            <div className="flex flex-wrap items-center justify-center gap-x-6 gap-y-4">
                <div className="flex items-center bg-muted/40 p-1 rounded-full border border-border">
                    <span className="text-[10px] font-black uppercase text-muted-foreground ml-3 mr-2">Summary:</span>
                    {(['short', 'medium', 'detailed'] as SummaryLength[]).map((len) => (
                        <button
                        key={len}
                        type="button"
                        onClick={() => onLengthChange(len)}
                        className={`px-4 py-1.5 rounded-full text-[11px] font-bold uppercase tracking-wider transition-all ${
                            summaryLength === len
                            ? 'bg-primary text-primary-foreground shadow-sm'
                            : 'text-muted-foreground hover:bg-muted'
                        }`}
                        >
                        {len}
                        </button>
                    ))}
                </div>
                 <div className="flex items-center bg-muted/40 p-1 rounded-full border border-border">
                    <span className="text-[10px] font-black uppercase text-muted-foreground ml-3 mr-2">Style:</span>
                    {summaryStyles.map((style) => (
                        <button
                        key={style.id}
                        type="button"
                        onClick={() => onStyleChange(style.id)}
                        className={`px-4 py-1.5 rounded-full text-[11px] font-bold uppercase tracking-wider transition-all ${
                            summaryStyle === style.id
                            ? 'bg-primary text-primary-foreground shadow-sm'
                            : 'text-muted-foreground hover:bg-muted'
                        }`}
                        >
                        {style.name}
                        </button>
                    ))}
                </div>
            </div>

            <div className="flex items-center gap-3">
                <button
                    type="button"
                    onClick={onOpenDeepResearch}
                    className="h-10 px-5 bg-purple-600 text-white text-xs font-black uppercase tracking-widest rounded-full hover:bg-purple-700 flex items-center gap-2 transition-all shadow-md hover:-translate-y-0.5 active:translate-y-0"
                >
                    <RobotIcon className="w-4 h-4" />
                    Deep Research
                </button>
            </div>
        </div>
      </form>
      {searchMode === 'topic' && (isSuggestionsLoading || suggestions.length > 0) && (
        <div className="max-w-5xl mx-auto">
            <SearchSuggestions
                suggestions={suggestions}
                isLoading={isSuggestionsLoading}
                onSuggestionClick={onSuggestionClick}
            />
        </div>
      )}
    </div>
  );
};

