                if (p.id === projectId) {
                    // 10% chance of error for simulation purposes
                    const status = Math.random() > 0.9 ? 'error' : 'indexed';
                    const newStatuses = { ...p.paperStatuses, [paperId]: status };
                    return { ...p, paperStatuses: newStatuses };
