    const [searchSources, setSearchSources] = useState<SearchSourceInfo[]>([{ id: 'openalex', name: 'OpenAlex', description: 'A comprehensive open index of scholarly works.' }]);

    // Workspace Chat State (Replaces projectChats)
    const [workspaceChatHistory, setWorkspaceChatHistory] = useState<ChatMessage[]>([]);
    const [isWorkspaceChatLoading, setIsWorkspaceChatLoading] = useState(false);
    const [projectChats, setProjectChats] = useState<{ [projectId: string]: { history: ChatMessage[], isLoading: boolean } }>({}); // Kept for backwards compat if needed, but unused in UI

    // Live Search Suggestions
    const [searchSuggestions, setSearchSuggestions] = useState<string[]>([]);
    const [isGeneratingSearchSuggestions, setIsGeneratingSearchSuggestions] = useState(false);

    // Pagination state
    const [summary, setSummary] = useState<string>('');
    const [isSummaryLoading, setIsSummaryLoading] = useState(false);
    const [currentPage, setCurrentPage] = useState(1);
    const [isLoadingMore, setIsLoadingMore] = useState(false);
    const [hasMore, setHasMore] = useState(false);
    const [lastUsedOptions, setLastUsedOptions] = useState<AdvancedSearchOptions>({
        startYear: '',
        endYear: '',
        authors: '',
        excludeKeywords: '',
        inclusionCriteria: '',
        exclusionCriteria: '',
        studyDesign: 'any',
        journal: '',
        minCitations: '',
        titleKeywords: '',
        abstractKeywords: '',
        isOpenAccess: false,
    });

    // Modals State
    const [isVerificationModalOpen, setIsVerificationModalOpen] = useState(false);
    const [paperToVerify, setPaperToVerify] = useState<ResearchPaper | null>(null);
    const [isOnboardingOpen, setIsOnboardingOpen] = useState(false);
    const [isAboutModalOpen, setIsAboutModalOpen] = useState(false);
    const [isGapAnalysisModalOpen, setIsGapAnalysisModalOpen] = useState(false);
    const [isAnalyzingGaps, setIsAnalyzingGaps] = useState(false);
    const [gapAnalysisResult, setGapAnalysisResult] = useState<string | null>(null);
    const [gapAnalysisError, setGapAnalysisError] = useState<string | null>(null);
    const [isAnalysisModalOpen, setIsAnalysisModalOpen] = useState(false);
    const [isAnalyzingPaper, setIsAnalyzingPaper] = useState(false);
    const [analysisError, setAnalysisError] = useState<string | null>(null);
    const [analysisResult, setAnalysisResult] = useState<{paper: ResearchPaper, analysis: PaperAnalysis} | null>(null);
    const [isSynthesisModalOpen, setIsSynthesisModalOpen] = useState(false);
    const [isSynthesizing, setIsSynthesizing] = useState(false);
    const [synthesisResult, setSynthesisResult] = useState<SynthesisResult | null>(null);
    const [synthesisError, setSynthesisError] = useState<string | null>(null);
    const [isCitationModalOpen, setIsCitationModalOpen] = useState(false);
    const [paperForCitation, setPaperForCitation] = useState<ResearchPaper | null>(null);
    const [paperForCitationStyle, setPaperForCitationStyle] = useState<CitationStyle>('apa');
    const [isDbFinderOpen, setIsDbFinderOpen] = useState(false);
    const [isSuggestionsModalOpen, setIsSuggestionsModalOpen] = useState(false);
    const [suggestionsResult, setSuggestionsResult] = useState<SuggestionsResult | null>(null);
    const [isGeneratingSuggestions, setIsGeneratingSuggestions] = useState(false);
    const [suggestionsError, setSuggestionsError] = useState<string | null>(null);
    const [isConnectionsModalOpen, setIsConnectionsModalOpen] = useState(false);
    const [connectionsResult, setConnectionsResult] = useState<{ seedPaper: ResearchPaper; connections: ConnectedPaper[] } | null>(null);
    const [isFindingConnections, setIsFindingConnections] = useState(false);
    const [connectionsError, setConnectionsError] = useState<string | null>(null);
    const [isJournalFinderOpen, setIsJournalFinderOpen] = useState(false);
    const [journalRecommendations, setJournalRecommendations] = useState<JournalRecommendation[]>([]);
    const [isFindingJournals, setIsFindingJournals] = useState(false);
    const [journalFinderError, setJournalFinderError] = useState<string | null>(null);
    const [paperForJournalFinder, setPaperForJournalFinder] = useState<ResearchPaper | null>(null);
    const [isOrgFinderOpen, setIsOrgFinderOpen] = useState(false);
    const [selectedInstitution, setSelectedInstitution] = useState<{ id: string; name: string } | undefined>(undefined);
    const [isFindingSimilar, setIsFindingSimilar] = useState(false); // New state for similar papers loading
    const [isDeepResearchOpen, setIsDeepResearchOpen] = useState(false);

    // Workspace Analysis Dashboard State
    const [showWorkspaceAnalysisDrawer, setShowWorkspaceAnalysisDrawer] = useState(false);
    const [workspaceAnalysisResult, setWorkspaceAnalysisResult] = useState<AnalysisResult | null>(null);
    const [workspaceSynthesisSummary, setWorkspaceSynthesisSummary] = useState<SynthesisResult | null>(null);
    const [workspaceGapAnalysisReport, setWorkspaceGapAnalysisReport] = useState<string | null>(null);
    const [isWorkspaceAnalysisLoading, setIsWorkspaceAnalysisLoading] = useState(false); // Overall loading for dashboard data
    const [isWorkspaceSynthesisLoading, setIsWorkspaceSynthesisLoading] = useState(false); // Specific loading for synthesis within dashboard
    const [isWorkspaceGapAnalysisLoading, setIsWorkspaceGapAnalysisLoading] = useState(false); // Specific loading for gap analysis within dashboard


    // Track AI-parsed filters and hypothetical answer for background processing and caching
    const [aiParsedFilters, setAiParsedFilters] = useState<Partial<AdvancedSearchOptions> & { core_search_query: string } | null>(null);
    const [aiHypotheticalAnswer, setAiHypotheticalAnswer] = useState<string | null>(null);

    // Dissertation Study State
    const [goldStandardDataset, setGoldStandardDataset] = useState<GoldStandardPaper[]>([]);
    const [testHarnessResults, setTestHarnessResults] = useState<TestHarnessResult[]>([]);
    const [userStudyData, setUserStudyData] = useState<UserStudyData[]>([]);

    useEffect(() => {
        const handlePaperReceived = (paper: ResearchPaper) => {
            setWorkspacePapers(prev => {
                if (prev.some(p => p.id === paper.id)) {
                    return prev; // Already in workspace
                }
                return [paper, ...prev];
            });
        };

        const cleanup = extensionService.listenForExtensionMessages(
            handlePaperReceived, // onPaperSaved (now used for adding to workspace)
            (paperId) => { // onPaperRemoved
                setWorkspacePapers(prev => prev.filter(p => p.id !== paperId));
            }
        );

        return cleanup;
    }, []);

    // Effect for debouncing search suggestions
    useEffect(() => {
        const fetchSearchSuggestions = async (currentQuery: string) => {
            setIsGeneratingSearchSuggestions(true);
            try {
                const suggestions = await apiService.generateSearchSuggestions(currentQuery, model);
                // Only update suggestions if the query hasn't changed while fetching
                setQuery(prevQuery => {
                    if (prevQuery === currentQuery) {
                        setSearchSuggestions(suggestions);
                    }
                    return prevQuery;
                });
            } catch (error) {
                console.error("Failed to fetch search suggestions:", error);
                setSearchSuggestions([]);
            } finally {
                setIsGeneratingSearchSuggestions(false);
            }
        };

        const handler = setTimeout(() => {
            if (query.length > 3 && !isLoading && !hasSearched) {
                fetchSearchSuggestions(query);
            } else {
                setSearchSuggestions([]);
            }
        }, 500); // 500ms debounce

        return () => {
            clearTimeout(handler);
        };
    }, [query, isLoading, hasSearched, model]);


    // Helper to trigger background validation
    const triggerBackgroundValidation = (papersToValidate: ResearchPaper[]) => {
        // Process validation in the background to populate badges
        papersToValidate.forEach(async (paper) => {
            // Avoid validating if we already have a 'validated' or 'validating' status
            if (paper.validation?.status === 'validated' || paper.validation?.status === 'validating') return;

            // Optimistic update to 'validating'
            const currentValidation = paper.validation || { 
                score: 0, 
                status: 'unvalidated', 
                checks: { crossref_match: false, title_match: false, author_match: false, open_access: false, doaj_indexed: false, source_enriched: false, has_citations: false }, 
                log: [] 
            };
            updatePaperState(paper.id, { validation: { ...currentValidation, status: 'validating' } });

            try {
                const { validation, updatedPaperData } = await apiService.validatePaper(paper);
                updatePaperState(paper.id, { ...updatedPaperData, validation });
            } catch (e) {
                console.warn(`Background validation failed for paper ${paper.id}`, e);
                 updatePaperState(paper.id, { validation: { ...currentValidation, status: 'error' } });
            }
        });
    };


    const handleSearch = async (searchQuery: string, options: AdvancedSearchOptions) => {
        // Use DOI from options if provided, otherwise check if the search query itself is a DOI
        const specificDoi = options.doi?.trim();
        const doiRegex = /^10.\d{4,9}\/[-._;()/:A-Z0-9]+$/i;
        const queryIsDoi = doiRegex.test(searchQuery.trim());
        const effectiveDoi = specificDoi || (queryIsDoi ? searchQuery.trim() : null);

        if (!searchQuery.trim() && !effectiveDoi) return;

        setSearchSuggestions([]);
        setIsGeneratingSearchSuggestions(false);
        setIsLoading(true);
        setIsSearchingGrounded(false);
        setIsRefiningAI(true); // Indicate general AI refinement is starting
        setError(null);
        setPapers([]);
        setSummary(''); 
        setIsSummaryLoading(true); // Summary loading starts with AI refinement
        setHasSearched(true);
        setSelectedPaper(null);
        setAnalysis(null);
        setIsScreeningMode(false);
        setSortConfig({ key: 'relevance', direction: 'desc' });
        setCurrentPage(1);
        setLastUsedOptions(options);
        setAiParsedFilters(null); // Clear previous AI parsed filters
        setAiHypotheticalAnswer(null); // Clear previous AI hypothetical answer
        setIsFindingSimilar(false); // Reset this loading state

        if (effectiveDoi) {
            try {
                const result = await apiService.searchByDoi(effectiveDoi, model);
                if (result) {
                    setPapers([result]);
                    setHasMore(false);
                    handleSelectPaper(result);
                    // Single DOI results don't need background analysis
                    setSummary("DOI direct lookup successful. Showing specific paper details.");
                } else {
                    setError(`No paper found for DOI: ${effectiveDoi}`);
                }
            } catch (err) {
                setError(err instanceof Error ? err.message : "An unknown error occurred while searching by DOI.");
            } finally {
                setIsLoading(false);
                setIsRefiningAI(false);
                setIsSummaryLoading(false);
            }
        } else {
            try {
                // Phase 1: Fast API Search (immediate results)
                const { papers: fastPapers, hasMore: fastHasMore, rawQueryUsed } = await apiService.searchFast(searchQuery, options, searchSources, 1);

                setPapers(fastPapers);
                setHasMore(fastHasMore);
                setIsLoading(false); // Stop main spinner, results are on screen!

                // Trigger basic validation for immediate feedback
                triggerBackgroundValidation(fastPapers);

                // Phase 2: Background AI Analysis and Refinement
                // This promise chain runs after initial results are displayed.
                apiService.runBackgroundAIAnalysis(rawQueryUsed, options, fastPapers, model, summaryLength, summaryStyle, searchSources, setAiParsedFilters, setAiHypotheticalAnswer)
                    .then((result) => { // Capture the returned object
                        // Merge and update papers based on AI refinement and grounded search
                        setPapers(prevPapers => {
                            const combinedPapers = apiService.mergePapers([...prevPapers, ...result.refinedPapers, ...result.newGroundedPapers]);
                            const scoredMap = new Map(combinedPapers.map(p => [p.id, p]));

                            // Re-map existing papers to update their scores and add new papers
                            const updatedAndNewPapers = prevPapers.map(p => scoredMap.get(p.id) || p);
                            const newlyAddedPapers = combinedPapers.filter(p => !prevPapers.some(ep => ep.id === p.id));

                            return [...updatedAndNewPapers, ...newlyAddedPapers];
                        });

                        setSummary(result.newSummary);
                        setAnalysis(result.newAnalysis);

                        // Set the final AI-parsed filters and hypothetical answer for subsequent actions/caching
                        setAiParsedFilters(result.finalParsedFilters);
                        setAiHypotheticalAnswer(result.finalHypotheticalAnswer);

                        // Trigger validation for newly added grounded papers or any new papers from refinement
                        triggerBackgroundValidation(result.newGroundedPapers);

                        analyticsService.logEvent('search_refined_ai', {
                            query: searchQuery,
                            numFastPapers: fastPapers.length,
                            numRefinedPapers: result.refinedPapers.length,
                            numGroundedPapers: result.newGroundedPapers.length,
                            model: model.id,
                        });
                    })
                    .catch(error => { // Use 'error' here
                        console.warn("Background AI analysis failed:", error);
                        // Display a non-blocking message about AI failure if necessary
                        setError(prev => prev ? prev : "AI refinement encountered an issue. Displaying basic results.");
                    })
                    .finally(() => {
                        setIsRefiningAI(false); // All AI refinement tasks are done
                        setIsSearchingGrounded(false); // Grounded search is part of AI refinement
                        setIsSummaryLoading(false); // Summary generation is part of AI refinement
                    });

                // Indicate that deep AI search is starting as part of the background refinement
                setIsSearchingGrounded(true);

            } catch (err) {
                setError(err instanceof Error ? err.message : "An unknown error occurred.");
                setIsLoading(false);
                setIsRefiningAI(false);
                setIsSummaryLoading(false);
            }
        }
    };

    const handleSuggestionSearch = (suggestion: string) => {
        setQuery(suggestion);
        handleSearch(suggestion, lastUsedOptions);
    };

    const handleLoadMore = async () => {
        if (!query.trim() || isLoadingMore || !hasMore) return;

        setIsLoadingMore(true);
        setError(null);

        const pageToFetch = currentPage + 1;

        try {
            // Pagination uses the fast API search
            const { papers: newPapers, hasMore: newHasMore, rawQueryUsed } = await apiService.searchFast(query, lastUsedOptions, searchSources, pageToFetch);

            // Append basic papers immediately
            setPapers(prev => [...prev, ...newPapers]);
            setCurrentPage(pageToFetch);
            setHasMore(newHasMore);

            // Trigger background AI refinement for the new set of papers
            // This is a simpler version, only applying semantic scoring and validation to new papers.
            // Full re-analysis/summary would be too heavy for pagination.
            if (aiHypotheticalAnswer) {
                apiService.calculatePaperScores(newPapers, rawQueryUsed, aiHypotheticalAnswer, model, lastUsedOptions).then(scoredNewPapers => {
                    setPapers(current => {
                        const scoredMap = new Map(scoredNewPapers.map(p => [p.id, p]));
                        return current.map(p => scoredMap.get(p.id) || p);
                    });
                    triggerBackgroundValidation(scoredNewPapers);
                }).catch(e => console.warn("Semantic scoring for loaded more papers failed", e));
            } else {
                 triggerBackgroundValidation(newPapers); // Just basic validation if no hypothesis is ready
            }

        } catch (err) {
            setError(err instanceof Error ? err.message : "An unknown error occurred.");
        } finally {
            setIsLoadingMore(false);
        }
    };

    const updatePaperState = (paperId: string, updates: Partial<ResearchPaper>) => {
        const updater = (p: ResearchPaper) => p.id === paperId ? { ...p, ...updates } : p;
        setPapers(prev => prev.map(updater));
        setWorkspacePapers(prev => prev.map(updater));
        if (selectedPaper?.id === paperId) {
            setSelectedPaper(prev => prev ? { ...prev, ...updates } : null);
        }
    };

    // Asynchronously classify study designs for new papers without blocking the UI
    useEffect(() => {
        const papersToClassify = papers.filter(p => p.detectedStudyDesign === undefined);

        if (papersToClassify.length > 0) {
            // Mark papers as "classification in progress" to avoid re-triggering on re-renders.
            papersToClassify.forEach(p => updatePaperState(p.id, { detectedStudyDesign: '...' as any }));

            papersToClassify.forEach(paper => {
                apiService.classifyStudyDesign(paper, model)
                    .then(design => {
                        updatePaperState(paper.id, { detectedStudyDesign: design });
                    })
                    .catch(error => {
                        console.error(`Failed to classify study design for paper ${paper.id}`, error);
                        updatePaperState(paper.id, { detectedStudyDesign: 'N/A' });
                    });
            });
        }
    }, [papers, model]);

    const handleSelectPaper = async (paper: ResearchPaper) => {
        setSelectedPaper(paper);

        // Fetch open access PDF if DOI is available and not yet fetched
        if (paper.doi && !paper.openAccessState) {
            updatePaperState(paper.id, { openAccessState: 'loading' });
            try {
                const url = await apiService.findOpenAccessPdf(paper.doi);
                updatePaperState(paper.id, { openAccessPdfUrl: url || undefined, openAccessState: 'loaded' });
            } catch (error) {
                console.error("Failed to find open access PDF:", error);
                updatePaperState(paper.id, { openAccessState: 'error' });
            }
        }

        // Fetch Key Concepts if not already fetched
        if (!paper.keyConceptsState || paper.keyConceptsState === 'idle') {
            updatePaperState(paper.id, { keyConceptsState: 'loading' });
            try {
                // Pass title and abstract for better extraction
                const concepts = await apiService.extractKeyConcepts(paper.title, paper.abstract, model);
                updatePaperState(paper.id, { keyConcepts: concepts, keyConceptsState: 'loaded' });
            } catch (error) {
                console.error("Failed to extract key concepts:", error);
                updatePaperState(paper.id, { keyConceptsState: 'error' });
            }
        }

        // Fetch Knowledge Graph if not already fetched
        if (!paper.knowledgeGraphState || paper.knowledgeGraphState === 'idle') {
            if (paper.abstract.length < 150) {
                 updatePaperState(paper.id, { knowledgeGraph: { entities: [], relationships: [] }, knowledgeGraphState: 'loaded' });
            } else {
                updatePaperState(paper.id, { knowledgeGraphState: 'loading' });
                try {
                    const graph = await apiService.extractKnowledgeGraph(paper.abstract, model);
                    updatePaperState(paper.id, { knowledgeGraph: graph, knowledgeGraphState: 'loaded' });
                } catch (error) {
                    console.error("Failed to extract knowledge graph:", error);
                    updatePaperState(paper.id, { knowledgeGraphState: 'error' });
                }
            }
        }
    };

    const handleToggleWorkspacePaper = (paper: ResearchPaper) => {
        setWorkspacePapers(prev => {
            const exists = prev.some(p => p.id === paper.id);
            if (exists) {
                // If removing, also remove from any project it's in
                setProjects(projs => projs.map(p => ({...p, paperIds: p.paperIds.filter(id => id !== paper.id) })));
                return prev.filter(p => p.id !== paper.id);
            } else {
                return [...prev, paper];
            }
        });
    };

    const handleOpenVerificationModal = (paper: ResearchPaper) => {
        analyticsService.logEvent('tool_used', { tool: 'verify_paper_modal_opened', paperId: paper.id });
        setPaperToVerify(paper);
        setIsVerificationModalOpen(true);
    };

    const handleVerificationComplete = (doi: string, result: VerificationResult) => {
        setPapers(prev => prev.map(p => p.doi === doi ? { ...p, verificationResult: result } : p));
        setWorkspacePapers(prev => prev.map(p => p.doi === doi ? { ...p, verificationResult: result } : p));
        if (selectedPaper?.doi === doi) {
            setSelectedPaper(prev => prev ? { ...prev, verificationResult: result } : null);
        }
    };

    const handleAnalyzeGaps = async (papersToAnalyze: ResearchPaper[], modelToUse: ModelDefinition, isWorkspaceContext: boolean = false) => {
        analyticsService.logEvent('tool_used', { tool: 'analyze_gaps', paperCount: papersToAnalyze.length, context: isWorkspaceContext ? 'workspace' : 'search_results' });
        if (isWorkspaceContext) {
            setShowWorkspaceAnalysisDrawer(true); // Open the drawer
            setIsWorkspaceGapAnalysisLoading(true);
            setWorkspaceGapAnalysisReport(null);
        } else {
            setIsGapAnalysisModalOpen(true);
            setIsAnalyzingGaps(true);
            setGapAnalysisError(null);
            setGapAnalysisResult(null);
        }

        try {
            const result = await apiService.analyzeGaps(papersToAnalyze, modelToUse);
            if (isWorkspaceContext) {
                setWorkspaceGapAnalysisReport(result);
            } else {
                setGapAnalysisResult(result);
            }
        } catch (err) {
            const message = err instanceof Error ? err.message : "An unknown error occurred.";
            if (isWorkspaceContext) {
                setWorkspaceGapAnalysisReport(message); // Display error in dashboard
            } else {
                setGapAnalysisError(message);
            }
        } finally {
            if (isWorkspaceContext) {
                setIsWorkspaceGapAnalysisLoading(false);
            } else {
                setIsAnalyzingGaps(false);
            }
        }
    };

    const handleAnalyzePaper = async (paper: ResearchPaper) => {
        analyticsService.logEvent('tool_used', { tool: 'analyze_single_paper', paperId: paper.id });
        setIsAnalysisModalOpen(true);
        setIsAnalyzingPaper(true);
        setAnalysisError(null);
        // Set paper immediately for the modal header, but analysis will be fetched.
        setAnalysisResult({ paper, analysis: paper.savedAnalysis || {} as PaperAnalysis });

        try {
            const analysis = await apiService.analyzeSinglePaper(paper, model);
            setAnalysisResult({ paper, analysis });
        } catch (err) {
            const message = err instanceof Error ? err.message : "An unknown error occurred.";
            setAnalysisError(message);
        } finally {
            setIsAnalyzingPaper(false);
        }
    };

    const handleSaveAnalysis = (paper: ResearchPaper, analysis: PaperAnalysis) => {
        const updatePaper = (p: ResearchPaper) => p.id === paper.id ? { ...p, savedAnalysis: analysis } : p;
