const DoiDisplay: React.FC<{ paper: ResearchPaper; onFindDoi: () => void }> = ({ paper, onFindDoi }) => {
    const { doi, doiState } = paper;

    if (doiState === 'loading') {
        return (
            <div className="flex items-center gap-1.5 px-2 py-0.5 rounded-full bg-muted/50 text-xs text-muted-foreground animate-pulse">
                <svg className="animate-spin h-3 w-3 text-primary" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                <span>Fetching DOI...</span>
            </div>
        );
    }

    if (doiState === 'error') {
        return (
            <div className="flex items-center gap-1.5 text-xs text-destructive bg-destructive/10 px-2 py-0.5 rounded-full" title="Could not find DOI">
                <WarningIcon className="w-3.5 h-3.5" />
                <span>DOI not found</span>
            </div>
        );
    }

    if (doi) {
        return (
            <a 
                href={`https://doi.org/${doi}`} 
                target="_blank" 
                rel="noopener noreferrer" 
                className="flex items-center gap-1.5 px-2 py-0.5 rounded-full bg-blue-50 text-xs font-medium text-blue-700 hover:bg-blue-100 hover:underline transition-colors"
                title={`DOI: ${doi}`}
            >
                <DoiIcon className="w-3.5 h-3.5" />
                <span className="truncate max-w-[150px]">{doi}</span>
            </a>
        );
    }

    if (paper.validation?.status === 'validated' && !doi) {
        return (
            <span className="flex items-center gap-1.5 px-2 py-0.5 rounded-full bg-muted text-xs text-muted-foreground italic">
                <DoiIcon className="w-3.5 h-3.5 opacity-50" /> 
                Not found
            </span>
        );
    }

    return (
        <button 
            onClick={() => onFindDoi(paper)} 
            className="flex items-center gap-1.5 px-2 py-0.5 rounded-full bg-muted hover:bg-muted/80 text-xs font-medium text-primary transition-colors"
        >
            <SearchIcon className="w-3.5 h-3.5" />
            <span>Find DOI</span>
        </button>
    );
};

