export const PaperDetails: React.FC<PaperDetailsProps> = (props) => {
    const { paper, isInWorkspace, onToggleWorkspacePaper, onConceptClick, onFindDoi, logAnalyticsEvent, model, onOpenAnalysis, onCitePaper, onAuthorClick, onFindSimilar, isFindingSimilar } = props;
    const [activeTab, setActiveTab] = useState<'overview' | 'metadata'>('overview');

    const [enrichedAbstract, setEnrichedAbstract] = useState<string | null>(null);
    const [isAbstractLoading, setIsAbstractLoading] = useState(false);

    // Citation style selection
    const [selectedStyle, setSelectedStyle] = useState<CitationStyle>('apa');
    const [quickCitation, setQuickCitation] = useState<string | null>(null);
    const [isCiting, setIsCiting] = useState(false);
    const [copied, setCopied] = useState(false);

    // Reset local state when selected paper changes
    useEffect(() => {
        setEnrichedAbstract(null);
        setIsAbstractLoading(false);
        setActiveTab('overview');
        setQuickCitation(null);
        setIsCiting(false);

        // Automatically attempt to find DOI if it's missing.
        if (!paper.doi && (!paper.doiState || paper.doiState === 'idle')) {
            onFindDoi(paper);
        }
    }, [paper.id, paper.doi, paper.doiState, onFindDoi]);

    // Lazy load abstract content when in overview tab
    useEffect(() => {
        if (activeTab === 'overview' && !enrichedAbstract && !isAbstractLoading) {
             const currentText = paper.abstract;
             const isPlaceholder = !currentText || currentText.length < 50 || currentText === 'No abstract available for this paper.';

             // Only fetch if it's a placeholder and we have a DOI to fetch from
             if (isPlaceholder && paper.doi) {
                 setIsAbstractLoading(true);

                 apiService.fetchMetadataByDOI(paper.doi)
                    .then(fetched => {
                        if (fetched && fetched.abstract && fetched.abstract.length > 50) {
                            setEnrichedAbstract(fetched.abstract);
                        }
                    })
                    .catch(e => {
                        console.warn("Could not fetch enriched abstract:", e);
                    })
                    .finally(() => {
                        setIsAbstractLoading(false);
                    });
             }
        }
    }, [activeTab, paper.id, paper.doi, paper.abstract, enrichedAbstract, isAbstractLoading]);


    const googleScholarSearchUrl = `https://scholar.google.com/scholar?hl=en&as_sdt=0,34&q=${encodeURIComponent(`"${paper.title}"`)}`;

    const handleShare = async () => {
        if (!navigator.share) return;
        try {
            await navigator.share({
                title: paper.title,
                text: `Check out this research paper: "${paper.title}"`,
                url: paper.sourceURL || window.location.href,
            });
            logAnalyticsEvent('paper_shared', { title: paper.title });
        } catch (error) {
            console.error('Error sharing paper:', error);
        }
    };

    const handleQuickCite = async () => {
        setIsCiting(true);
        try {
            const results = await citationService.generateCitations([paper], selectedStyle, model);
            setQuickCitation(results[0] || null);
        } catch (error) {
            console.error("Failed to generate quick citation", error);
        } finally {
            setIsCiting(false);
        }
    };

    const handleCopyCitation = () => {
        if (quickCitation) {
            const plainText = quickCitation.replace(/<[^>]*>?/gm, '');
            navigator.clipboard.writeText(plainText);
            setCopied(true);
            setTimeout(() => setCopied(false), 2000);
        }
    };

    const renderKeyConcepts = () => {
        if (!paper.keyConceptsState || paper.keyConceptsState === 'idle') {
            if (paper.abstract.length < 150) return null; // Only show spinner if abstract is substantial enough for extraction
            return (
                <div className="py-2">
                    <LoadingSpinner message="Extracting concepts..." />
                </div>
            );
        }

        if (paper.keyConceptsState === 'loading') {
            return (
                <div className="py-2">
                    <LoadingSpinner message="Extracting concepts..." />
                </div>
            );
        }

        if (paper.keyConceptsState === 'error') {
            return <p className="text-sm text-destructive">Could not extract concepts.</p>;
        }

        if (paper.keyConceptsState === 'loaded' && paper.keyConcepts && paper.keyConcepts.length > 0) {
            return (
                <div className="flex flex-wrap gap-2">
                    {paper.keyConcepts.map((concept) => (
                        <button
                            key={concept}
                            onClick={() => onConceptClick(concept)}
                            className="group flex items-center gap-1.5 px-2.5 py-1 bg-secondary text-secondary-foreground text-xs font-medium rounded-full hover:bg-primary/10 hover:text-primary transition-colors"
                            title={`Search for "${concept}"`}
                        >
                            <span>{concept}</span>
                            <SearchIcon className="w-3 h-3 opacity-0 group-hover:opacity-100 transition-opacity" />
                        </button>
                    ))}
                </div>
            );
        }

        return <p className="text-sm text-muted-foreground italic">No distinct concepts identified.</p>;
    }

    return (
        <div className="flex flex-col h-full space-y-4">
             <div>
                <div className="flex justify-between items-start gap-4">
                    <div className="flex-grow pr-2">
                        <h3 className="text-lg font-bold text-foreground leading-tight">{paper.title}</h3>
                        <div className="flex flex-wrap items-center gap-x-3 gap-y-1 mt-1">
                            <span className="text-sm text-muted-foreground">{paper.authors.split(',')[0]} et al. ({paper.year})</span>
                            <DoiDisplay paper={paper} onFindDoi={() => onFindDoi(paper)} />
                        </div>
                    </div>
                    <div className="flex-shrink-0 flex flex-col gap-2">
                        <button 
                            onClick={() => onToggleWorkspacePaper(paper)} 
                            className={`flex items-center justify-center gap-2 h-9 px-4 rounded-md text-sm font-semibold transition-colors w-full ${
                                isInWorkspace 
                                ? 'bg-green-100 text-green-800 hover:bg-green-200' 
                                : 'bg-secondary text-secondary-foreground hover:bg-accent'
                            }`}
                        >
                            {isInWorkspace ? <CheckIcon className="w-4 h-4" /> : <AddIcon className="w-4 h-4" />}
                            <span>{isInWorkspace ? 'Saved' : 'Save'}</span>
                        </button>

                        <div className="flex flex-col gap-1">
                            <select 
                                value={selectedStyle}
                                onChange={(e) => setSelectedStyle(e.target.value as CitationStyle)}
                                className="h-7 text-[10px] font-bold uppercase tracking-wider bg-muted border rounded-md px-1 focus:ring-1 focus:ring-primary outline-none transition-all"
                            >
                                <option value="apa">APA 7</option>
                                <option value="mla">MLA 9</option>
                                <option value="chicago">Chicago</option>
                                <option value="harvard">Harvard</option>
                                <option value="ieee">IEEE</option>
                                <option value="vancouver">Vancouver</option>
                                <option value="bibtex">BibTeX</option>
                            </select>
                            <button 
                                onClick={() => onCitePaper(paper, selectedStyle)}
                                className="flex items-center justify-center gap-2 h-8 px-3 rounded-md text-xs font-bold bg-secondary text-secondary-foreground hover:bg-accent transition-colors border border-transparent hover:border-border w-full"
                                title="Open Citation Tool"
                            >
                                <CitationIcon className="w-3.5 h-3.5" />
                                <span>Cite</span>
                            </button>
                        </div>

                        <button 
                            onClick={() => onFindSimilar(paper)}
                            disabled={isFindingSimilar}
                            className="flex items-center justify-center gap-2 h-9 px-3 rounded-md text-sm font-semibold bg-secondary text-secondary-foreground hover:bg-accent transition-colors border border-transparent hover:border-border w-full disabled:opacity-50"
                            title="Pivot Search: Find Semantically Similar Papers"
                        >
                            {isFindingSimilar ? (
                                <svg className="animate-spin h-3.5 w-3.5" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                            ) : (
                                <SearchIcon className="w-4 h-4" />
                            )}
                            <span>Similar</span>
                        </button>
                    </div>
                </div>
            </div>

            <div className="border-b border-border overflow-x-auto">
                <nav className="-mb-px flex space-x-6" aria-label="Tabs">
                    <TabButton isActive={activeTab === 'overview'} onClick={() => setActiveTab('overview')}>Overview</TabButton>
                    <TabButton isActive={activeTab === 'metadata'} onClick={() => setActiveTab('metadata')}>Metadata</TabButton>
                </nav>
            </div>

            <div className="pt-2 flex-grow">
                {activeTab === 'overview' && (
                    <div className="space-y-4 animate-fade-in">
                        <div>
                            <h4 className="font-semibold text-foreground">Abstract</h4>
                            {isAbstractLoading ? (
                                <div className="py-4">
                                    <LoadingSpinner message="Loading abstract..." />
                                </div>
                            ) : (
                                <p className="mt-1 text-sm text-muted-foreground leading-relaxed">
                                    {enrichedAbstract || paper.abstract}
                                </p>
                            )}
                        </div>
                         <div>
                            <h4 className="font-semibold text-foreground mb-2 flex items-center gap-2">
                                <TagIcon className="w-4 h-4 text-muted-foreground" />
                                Key Concepts
                            </h4>
                            {renderKeyConcepts()}
                        </div>

                        {paper.savedAnalysis && <SavedAnalysisSummary analysis={paper.savedAnalysis} />}

                        <div className="pt-4 mt-2 border-t border-border">
                            <button 
                                onClick={() => onOpenAnalysis(paper)}
                                className="w-full flex items-center justify-center gap-2 p-3 bg-primary text-primary-foreground font-semibold rounded-lg hover:bg-primary/90 transition-all shadow-sm hover:shadow-md hover:-translate-y-0.5"
                            >
                                <AnalyzeIcon className="w-5 h-5" />
                                <span>Open Analysis Dashboard</span>
                            </button>
                            <p className="text-xs text-center text-muted-foreground mt-2">
                                Access Chats, Knowledge Graphs, Connections, and Verification Tools.
                            </p>
                        </div>
                    </div>
                )}

                {activeTab === 'metadata' && (
                     <div className="space-y-6 animate-fade-in">
                        {paper.validation && <ValidationScoreDisplay validation={paper.validation} />}

                        <div className="space-y-3">
                             <div className="flex justify-between items-start">
                                <div>
                                    <h4 className="font-semibold text-foreground text-sm">Authors</h4>
                                    <AuthorList authors={paper.authors} authorList={paper.authorList} onAuthorClick={onAuthorClick} />
                                </div>
                                <div className="text-right">
                                    <h4 className="font-semibold text-foreground text-sm">Year</h4>
                                    <p className="text-sm text-muted-foreground">{paper.year}</p>
                                </div>
                            </div>
                             <div>
                                <h4 className="font-semibold text-foreground text-sm">Journal</h4>
                                <p className="text-sm text-muted-foreground">{paper.journal || 'N/A'}</p>
                            </div>
                            {paper.citations !== undefined && (
                                <div>
                                    <h4 className="font-semibold text-foreground text-sm">Citations</h4>
                                    <p className="text-sm text-muted-foreground">{paper.citations.toLocaleString()}</p>
                                </div>
                            )}

                            <div className="pt-4 border-t border-border">
                                <div className="flex items-center justify-between mb-2">
                                    <h4 className="font-semibold text-foreground text-sm">AI Citation Generator</h4>
                                    <button 
                                        onClick={handleQuickCite}
                                        disabled={isCiting}
                                        className="text-[10px] font-bold uppercase text-primary hover:underline disabled:opacity-50"
                                    >
                                        {isCiting ? 'Generating...' : `Generate ${selectedStyle.toUpperCase()}`}
                                    </button>
                                </div>
                                {quickCitation ? (
                                    <div className="p-3 bg-muted/50 rounded-lg border border-border group relative">
                                        <div 
                                            className="text-xs text-foreground prose-xs leading-relaxed pr-8" 
                                            dangerouslySetInnerHTML={{ __html: quickCitation }}
                                        />
                                        <button 
                                            onClick={handleCopyCitation}
                                            className="absolute right-2 top-2 p-1.5 text-muted-foreground hover:text-primary transition-colors"
                                            title="Copy to clipboard"
                                        >
                                            {copied ? <CheckIcon className="w-3.5 h-3.5 text-green-600" /> : <CopyIcon className="w-3.5 h-3.5" />}
                                        </button>
                                    </div>
                                ) : (
                                    <p className="text-[11px] text-muted-foreground italic">Select a style and click generate to see the formatted citation.</p>
                                )}
                            </div>
                        </div>

                        <div className="pt-3 border-t border-border flex flex-wrap items-center justify-between gap-x-4 gap-y-2">
                            <div className="flex items-center gap-4">
                                <a href={googleScholarSearchUrl} target="_blank" rel="noopener noreferrer" className="flex items-center gap-1.5 text-sm font-medium text-primary hover:underline">
                                    <ScholarIcon className="w-4 h-4" /> Google Scholar
                                </a>
                                {(paper.pdfURL || paper.openAccessPdfUrl) && (
                                    <a href={paper.pdfURL || paper.openAccessPdfUrl} target="_blank" rel="noopener noreferrer" className="flex items-center gap-1.5 text-sm font-medium text-primary hover:underline">
                                        <PdfIcon className="w-4 h-4" /> PDF
                                    </a>
                                )}
                            </div>
                            <button
                                onClick={handleShare}
                                className="flex items-center gap-1.5 text-sm font-medium text-muted-foreground hover:text-foreground hover:underline"
                            >
                                <ShareIcon className="w-4 h-4" /> Share
                            </button>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import type { ResearchPaper, AnalysisResult, Project, SearchSourceInfo, ModelDefinition, ChatMessage, AuthorProfile, SynthesisResult, CitationStyle } from '../types';
import { PaperDetails } from './PaperDetails';
import { SearchResultsAnalysis } from './SearchResultsAnalysis';
import { LightbulbIcon } from './icons/LightbulbIcon';
import { SearchIcon } from './icons/SearchIcon';
import { BibliographyGenerator } from './BibliographyGenerator';
import { ProjectWorkspace } from './ProjectWorkspace';
import { WorkspaceAnalysisDashboard } from './WorkspaceAnalysisDashboard';
import { PaperAnalysisDashboard } from './PaperAnalysisDashboard';


interface RefinedQueriesProps {
  queries: string[];
  isLoading: boolean;
  onQueryClick: (query: string) => void;
}

const RefinedQueries: React.FC<RefinedQueriesProps> = ({ queries, isLoading, onQueryClick }) => {
  if (isLoading || queries.length === 0) {
    return null;
  }

