                    <PaperDetails
                        paper={selectedPaper}
                        isInWorkspace={workspacePapers.some(p => p.id === selectedPaper.id)}
                        onToggleWorkspacePaper={props.onToggleWorkspacePaper}
                        onConceptClick={props.onConceptClick}
