/**
 * FIX: Implementation of rerankForScreening based on inclusion/exclusion criteria.
 */
export const rerankForScreening = async (included: ResearchPaper[], excluded: ResearchPaper[], unscreened: ResearchPaper[], model: ModelDefinition): Promise<{ paperId: string, score: number, rationale: string }[]> => {
    const includedCtx = papersToToonCollection(included);
    const excludedCtx = papersToToonCollection(excluded);
    const unscreenedCtx = papersToToonCollection(unscreened.slice(0, 10)); // Limit to prevent context overflow

    const prompt = `Act as a screening assistant. Based on previously included and excluded papers, score the unscreened papers for relevance (0-100).
    Included: ${includedCtx}
    Excluded: ${excludedCtx}
    Unscreened: ${unscreenedCtx}
    Return JSON array "reranked" of {paperId, score, rationale}.`;

    try {
        const response = await ai.models.generateContent({
            model: "gemini-3-pro-preview",
            contents: prompt,
            config: { responseMimeType: "application/json" }
        });
        const result = safeJsonParse(response.text ?? '');
        return result?.reranked || [];
    } catch { return []; }
};

