/**
 * Prepares a search strategy using HyDE (Hypothetical Document Embeddings).
 * Generates a hypothetical "Gold Standard" abstract that would perfectly answer the query.
 */
export const getUnifiedSearchStrategy = async (userQuery: string, model: ModelDefinition): Promise<{ filters: any, hypothesis: string }> => {
    const prompt = `Task: Prepare a deep research retrieval strategy for: "${userQuery}".

    1. Parse the query into structured filters (years, authors, core keywords).
    2. HyDE (Hypothetical Document Embeddings): Generate a highly detailed, 250-word "Gold Standard" hypothetical abstract that perfectly answers the research question. This abstract must sound like a real, high-impact peer-reviewed paper including specific methodology, results, and implications.

    Return JSON with "parsedFilters" and "hypotheticalAbstract".`;

    try {
        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview", 
            contents: prompt,
            config: { responseMimeType: "application/json" }
        });
        const result = safeJsonParse(response.text ?? '');
        return { 
            filters: result?.parsedFilters || { core_search_query: userQuery }, 
            hypothesis: result?.hypotheticalAbstract || userQuery 
        };
    } catch (e) { 
        return { filters: { core_search_query: userQuery }, hypothesis: userQuery }; 
    }
};

