                            </button>

                            {isConnectionsExpanded && (
                                <div className="p-4 border-t border-border space-y-4 bg-background/50">
                                    {isLoadingConnections ? (
                                        <div className="py-4 text-center">
                                            <LoadingSpinner message="Mapping relationships via Semantic Scholar..." />
                                        </div>
                                    ) : connectedPapers && connectedPapers.length > 0 ? (
                                        <div className="space-y-3">
                                            {connectedPapers.map((cp, idx) => (
                                                <div key={idx} className="p-3 bg-card border rounded-lg hover:border-blue-300 transition-colors shadow-sm group">
                                                    <div className="flex justify-between items-start gap-2">
                                                        <h5 className="text-sm font-bold text-foreground leading-tight group-hover:text-blue-700 transition-colors">{cp.title}</h5>
                                                        {cp.sourceURL && (
