                                                            </a>
                                                        )}
                                                    </div>
                                                    <div className="flex items-center gap-2 mt-1 flex-wrap">
                                                        <span className="text-[10px] font-bold uppercase px-1.5 py-0.5 bg-blue-50 text-blue-700 rounded border border-blue-100">
                                                            {cp.connection === 'This paper cites' ? 'Cited' : cp.connection === 'Cited by this paper' ? 'Citing' : 'Related'}
                                                        </span>
                                                        <span className="text-xs text-muted-foreground">{cp.authors} ({cp.year})</span>
                                                    </div>
                                                    {cp.summary && cp.summary !== 'Abstract not available.' && (
                                                        <p className="text-xs text-muted-foreground mt-2 line-clamp-2 italic">"{cp.summary}"</p>
                                                    )}
                                                </div>
                                            ))}
                                            <div className="pt-2 text-center">
                                                <button 
                                                    onClick={() => onOpenAnalysis(paper)}
                                                    className="text-xs font-bold text-primary hover:underline flex items-center justify-center gap-1 mx-auto"
                                                >
                                                    <AnalyzeIcon className="w-3 h-3" />
                                                    Explore Full Graph in Dashboard
                                                </button>
                                            </div>
                                        </div>
                                    ) : (
                                        <div className="text-center py-6 text-muted-foreground">
                                            <p className="text-sm italic">No connections found for this paper.</p>
                                        </div>
                                    )}
                                </div>
                            )}
                        </div>

                        {paper.savedAnalysis && <SavedAnalysisSummary analysis={paper.savedAnalysis} />}

                        <div className="pt-4 mt-2 border-t border-border">
                            <button 
