export const fetchMetadataByDOI = async (doi: string) => {
    // Check Semantic Scholar for influence data when fetching metadata
    const [openAlexMeta, s2Graph] = await Promise.all([
        openalexService.searchOpenAlexByDoi(doi),
        semanticScholarService.getPaperGraphData(doi)
    ]);

    if (openAlexMeta && s2Graph) {
        return {
            ...openAlexMeta,
            citations: s2Graph.influence.citations ?? openAlexMeta.citations,
            influentialCitationCount: s2Graph.influence.influentialCitationCount,
            highlights: [...(openAlexMeta.highlights || []), ...(s2Graph.influence.highlights || [])]
        };
    }
    return openAlexMeta;
};

export const mergePapers = (papers: ResearchPaper[]): ResearchPaper[] => {
    const unique = new Map<string, ResearchPaper>();
    papers.forEach(p => unique.set(p.id, { ...(unique.get(p.id) || {}), ...p }));
    return Array.from(unique.values());
};

