import type { McpStatus, LocalLibraryMetadata, ResearchPaper } from '../types';

const DEFAULT_MCP_URL = 'http://localhost:3000';

class McpClientService {
    private currentStatus: McpStatus = {
        isConnected: false,
        serverUrl: DEFAULT_MCP_URL,
        capabilities: []
    };

    public async connect(url: string = DEFAULT_MCP_URL): Promise<McpStatus> {
        console.log(`[MCP] Attempting connection to ${url}...`);
        try {
            const controller = new AbortController();
            const id = setTimeout(() => controller.abort(), 2000);

            // Standard MCP info ping (mocking for the UI demonstration)
            const response = await fetch(`${url}/info`, { signal: controller.signal });
            clearTimeout(id);

            if (response.ok) {
                const info = await response.json();
                this.currentStatus = {
                    isConnected: true,
                    serverUrl: url,
                    version: info.version,
                    capabilities: info.tools || ['zotero_search', 'pdf_reader']
                };
            }
        } catch (e) {
            this.currentStatus = { ...this.currentStatus, isConnected: false, serverUrl: url };
        }
        return this.currentStatus;
    }

    public getStatus(): McpStatus {
        return this.currentStatus;
    }

    /**
     * Queries the local MCP server for Zotero library metadata.
     */
    public async getLocalLibraryStats(): Promise<LocalLibraryMetadata | null> {
        if (!this.currentStatus.isConnected) return null;

        try {
            const response = await fetch(`${this.currentStatus.serverUrl}/call/get_library_stats`);
            if (response.ok) return await response.json();
        } catch (e) {
            console.error("[MCP] Failed to fetch library stats", e);
        }
        return null;
    }

    /**
     * Checks if a paper exists in the local researcher's Zotero database via MCP.
     */
    public async checkLocalLibrary(paper: ResearchPaper): Promise<boolean> {
        if (!this.currentStatus.isConnected) return false;

        try {
            const response = await fetch(`${this.currentStatus.serverUrl}/call/search_zotero`, {
                method: 'POST',
                body: JSON.stringify({ query: paper.title })
            });
            if (response.ok) {
                const results = await response.json();
                return results.length > 0;
            }
        } catch (e) {}
        return false;
    }
}

