/**
 * OPTIMIZED: Parallel Multi-Source Search.
 * Fetches from OpenAlex, arXiv, and Semantic Scholar concurrently for maximum speed and coverage.
 */
export const searchFast = async (query: string, options: AdvancedSearchOptions, sources: SearchSourceInfo[], page: number): Promise<{ papers: ResearchPaper[], hasMore: boolean, rawQueryUsed: string }> => {
    const results = await Promise.allSettled([
        openalexService.searchOpenAlex(query, options, page),
        arxivService.searchArxiv(query, page),
        semanticScholarService.searchSemanticScholar(query, options, page)
    ]);

    let allPapers: ResearchPaper[] = [];
    let hasMore = false;

    results.forEach(result => {
        if (result.status === 'fulfilled') {
            allPapers = [...allPapers, ...result.value.papers];
            if (result.value.hasMore) hasMore = true;
        }
    });

    const merged = mergePapers(allPapers);

    return { 
        papers: merged, 
        hasMore, 
        rawQueryUsed: query 
    };
};

/**
 * OPTIMIZED: Deep background AI analysis.
 * Now takes an optional hypotheticalAnswer to allow starting AI planning concurrently with data fetching.
 */
export const runBackgroundAIAnalysis = async (
    query: string, 
    options: AdvancedSearchOptions, 
    initialPapers: ResearchPaper[], 
    model: ModelDefinition, 
    length: SummaryLength, 
    style: SummaryStyle, 
    sources: SearchSourceInfo[], 
    setAiParsedFilters: (f: any) => void, 
    setAiHypotheticalAnswer: (a: string) => void,
    prefetchedHypothesis?: { filters: any, hypothesis: string }
) => {
    const cacheKey = `${SESSION_CACHE_KEY_PREFIX}${query}_${length}_${style}_${model.id}`;
    const cached = getCache<any>(cacheKey);
    if (cached) {
        setAiParsedFilters(cached.finalParsedFilters);
        setAiHypotheticalAnswer(cached.finalHypotheticalAnswer);
        return cached;
    }

    // 1. Use prefetched strategy or generate it now
    const strategy = prefetchedHypothesis || await geminiService.getUnifiedSearchStrategy(query, model);
    const { filters: parsedFilters, hypothesis: hypotheticalAnswer } = strategy;

    setAiParsedFilters(parsedFilters);
    setAiHypotheticalAnswer(hypotheticalAnswer);

    // 2. Parallel Grounded Search (Google Search) while we start other tasks
    const groundedResultsPromise = geminiService.findPapersWithGoogleSearch(query, model).catch(() => []);

    // 3. SEMANTIC SEARCH ENHANCEMENT: Calculate relevance scores using HyDE hypothesis on initial papers
    // This part runs while grounded search is still fetching
    const scoredPapersPromise = embeddingService.calculateSemanticScores(hypotheticalAnswer, initialPapers);

    const [groundedResults, scoredInitialPapers] = await Promise.all([
        groundedResultsPromise,
        scoredPapersPromise
    ]);

    const groundedPapers = groundedResults.map(p => ({ ...p, id: createPaperId(p) } as ResearchPaper));

    // 4. Scoring for Grounded results (separate to prioritize initial results)
    const scoredGroundedPapers = await embeddingService.calculateSemanticScores(hypotheticalAnswer, groundedPapers);

    const combined = mergePapers([...scoredInitialPapers, ...scoredGroundedPapers]);

    const finalizedPapers = combined.map(p => {
        const citationBoost = Math.min(15, Math.log10((p.citations || 0) + 1) * 3);
        const semanticScore = p.semanticScore || 0;
        return {
            ...p,
            combinedScore: Math.min(100, Math.round(semanticScore + citationBoost))
        };
    });

    // 5. Generate summary and analysis based on the most relevant (scored) papers
    const [summary, analysis] = await Promise.all([
        geminiService.generateSummaryForPapers(finalizedPapers, length, style, model),
        analysisService.analyzePapers(finalizedPapers)
    ]);

    const result = { 
        refinedPapers: finalizedPapers.filter(p => initialPapers.some(ip => ip.id === p.id)), 
        newGroundedPapers: finalizedPapers.filter(p => groundedPapers.some(gp => gp.id === p.id)), 
        newSummary: summary, 
        newAnalysis: analysis, 
        finalParsedFilters: parsedFilters, 
        finalHypotheticalAnswer: hypotheticalAnswer 
    };

    setCache(cacheKey, result, 10 * 60 * 1000);
    return result;
};

