/**
 * Enhanced Connected Papers discovery: Prefer real citation data from Semantic Scholar.
 */
export const findConnectedPapers = async (paper: ResearchPaper, model: ModelDefinition) => {
    if (paper.doi) {
        const s2Data = await semanticScholarService.getPaperGraphData(paper.doi);
        if (s2Data && s2Data.connections.length > 0) {
            return s2Data.connections;
        }
    }
    // Fallback to AI-based discovery if DOI is missing or S2 fails
    return geminiService.findConnectedPapers(paper, model);
};

