    const handleAnalyzeGaps = async (papersToAnalyze: ResearchPaper[], modelToUse: ModelDefinition, isWorkspaceContext: boolean = false) => {
        analyticsService.logEvent('tool_used', { tool: 'analyze_gaps', paperCount: papersToAnalyze.length, context: isWorkspaceContext ? 'workspace' : 'search_results' });
