export const searchFast = async (query: string, options: AdvancedSearchOptions, sources: SearchSourceInfo[], page: number, settings?: UserSettings): Promise<{ papers: ResearchPaper[], hasMore: boolean, rawQueryUsed: string }> => {
    const aggregateCacheKey = `aggregate_search_${query}_p${page}_${JSON.stringify(options)}_${settings?.oaiEndpoint || ''}`;
