import { GoogleGenAI, Type } from "@google/genai";
import type { ModelDefinition, ResearchPaper, DeepResearchStep, DeepResearchReport, UserSettings } from "../types";
import * as openalexService from "./openalexService";
import * as oaiService from "./oaiService";
import { createPaperId } from "./extensionService";
import { papersToToonCollection } from "../utils/toon";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const safeJsonParse = (jsonString: string) => {
    try {
        const cleanedString = jsonString.replace(/```json/g, '').replace(/```/g, '').trim();
        return JSON.parse(cleanedString);
    } catch (e) {
        console.error("Failed to parse JSON:", e);
        return null;
    }
};

const planSchema = {
    type: Type.OBJECT,
    properties: {
        sub_queries: {
            type: Type.ARRAY,
            items: { type: Type.STRING },
            description: "A list of exactly 3 distinct, targeted search queries."
        }
    },
    required: ["sub_queries"]
};

export const generateResearchPlan = async (topic: string, model: ModelDefinition): Promise<DeepResearchStep[]> => {
    const isTechnical = /implement|architecture|code|system|agent|software|algorithm/i.test(topic);

    const prompt = `Plan a comprehensive literature review on: "${topic}".
    ${isTechnical ? "This is a technical implementation query. Focus queries on system architectures, methodologies, and technical challenges." : ""}
    Generate exactly 3 distinct search queries to cover:
    1. The core theoretical concept.
    2. State-of-the-art methodologies and technical implementations.
    3. Recent (post-2021) evaluations and comparative studies.

    Return JSON with "sub_queries".`;

    try {
        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview", 
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: planSchema,
            }
        });

        const result = safeJsonParse(response.text || '');
        if (!result || !result.sub_queries) return [];

        return result.sub_queries.map((q: string, i: number) => ({
            id: `step_${i}`,
            query: q,
            status: 'pending',
            papersFound: 0
        }));
    } catch (e) {
        console.error("Deep Research Plan Error:", e);
        return [{ id: 'step_0', query: topic, status: 'pending', papersFound: 0 }];
    }
};

export const executeSearchStep = async (step: DeepResearchStep, settings?: UserSettings): Promise<ResearchPaper[]> => {
    try {
        const searchPromises: Promise<ResearchPaper[]>[] = [
            openalexService.searchOpenAlex(step.query, {
                startYear: '', endYear: '', authors: '', excludeKeywords: '', inclusionCriteria: '', exclusionCriteria: '', studyDesign: 'any',
                isOpenAccess: false
            }).then(res => res.papers)
        ];

        // If institutional OAI is enabled, the agent queries the archive too
        if (settings?.isOaiEnabled && settings?.oaiEndpoint) {
            searchPromises.push(oaiService.queryInstitutionalRepository(settings.oaiEndpoint, step.query));
        }

        const results = await Promise.all(searchPromises);
        return results.flat().slice(0, 15); 
    } catch (e) {
        console.error(`Search failed for ${step.query}:`, e);
        return [];
    }
};

const reportSchema = {
    type: Type.OBJECT,
    properties: {
        title: { type: Type.STRING },
        summary: { type: Type.STRING },
        sections: {
            type: Type.ARRAY,
            items: {
                type: Type.OBJECT,
                properties: {
                    heading: { type: Type.STRING },
                    content: { type: Type.STRING, description: "Markdown content for this section." }
                },
                required: ["heading", "content"]
            }
        }
    },
    required: ["title", "summary", "sections"]
};

export const synthesizeReport = async (topic: string, papers: ResearchPaper[], model: ModelDefinition): Promise<DeepResearchReport> => {
    const uniquePapers = Array.from(new Map(papers.map(p => [p.id, p])).values());
    uniquePapers.sort((a, b) => (b.citations || 0) - (a.citations || 0));

    const context = papersToToonCollection(uniquePapers.slice(0, 35));
    const isTechnical = /implement|architecture|code|system|agent|software|algorithm/i.test(topic);

    const prompt = `Act as a Senior Research Lead. Write a comprehensive literature review report on: "${topic}".

    Source Material (TOON Optimized Academic Collection):
    ${context}

    Instructions:
    1. Synthesize findings across all provided sources. 
    2. Explicitly reference any papers flagged as [Institutional Repository (OAI)] to highlight local/archival research if available.
    3. Cite sources using [#ID] notation strictly matching the list provided.
    ${isTechnical ? "4. Include a dedicated section on 'Technical Implementation Strategies' described in the sources." : "4. Focus on methodological trends."}
    5. Structure: Title, Executive Summary, 3-5 Detailed Thematic Sections.

    Return a JSON object matching the report schema.`;

    try {
        const response = await ai.models.generateContent({
            model: "gemini-3-pro-preview",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: reportSchema,
                thinkingConfig: { thinkingBudget: 16000 }
            }
        });

        const result = safeJsonParse(response.text || '');
        if (!result) throw new Error("Failed to parse report.");

        return {
            title: result.title,
            summary: result.summary,
            sections: result.sections,
            references: uniquePapers.slice(0, 25)
        };
    } catch (e) {
        console.error("Report Synthesis Error:", e);
        throw new Error("Failed to generate research report.");
    }
};

import React, { useState, useEffect } from 'react';
import type { ModelDefinition, DeepResearchStep, DeepResearchReport, ResearchPaper, UserSettings } from '../types';
