interface DeepResearchModalProps {
    isOpen: boolean;
    onClose: () => void;
    initialTopic: string;
    model: ModelDefinition;
    onAddPapersToWorkspace: (papers: ResearchPaper[]) => void;
    userSettings: UserSettings;
}

export const DeepResearchModal: React.FC<DeepResearchModalProps> = ({ isOpen, onClose, initialTopic, model, onAddPapersToWorkspace, userSettings }) => {
    const [topic, setTopic] = useState(initialTopic);
    const [status, setStatus] = useState<'idle' | 'planning' | 'researching' | 'synthesizing' | 'completed'>('idle');
    const [steps, setSteps] = useState<DeepResearchStep[]>([]);
    const [report, setReport] = useState<DeepResearchReport | null>(null);
    const [progress, setProgress] = useState(0);
    const [isSaved, setIsSaved] = useState(false);

    useEffect(() => {
        if (isOpen) {
            setTopic(initialTopic);
            setStatus('idle');
            setSteps([]);
            setReport(null);
            setProgress(0);
            setIsSaved(false);
        }
    }, [isOpen, initialTopic]);

    const startDeepResearch = async () => {
        if (!topic.trim()) return;

        setStatus('planning');
        setProgress(5);

        try {
            const plan = await deepResearchService.generateResearchPlan(topic, model);
            setSteps(plan);
            setStatus('researching');
            setProgress(15);

            let completedSteps = 0;
            const totalSteps = plan.length;

            const searchPromises = plan.map(async (step) => {
                setSteps(prev => prev.map(s => s.id === step.id ? { ...s, status: 'searching' } : s));

                try {
                    const foundPapers = await deepResearchService.executeSearchStep(step, userSettings);
                    setSteps(prev => prev.map(s => s.id === step.id ? { ...s, status: 'completed', papersFound: foundPapers.length } : s));
                    completedSteps++;
                    setProgress(prev => Math.max(prev, 15 + (completedSteps / totalSteps) * 60));
                    return foundPapers;
                } catch (e) {
                    console.error(`Error in search step ${step.id}:`, e);
                    setSteps(prev => prev.map(s => s.id === step.id ? { ...s, status: 'error' } : s));
                    completedSteps++;
                    setProgress(prev => Math.max(prev, 15 + (completedSteps / totalSteps) * 60));
                    return [];
                }
            });

            const results = await Promise.all(searchPromises);
            const allFoundPapers = results.flat();

            setStatus('synthesizing');
            setProgress(80);

            const finalReport = await deepResearchService.synthesizeReport(topic, allFoundPapers, model);
            setReport(finalReport);

            setStatus('completed');
            setProgress(100);

        } catch (error) {
            console.error("Deep Research Failed:", error);
            alert("Deep research encountered an error. Please try again.");
            setStatus('idle');
        }
    };

    const handleSaveToWorkspace = () => {
        if (report?.references) {
            onAddPapersToWorkspace(report.references);
            setIsSaved(true);
        }
    };

    const handleExportMarkdown = () => {
        if (!report) return;

        let md = `# ${report.title}\n\n`;
        md += `## Executive Summary\n\n${report.summary}\n\n`;

        report.sections.forEach(s => {
            md += `## ${s.heading}\n\n${s.content}\n\n`;
        });

        md += `## References\n\n`;
        report.references.forEach((p, i) => {
            md += `[${i + 1}] ${p.authors} (${p.year}). **${p.title}**. ${p.journal || ''} [Link](${p.sourceURL})\n\n`;
        });

        const blob = new Blob([md], { type: 'text/markdown' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `${report.title.replace(/\s+/g, '_')}_Report.md`;
        a.click();
        URL.revokeObjectURL(url);
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-background/90 backdrop-blur-sm z-50 flex items-center justify-center p-4">
            <div className="bg-card rounded-2xl shadow-2xl w-[95vw] h-[95vh] flex flex-col border border-border overflow-hidden animate-fade-in transition-all duration-300">
                <header className="p-6 border-b border-border bg-muted/30 flex justify-between items-center">
                    <div className="flex items-center gap-4">
                        <div className="bg-purple-600 text-white p-3 rounded-xl shadow-lg">
                            <RobotIcon className="w-8 h-8" />
                        </div>
                        <div>
                            <h2 className="text-2xl font-black text-foreground tracking-tight">Deep Research Agent</h2>
                            <p className="text-sm text-muted-foreground font-bold uppercase tracking-widest opacity-70">Autonomous Academic Synthesis & Technical Blueprints</p>
                        </div>
                    </div>
                    <button onClick={onClose} className="p-2 text-muted-foreground hover:bg-accent rounded-full transition-colors">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                </header>

                <div className="flex flex-grow overflow-hidden">
                    <aside className="w-96 border-r border-border bg-muted/5 flex flex-col shrink-0">
                        <div className="p-6 border-b border-border">
                            {status === 'idle' ? (
                                <div className="space-y-6">
                                    <div>
                                        <label className="block text-xs font-black uppercase tracking-widest text-muted-foreground mb-3">Define Research Objective</label>
                                        <textarea 
                                            value={topic}
                                            onChange={(e) => setTopic(e.target.value)}
                                            className="w-full p-4 rounded-xl border bg-background text-base min-h-[150px] focus:ring-4 focus:ring-primary/10 transition-all font-medium"
                                            placeholder="e.g., Comparative analysis of Transformer-based vs State-Space models for long-context sequences..."
                                        />
                                    </div>
                                    <button 
