import { User, UserRole } from '../types';

const USER_STORAGE_KEY = 'are_current_user';

class AuthService {
    private currentUser: User | null = null;

    constructor() {
        this.loadUser();
    }

    private loadUser() {
        try {
            const stored = localStorage.getItem(USER_STORAGE_KEY);
            if (stored) {
                this.currentUser = JSON.parse(stored);
            }
        } catch (e) {
            console.error("Failed to load user session", e);
        }
    }

    public loginAsResearcher(name: string): User {
        const user: User = {
            id: `researcher_${Date.now()}`,
            role: 'researcher',
            name: name || 'Researcher',
            sessionId: crypto.randomUUID()
        };
        this.currentUser = user;
        localStorage.setItem(USER_STORAGE_KEY, JSON.stringify(user));
        return user;
    }

    public loginAsParticipant(participantId: string): User {
        const user: User = {
            id: participantId,
            role: 'participant',
            name: `Participant ${participantId}`,
            sessionId: crypto.randomUUID()
        };
        this.currentUser = user;
        localStorage.setItem(USER_STORAGE_KEY, JSON.stringify(user));
        return user;
    }

    public logout() {
        this.currentUser = null;
        localStorage.removeItem(USER_STORAGE_KEY);
    }

    public getUser(): User | null {
        return this.currentUser;
    }

    public isAuthenticated(): boolean {
        return !!this.currentUser;
    }

    public isResearcher(): boolean {
        return this.currentUser?.role === 'researcher';
    }
}

export const authService = new AuthService();

