    const handleAiRerank = async () => { /* ... */ };
    const handleGenerateSuggestions = async (paper: ResearchPaper) => { /* ... */ };
    const handleSuggestionClick = (q: string) => { setQuery(q); handleSearch(q, lastUsedOptions); };
    const handleFindDoi = (paper: ResearchPaper) => { /* ... */ };
    const handleFindConnectedPapers = (paper: ResearchPaper) => { /* ... */ };
    const handleFindJournals = (paper: ResearchPaper) => { /* ... */ };
    const handleAuthorSearch = (author: AuthorProfile) => { /* ... */ };
    const handleFindSimilar = (paper: ResearchPaper) => { /* ... */ };
    const handleAddPapersToWorkspace = (newPapers: ResearchPaper[]) => { /* ... */ };
    const sortedPapers = useMemo(() => papers, [papers]); 
    const handleCreateProject = () => {}; 
    const handleDeleteProject = () => {};
    const handleMovePaperToProject = () => {};
    const handleUpdateProjectColor = () => {};
    const handleSynthesizeWorkspace = async () => {};
    const handleAnalyzeWorkspace = async () => {};
    const handleIndexPaperForRag = () => {};
    const handleProjectChat = () => {};
    const handleWorkspaceChat = () => {};
    const handleAddSource = () => {};
    const handleUpdateGoldStandardPaper = () => {};
