            <ReportModal isOpen={isGapAnalysisModalOpen} onClose={() => setIsGapAnalysisModalOpen(false)} isLoading={isAnalyzingGaps} content={gapAnalysisResult} error={gapAnalysisError} />
            <PaperAnalysisModal isOpen={isAnalysisModalOpen} onClose={() => setIsAnalysisModalOpen(false)} isLoading={isAnalyzingPaper} error={analysisError} result={analysisResult} onSaveAnalysis={handleSaveAnalysis} isAnalysisSaved={!!analysisResult?.paper.savedAnalysis} />
            <SynthesisModal isOpen={isSynthesisModalOpen} onClose={() => setIsSynthesisModalOpen(false)} isLoading={isSynthesizing} result={synthesisResult} error={synthesisError} />
            <CitationModal isOpen={isCitationModalOpen} onClose={() => setIsCitationModalOpen(false)} paper={paperForCitation} model={model} initialStyle={paperForCitationStyle} />
            <DatabaseFinderModal isOpen={isDbFinderOpen} onClose={() => setIsDbFinderOpen(false)} onAddSource={handleAddSource} existingSources={searchSources} />
            <SuggestionsModal isOpen={isSuggestionsModalOpen} result={suggestionsResult} onClose={() => setIsSuggestionsModalOpen(false)} error={suggestionsError} isLoading={isGeneratingSuggestions} onSuggestionClick={handleSuggestionClick} />
            <ConnectedPapersModal isOpen={isConnectionsModalOpen} result={connectionsResult} onClose={() => setIsConnectionsModalOpen(false)} error={connectionsError} isLoading={isFindingConnections} />
            <JournalFinderModal isOpen={isJournalFinderOpen} onClose={() => setIsJournalFinderOpen(false)} paper={paperForJournalFinder} recommendations={journalRecommendations} isLoading={isFindingJournals} error={journalFinderError} />
            <OrganizationFinderModal isOpen={isOrgFinderOpen} onClose={() => setIsOrgFinderOpen(false)} onSelectOrganization={handleSelectOrganization} />
            <DeepResearchModal isOpen={isDeepResearchOpen} onClose={() => setIsDeepResearchOpen(false)} initialTopic={query} model={model} onAddPapersToWorkspace={handleAddPapersToWorkspace} userSettings={userSettings} />
            <ProxySettingsModal isOpen={isProxyModalOpen} onClose={() => setIsProxyModalOpen(false)} settings={userSettings} onSave={setUserSettings} />
        </div>
    );
};

export default App;

