            }
        );

        return cleanup;
    }, []);

    // ... (Keep existing useEffects for suggestions, validation etc.) ...

    const handleLogin = (newUser: User) => {
        setUser(newUser);
        setAppMode(newUser.role === 'participant' ? 'participant_tasks' : 'search');
        setIsLoginModalOpen(false);
    };

