        setGoldStandardDataset([]);
        setUserStudyData([]);
    };

    const handleStartTask = (task: StudyTask) => {
        setActiveTask(task);
        if (task.targetQuery) {
            setQuery(task.targetQuery);
            handleSearch(task.targetQuery, lastUsedOptions);
        }
        setAppMode('search'); // Switch to search view for the task
    };

    const handleCompleteTask = () => {
        setIsSurveyOpen(true);
    };

    const handleSurveySubmit = (responses: any) => {
        if (activeTask && user) {
            analyticsService.logEvent('task_survey_submitted', {
                taskId: activeTask.id,
                participantId: user.id,
                responses
            });
        }
        setIsSurveyOpen(false);
        setActiveTask(null);
        setAppMode('participant_tasks'); // Return to task list
    };

    const triggerBackgroundValidation = (papersToValidate: ResearchPaper[]) => {
        papersToValidate.forEach(async (paper) => {
            if (paper.validation?.status === 'validated' || paper.validation?.status === 'validating') return;
            const currentValidation = paper.validation || { score: 0, status: 'unvalidated', checks: { crossref_match: false, title_match: false, author_match: false, open_access: false, doaj_indexed: false, source_enriched: false, has_citations: false }, log: [] };
            updatePaperState(paper.id, { validation: { ...currentValidation, status: 'validating' } });
            try {
                const { validation, updatedPaperData } = await apiService.validatePaper(paper);
                updatePaperState(paper.id, { ...updatedPaperData, validation });
            } catch (e) {
                 updatePaperState(paper.id, { validation: { ...currentValidation, status: 'error' } });
            }
        });
    };

    const handleSearch = async (searchQuery: string, options: AdvancedSearchOptions) => {
        const specificDoi = options.doi?.trim();
        const doiRegex = /^10.\d{4,9}\/[-._;()/:A-Z0-9]+$/i;
        const queryIsDoi = doiRegex.test(searchQuery.trim());
        const effectiveDoi = specificDoi || (queryIsDoi ? searchQuery.trim() : null);

        if (!searchQuery.trim() && !effectiveDoi) return;

        setSearchSuggestions([]);
        setIsGeneratingSearchSuggestions(false);
        setIsLoading(true);
        setIsSearchingGrounded(false);
        setIsRefiningAI(true); 
        setError(null);
        setPapers([]);
        setSummary(''); 
        setIsSummaryLoading(true); 
        setHasSearched(true);
        setSelectedPaper(null);
        setAnalysis(null);
        setIsScreeningMode(false);
        setSortConfig({ key: 'relevance', direction: 'desc' });
        setCurrentPage(1);
        setLastUsedOptions(options);
        setAiParsedFilters(null); 
        setAiHypotheticalAnswer(null); 
        setIsFindingSimilar(false); 

        if (effectiveDoi) {
            try {
                const result = await apiService.searchByDoi(effectiveDoi, model);
                if (result) {
                    setPapers([result]);
                    setHasMore(false);
                    handleSelectPaper(result);
                    setSummary("DOI direct lookup successful. Showing specific paper details.");
                } else {
                    setError(`No paper found for DOI: ${effectiveDoi}`);
                }
            } catch (err) {
                setError(err instanceof Error ? err.message : "An unknown error occurred while searching by DOI.");
            } finally {
                setIsLoading(false);
                setIsRefiningAI(false);
                setIsSummaryLoading(false);
            }
        } else {
            try {
                const strategyPromise = geminiService.getUnifiedSearchStrategy(searchQuery, model);
                const fastSearchPromise = apiService.searchFast(searchQuery, options, searchSources, 1, userSettings);
                const { papers: fastPapers, hasMore: fastHasMore, rawQueryUsed } = await fastSearchPromise;
                setPapers(fastPapers);
                setHasMore(fastHasMore);
                setIsLoading(false); 
                triggerBackgroundValidation(fastPapers);
                const prefetchedStrategy = await strategyPromise;
                apiService.runBackgroundAIAnalysis(rawQueryUsed, options, fastPapers, model, summaryLength, summaryStyle, searchSources, setAiParsedFilters, setAiHypotheticalAnswer, prefetchedStrategy)
                    .then((result) => { 
                        setPapers(prevPapers => {
                            const combinedPapers = apiService.mergePapers([...prevPapers, ...result.refinedPapers, ...result.newGroundedPapers]);
                            const scoredMap = new Map(combinedPapers.map(p => [p.id, p]));
                            const updatedAndNewPapers = prevPapers.map(p => scoredMap.get(p.id) || p);
                            const newlyAddedPapers = combinedPapers.filter(p => !prevPapers.some(ep => ep.id === p.id));
                            return [...updatedAndNewPapers, ...newlyAddedPapers];
                        });
                        setSummary(result.newSummary);
                        setAnalysis(result.newAnalysis);
                        setAiParsedFilters(result.finalParsedFilters);
                        setAiHypotheticalAnswer(result.finalHypotheticalAnswer);
                        triggerBackgroundValidation(result.newGroundedPapers);
                    })
                    .finally(() => {
                        setIsRefiningAI(false); 
                        setIsSearchingGrounded(false); 
                        setIsSummaryLoading(false); 
                    });
                setIsSearchingGrounded(true);
            } catch (err) {
                setError(err instanceof Error ? err.message : "An unknown error occurred.");
                setIsLoading(false);
                setIsRefiningAI(false);
                setIsSummaryLoading(false);
            }
        }
    };

    // Placeholder handlers to satisfy WorkspacePanel props (preventing build errors)
    const handleLoadMore = async () => { /* ... */ };
    const updatePaperState = (paperId: string, updates: Partial<ResearchPaper>) => { setPapers(prev => prev.map(p => p.id === paperId ? { ...p, ...updates } : p)); };
    const handleSelectPaper = (paper: ResearchPaper) => { setSelectedPaper(paper); };
    const handleToggleWorkspacePaper = (paper: ResearchPaper) => { setWorkspacePapers(prev => prev.some(p => p.id === paper.id) ? prev.filter(p => p.id !== paper.id) : [...prev, paper]); };
    const handleOpenVerificationModal = (paper: ResearchPaper) => { setPaperToVerify(paper); setIsVerificationModalOpen(true); };
    const handleVerificationComplete = (doi: string, result: VerificationResult) => { updatePaperState(paperToVerify!.id, { verificationResult: result }); };
    const handleAnalyzeGaps = async (papers: ResearchPaper[], model: ModelDefinition) => { /* Placeholder */ };
    const handleAnalyzePaper = async (paper: ResearchPaper) => { /* Placeholder */ };
    const handleSaveAnalysis = (paper: ResearchPaper, analysis: PaperAnalysis) => { updatePaperState(paper.id, { savedAnalysis: analysis }); };
    const handleConceptSearch = (concept: string) => { setQuery(concept); handleSearch(concept, lastUsedOptions); };
    const handleOpenCitationModal = (paper: ResearchPaper) => { setPaperForCitation(paper); setIsCitationModalOpen(true); };
    const handleSortChange = (key: SortKey) => { setSortConfig({ key, direction: 'desc' }); };
    const handleSetScreeningMode = (enabled: boolean) => { setIsScreeningMode(enabled); };
    const handleScreenPaper = (id: string, status: any) => { updatePaperState(id, { screeningStatus: status }); };
    const handleAiRerank = async () => { /* Placeholder */ };
    const handleGenerateSuggestions = async (paper: ResearchPaper) => { /* Placeholder */ };
    const handleSuggestionClick = (q: string) => { setQuery(q); handleSearch(q, lastUsedOptions); };
