interface SemanticScoreIndicatorProps {
    score: number | undefined;
}

export const SemanticScoreIndicator: React.FC<SemanticScoreIndicatorProps> = ({ score }) => {
    if (score === undefined) return null;

    let barColorClass = 'bg-slate-300';
    let textColorClass = 'text-slate-500';

    if (score >= 75) {
        barColorClass = 'bg-green-500';
        textColorClass = 'text-green-700';
    } else if (score >= 50) {
        barColorClass = 'bg-yellow-500';
        textColorClass = 'text-yellow-700';
    } else if (score > 0) {
        barColorClass = 'bg-orange-400';
        textColorClass = 'text-orange-700';
    }

    return (
        <div className="flex items-center gap-2 mt-2" title="AI Relevance Score based on semantic analysis">
            <div className="flex-grow max-w-[100px] h-1.5 bg-gray-100 rounded-full overflow-hidden">
                <div 
                    className={`h-full ${barColorClass} transition-all duration-500 ease-out`} 
                    style={{ width: `${score}%` }}
                ></div>
            </div>
            <span className={`text-xs font-bold ${textColorClass}`}>{score}% Relevance</span>
        </div>
    );
};

