import React, { useState, useMemo } from 'react';
import type { ResearchPaper, SummaryLength, SummaryStyle, AdvancedSearchOptions, AnalysisResult, SortConfig, SortKey } from './types';
import * as apiService from './services/apiService';
import { SearchForm } from './components/SearchForm';
import { ResultsDisplay } from './components/ResultsDisplay';
import { PaperDetails } from './components/PaperDetails';
import { AnalysisDisplay } from './components/AnalysisDisplay';
import { LoadingSpinner } from './components/LoadingSpinner';
import { ErrorMessage } from './components/ErrorMessage';

const App: React.FC = () => {
  const [query, setQuery] = useState('');
  const [papers, setPapers] = useState<ResearchPaper[]>([]);
  const [selectedPaper, setSelectedPaper] = useState<ResearchPaper | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [summaryLength, setSummaryLength] = useState<SummaryLength>('medium');
  const [summaryStyle, setSummaryStyle] = useState<SummaryStyle>('paragraph');
  const [summary, setSummary] = useState<string>('');
  const [isSummaryLoading, setIsSummaryLoading] = useState(false);
  const [analysis, setAnalysis] = useState<AnalysisResult | null>(null);
  const [isAnalysisLoading, setIsAnalysisLoading] = useState(false);

  // New state for sorting
  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: 'relevance', direction: 'desc' });

  const handleSearch = async (searchQuery: string, options: AdvancedSearchOptions) => {
    setIsLoading(true);
    setError(null);
    setPapers([]);
    setSelectedPaper(null);
    setSummary('');
    setAnalysis(null);
    setSortConfig({ key: 'relevance', direction: 'desc' }); // Reset sort to relevance on new search

    try {
      // 1. Fetch raw results from OpenAlex
      const { papers: results } = await apiService.searchPapers(searchQuery, options);

      // 2. Calculate Semantic Scores (HyDE)
      // We pass the raw results and the query to generate relevance scores
      const scoredResults = await apiService.calculatePaperScores(results, searchQuery);

      setPapers(scoredResults);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An error occurred during search.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleGenerateSummary = async () => {
    if (papers.length === 0) return;
    setIsSummaryLoading(true);
    try {
      const result = await apiService.generateSummary(papers.slice(0, 10), summaryLength, summaryStyle);
      setSummary(result);
    } catch (err) {
      console.error(err);
    } finally {
      setIsSummaryLoading(false);
    }
  };

  const handleAnalyzePapers = async () => {
    if (papers.length === 0) return;
    setIsAnalysisLoading(true);
    try {
      const result = await apiService.analyzePapers(papers);
      setAnalysis(result);
    } catch (err) {
      console.error(err);
    } finally {
      setIsAnalysisLoading(false);
    }
  };

  const handleSortChange = (key: SortKey) => {
    setSortConfig(current => {
      if (current.key === key) {
        // Toggle direction if clicking same key
        return { ...current, direction: current.direction === 'asc' ? 'desc' : 'asc' };
      }
      // Default to descending for new keys (usually higher score/year/citations is better)
      return { key, direction: 'desc' };
    });
  };

  const sortedPapers = useMemo(() => {
    return [...papers].sort((a, b) => {
      const { key, direction } = sortConfig;
      const dir = direction === 'asc' ? 1 : -1;

      if (key === 'relevance') {
        // Handle undefined scores by treating them as 0
        return ((a.semanticScore || 0) - (b.semanticScore || 0)) * dir;
      } else if (key === 'year') {
        return (a.year - b.year) * dir;
      } else if (key === 'citations') {
        // Handle undefined citations
        return ((a.citations || 0) - (b.citations || 0)) * dir;
      }
      return 0;
    });
  }, [papers, sortConfig]);

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 pb-12">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-10">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-blue-600 rounded-lg p-1.5">
              <svg className="w-6 h-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
              </svg>
            </div>
            <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-700 to-blue-500">
              AI Research Explorer
            </h1>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

          {/* Left Column: Search & Results */}
          <div className={`lg:col-span-${selectedPaper ? '5' : '12'} transition-all duration-300`}>
            {/* SearchForm integration */}
            <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 mb-6">
               <SearchForm 
                  query={query}
                  onQueryChange={setQuery}
                  onSearch={handleSearch}
                  isLoading={isLoading}
                  summaryLength={summaryLength}
                  onLengthChange={setSummaryLength}
                  summaryStyle={summaryStyle}
                  onStyleChange={setSummaryStyle}
                  model={{ id: 'gemini-3-flash-preview', name: 'Gemini 3 Flash' }}
                  onModelChange={() => {}}
                  availableModels={[{ id: 'gemini-3-flash-preview', name: 'Gemini 3 Flash' }]}
                  logAnalyticsEvent={() => {}}
                  suggestions={[]}
                  isSuggestionsLoading={false}
                  onSuggestionClick={() => {}}
                  onOpenOrgFinder={() => {}}
                  onClearInstitution={() => {}}
                  onOpenDeepResearch={() => {}}
               />
            </div>

            {error && <ErrorMessage message={error} />}

            {isLoading ? (
              <LoadingSpinner />
            ) : (
              <>
                <ResultsDisplay 
                  papers={sortedPapers} 
                  selectedPaperId={selectedPaper?.id || null} 
                  onSelectPaper={setSelectedPaper}
                  sortConfig={sortConfig}
                  onSortChange={handleSortChange}
                />
              </>
            )}
          </div>

          {/* Right Column: Details & Analysis */}
          {selectedPaper && (
            <div className="lg:col-span-7 space-y-6">
              <div className="sticky top-24 space-y-6">
                {/* PaperDetails integration */}
                <div className="bg-white p-0 rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                    <div className="p-6">
                        <PaperDetails 
                            paper={selectedPaper}
                            isInWorkspace={false}
                            onToggleWorkspacePaper={() => {}}
                            onConceptClick={() => {}}
                            onFindDoi={() => {}}
                            logAnalyticsEvent={() => {}}
                            onCitePaper={() => {}}
                            model={{ id: 'gemini-3-flash-preview', name: 'Gemini 3 Flash' }}
                            onOpenAnalysis={() => {}}
                            onFindSimilar={() => {}}
                            isFindingSimilar={false}
                            userSettings={{}}
                        />
                    </div>
                </div>

                <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                  <div className="border-b border-slate-100 bg-slate-50/50 px-6 py-4 flex flex-wrap gap-4 items-center justify-between">
                    <h3 className="font-semibold text-slate-800">Collection Analysis</h3>
                    <div className="flex gap-2">
                      <button
                        onClick={handleAnalyzePapers}
                        disabled={isAnalysisLoading}
                        className="px-3 py-1.5 text-sm font-medium text-purple-700 bg-purple-50 hover:bg-purple-100 rounded-md transition-colors disabled:opacity-50"
                      >
                        {isAnalysisLoading ? 'Analyzing...' : 'Analyze Trends'}
                      </button>
                      <button
                        onClick={handleGenerateSummary}
                        disabled={isSummaryLoading}
                        className="px-3 py-1.5 text-sm font-medium text-blue-700 bg-blue-50 hover:bg-blue-100 rounded-md transition-colors disabled:opacity-50"
                      >
                        {isSummaryLoading ? 'Generating...' : 'Generate Summary'}
                      </button>
                    </div>
                  </div>

                  {(summary || analysis) && (
                    <div className="p-6">
                      <AnalysisDisplay 
                        summary={summary} 
                        analysis={analysis} 
                        summaryLength={summaryLength}
                        onLengthChange={setSummaryLength}
                        summaryStyle={summaryStyle}
                        onStyleChange={setSummaryStyle}
                        onRegenerateSummary={handleGenerateSummary}
                      />
                    </div>
                  )}

                  {!summary && !analysis && (
                    <div className="p-12 text-center text-slate-400">
                      <p>Run analysis tools to generate insights from your search results.</p>
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default App;

