                        {activeTab === 'insights' && (
                            <div className="max-w-4xl mx-auto animate-fade-in">
                                <h3 className="text-2xl font-black text-foreground mb-6 flex items-center gap-3">
                                    <ReportIcon className="w-8 h-8 text-primary"/> 
                                    Theoretical & Empirical Gaps
                                </h3>
                                {isGapAnalysisLoading ? <LoadingSpinner message="Identifying research voids..." /> : (
                                    <div className="bg-muted/20 p-8 rounded-2xl border border-dashed border-border">
                                        <div className="prose prose-lg max-w-none">
                                            <FormattedReport text={gapAnalysisReport || "Insufficient data for gap analysis. Add more papers to the workspace."}/>
                                        </div>
                                    </div>
                                )}
                            </div>
                        )}

                        {activeTab === 'assistant' && (
                            <div className="h-full flex flex-col animate-fade-in">
                                <div className="mb-4">
                                    <h3 className="text-2xl font-black text-foreground flex items-center gap-3">
                                        <ChatIcon className="w-8 h-8 text-primary"/> 
                                        Workspace Assistant
                                    </h3>
                                    <p className="text-muted-foreground">Ask questions across your entire collection of {workspacePapers.length} papers.</p>
                                </div>
                                <div className="flex-grow border-4 border-muted rounded-3xl overflow-hidden shadow-2xl">
                                    <ChatPanel history={chatHistory} isLoading={isChatLoading} error={null} onSendMessage={onChat} />
                                </div>
                            </div>
                        )}
                    </div>
                </main>
            </div>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import type { ResearchPaper, SummaryLength, SummaryStyle, AdvancedSearchOptions, AnalysisResult, SortConfig, SortKey, User, AppMode, Project, SearchSourceInfo, ModelDefinition, ChatMessage, SynthesisResult, CitationStyle, UserSettings } from './types';
import * as apiService from './services/apiService';
import { authService } from './services/authService';
import { analyticsService } from './services/analyticsService';
import { mcpService } from './services/mcpService';

// Components
import { Header } from './components/Header';
import { InitialSearchScreen } from './components/InitialSearchScreen';
import { SearchForm } from './components/SearchForm';
import { ResultsDisplay } from './components/ResultsDisplay';
import { WorkspacePanel } from './components/WorkspacePanel';
import { LoginScreen } from './components/LoginScreen';
import { ProxySettingsModal } from './components/ProxySettingsModal';
import { InfoModal } from './components/InfoModal';
import { AboutModalContent } from './components/AboutModalContent';
import { OnboardingModal } from './components/OnboardingModal';
import { LoadingSpinner } from './components/LoadingSpinner';
import { ErrorMessage } from './components/ErrorMessage';
import { ResearcherDashboard } from './components/ResearcherDashboard';
import { ParticipantDashboard } from './components/ParticipantDashboard';
import { PaperVerificationApp } from './components/PaperVerificationApp';
import { EvaluationMode } from './components/EvaluationMode';
import { DatabaseFinderModal } from './components/DatabaseFinderModal';
import { OrganizationFinderModal } from './components/OrganizationFinderModal';
import { DeepResearchModal } from './components/DeepResearchModal';

const App: React.FC = () => {
  // --- AUTH & USER STATE ---
  const [user, setUser] = useState<User | null>(authService.getUser());
  const [appMode, setAppMode] = useState<AppMode>('search');
  const [userSettings, setUserSettings] = useState<UserSettings>({
      isMcpEnabled: false,
      mcpServerUrl: 'http://localhost:3000'
  });

  // --- UI MODAL STATE ---
  const [showLogin, setShowLogin] = useState(false);
  const [showProxy, setShowProxy] = useState(false);
  const [showAbout, setShowAbout] = useState(false);
  const [showHelp, setShowHelp] = useState(false);
  const [showOnboarding, setShowOnboarding] = useState(false);
  const [showDbFinder, setShowDbFinder] = useState(false);
  const [showOrgFinder, setShowOrgFinder] = useState(false);
  const [showDeepResearch, setShowDeepResearch] = useState(false);

  // --- SEARCH & DATA STATE ---
  const [query, setQuery] = useState('');
  const [papers, setPapers] = useState<ResearchPaper[]>([]);
  const [hasSearched, setHasSearched] = useState(false);
  const [selectedPaper, setSelectedPaper] = useState<ResearchPaper | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // --- SORTING ---
  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: 'relevance', direction: 'desc' });

  // --- ANALYSIS STATE ---
  const [summaryLength, setSummaryLength] = useState<SummaryLength>('medium');
  const [summaryStyle, setSummaryStyle] = useState<SummaryStyle>('paragraph');
  const [summary, setSummary] = useState<string>('');
  const [isSummaryLoading, setIsSummaryLoading] = useState(false);
  const [analysis, setAnalysis] = useState<AnalysisResult | null>(null);
  const [isAnalysisLoading, setIsAnalysisLoading] = useState(false);

  // --- WORKSPACE STATE ---
  const [workspacePapers, setWorkspacePapers] = useState<ResearchPaper[]>([]);
  const [projects, setProjects] = useState<Project[]>([{ id: 'default', name: 'General Research', color: 'blue' }]);

  // --- REFINED QUERY STATE ---
  const [refinedQueries, setRefinedQueries] = useState<string[]>([]);
  const [isGeneratingRefined, setIsGeneratingRefined] = useState(false);

  // --- MODELS ---
  const [availableModels] = useState<ModelDefinition[]>([
      { id: 'gemini-3-flash-preview', name: 'Gemini 3 Flash' },
      { id: 'gemini-3-pro-preview', name: 'Gemini 3 Pro' }
  ]);
  const [selectedModel, setSelectedModel] = useState<ModelDefinition>(availableModels[0]);

  // --- SEARCH SOURCES ---
  const [searchSources, setSearchSources] = useState<SearchSourceInfo[]>([
      { id: 'openalex', name: 'OpenAlex', description: 'Primary Index' }
  ]);

  // --- WORKSPACE DASHBOARD STATE ---
  const [showWorkspaceAnalysisDrawer, setShowWorkspaceAnalysisDrawer] = useState(false);
  const [workspaceAnalysisResult, setWorkspaceAnalysisResult] = useState<AnalysisResult | null>(null);
  const [workspaceSynthesisSummary, setWorkspaceSynthesisSummary] = useState<SynthesisResult | null>(null);
  const [workspaceGapAnalysisReport, setWorkspaceGapAnalysisReport] = useState<string | null>(null);
  const [isWorkspaceAnalysisLoading, setIsWorkspaceAnalysisLoading] = useState(false);
  const [isWorkspaceSynthesisLoading, setIsWorkspaceSynthesisLoading] = useState(false);
  const [isWorkspaceGapAnalysisLoading, setIsWorkspaceGapAnalysisLoading] = useState(false);
  const [workspaceChatHistory, setWorkspaceChatHistory] = useState<ChatMessage[]>([]);
  const [isWorkspaceChatLoading, setIsWorkspaceChatLoading] = useState(false);

  // --- PAPER ACTION STATES ---
  const [isAnalyzingPaper, setIsAnalyzingPaper] = useState(false);
  const [isGeneratingSuggestions, setIsGeneratingSuggestions] = useState(false);
  const [isFindingJournals, setIsFindingJournals] = useState(false);
  const [isFindingSimilar, setIsFindingSimilar] = useState(false);
  const [isFindingConnected, setIsFindingConnected] = useState(false);

  // --- EFFECTS ---
  useEffect(() => {
      const hasOnboarded = localStorage.getItem('onboardingCompleted');
      if (!hasOnboarded) {
          setShowOnboarding(true);
      }
  }, []);

  // --- AUTH HANDLERS ---
  const handleLogin = (loggedInUser: User) => {
      setUser(loggedInUser);
      if (loggedInUser.role === 'participant') {
          setAppMode('evaluation');
      } else {
          setAppMode('dashboard');
      }
  };

  const handleLogout = () => {
      authService.logout();
      setUser(null);
      setAppMode('search');
  };

  // --- SEARCH HANDLER ---
  const handleSearch = async (searchQuery: string, options: AdvancedSearchOptions) => {
    setIsLoading(true);
    setError(null);
    setPapers([]);
    setSelectedPaper(null);
    setSummary('');
    setAnalysis(null);
    setRefinedQueries([]);
    setSortConfig({ key: 'relevance', direction: 'desc' });

    // Ensure we track that a search has been attempted
    setHasSearched(true); 

    try {
      const { papers: results } = await apiService.searchPapers(searchQuery, options);

      // Calculate scores immediately to show relevance
      const scoredResults = await apiService.calculatePaperScores(results, searchQuery);

      setPapers(scoredResults);

      // Trigger side-effects: Summary generation
      if (results.length > 0) {
          setIsSummaryLoading(true);
          apiService.generateSummary(results.slice(0, 5), summaryLength, summaryStyle)
            .then(setSummary)
            .catch(console.error)
            .finally(() => setIsSummaryLoading(false));

          setIsAnalysisLoading(true);
          apiService.analyzePapers(results)
            .then(setAnalysis)
            .catch(console.error)
            .finally(() => setIsAnalysisLoading(false));
      }

    } catch (err) {
      setError(err instanceof Error ? err.message : 'An error occurred during search.');
    } finally {
      setIsLoading(false);
    }
  };

  // --- SORTING HANDLER ---
  const handleSortChange = (key: SortKey) => {
    setSortConfig(current => {
      if (current.key === key) {
        return { ...current, direction: current.direction === 'asc' ? 'desc' : 'asc' };
      }
      return { key, direction: 'desc' };
    });
  };

  const sortedPapers = React.useMemo(() => {
    return [...papers].sort((a, b) => {
      const { key, direction } = sortConfig;
      const dir = direction === 'asc' ? 1 : -1;

      if (key === 'relevance') {
        return ((a.semanticScore || 0) - (b.semanticScore || 0)) * dir;
      } else if (key === 'year') {
        return (a.year - b.year) * dir;
      } else if (key === 'citations') {
        return ((a.citations || 0) - (b.citations || 0)) * dir;
      }
      return 0;
    });
  }, [papers, sortConfig]);

  // --- WORKSPACE HANDLERS ---
  const handleToggleWorkspacePaper = (paper: ResearchPaper) => {
      setWorkspacePapers(prev => {
          const exists = prev.some(p => p.id === paper.id);
          if (exists) {
              return prev.filter(p => p.id !== paper.id);
          } else {
              return [...prev, paper];
          }
      });
  };

  const handleAddPapersToWorkspace = (newPapers: ResearchPaper[]) => {
      setWorkspacePapers(prev => {
          const combined = [...prev];
          newPapers.forEach(p => {
              if (!combined.some(existing => existing.id === p.id)) {
                  combined.push(p);
              }
          });
          return combined;
      });
  };

  // --- RENDER HELPERS ---
  const renderMainContent = () => {
      if (appMode === 'dashboard' && user?.role === 'researcher') {
          return (
              <div className="container mx-auto px-4 py-8">
                  <ResearcherDashboard 
                      dataset={[]} // Mock: Needs state lifting in real app
                      setDataset={() => {}} 
                      testResults={[]} 
                      runTestHarness={() => {}} 
                      userStudyData={[]} 
                      onStartUserStudy={() => {}} 
                  />
              </div>
          );
      }

      if (appMode === 'evaluation' && user?.role === 'participant') {
          return (
              <ParticipantDashboard 
                  user={user} 
                  onStartTask={() => {}} 
              />
          );
      }

      // Search Mode
      if (!hasSearched && papers.length === 0 && !isLoading) {
          return (
              <InitialSearchScreen 
                  query={query}
                  onQueryChange={setQuery}
                  onSearch={handleSearch}
                  isLoading={isLoading}
                  summaryLength={summaryLength}
                  onLengthChange={setSummaryLength}
                  summaryStyle={summaryStyle}
                  onStyleChange={setSummaryStyle}
                  model={selectedModel}
                  onModelChange={setSelectedModel}
                  availableModels={availableModels}
                  logAnalyticsEvent={analyticsService.logEvent}
                  onOpenDbFinder={() => setShowDbFinder(true)}
                  searchSources={searchSources}
                  suggestions={[]}
                  isSuggestionsLoading={false}
                  onSuggestionClick={(s) => setQuery(s)}
                  onOpenOrgFinder={() => setShowOrgFinder(true)}
                  onOpenDeepResearch={() => setShowDeepResearch(true)}
              />
          );
      }

      return (
          <div className="container mx-auto px-4 sm:px-6 lg:px-8 py-8">
              <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
                  {/* Left Column: Results */}
                  <div className="lg:col-span-8 space-y-6">
                      <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
                          <SearchForm 
                              query={query}
                              onQueryChange={setQuery}
                              onSearch={handleSearch}
                              isLoading={isLoading}
                              summaryLength={summaryLength}
                              onLengthChange={setSummaryLength}
                              summaryStyle={summaryStyle}
                              onStyleChange={setSummaryStyle}
                              model={selectedModel}
                              onModelChange={setSelectedModel}
                              availableModels={availableModels}
                              logAnalyticsEvent={analyticsService.logEvent}
                              suggestions={[]}
                              isSuggestionsLoading={false}
                              onSuggestionClick={(s) => setQuery(s)}
                              onOpenOrgFinder={() => setShowOrgFinder(true)}
                              onOpenDeepResearch={() => setShowDeepResearch(true)}
                          />
                      </div>

                      {error && <ErrorMessage message={error} />}

                      {isLoading ? (
                          <LoadingSpinner />
                      ) : (
