const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

async function runWithRetry<T>(fn: () => Promise<T>, retries = 3, delay = 2000): Promise<T> {
  try {
    return await fn();
  } catch (error: any) {
    if (retries > 0 && (
        error?.status === 429 || 
        error?.code === 429 || 
        error?.message?.includes('429') || 
        error?.message?.includes('RESOURCE_EXHAUSTED')
    )) {
      console.warn(`Deep Research API rate limit hit. Retrying in ${delay}ms...`);
      await wait(delay);
      return runWithRetry(fn, retries - 1, delay * 2);
    }
    throw error;
  }
}

const safeJsonParse = (jsonString: string) => {
    try {
        const cleanedString = jsonString.replace(/```json/g, '').replace(/```/g, '').trim();
        return JSON.parse(cleanedString);
    } catch (e) {
        console.error("Failed to parse JSON:", e);
        return null;
    }
};

const planSchema = {
    type: Type.OBJECT,
    properties: {
        sub_queries: {
            type: Type.ARRAY,
            items: { type: Type.STRING },
            description: "A list of exactly 3 distinct, targeted search queries."
        }
    },
    required: ["sub_queries"]
};

export const generateResearchPlan = async (topic: string, model: ModelDefinition): Promise<DeepResearchStep[]> => {
    const isTechnical = /implement|architecture|code|system|agent|software|algorithm/i.test(topic);

    const prompt = `Plan a comprehensive literature review on: "${topic}".
    ${isTechnical ? "This is a technical implementation query. Focus queries on system architectures, methodologies, and technical challenges." : ""}
    Generate exactly 3 distinct search queries to cover:
    1. The core theoretical concept.
    2. State-of-the-art methodologies and technical implementations.
    3. Recent (post-2021) evaluations and comparative studies.

    Return JSON with "sub_queries".`;

    try {
        const response = await runWithRetry<GenerateContentResponse>(() => ai.models.generateContent({
            model: "gemini-3-flash-preview", 
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: planSchema,
            }
        }));

        const result = safeJsonParse(response.text || '');
        if (!result || !result.sub_queries) return [];

        return result.sub_queries.map((q: string, i: number) => ({
            id: `step_${i}`,
            query: q,
            status: 'pending',
            papersFound: 0
        }));
    } catch (e) {
        console.error("Deep Research Plan Error:", e);
        return [{ id: 'step_0', query: topic, status: 'pending', papersFound: 0 }];
    }
};

export const executeSearchStep = async (step: DeepResearchStep, settings?: UserSettings): Promise<ResearchPaper[]> => {
    try {
        const searchPromises: Promise<ResearchPaper[]>[] = [
            openalexService.searchOpenAlex(step.query, {
                startYear: '', endYear: '', authors: '', excludeKeywords: '', inclusionCriteria: '', exclusionCriteria: '', studyDesign: 'any',
                isOpenAccess: false
            }).then(res => res.papers)
        ];

        // If institutional OAI is enabled, the agent queries the archive too
        if (settings?.isOaiEnabled && settings?.oaiEndpoint) {
            searchPromises.push(oaiService.queryInstitutionalRepository(settings.oaiEndpoint, step.query));
        }

        const results = await Promise.all(searchPromises);
        return results.flat().slice(0, 15); 
    } catch (e) {
        console.error(`Search failed for ${step.query}:`, e);
        return [];
    }
};

const reportSchema = {
    type: Type.OBJECT,
    properties: {
        title: { type: Type.STRING },
        summary: { type: Type.STRING },
        sections: {
            type: Type.ARRAY,
            items: {
                type: Type.OBJECT,
                properties: {
                    heading: { type: Type.STRING },
                    content: { type: Type.STRING, description: "Markdown content for this section." }
                },
                required: ["heading", "content"]
            }
        }
    },
    required: ["title", "summary", "sections"]
};

export const synthesizeReport = async (topic: string, papers: ResearchPaper[], model: ModelDefinition): Promise<DeepResearchReport> => {
    // Deduplicate papers
    const uniquePapers = Array.from(new Map(papers.map(p => [p.id, p])).values());
    // Sort by influence/citations to prioritize top content in the TOON context
    uniquePapers.sort((a, b) => (b.citations || 0) - (a.citations || 0));

    // Convert to Token-Optimized Object Notation (TOON)
    // We can now fit more papers (e.g. 45 instead of 25) due to reduced overhead
    const context = papersToToonCollection(uniquePapers.slice(0, 45));

    const isTechnical = /implement|architecture|code|system|agent|software|algorithm/i.test(topic);

    const prompt = `Act as a Senior Research Lead. Write a comprehensive literature review report on: "${topic}".

    Source Material (TOON Format: #ID|Title|Authors|Year|Citations|Influence|Snippet):
    ${context}

    Instructions:
    1. Synthesize findings across all provided sources. 
    2. Explicitly reference any papers flagged as [Institutional Repository (OAI)] to highlight local/archival research if available.
    3. Cite sources using [#ID] notation strictly matching the list provided in the TOON block.
    ${isTechnical ? "4. Include a dedicated section on 'Technical Implementation Strategies' described in the sources." : "4. Focus on methodological trends."}
    5. Structure: Title, Executive Summary, 3-5 Detailed Thematic Sections.

    Return a JSON object matching the report schema.`;

    try {
        const response = await runWithRetry<GenerateContentResponse>(() => ai.models.generateContent({
            model: "gemini-3-pro-preview",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: reportSchema,
                thinkingConfig: { thinkingBudget: 16000 }
            }
        }));

        const result = safeJsonParse(response.text || '');
        if (!result) throw new Error("Failed to parse report.");

        return {
            title: result.title,
            summary: result.summary,
            sections: result.sections,
            // Return top referenced papers for the UI list
            references: uniquePapers.slice(0, 30)
        };
    } catch (e) {
        console.error("Report Synthesis Error:", e);
        throw new Error("Failed to generate research report.");
    }
};

import { GoogleGenAI, Type, Chat, GenerateContentResponse } from "@google/genai";
import type { ResearchPaper, SummaryLength, SummaryStyle, ModelDefinition, CitationStyle } from "../types";
import { papersToToonCollection } from "../utils/toon";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Helper for exponential backoff
const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

async function runWithRetry<T>(fn: () => Promise<T>, retries = 3, delay = 2000): Promise<T> {
  try {
    return await fn();
  } catch (error: any) {
    // Check for rate limit errors (429 or RESOURCE_EXHAUSTED)
    if (retries > 0 && (
        error?.status === 429 || 
        error?.code === 429 || 
        error?.message?.includes('429') || 
        error?.message?.includes('RESOURCE_EXHAUSTED')
    )) {
      console.warn(`Gemini API rate limit hit. Retrying in ${delay}ms...`);
      await wait(delay);
      return runWithRetry(fn, retries - 1, delay * 2);
    }
    throw error;
  }
}

// Existing summarization function updated to use TOON
export const generateSummaryForPapers = async (papers: ResearchPaper[], length: SummaryLength, style: SummaryStyle): Promise<string> => {
  if (papers.length === 0) return "";

  // Use TOON format for denser context representation
  const papersText = papersToToonCollection(papers);

  const lengthPrompt = length === 'short' ? "1-2 paragraphs" : length === 'medium' ? "3-4 paragraphs" : "a detailed report";
  const stylePrompt = style === 'bullets' ? "bullet points" : "paragraphs";

  const prompt = `Based on the following academic papers (formatted in TOON), write a synthesis summary of the research topic. 

  Format: ${stylePrompt}
  Length: ${lengthPrompt}

  Source Material (TOON):
  ${papersText}

  Focus on common themes, conflicting results, and the overall state of research represented by these papers. Cite the papers using their index numbers like [1], [2].`;

  try {
    const response = await runWithRetry<GenerateContentResponse>(() => ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
    }));
    return response.text || "Failed to generate summary.";
  } catch (error) {
    console.error("Error generating summary:", error);
    return "Error generating summary. Rate limit exceeded or API error.";
  }
};

/**
 * Generates a hypothetical answer (abstract) for the user's query.
 * This is used for HyDE (Hypothetical Document Embeddings).
 */
export const generateHypotheticalAnswer = async (query: string): Promise<string> => {
  const prompt = `Please write a hypothetical scientific abstract (about 150 words) that would perfectly answer the following research question: "${query}". 
  Do not include placeholders. Write it as if it were a real paper summary found in a database.`;

  try {
    const response = await runWithRetry<GenerateContentResponse>(() => ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
    }));
    return response.text || query; // Fallback to query if generation fails
  } catch (error) {
    console.error("Error generating hypothetical answer:", error);
    return query;
  }
};

/**
 * Generates an embedding vector for a given text string.
 */
export const getEmbedding = async (text: string): Promise<number[]> => {
  try {
    const model = "text-embedding-004";
    const result = await runWithRetry<any>(() => ai.models.embedContent({
      model: model,
      contents: text,
    }));
    return result.embedding?.values || [];
  } catch (error) {
    console.error("Error fetching embedding:", error);
    return [];
  }
};

/**
 * Extracts detailed metadata for citation purposes when standard fields are missing.
 */
export const extractCitationMetadata = async (paper: ResearchPaper, model: ModelDefinition): Promise<object> => {
    const prompt = `Extract citation metadata from the following paper information into CSL-JSON format.
    Title: ${paper.title}
    Abstract: ${paper.abstract}
    Authors: ${paper.authors}
    Year: ${paper.year}
    Journal: ${paper.journal || ''}
    DOI: ${paper.doi || ''}

    Return ONLY JSON.`;

    try {
        const response = await runWithRetry<GenerateContentResponse>(() => ai.models.generateContent({
            model: model.id || "gemini-3-flash-preview",
            contents: prompt,
            config: { responseMimeType: "application/json" }
        }));

        try {
            return JSON.parse(response.text || '{}');
        } catch {
            return {};
        }
    } catch (e) {
        return {};
    }
};

/**
 * Fallback citation formatter using LLM if CSL processor fails.
 */
export const formatCitation = async (paper: ResearchPaper, style: CitationStyle, model: ModelDefinition): Promise<string> => {
    const prompt = `Generate a citation for this paper in ${style.toUpperCase()} format.
    Title: ${paper.title}
    Authors: ${paper.authors}
    Year: ${paper.year}
    Journal: ${paper.journal || ''}
    DOI: ${paper.doi || ''}

    Return only the citation string.`;

    try {
        const response = await runWithRetry<GenerateContentResponse>(() => ai.models.generateContent({
            model: model.id || "gemini-3-flash-preview",
            contents: prompt,
        }));
        return response.text?.trim() || "";
    } catch (e) {
        return `${paper.authors} (${paper.year}). ${paper.title}.`;
    }
};

/**
 * Creates a chat session context aware of a specific paper.
 */
export const createPaperChatSession = (paper: ResearchPaper, modelId: string): Chat => {
    return ai.chats.create({
        model: modelId,
        config: {
            systemInstruction: `You are a helpful research assistant discussing the paper: "${paper.title}".
            Abstract: "${paper.abstract}"
            Authors: "${paper.authors}"
            Year: "${paper.year}"

            Answer questions based on the abstract and metadata provided. If you don't know, say so.`
        }
    });
};

import type { ResearchPaper } from '../types';
import { generateHypotheticalAnswer, getEmbedding } from './geminiService';
import { cosineSimilarity } from '../utils/math';

/**
 * Generates the embedding for the hypothetical answer.
 * This is step 1 & 2 of the HyDE process, separated to allow parallelism.
 */
export const precomputeQueryEmbedding = async (query: string): Promise<number[]> => {
    try {
        // 1. Generate Hypothetical Answer
        const hypotheticalAnswer = await generateHypotheticalAnswer(query);
        // 2. Get Embedding for it
        const queryEmbedding = await getEmbedding(hypotheticalAnswer);

        if (queryEmbedding.length === 0) {
            console.warn("Embedding generation failed for query.");
            return [];
        }
        return queryEmbedding;
    } catch (e) {
        console.error("Error precomputing query embedding:", e);
        return [];
    }
};

/**
 * Calculates semantic scores using a precomputed query embedding.
 * This allows the search results to be displayed first, then updated with scores.
 */
export const computeScores = async (papers: ResearchPaper[], queryEmbedding: number[]): Promise<ResearchPaper[]> => {
    if (papers.length === 0) return [];
    if (queryEmbedding.length === 0) return papers.map(p => ({ ...p, semanticScore: 0 }));

    try {
        // 3. Get Embeddings for Papers (in parallel)
        const papersWithScores = await Promise.all(papers.map(async (paper) => {
            // If abstract is missing or too short, rely on title
            const textToEmbed = (paper.abstract && paper.abstract.length > 50 && !paper.abstract.includes("No abstract")) 
              ? paper.abstract 
              : `${paper.title} ${paper.title}`; // Duplicate title to give it weight

            const paperEmbedding = await getEmbedding(textToEmbed);

            let score = 0;
            if (paperEmbedding.length > 0) {
              const similarity = cosineSimilarity(queryEmbedding, paperEmbedding);
              // Convert cosine similarity (-1 to 1) to a 0-100 score
              // Academic texts usually range 0.4 to 0.9 in similarity, so we normalize specifically for better UI visuals
              score = Math.max(0, Math.min(100, Math.round(((similarity - 0.4) / 0.5) * 100)));
            }

            return {
              ...paper,
              semanticScore: score
            };
        }));

        return papersWithScores;
    } catch (e) {
        console.error("Error computing scores:", e);
        return papers;
    }
};

/**
 * Legacy combined function for backward compatibility.
 */
export const calculatePaperScores = async (papers: ResearchPaper[], query: string): Promise<ResearchPaper[]> => {
  const queryEmbedding = await precomputeQueryEmbedding(query);
  return computeScores(papers, queryEmbedding);
};

