import type { ResearchPaper } from '../types';
import { generateHypotheticalAnswer, getEmbedding } from './geminiService';
import { cosineSimilarity } from '../utils/math';

/**
 * Generates the embedding for the hypothetical answer.
 * This is step 1 & 2 of the HyDE process, separated to allow parallelism.
 */
export const precomputeQueryEmbedding = async (query: string): Promise<number[]> => {
    try {
        // 1. Generate Hypothetical Answer
        const hypotheticalAnswer = await generateHypotheticalAnswer(query);
        // 2. Get Embedding for it
        const queryEmbedding = await getEmbedding(hypotheticalAnswer);

        if (queryEmbedding.length === 0) {
            console.warn("Embedding generation failed for query.");
            return [];
        }
        return queryEmbedding;
    } catch (e) {
        console.error("Error precomputing query embedding:", e);
        return [];
    }
};

/**
 * Calculates semantic scores using a precomputed query embedding.
 * This allows the search results to be displayed first, then updated with scores.
 */
export const computeScores = async (papers: ResearchPaper[], queryEmbedding: number[]): Promise<ResearchPaper[]> => {
    if (papers.length === 0) return [];
    if (queryEmbedding.length === 0) return papers.map(p => ({ ...p, semanticScore: 0 }));

    const scoredPapers: ResearchPaper[] = [];
    const CHUNK_SIZE = 3; // Process only 3 papers at a time to respect rate limits

    try {
        // Process papers in chunks
        for (let i = 0; i < papers.length; i += CHUNK_SIZE) {
            const chunk = papers.slice(i, i + CHUNK_SIZE);

            const chunkResults = await Promise.all(chunk.map(async (paper) => {
                // If abstract is missing or too short, rely on title
                const textToEmbed = (paper.abstract && paper.abstract.length > 50 && !paper.abstract.includes("No abstract")) 
                  ? paper.abstract 
                  : `${paper.title} ${paper.title}`; // Duplicate title to give it weight

                const paperEmbedding = await getEmbedding(textToEmbed);

                let score = 0;
                if (paperEmbedding.length > 0) {
                  const similarity = cosineSimilarity(queryEmbedding, paperEmbedding);
                  // Convert cosine similarity (-1 to 1) to a 0-100 score
                  // Academic texts usually range 0.4 to 0.9 in similarity, so we normalize specifically for better UI visuals
                  score = Math.max(0, Math.min(100, Math.round(((similarity - 0.4) / 0.5) * 100)));
                }

                return {
                  ...paper,
                  semanticScore: score
                };
            }));

            scoredPapers.push(...chunkResults);

            // Short pause between chunks if there are more
            if (i + CHUNK_SIZE < papers.length) {
                await new Promise(resolve => setTimeout(resolve, 500));
            }
        }

        return scoredPapers;
    } catch (e) {
        console.error("Error computing scores:", e);
        return papers;
    }
};

/**
 * Legacy combined function for backward compatibility.
 */
export const calculatePaperScores = async (papers: ResearchPaper[], query: string): Promise<ResearchPaper[]> => {
  const queryEmbedding = await precomputeQueryEmbedding(query);
  return computeScores(papers, queryEmbedding);
};

