const safeJsonParse = (jsonString: string) => {
    try {
        const cleanedString = jsonString.replace(/```json/g, '').replace(/```/g, '').trim();
        return JSON.parse(cleanedString);
    } catch (e) {
        console.error("Failed to parse JSON:", e);
        return null;
    }
};

const planSchema = {
    type: Type.OBJECT,
    properties: {
        sub_queries: {
            type: Type.ARRAY,
            items: { type: Type.STRING },
            description: "A list of exactly 3 distinct, targeted search queries."
        }
    },
    required: ["sub_queries"]
};

export const generateResearchPlan = async (topic: string, model: ModelDefinition): Promise<DeepResearchStep[]> => {
    const isTechnical = /implement|architecture|code|system|agent|software|algorithm/i.test(topic);

    const prompt = `Plan a comprehensive literature review on: "${topic}".
    ${isTechnical ? "This is a technical implementation query. Focus queries on system architectures, methodologies, and technical challenges." : ""}
    Generate exactly 3 distinct search queries to cover:
    1. The core theoretical concept.
    2. State-of-the-art methodologies and technical implementations.
    3. Recent (post-2021) evaluations and comparative studies.

    Return JSON with "sub_queries".`;

    try {
        const response = await runWithRetry<GenerateContentResponse>(() => ai.models.generateContent({
            model: "gemini-3-flash-preview", 
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: planSchema,
            }
        }));

        const result = safeJsonParse(response.text || '');
        if (!result || !result.sub_queries) return [];

        return result.sub_queries.map((q: string, i: number) => ({
            id: `step_${i}`,
            query: q,
            status: 'pending',
            papersFound: 0
        }));
    } catch (e) {
        console.error("Deep Research Plan Error:", e);
        return [{ id: 'step_0', query: topic, status: 'pending', papersFound: 0 }];
    }
};

export const executeSearchStep = async (step: DeepResearchStep, settings?: UserSettings): Promise<ResearchPaper[]> => {
    try {
        const searchPromises: Promise<ResearchPaper[]>[] = [
            openalexService.searchOpenAlex(step.query, {
                startYear: '', endYear: '', authors: '', excludeKeywords: '', inclusionCriteria: '', exclusionCriteria: '', studyDesign: 'any',
                isOpenAccess: false
            }).then(res => res.papers)
        ];

        // If institutional OAI is enabled, the agent queries the archive too
        if (settings?.isOaiEnabled && settings?.oaiEndpoint) {
            searchPromises.push(oaiService.queryInstitutionalRepository(settings.oaiEndpoint, step.query));
        }

        const results = await Promise.all(searchPromises);
        return results.flat().slice(0, 15); 
    } catch (e) {
        console.error(`Search failed for ${step.query}:`, e);
        return [];
    }
};

const reportSchema = {
    type: Type.OBJECT,
    properties: {
        title: { type: Type.STRING },
        summary: { type: Type.STRING },
        sections: {
            type: Type.ARRAY,
            items: {
                type: Type.OBJECT,
                properties: {
                    heading: { type: Type.STRING },
                    content: { type: Type.STRING, description: "Markdown content for this section." }
                },
                required: ["heading", "content"]
            }
        }
    },
    required: ["title", "summary", "sections"]
};

export const synthesizeReport = async (topic: string, papers: ResearchPaper[], model: ModelDefinition): Promise<DeepResearchReport> => {
    // Deduplicate papers
    const uniquePapers = Array.from(new Map(papers.map(p => [p.id, p])).values());
    // Sort by influence/citations to prioritize top content in the TOON context
    uniquePapers.sort((a, b) => (b.citations || 0) - (a.citations || 0));

    // Convert to Token-Optimized Object Notation (TOON)
    // We can now fit more papers (e.g. 45 instead of 25) due to reduced overhead
    const context = papersToToonCollection(uniquePapers.slice(0, 45));

    const isTechnical = /implement|architecture|code|system|agent|software|algorithm/i.test(topic);

    const prompt = `Act as a Senior Research Lead. Write a comprehensive literature review report on: "${topic}".

    Source Material (TOON Format: #ID|Title|Authors|Year|Citations|Influence|Snippet):
    ${context}

    Instructions:
    1. Synthesize findings across all provided sources. 
    2. Explicitly reference any papers flagged as [Institutional Repository (OAI)] to highlight local/archival research if available.
    3. Cite sources using [#ID] notation strictly matching the list provided in the TOON block.
    ${isTechnical ? "4. Include a dedicated section on 'Technical Implementation Strategies' described in the sources." : "4. Focus on methodological trends."}
    5. Structure: Title, Executive Summary, 3-5 Detailed Thematic Sections.

    Return a JSON object matching the report schema.`;

    try {
        const response = await runWithRetry<GenerateContentResponse>(() => ai.models.generateContent({
            model: "gemini-3-pro-preview",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: reportSchema,
                thinkingConfig: { thinkingBudget: 16000 }
            }
        }));

        const result = safeJsonParse(response.text || '');
        if (!result) throw new Error("Failed to parse report.");

        return {
            title: result.title,
            summary: result.summary,
            sections: result.sections,
            // Return top referenced papers for the UI list
            references: uniquePapers.slice(0, 30)
        };
    } catch (e) {
        console.error("Report Synthesis Error:", e);
        throw new Error("Failed to generate research report.");
    }
};

import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
const EMBEDDING_MODEL = "text-embedding-004";

// Persistent Cache using localStorage (simple string-key store)
const PERSISTENT_CACHE_KEY = 'are_embeddings_index_v1';
const getStoredEmbeddings = (): Record<string, number[]> => {
    try {
        const stored = localStorage.getItem(PERSISTENT_CACHE_KEY);
        return stored ? JSON.parse(stored) : {};
    } catch { return {}; }
};

const saveEmbeddingsToStore = (newEmbeddings: Record<string, number[]>) => {
    try {
        const current = getStoredEmbeddings();
        const updated = { ...current, ...newEmbeddings };
        // Basic eviction: if cache > 1MB, clear old entries
        if (JSON.stringify(updated).length > 1024 * 1024) {
            localStorage.removeItem(PERSISTENT_CACHE_KEY);
            localStorage.setItem(PERSISTENT_CACHE_KEY, JSON.stringify(newEmbeddings));
        } else {
            localStorage.setItem(PERSISTENT_CACHE_KEY, JSON.stringify(updated));
        }
    } catch {}
};

// Helper for exponential backoff with jitter
const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

async function runWithRetry<T>(fn: () => Promise<T>, retries = 5, delay = 3000): Promise<T> {
  try {
    return await fn();
  } catch (error: any) {
    const errBody = error?.error || error;
    const errorCode = errBody?.code || error?.status;
    const errorMessage = errBody?.message || error?.message || JSON.stringify(error);
    const errorStatus = errBody?.status;

    if (retries > 0 && (
        errorCode === 429 || 
        errorStatus === 'RESOURCE_EXHAUSTED' ||
        errorMessage?.includes('429') || 
        errorMessage?.includes('RESOURCE_EXHAUSTED') ||
        errorMessage?.includes('quota')
    )) {
      const jitter = Math.random() * 1000;
      console.warn(`Embedding API rate limit hit. Retrying in ${(delay + jitter).toFixed(0)}ms...`);
      await wait(delay + jitter);
      return runWithRetry(fn, retries - 1, delay * 2);
    }
    throw error;
  }
}

export const embedText = async (text: string): Promise<number[]> => {
    if (!text || text.trim() === '') return [];

    const cacheKey = text.trim().substring(0, 500); // Index by truncated text
    const store = getStoredEmbeddings();

    if (store[cacheKey]) return store[cacheKey];

    try {
        const response = await runWithRetry<any>(() => ai.models.embedContent({ 
            model: EMBEDDING_MODEL, 
            contents: text
        }));

        const embedding = response.embedding?.values || [];
        if (embedding.length > 0) {
            saveEmbeddingsToStore({ [cacheKey]: embedding });
        }
        return embedding;
    } catch (e) {
        console.error("Embedding failed:", e);
        return [];
    }
};

export const batchEmbedText = async (texts: string[]): Promise<number[][]> => {
    if (!texts || texts.length === 0) return [];

    // Efficiently separate cached vs new items
    const store = getStoredEmbeddings();
    const results: number[][] = new Array(texts.length);
    const indicesToFetch: number[] = [];
    const textsToFetch: string[] = [];

    texts.forEach((text, i) => {
        const key = text.substring(0, 500);
        if (store[key]) {
            results[i] = store[key];
        } else {
            indicesToFetch.push(i);
            textsToFetch.push(text);
        }
    });

    if (textsToFetch.length > 0) {
        // Limit concurrency to 3 parallel requests for embedding batching
        const BATCH_SIZE = 3;
        for (let i = 0; i < textsToFetch.length; i += BATCH_SIZE) {
            const chunk = textsToFetch.slice(i, i + BATCH_SIZE);
            const chunkIndices = indicesToFetch.slice(i, i + BATCH_SIZE);

            // Process chunk
            const fetchedChunk = await Promise.all(chunk.map(t => embedText(t)));

            fetchedChunk.forEach((embedding, idx) => {
                const originalIndex = chunkIndices[idx];
                results[originalIndex] = embedding;
            });

            // Small delay between batches if there are more
            if (i + BATCH_SIZE < textsToFetch.length) {
                await wait(500);
            }
        }
    }

    return results;
};

import type { ResearchPaper } from '../types';
import { getCache, setCache } from '../utils/cache';

const CACHE_TTL_MS = 5 * 60 * 1000; // 5 minutes for searches (Standardized)
const ENRICH_TTL_MS = 48 * 60 * 60 * 1000; // 48 hours for stable metadata

const extractArxivId = (url?: string): string | null => {
    if (!url) return null;
    const match = url.match(/(?:abs|pdf)\/(\d{4}\.\d{4,5}(v\d+)?)/);
    return match ? match[1] : null;
};

export const enrichFromArxiv = async (paper: ResearchPaper): Promise<Partial<ResearchPaper> | null> => {
    const arxivId = extractArxivId(paper.sourceURL);
    if (!arxivId) return null;

    const cacheKey = `arxiv_enrich_${arxivId}`;
    const cached = getCache<Partial<ResearchPaper>>(cacheKey);
    if (cached) return cached;

    try {
        const response = await fetch(`https://export.arxiv.org/api/query?id_list=${arxivId}`);
        if (!response.ok) return null;

        const xmlText = await response.text();
        const parser = new DOMParser();
        const xmlDoc = parser.parseFromString(xmlText, "application/xml");
        const entry = xmlDoc.querySelector("entry");
        if (!entry) return null;

        const enrichedData: Partial<ResearchPaper> = {
            title: entry.querySelector("title")?.textContent?.trim().replace(/\s+/g, ' ') || undefined,
            abstract: entry.querySelector("summary")?.textContent?.trim().replace(/\s+/g, ' ') || undefined,
            year: entry.querySelector("published")?.textContent ? new Date(entry.querySelector("published")!.textContent!).getFullYear() : undefined,
            authors: Array.from(entry.querySelectorAll("author > name")).map(n => n.textContent?.trim()).filter(Boolean).join(', '),
            pdfURL: Array.from(entry.querySelectorAll("link")).find(l => l.getAttribute('title') === 'pdf')?.getAttribute('href') || undefined,
            sourceURL: entry.querySelector("id")?.textContent?.trim() || undefined,
            enrichmentSource: 'arXiv'
        };

        setCache(cacheKey, enrichedData, ENRICH_TTL_MS);
        return enrichedData;
    } catch (e) {
        return null;
    }
};

export const searchArxiv = async (query: string, page: number = 1): Promise<{ papers: ResearchPaper[], hasMore: boolean }> => {
    const cacheKey = `arxiv_search_${query}_${page}`;
    const cached = getCache<{ papers: ResearchPaper[], hasMore: boolean }>(cacheKey);
    if (cached) return cached;

    const resultsPerPage = 15;
    const start = (page - 1) * resultsPerPage;
    const apiUrl = `https://export.arxiv.org/api/query?search_query=all:${encodeURIComponent(query)}&max_results=${resultsPerPage}&start=${start}`;

    try {
        const response = await fetch(apiUrl);
        if (!response.ok) return { papers: [], hasMore: false };
        const xmlText = await response.text();
        const xmlDoc = new DOMParser().parseFromString(xmlText, "application/xml");

        const totalResults = parseInt(xmlDoc.querySelector("opensearch\\:totalResults")?.textContent || '0', 10);
        const entries = Array.from(xmlDoc.querySelectorAll("entry"));

        const papers: ResearchPaper[] = entries.map(entry => ({
            id: `arxiv:${extractArxivId(entry.querySelector("id")?.textContent?.trim()) || Math.random()}`,
            title: entry.querySelector("title")?.textContent?.trim().replace(/\s+/g, ' ') || 'Untitled',
            abstract: entry.querySelector("summary")?.textContent?.trim().replace(/\s+/g, ' ') || 'No abstract.',
            year: entry.querySelector("published")?.textContent ? new Date(entry.querySelector("published")!.textContent!).getFullYear() : new Date().getFullYear(),
            authors: Array.from(entry.querySelectorAll("author > name")).map(n => n.textContent?.trim()).filter(Boolean).join(', '),
            pdfURL: Array.from(entry.querySelectorAll("link")).find(l => l.getAttribute('title') === 'pdf')?.getAttribute('href') || undefined,
            sourceURL: entry.querySelector("id")?.textContent?.trim() || '',
            enrichmentSource: 'arXiv'
        }));

        const result = { papers, hasMore: (start + resultsPerPage) < totalResults };
        setCache(cacheKey, result, CACHE_TTL_MS);
        return result;
    } catch (e) {
        return { papers: [], hasMore: false };
    }
};

import type { ResearchPaper, AdvancedSearchOptions, ConnectedPaper } from '../types';
import { getCache, setCache } from '../utils/cache';

const S2_API_BASE = 'https://api.semanticscholar.org/graph/v1';
const CACHE_TTL_MS = 5 * 60 * 1000; // 5 minutes for graph/search data (Standardized)

export const searchSemanticScholar = async (query: string, options: AdvancedSearchOptions, page: number = 1): Promise<{ papers: ResearchPaper[], hasMore: boolean }> => {
    const cacheKey = `s2_search_${query}_${page}`;
    const cached = getCache<any>(cacheKey);
    if (cached) return cached;

    const limit = 15;
    const offset = (page - 1) * limit;
    const fields = 'title,authors,year,abstract,url,citationCount,influentialCitationCount,openAccessPdf,venue,externalIds,tldr';

    const url = `${S2_API_BASE}/paper/search?query=${encodeURIComponent(query)}&limit=${limit}&offset=${offset}&fields=${fields}`;

    try {
        const response = await fetch(url);
        if (!response.ok) throw new Error("S2 API Error");
        const data = await response.json();

        const papers: ResearchPaper[] = (data.data || []).map((p: any) => ({
            id: `s2:${p.paperId}`,
            title: p.title,
            authors: (p.authors || []).map((a: any) => a.name).join(', '),
            year: p.year,
            abstract: p.abstract || 'No abstract available.',
            sourceURL: p.url,
            pdfURL: p.openAccessPdf?.url || undefined,
            citations: p.citationCount,
            influentialCitationCount: p.influentialCitationCount,
            doi: p.externalIds?.DOI,
            journal: p.venue,
            isOpenAccess: !!p.openAccessPdf,
            enrichmentSource: 'Semantic Scholar',
            highlights: p.tldr?.text ? [{ category: 'TLDR', text: p.tldr.text }] : []
        }));

        const result = { papers, hasMore: !!data.next };
        setCache(cacheKey, result, CACHE_TTL_MS);
        return result;
    } catch (e) {
        console.error("Semantic Scholar search failed:", e);
        return { papers: [], hasMore: false };
    }
};

/**
 * Fetches real-time citation data and connections for a specific DOI.
 */
export const getPaperGraphData = async (doi: string): Promise<{ 
    influence: Partial<ResearchPaper>, 
    connections: ConnectedPaper[] 
} | null> => {
    const cacheKey = `s2_graph_${doi}`;
    const cached = getCache<any>(cacheKey);
    if (cached) return cached;

    // We fetch citations and references in one go for efficiency
    // We prioritize "influential" citations to reduce noise
    const fields = 'citationCount,influentialCitationCount,tldr,citations.title,citations.authors,citations.year,citations.url,citations.influentialCitationCount,references.title,references.authors,references.year,references.url';
    const url = `${S2_API_BASE}/paper/DOI:${doi}?fields=${fields}`;

    try {
        const response = await fetch(url);
        if (!response.ok) return null;
        const p = await response.json();

        const influence: Partial<ResearchPaper> = {
            citations: p.citationCount,
            influentialCitationCount: p.influentialCitationCount,
            highlights: p.tldr?.text ? [{ category: 'TLDR', text: p.tldr.text }] : []
        };

        const connections: ConnectedPaper[] = [];

        // Add Top 5 Influential Citations
        if (p.citations) {
            const topCitations = p.citations
                .filter((c: any) => c.title)
                .sort((a: any, b: any) => (b.influentialCitationCount || 0) - (a.influentialCitationCount || 0))
                .slice(0, 5);

            topCitations.forEach((c: any) => {
                connections.push({
                    title: c.title,
                    authors: (c.authors || []).map((a: any) => a.name).join(', '),
                    year: c.year,
                    connection: 'Cited by this paper', // Semantic Scholar context: "this paper" is the result, "citing paper" is the input
                    summary: 'Highly influential citation found via Semantic Scholar.',
                    sourceURL: c.url
                });
            });
        }

        // Add Top 5 References
        if (p.references) {
            const topRefs = p.references
                .filter((r: any) => r.title)
                .slice(0, 5);

            topRefs.forEach((r: any) => {
                connections.push({
                    title: r.title,
                    authors: (r.authors || []).map((a: any) => a.name).join(', '),
                    year: r.year,
                    connection: 'This paper cites',
                    summary: 'Key reference identified in the original text.',
                    sourceURL: r.url
                });
            });
        }

        const result = { influence, connections };
        setCache(cacheKey, result, CACHE_TTL_MS);
        return result;
    } catch (e) {
        console.error("S2 Graph Fetch Failed:", e);
        return null;
    }
};

import type { ResearchPaper, AdvancedSearchOptions } from '../types';
import { getCache, setCache } from '../utils/cache';

const CORE_API_BASE = 'https://api.core.ac.uk/v3';
const CACHE_TTL_MS = 5 * 60 * 1000; // 5 minutes (Standardized)

/**
 * CORE Integration focuses on finding repository-hosted versions 
 * of papers that might be paywalled on official sites.
 */
export const searchCORE = async (query: string, page: number = 1): Promise<{ papers: ResearchPaper[], hasMore: boolean }> => {
    const cacheKey = `core_search_${query}_${page}`;
    const cached = getCache<any>(cacheKey);
    if (cached) return cached;

    // CORE API usually requires a key for high volume, 
    // but they offer a limited public tier for search.
    const url = `${CORE_API_BASE}/search/works?q=${encodeURIComponent(query)}&limit=10&offset=${(page-1)*10}`;

    try {
        const response = await fetch(url);
        if (!response.ok) return { papers: [], hasMore: false };
        const data = await response.json();

        const papers: ResearchPaper[] = (data.results || []).map((p: any) => ({
            id: `core:${p.id}`,
            coreId: p.id.toString(),
            title: p.title,
            authors: (p.authors || []).map((a: any) => a.name).join(', '),
            year: p.publishedDate ? new Date(p.publishedDate).getFullYear() : 0,
            abstract: p.abstract || 'No abstract.',
            sourceURL: p.downloadUrl || p.fullTextUrl || undefined,
            pdfURL: p.downloadUrl || undefined,
            repositoryURL: p.publisher || undefined,
            doi: p.doi,
            isOpenAccess: true, // CORE mostly indexes OA
            enrichmentSource: 'CORE'
        }));

        const result = { papers, hasMore: data.totalHits > (page * 10) };
        setCache(cacheKey, result, CACHE_TTL_MS);
        return result;
    } catch { return { papers: [], hasMore: false }; }
};

