import React from 'react';
import type { ResearchPaper, SortConfig, SortKey } from '../types';
import { PaperCard } from './PaperCard';

interface ResultsDisplayProps {
  papers: ResearchPaper[];
  selectedPaperId: string | null;
  onSelectPaper: (paper: ResearchPaper) => void;
  sortConfig: SortConfig;
  onSortChange: (key: SortKey) => void;
  workspacePaperIds: Set<string>;
  onToggleWorkspace: (paper: ResearchPaper) => void;
}

const sortOptions: { key: SortKey; label: string }[] = [
    { key: 'relevance', label: 'Relevance (AI)' },
    { key: 'year', label: 'Year' },
    { key: 'citations', label: 'Citations' },
];

export const ResultsDisplay: React.FC<ResultsDisplayProps> = ({ 
    papers, 
    selectedPaperId, 
    onSelectPaper,
    sortConfig,
    onSortChange,
    workspacePaperIds,
    onToggleWorkspace
}) => {
    if (papers.length === 0) {
        return <p className="text-gray-500 italic mt-8 text-center">No papers found.</p>;
    }

    return (
        <div className="space-y-4">
            <div className="flex justify-between items-center mb-4">
                <h2 className="text-xl font-bold text-gray-800">Results ({papers.length})</h2>

                <div className="flex items-center gap-2">
                    <span className="text-sm text-gray-500">Sort by:</span>
                    <div className="flex bg-gray-100 rounded-lg p-1">
                        {sortOptions.map((option) => (
                            <button
                                key={option.key}
                                onClick={() => onSortChange(option.key)}
                                className={`px-3 py-1 text-sm rounded-md transition-all ${
                                    sortConfig.key === option.key 
                                        ? 'bg-white text-blue-600 shadow-sm font-medium' 
                                        : 'text-gray-600 hover:text-gray-900'
                                }`}
                            >
                                {option.label}
                            </button>
                        ))}
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 gap-4">
                {papers.map((paper) => (
                    <PaperCard 
                        key={paper.id} 
                        paper={paper} 
                        isSelected={paper.id === selectedPaperId}
                        onSelect={() => onSelectPaper(paper)}
                        isInWorkspace={workspacePaperIds.has(paper.id)}
                        onToggleWorkspace={() => onToggleWorkspace(paper)}
                    />
                ))}
            </div>
        </div>
    );
};

import React from 'react';
import type { ResearchPaper } from '../types';
import { SemanticScoreIndicator } from './SemanticScoreIndicator';
import { AddIcon } from './icons/AddIcon';
import { CheckIcon } from './icons/CheckIcon';

interface PaperCardProps {
    paper: ResearchPaper;
    isSelected: boolean;
    onSelect: () => void;
    isInWorkspace: boolean;
    onToggleWorkspace: () => void;
}

export const PaperCard: React.FC<PaperCardProps> = ({ paper, isSelected, onSelect, isInWorkspace, onToggleWorkspace }) => {
    return (
        <div 
            onClick={onSelect}
            className={`p-5 rounded-xl border-2 cursor-pointer transition-all duration-300 group relative ${
                isSelected 
                    ? 'border-primary bg-primary/5 shadow-lg scale-[1.01]' 
                    : 'border-slate-200 bg-white hover:border-primary/30 hover:shadow-md'
            }`}
        >
            <div className="flex justify-between items-start gap-4">
                <div className="flex-grow pr-10">
                    <h3 className={`font-bold text-lg leading-tight transition-colors ${isSelected ? 'text-primary' : 'text-slate-900 group-hover:text-primary'}`}>
                        {paper.title}
                    </h3>
                </div>
                {paper.pdfURL && (
                    <span className="flex-shrink-0 px-2.5 py-1 text-[10px] font-black tracking-widest text-red-600 bg-red-50 border border-red-100 rounded-md uppercase">
                        PDF
                    </span>
