import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
const EMBEDDING_MODEL = "text-embedding-004";

// Persistent Cache using localStorage (simple string-key store)
const PERSISTENT_CACHE_KEY = 'are_embeddings_index_v1';
const getStoredEmbeddings = (): Record<string, number[]> => {
    try {
        const stored = localStorage.getItem(PERSISTENT_CACHE_KEY);
        return stored ? JSON.parse(stored) : {};
    } catch { return {}; }
};

const saveEmbeddingsToStore = (newEmbeddings: Record<string, number[]>) => {
    try {
        const current = getStoredEmbeddings();
        const updated = { ...current, ...newEmbeddings };
        // Basic eviction: if cache > 1MB, clear old entries
        if (JSON.stringify(updated).length > 1024 * 1024) {
            localStorage.removeItem(PERSISTENT_CACHE_KEY);
            localStorage.setItem(PERSISTENT_CACHE_KEY, JSON.stringify(newEmbeddings));
        } else {
            localStorage.setItem(PERSISTENT_CACHE_KEY, JSON.stringify(updated));
        }
    } catch {}
};

// Helper for exponential backoff with jitter
const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

async function runWithRetry<T>(fn: () => Promise<T>, retries = 5, delay = 3000): Promise<T> {
  try {
    return await fn();
  } catch (error: any) {
    const errBody = error?.error || error;
    const errorCode = errBody?.code || error?.status;
    const errorMessage = errBody?.message || error?.message || JSON.stringify(error);
    const errorStatus = errBody?.status;

    if (retries > 0 && (
        errorCode === 429 || 
        errorStatus === 'RESOURCE_EXHAUSTED' ||
        errorMessage?.includes('429') || 
        errorMessage?.includes('RESOURCE_EXHAUSTED') ||
        errorMessage?.includes('quota')
    )) {
      const jitter = Math.random() * 1000;
      console.warn(`Embedding API rate limit hit. Retrying in ${(delay + jitter).toFixed(0)}ms...`);
      await wait(delay + jitter);
      return runWithRetry(fn, retries - 1, delay * 2);
    }
    throw error;
  }
}

export const embedText = async (text: string): Promise<number[]> => {
    if (!text || text.trim() === '') return [];

    const cacheKey = text.trim().substring(0, 500); // Index by truncated text
    const store = getStoredEmbeddings();

    if (store[cacheKey]) return store[cacheKey];

    try {
        const response = await runWithRetry<any>(() => ai.models.embedContent({ 
            model: EMBEDDING_MODEL, 
            contents: text
        }));

        const embedding = response.embedding?.values || [];
        if (embedding.length > 0) {
            saveEmbeddingsToStore({ [cacheKey]: embedding });
        }
        return embedding;
    } catch (e) {
        console.error("Embedding failed with primary model:", e);
        // Fallback to text-embedding-004 is failing, try generic
        return [];
    }
};

export const batchEmbedText = async (texts: string[]): Promise<number[][]> => {
    if (!texts || texts.length === 0) return [];

    // Efficiently separate cached vs new items
    const store = getStoredEmbeddings();
    const results: number[][] = new Array(texts.length);
    const indicesToFetch: number[] = [];
    const textsToFetch: string[] = [];

    texts.forEach((text, i) => {
        const key = text.substring(0, 500);
        if (store[key]) {
            results[i] = store[key];
        } else {
            indicesToFetch.push(i);
            textsToFetch.push(text);
        }
    });

    if (textsToFetch.length > 0) {
        // Limit concurrency to 3 parallel requests for embedding batching
        const BATCH_SIZE = 3;
        for (let i = 0; i < textsToFetch.length; i += BATCH_SIZE) {
            const chunk = textsToFetch.slice(i, i + BATCH_SIZE);
            const chunkIndices = indicesToFetch.slice(i, i + BATCH_SIZE);

            // Process chunk
            const fetchedChunk = await Promise.all(chunk.map(t => embedText(t)));

            fetchedChunk.forEach((embedding, idx) => {
                const originalIndex = chunkIndices[idx];
                results[originalIndex] = embedding;
            });

            // Small delay between batches if there are more
            if (i + BATCH_SIZE < textsToFetch.length) {
                await wait(500);
            }
        }
    }

    return results;
};

import { GoogleGenAI, Type, Chat, GenerateContentResponse } from "@google/genai";
import type { ResearchPaper, SummaryLength, SummaryStyle, ModelDefinition, CitationStyle } from "../types";
import { papersToToonCollection } from "../utils/toon";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Helper for exponential backoff with jitter
const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

async function runWithRetry<T>(fn: () => Promise<T>, retries = 5, delay = 3000): Promise<T> {
  try {
    return await fn();
  } catch (error: any) {
    // Check for rate limit errors (429 or RESOURCE_EXHAUSTED)
    // The error object typically comes as { error: { code: 429, message: "...", status: "RESOURCE_EXHAUSTED" } }
    const errBody = error?.error || error;
    const errorCode = errBody?.code || error?.status;
    const errorMessage = errBody?.message || error?.message || JSON.stringify(error);
    const errorStatus = errBody?.status;

    if (retries > 0 && (
        errorCode === 429 || 
        errorStatus === 'RESOURCE_EXHAUSTED' ||
        errorMessage?.includes('429') || 
        errorMessage?.includes('RESOURCE_EXHAUSTED') ||
        errorMessage?.includes('quota')
    )) {
      const jitter = Math.random() * 1000;
      console.warn(`Gemini API rate limit hit. Retrying in ${(delay + jitter).toFixed(0)}ms...`);
      await wait(delay + jitter);
      return runWithRetry(fn, retries - 1, delay * 2);
    }
    throw error;
  }
}

// Existing summarization function updated to use TOON
export const generateSummaryForPapers = async (papers: ResearchPaper[], length: SummaryLength, style: SummaryStyle): Promise<string> => {
  if (papers.length === 0) return "";

  // Use TOON format for denser context representation
  const papersText = papersToToonCollection(papers);

  const lengthPrompt = length === 'short' ? "1-2 paragraphs" : length === 'medium' ? "3-4 paragraphs" : "a detailed report";
  const stylePrompt = style === 'bullets' ? "bullet points" : "paragraphs";

  const prompt = `Based on the following academic papers (formatted in TOON), write a synthesis summary of the research topic. 

  Format: ${stylePrompt}
  Length: ${lengthPrompt}

  Source Material (TOON):
  ${papersText}

  Focus on common themes, conflicting results, and the overall state of research represented by these papers. Cite the papers using their index numbers like [1], [2].`;

  try {
    const response = await runWithRetry<GenerateContentResponse>(() => ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
    }));
    return response.text || "Failed to generate summary.";
  } catch (error) {
    console.error("Error generating summary:", error);
    return "Error generating summary. Rate limit exceeded or API error.";
  }
};

/**
 * Generates a hypothetical answer (abstract) for the user's query.
 * This is used for HyDE (Hypothetical Document Embeddings).
 */
export const generateHypotheticalAnswer = async (query: string): Promise<string> => {
  const prompt = `Please write a hypothetical scientific abstract (about 150 words) that would perfectly answer the following research question: "${query}". 
  Do not include placeholders. Write it as if it were a real paper summary found in a database.`;

  try {
    const response = await runWithRetry<GenerateContentResponse>(() => ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
    }));
    return response.text || query; // Fallback to query if generation fails
  } catch (error) {
    console.error("Error generating hypothetical answer:", error);
    return query;
  }
};

/**
 * Generates an embedding vector for a given text string.
 */
export const getEmbedding = async (text: string): Promise<number[]> => {
  try {
    // Attempt with text-embedding-004
    const model = "text-embedding-004";
    const result = await runWithRetry<any>(() => ai.models.embedContent({
      model: model,
      contents: text,
    }));
    return result.embedding?.values || [];
  } catch (error) {
    console.error("Error fetching embedding:", error);
    return [];
  }
};

/**
 * Extracts detailed metadata for citation purposes when standard fields are missing.
 */
export const extractCitationMetadata = async (paper: ResearchPaper, model: ModelDefinition): Promise<object> => {
    const prompt = `Extract citation metadata from the following paper information into CSL-JSON format.
    Title: ${paper.title}
    Abstract: ${paper.abstract}
    Authors: ${paper.authors}
    Year: ${paper.year}
    Journal: ${paper.journal || ''}
    DOI: ${paper.doi || ''}

    Return ONLY JSON.`;

    try {
        const response = await runWithRetry<GenerateContentResponse>(() => ai.models.generateContent({
            model: model.id || "gemini-3-flash-preview",
            contents: prompt,
            config: { responseMimeType: "application/json" }
        }));

        try {
            return JSON.parse(response.text || '{}');
        } catch {
            return {};
        }
    } catch (e) {
        return {};
    }
};

/**
 * Fallback citation formatter using LLM if CSL processor fails.
 */
export const formatCitation = async (paper: ResearchPaper, style: CitationStyle, model: ModelDefinition): Promise<string> => {
    const prompt = `Generate a citation for this paper in ${style.toUpperCase()} format.
    Title: ${paper.title}
    Authors: ${paper.authors}
    Year: ${paper.year}
    Journal: ${paper.journal || ''}
    DOI: ${paper.doi || ''}

    Return only the citation string.`;

    try {
        const response = await runWithRetry<GenerateContentResponse>(() => ai.models.generateContent({
            model: model.id || "gemini-3-flash-preview",
            contents: prompt,
        }));
        return response.text?.trim() || "";
    } catch (e) {
        return `${paper.authors} (${paper.year}). ${paper.title}.`;
    }
};

/**
 * Creates a chat session context aware of a specific paper.
 */
export const createPaperChatSession = (paper: ResearchPaper, modelId: string): Chat => {
    return ai.chats.create({
        model: modelId,
        config: {
            systemInstruction: `You are a helpful research assistant discussing the paper: "${paper.title}".
            Abstract: "${paper.abstract}"
            Authors: "${paper.authors}"
            Year: "${paper.year}"

            Answer questions based on the abstract and metadata provided. If you don't know, say so.`
        }
    });
};

