  const [isFindingJournals, setIsFindingJournals] = useState(false);
  const [isFindingSimilar, setIsFindingSimilar] = useState(false);
  const [isFindingConnected, setIsFindingConnected] = useState(false);

  // --- EFFECTS ---
  useEffect(() => {
      const hasOnboarded = localStorage.getItem('onboardingCompleted');
      if (!hasOnboarded) {
          setShowOnboarding(true);
      }
  }, []);

  // --- AUTH HANDLERS ---
  const handleLogin = (loggedInUser: User) => {
      setUser(loggedInUser);
      if (loggedInUser.role === 'participant') {
          setAppMode('evaluation');
      } else {
          setAppMode('dashboard');
      }
  };

  const handleLogout = () => {
      authService.logout();
      setUser(null);
      setAppMode('search');
  };

  // --- SEARCH HANDLER ---
  const handleSearch = async (searchQuery: string, options: AdvancedSearchOptions) => {
    setIsLoading(true);
    setError(null);
    setPapers([]);
    setSelectedPaper(null);
    setSummary('');
    setAnalysis(null);
    setRefinedQueries([]);
    setSortConfig({ key: 'relevance', direction: 'desc' });
    setHasSearched(true); 

    try {
      // 1. Start Semantic Analysis (HyDE) in parallel with Search
      const queryEmbeddingPromise = apiService.precomputeQueryEmbedding(searchQuery);

      // 2. Execute Search (Fast)
      const { papers: results } = await apiService.searchPapers(searchQuery, options);

      // 3. Render Results Immediately
      setPapers(results);
      setIsLoading(false); 

      // 4. Update with Scores when ready (Background)
      try {
          const queryEmbedding = await queryEmbeddingPromise;
          const scoredResults = await apiService.computeScores(results, queryEmbedding);
          setPapers(scoredResults);
      } catch (scoreError) {
          console.error("Scoring failed silently:", scoreError);
          // Update papers to remove loading state even if scoring fails
          setPapers(prev => prev.map(p => ({ ...p, semanticScore: 0 })));
      }

      // 5. Trigger Analysis Side-Effects (Background)
      if (results.length > 0) {
          setIsSummaryLoading(true);
          apiService.generateSummary(results.slice(0, 10), summaryLength, summaryStyle) 
            .then(setSummary)
            .catch(console.error)
            .finally(() => setIsSummaryLoading(false));

          setIsAnalysisLoading(true);
          apiService.analyzePapers(results)
            .then(setAnalysis)
            .catch(console.error)
            .finally(() => setIsAnalysisLoading(false));
      }

    } catch (err) {
      setError(err instanceof Error ? err.message : 'An error occurred during search.');
      setIsLoading(false);
    }
  };

  // --- SORTING HANDLER ---
  const handleSortChange = (key: SortKey) => {
    setSortConfig(current => {
      if (current.key === key) {
        return { ...current, direction: current.direction === 'asc' ? 'desc' : 'asc' };
      }
      return { key, direction: 'desc' };
    });
  };

  const sortedPapers = React.useMemo(() => {
    return [...papers].sort((a, b) => {
      const { key, direction } = sortConfig;
      const dir = direction === 'asc' ? 1 : -1;

      if (key === 'relevance') {
        return ((a.semanticScore || 0) - (b.semanticScore || 0)) * dir;
      } else if (key === 'year') {
        return (a.year - b.year) * dir;
      } else if (key === 'citations') {
        return ((a.citations || 0) - (b.citations || 0)) * dir;
      }
      return 0;
    });
