import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
const EMBEDDING_MODEL = "text-embedding-004";

// Persistent Cache using localStorage (simple string-key store)
const PERSISTENT_CACHE_KEY = 'are_embeddings_index_v1';
const getStoredEmbeddings = (): Record<string, number[]> => {
    try {
        const stored = localStorage.getItem(PERSISTENT_CACHE_KEY);
        return stored ? JSON.parse(stored) : {};
    } catch { return {}; }
};

const saveEmbeddingsToStore = (newEmbeddings: Record<string, number[]>) => {
    try {
        const current = getStoredEmbeddings();
        const updated = { ...current, ...newEmbeddings };
        // Basic eviction: if cache > 1MB, clear old entries
        if (JSON.stringify(updated).length > 1024 * 1024) {
            localStorage.removeItem(PERSISTENT_CACHE_KEY);
            localStorage.setItem(PERSISTENT_CACHE_KEY, JSON.stringify(newEmbeddings));
        } else {
            localStorage.setItem(PERSISTENT_CACHE_KEY, JSON.stringify(updated));
        }
    } catch {}
};

// Helper for exponential backoff with jitter
const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

async function runWithRetry<T>(fn: () => Promise<T>, retries = 3, delay = 1000): Promise<T> {
  try {
    return await fn();
  } catch (error: any) {
    const errBody = error?.error || error;
    // Log but allow retry
    // console.warn(`Embedding API error (attempt ${3 - retries + 1}):`, errBody?.message || error);

    if (retries > 0) {
      await wait(delay);
      return runWithRetry(fn, retries - 1, delay * 2);
    }
    throw error;
  }
}

export const embedText = async (text: string): Promise<number[]> => {
    if (!text || text.trim() === '') return [];

    const cacheKey = text.trim().substring(0, 500); // Index by truncated text
    const store = getStoredEmbeddings();

    if (store[cacheKey]) return store[cacheKey];

    try {
        const response = await runWithRetry<any>(() => ai.models.embedContent({ 
            model: EMBEDDING_MODEL, 
            contents: text
        }));

        const embedding = response.embedding?.values || [];
        if (embedding.length > 0) {
            saveEmbeddingsToStore({ [cacheKey]: embedding });
        }
        return embedding;
    } catch (e) {
        console.error(`Embedding failed for text "${text.substring(0, 20)}..."`, e);
        // Return empty array on failure so app keeps running (score will be 0)
        return [];
    }
};

export const batchEmbedText = async (texts: string[]): Promise<number[][]> => {
    if (!texts || texts.length === 0) return [];

    // Efficiently separate cached vs new items
    const store = getStoredEmbeddings();
    const results: number[][] = new Array(texts.length);
    const indicesToFetch: number[] = [];
    const textsToFetch: string[] = [];

    texts.forEach((text, i) => {
        const key = text.substring(0, 500);
        if (store[key]) {
            results[i] = store[key];
        } else {
            indicesToFetch.push(i);
            textsToFetch.push(text);
        }
    });

    if (textsToFetch.length > 0) {
        // Limit concurrency to 3 parallel requests for embedding batching
        const BATCH_SIZE = 3;
        for (let i = 0; i < textsToFetch.length; i += BATCH_SIZE) {
            const chunk = textsToFetch.slice(i, i + BATCH_SIZE);
            const chunkIndices = indicesToFetch.slice(i, i + BATCH_SIZE);

            // Process chunk
            try {
                const fetchedChunk = await Promise.all(chunk.map(t => embedText(t)));

                fetchedChunk.forEach((embedding, idx) => {
                    const originalIndex = chunkIndices[idx];
                    results[originalIndex] = embedding;
                });
            } catch (e) {
                console.error("Batch embedding chunk failed", e);
                // Fill failed chunks with empty embeddings
                chunkIndices.forEach(idx => {
                    results[idx] = []; 
                });
            }

            // Small delay between batches if there are more
            if (i + BATCH_SIZE < textsToFetch.length) {
                await wait(200);
            }
        }
    }

    // Fill any missing results with empty arrays to be safe
    for(let i=0; i<results.length; i++) {
        if(!results[i]) results[i] = [];
    }

    return results;
};

import type { ResearchPaper, SemanticSpan } from '../types';
import { generateHypotheticalAnswer, getEmbedding } from './geminiService';
import { cosineSimilarity } from '../utils/math';
import { batchEmbedText } from '../utils/embeddings';

/**
 * Splits text into overlapping chunks (passages) to improve retrieval context.
 * Window size: 3 sentences. Stride: 2 sentences.
 */
const chunkTextIntoPassages = (text: string): string[] => {
    if (!text || text.length < 50) return [text];

    // Simple sentence splitting
    const sentences = text.match(/[^.!?]+[.!?]+(\s|$)/g) || [text];

    if (sentences.length <= 3) return [text];

    const chunks: string[] = [];
    // Sliding window
    for (let i = 0; i < sentences.length; i += 2) {
        // Take 3 sentences, join them
        const chunk = sentences.slice(i, i + 3).join('').trim();
        if (chunk.length > 20) { // Filter out tiny chunks
            chunks.push(chunk);
        }
    }
    return chunks;
};

/**
 * Generates the embedding for the hypothetical answer.
 */
export const precomputeQueryEmbedding = async (query: string): Promise<number[]> => {
    try {
        // 1. Generate Hypothetical Answer
        const hypotheticalAnswer = await generateHypotheticalAnswer(query);

        // 2. Get Embedding for it
        const queryEmbedding = await getEmbedding(hypotheticalAnswer);

        if (queryEmbedding.length === 0) {
            console.warn("Embedding generation failed for HyDE answer, retrying with raw query.");
            return await getEmbedding(query);
        }
        return queryEmbedding;
    } catch (e) {
        console.error("Error precomputing query embedding:", e);
        return [];
    }
};

/**
 * Calculates semantic scores using PASSAGE-LEVEL ranking.
 */
export const computeScores = async (papers: ResearchPaper[], queryEmbedding: number[]): Promise<ResearchPaper[]> => {
    if (papers.length === 0) return [];

    // If query embedding failed, return 0 scores immediately to stop UI loading
    if (queryEmbedding.length === 0) {
        console.warn("Query embedding is empty, skipping scoring.");
        return papers.map(p => ({ ...p, semanticScore: 0 }));
    }

    const scoredPapers: ResearchPaper[] = [];
    const BATCH_SIZE = 5; 

    try {
        for (let i = 0; i < papers.length; i += BATCH_SIZE) {
            const paperBatch = papers.slice(i, i + BATCH_SIZE);

            // 1. Prepare all chunks for this batch
            const batchChunks: { text: string; paperIndex: number }[] = [];

            paperBatch.forEach((paper, idx) => {
                const text = (paper.abstract && paper.abstract.length > 50 && !paper.abstract.includes("No abstract")) 
                  ? paper.abstract 
                  : `${paper.title}.`; 

                const passages = chunkTextIntoPassages(text);
                passages.forEach(p => batchChunks.push({ text: p, paperIndex: idx }));
            });

            // 2. Batch Embed all passages
            const passageEmbeddings = await batchEmbedText(batchChunks.map(c => c.text));

            // 3. Score passages
            const scoredPassages = batchChunks.map((chunk, idx) => {
                const embedding = passageEmbeddings[idx];
                const similarity = (embedding && embedding.length > 0) 
                    ? cosineSimilarity(queryEmbedding, embedding) 
                    : 0;
                return { ...chunk, score: similarity };
            });

            // 4. Aggregate back to papers
            const processedPapers = paperBatch.map((paper, paperIdx) => {
                const paperPassages = scoredPassages.filter(p => p.paperIndex === paperIdx);
                paperPassages.sort((a, b) => b.score - a.score);

                const bestPassage = paperPassages[0];
                const similarity = bestPassage ? bestPassage.score : 0;

                // Normalization: 0.25 -> 0%, 0.85 -> 100%
                const minSim = 0.25;
                const maxSim = 0.85;
                const score = Math.max(0, Math.min(100, Math.round(((similarity - minSim) / (maxSim - minSim)) * 100)));

                // Store top 3 highlights
                const highlights: SemanticSpan[] = paperPassages.slice(0, 3).map(p => ({
                    text: p.text,
                    score: p.score
                }));

                return {
                    ...paper,
                    semanticScore: score,
                    semanticHighlights: highlights
                };
            });

            scoredPapers.push(...processedPapers);
        }

        return scoredPapers;
    } catch (e) {
        console.error("Error computing passage-level scores:", e);
        // Critical Fallback: Return papers with 0 score instead of throwing or undefined
        return papers.map(p => ({ ...p, semanticScore: 0 }));
    }
};

/**
 * Legacy combined function for backward compatibility.
 */
export const calculatePaperScores = async (papers: ResearchPaper[], query: string): Promise<ResearchPaper[]> => {
  const queryEmbedding = await precomputeQueryEmbedding(query);
  return computeScores(papers, queryEmbedding);
};

