// Heuristic to check if a query is a natural language question likely needing expansion
const isNaturalLanguageQuestion = (query: string): boolean => {
    const questionWords = ['what', 'how', 'why', 'when', 'where', 'who', 'which', 'can', 'does', 'do', 'is', 'are'];
    const lower = query.toLowerCase();
    return (query.split(' ').length > 4) || questionWords.some(w => lower.startsWith(w));
};

export const searchPapers = async (query: string, options: AdvancedSearchOptions): Promise<{ papers: ResearchPaper[], hasMore: boolean }> => {
    let searchQueries = [query];

    // 1. Query Expansion (Agentic Search Pattern - Ported from Python)
    // If the input is a question, generating keywords improves recall significantly.
    if (isNaturalLanguageQuestion(query)) {
        console.log(`[Smart Search] Expanding question: "${query}"`);
        try {
            const expandedKeywords = await geminiService.generateSearchQueries(query);
            if (expandedKeywords.length > 0) {
                // Add the top 2 generated keyword queries to our search list
                searchQueries = [...searchQueries, ...expandedKeywords.slice(0, 2)];
                console.log(`[Smart Search] Expanded to:`, searchQueries);
            }
        } catch (e) {
            console.warn("Query expansion failed, falling back to original query.", e);
        }
    }

    // 2. Parallel Search Execution (OpenAlex + Semantic Scholar + ArXiv)
    // We execute the search against multiple providers to maximize coverage.
    const searchPromises: Promise<ResearchPaper[]>[] = [];

    // OpenAlex
    searchPromises.push(
        openalexService.searchOpenAlex(query, options)
            .then(res => res.papers)
            .catch(e => { console.warn("OpenAlex search failed:", e); return []; })
    );

    // Semantic Scholar
    searchPromises.push(
        semanticScholarService.searchSemanticScholar(query, options)
            .then(res => res.papers)
            .catch(e => { console.warn("Semantic Scholar search failed:", e); return []; })
    );

    // ArXiv (New addition)
    searchPromises.push(
        arxivService.searchArxiv(query)
            .then(res => res.papers)
            .catch(e => { console.warn("ArXiv search failed:", e); return []; })
    );

    // If we have expanded queries, run them against Semantic Scholar (it handles keyword matching very well)
    if (searchQueries.length > 1) {
        searchQueries.slice(1).forEach(q => {
             searchPromises.push(
                semanticScholarService.searchSemanticScholar(q, options)
                    .then(res => res.papers)
                    .catch(() => [])
             );
        });
    }

    const resultsArray = await Promise.all(searchPromises);
    const allPapers = resultsArray.flat();

    // 3. Deduplication and Merging Strategy
    const uniquePapers = new Map<string, ResearchPaper>();

    for (const paper of allPapers) {
        // Create a normalized key: Title (lowercase, alphanumeric only) to detect duplicates across services
        const key = paper.title.toLowerCase().replace(/[^a-z0-9]/g, '');
        if (!key) continue;

        if (uniquePapers.has(key)) {
            // Intelligent Merge:
            const existing = uniquePapers.get(key)!;

            const merged: ResearchPaper = { 
                ...existing,
                ...paper, // Override with new, but let's be selective below
                id: existing.id // Keep the first ID encountered (usually OpenAlex if it finished first)
            };

            // Selective Field Merging
            merged.citations = Math.max(existing.citations || 0, paper.citations || 0);
            merged.pdfURL = existing.pdfURL || paper.pdfURL; // Keep PDF if either has it
            merged.abstract = (existing.abstract && existing.abstract.length > paper.abstract.length) 
                ? existing.abstract 
                : paper.abstract; // Keep the longer abstract
            merged.highlights = [...(existing.highlights || []), ...(paper.highlights || [])]; 

            uniquePapers.set(key, merged);
        } else {
            uniquePapers.set(key, paper);
        }
    }

    // 4. Initial Ranking
    // Sort by Citation count descending as a proxy for relevance
    const sortedPapers = Array.from(uniquePapers.values())
        .sort((a, b) => (b.citations || 0) - (a.citations || 0));

    return { papers: sortedPapers, hasMore: false };
};

