/**
 * Generates optimal search queries for academic databases based on a user's natural language question.
 * Ported from OpenScholar's use_search_apis.py keyword extraction logic.
 */
export const generateSearchQueries = async (question: string): Promise<string[]> => {
    // Exact prompt strategy from OpenScholar
    const prompt = `Suggest semantic scholar search APIs to retrieve relevant papers to answer the following question related to the most recent NLP research. The search queries must be short, and comma separated. Here's an example. I'll show one example and the test instance you should suggest the search queries.

    ##
    Question: How have prior work incorporated personality attributes to train personalized dialogue generation models?
