import { initializeApp, FirebaseApp } from 'firebase/app';
import { getFirestore, collection, addDoc, serverTimestamp, Firestore } from 'firebase/firestore';
import { getStorage, FirebaseStorage } from 'firebase/storage';

let db: Firestore | null = null;
let storage: FirebaseStorage | null = null;
let status: 'uninitialized' | 'initializing' | 'connected' | 'error' = 'uninitialized';
let statusMessage = 'Not connected to Firestore.';

const initializeFirestore = () => {
    // Prevent re-initialization
    if (db || status === 'initializing' || status === 'connected') return;

    status = 'initializing';
    try {
        const firebaseConfigString = typeof process !== 'undefined' ? process.env.FIREBASE_CONFIG : undefined;
        if (!firebaseConfigString) {
            status = 'error';
            statusMessage = "Firebase configuration is not available. Firestore logging is disabled.";
            console.warn("[FIRESTORE] " + statusMessage);
            return; // Exit gracefully
        }

        const firebaseConfig = JSON.parse(firebaseConfigString);

        const app: FirebaseApp = initializeApp(firebaseConfig);
        db = getFirestore(app);
        storage = getStorage(app);
        status = 'connected';
        statusMessage = 'Successfully connected to Firestore & Storage.';
        console.log("[FIRESTORE] Cloud services initialized.");

    } catch (error) {
        status = 'error';
        const message = error instanceof Error ? error.message : String(error);
        statusMessage = `Firestore connection failed: ${message}`;
        console.error("[FIRESTORE] " + statusMessage);
        db = null;
        storage = null;
    }
};

const logAnalyticsEvent = async (eventName: string, data: any) => {
    if (status !== 'connected' || !db) {
        return;
    }

    try {
        await addDoc(collection(db, "analyticsEvents"), {
            eventName,
            ...data,
            firestoreTimestamp: serverTimestamp() 
        });
    } catch (error) {
        console.error("[FIRESTORE] Error logging event:", error);
        status = 'error';
    }
};

const getStatus = () => {
    return { status, message: statusMessage };
};

// Initialize the connection as soon as the module is loaded.
initializeFirestore();

export const firestoreService = {
    logAnalyticsEvent,
    getStatus,
};

export { storage };

import { storage } from './firestoreService';
import { ref, uploadString, getDownloadURL, deleteObject } from 'firebase/storage';
import type { ResearchPaper } from '../types';

/**
 * Persists a paper to Cloud Storage. 
 * This caches the enriched abstract and any metadata so it can be re-used 
 * in synthesis tasks without hitting external APIs or LLM extraction again.
 */
export const syncPaperToCloud = async (paper: ResearchPaper): Promise<boolean> => {
    if (!storage) return false;

    try {
        const paperRef = ref(storage, `papers/${paper.id}.json`);
        const data = JSON.stringify(paper);
        await uploadString(paperRef, data);
        console.log(`[CloudStorage] Synced paper: ${paper.title}`);
        return true;
    } catch (e) {
        console.warn(`[CloudStorage] Sync failed for ${paper.id}`, e);
        return false;
    }
};

/**
 * Deletes a paper from Cloud Storage when removed from workspace.
 */
export const removePaperFromCloud = async (paperId: string): Promise<void> => {
    if (!storage) return;
    try {
        const paperRef = ref(storage, `papers/${paperId}.json`);
        await deleteObject(paperRef);
    } catch (e) {}
};

/**
 * Caches a Workspace Synthesis Result to the bucket.
 * This is the "Token Saver" feature: if the same set of papers is synthesized again, 
 * we serve it from storage.
 */
export const cacheSynthesisResult = async (papers: ResearchPaper[], result: any): Promise<void> => {
    if (!storage || papers.length === 0) return;

    // Create a deterministic hash from paper IDs
    const hash = Array.from(new Set(papers.map(p => p.id))).sort().join(',');
    const cacheKey = btoa(hash).substring(0, 32);

    try {
        const cacheRef = ref(storage, `cache/synthesis/${cacheKey}.json`);
        await uploadString(cacheRef, JSON.stringify({
            timestamp: Date.now(),
            papers: papers.map(p => p.id),
            result
        }));
    } catch (e) {}
};

/**
 * Attempts to retrieve a cached synthesis for a set of papers.
 */
export const getCachedSynthesis = async (papers: ResearchPaper[]): Promise<any | null> => {
    if (!storage || papers.length === 0) return null;

    const hash = Array.from(new Set(papers.map(p => p.id))).sort().join(',');
    const cacheKey = btoa(hash).substring(0, 32);

    try {
        const cacheRef = ref(storage, `cache/synthesis/${cacheKey}.json`);
        const url = await getDownloadURL(cacheRef);
        const response = await fetch(url);
        if (!response.ok) return null;
        const data = await response.json();

        // TTL: 24 hours
        if (Date.now() - data.timestamp > 24 * 60 * 60 * 1000) return null;

        return data.result;
    } catch (e) {
        return null;
    }
};

