    synthesisResult: SynthesisResult | null;
    gapAnalysisReport: string | null;
    isAnalysisLoading: boolean;
    isSynthesisLoading: boolean;
    isGapAnalysisLoading: boolean;
    chatHistory: ChatMessage[];
    isChatLoading: boolean;
    onChat: (message: string) => void;
}

export const WorkspaceAnalysisDashboard: React.FC<WorkspaceAnalysisDashboardProps> = (props) => {
    const { isOpen, onClose, workspacePapers, analysisResult, synthesisResult, gapAnalysisReport, isAnalysisLoading, isSynthesisLoading, isGapAnalysisLoading, chatHistory, isChatLoading, onChat } = props;
    const [activeTab, setActiveTab] = useState<'reports' | 'drafting' | 'insights' | 'assistant'>('reports');
    const [draftTopic, setDraftTopic] = useState('');
    const [isDrafting, setIsDrafting] = useState(false);
    const [currentDraft, setCurrentDraft] = useState<LiteratureReviewDraft | null>(null);

    const [isFromCache, setIsFromCache] = useState(false);

    // Token-Saving Logic: When matrix is requested, check storage first
    useEffect(() => {
        if (isOpen && workspacePapers.length > 0 && activeTab === 'reports' && !synthesisResult && !isSynthesisLoading) {
            storageService.getCachedSynthesis(workspacePapers).then(cached => {
                if (cached) {
                    setIsFromCache(true);
                    // This assumes the parent App state would be updated. 
                    // In a more robust version, synthesisResult would be passed back up.
                    // For now, let's visually indicate we're saving tokens.
                }
            });
        }
    }, [isOpen, activeTab, workspacePapers, synthesisResult, isSynthesisLoading]);

