 * Service Facade
 */

// Heuristic to check if a query is a natural language question likely needing expansion
const isNaturalLanguageQuestion = (query: string): boolean => {
    const questionWords = ['what', 'how', 'why', 'when', 'where', 'who', 'which', 'can', 'does', 'do', 'is', 'are'];
    const lower = query.toLowerCase();
    return (query.split(' ').length > 4) || questionWords.some(w => lower.startsWith(w));
};

export const searchPapers = async (query: string, options: AdvancedSearchOptions): Promise<{ papers: ResearchPaper[], hasMore: boolean }> => {
    let searchQueries = [query];

    // 1. Agentic Semantic Retrieval Expansion (HyDE-informed keyword search)
    if (isNaturalLanguageQuestion(query)) {
        console.log(`[SemanticSearch] Expanding topic with HyDE context...`);
        try {
            // Generate the hypothetical answer first to inform keyword extraction
            const hydeAbstract = await geminiService.generateHypotheticalAnswer(query);
            const expandedKeywords = await geminiService.extractKeywordsFromText(hydeAbstract);

            if (expandedKeywords.length > 0) {
                // Mix raw query keywords and HyDE keywords for maximum recall
                searchQueries = [...new Set([query, ...expandedKeywords])];
                console.log(`[SemanticSearch] Targeted queries:`, searchQueries);
            }
        } catch (e) {
            console.warn("Semantic expansion failed, falling back to basic keywords.", e);
            const basicKeywords = await geminiService.generateSearchQueries(query);
            searchQueries = [query, ...basicKeywords.slice(0, 2)];
        }
    }

    // 2. Multi-Source Search Orchestration
    const searchPromises: Promise<ResearchPaper[]>[] = [];

    // Search providers
    searchQueries.forEach(q => {
        // OpenAlex (Broad)
        searchPromises.push(
            openalexService.searchOpenAlex(q, options)
                .then(res => res.papers)
                .catch(() => [])
        );

        // Semantic Scholar (High precision citations)
        searchPromises.push(
            semanticScholarService.searchSemanticScholar(q, options)
                .then(res => res.papers)
                .catch(() => [])
        );

        // ArXiv (Pre-prints)
        searchPromises.push(
            arxivService.searchArxiv(q)
                .then(res => res.papers)
                .catch(() => [])
        );
    });

    const resultsArray = await Promise.all(searchPromises);
    const allPapers = resultsArray.flat();

    // 3. Global Deduplication and Intelligent Merge
    const uniquePapers = new Map<string, ResearchPaper>();

    for (const paper of allPapers) {
        const key = paper.title.toLowerCase().replace(/[^a-z0-9]/g, '');
        if (!key || key.length < 5) continue;

        if (uniquePapers.has(key)) {
            const existing = uniquePapers.get(key)!;
            const merged: ResearchPaper = { 
                ...existing,
                ...paper,
                id: existing.id 
            };

            // Keep most data-rich fields
            merged.citations = Math.max(existing.citations || 0, paper.citations || 0);
            merged.pdfURL = existing.pdfURL || paper.pdfURL;
            merged.abstract = (existing.abstract && existing.abstract.length > paper.abstract.length) 
                ? existing.abstract 
                : paper.abstract;
            merged.highlights = [...(existing.highlights || []), ...(paper.highlights || [])]; 

            uniquePapers.set(key, merged);
        } else {
            uniquePapers.set(key, paper);
        }
    }

    // 4. Initial Authority Ranking (Final semantic scoring happens in background in App.tsx)
    const sortedPapers = Array.from(uniquePapers.values())
        .sort((a, b) => (b.citations || 0) - (a.citations || 0));

    return { papers: sortedPapers, hasMore: false };
};

