/**
 * Highlights keywords within a text string.
 * Uses words from the title as a proxy for "relevant keywords" if the specific query isn't available.
 */
const HighlightedText: React.FC<{ text: string; keywords: string[] }> = ({ text, keywords }) => {
    if (!keywords.length || !text) return <>{text}</>;

    // Filter out very short words and common stop words to get meaningful keywords
    const stopWords = new Set(['the', 'and', 'with', 'from', 'that', 'this', 'for', 'was', 'were']);
    const validKeywords = keywords
        .filter(k => k.length > 3 && !stopWords.has(k.toLowerCase()))
        .map(k => k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')); // Escape regex chars

    if (validKeywords.length === 0) return <>{text}</>;

    const pattern = new RegExp(`(${validKeywords.join('|')})`, 'gi');
    const parts = text.split(pattern);

    return (
        <>
            {parts.map((part, i) => 
                pattern.test(part) ? (
                    <mark key={i} className="bg-amber-200/60 text-amber-900 rounded-sm px-0.5 font-semibold transition-colors group-hover:bg-amber-300/80">
                        {part}
                    </mark>
                ) : part
            )}
        </>
    );
};

export const PaperCard: React.FC<PaperCardProps> = ({ paper, isSelected, onSelect, isInWorkspace, onToggleWorkspace }) => {
    // Determine if we should show semantic highlights
    const topHighlight = paper.semanticHighlights?.[0];
    const hasStrongMatch = paper.semanticScore && paper.semanticScore > 50 && topHighlight;

    // Extract potential keywords from the title for highlighting
    const titleKeywords = paper.title.split(/[\s,.:;?!\(\)\[\]]+/);

    return (
        <div 
            onClick={onSelect}
            className={`p-5 rounded-xl border-2 cursor-pointer transition-all duration-300 group relative flex flex-col ${
                isSelected 
                    ? 'border-primary bg-primary/5 shadow-lg scale-[1.01]' 
                    : 'border-slate-200 bg-white hover:border-primary/30 hover:shadow-md'
            }`}
        >
            <div className="flex justify-between items-start gap-4">
                <div className="flex-grow min-w-0">
                    <div className="flex items-center gap-2 mb-1.5">
                         {paper.semanticScore && paper.semanticScore > 85 && (
                            <span className="px-2 py-0.5 bg-indigo-600 text-white text-[9px] font-black uppercase tracking-widest rounded shadow-sm">AI Top Match</span>
                        )}
                        {paper.year === new Date().getFullYear() && (
                            <span className="px-2 py-0.5 bg-green-100 text-green-700 text-[9px] font-black uppercase tracking-widest rounded">New Release</span>
                        )}
                    </div>
                    <h3 className={`font-bold text-lg leading-tight transition-colors break-words ${isSelected ? 'text-primary' : 'text-slate-900 group-hover:text-primary'}`}>
                        {paper.title}
                    </h3>
                </div>

                <button
                    onClick={(e) => {
                        e.stopPropagation();
                        onToggleWorkspace();
                    }}
                    className={`flex-shrink-0 p-2 rounded-full transition-all ${
                        isInWorkspace 
                        ? 'bg-green-100 text-green-700 hover:bg-green-200' 
                        : 'bg-slate-100 text-slate-400 hover:bg-primary hover:text-white'
                    }`}
                    title={isInWorkspace ? "Remove from Workspace" : "Quick Save to Workspace"}
                >
                    {isInWorkspace ? <CheckIcon className="w-4 h-4" /> : <AddIcon className="w-4 h-4" />}
                </button>
            </div>

            <div className="flex flex-wrap items-center gap-x-3 gap-y-2 mt-3 text-sm text-slate-500">
                <span className="font-semibold text-slate-700 truncate max-w-[200px]">{paper.authors.split(',')[0]} et al.</span>
                <span className="opacity-30">•</span>
                <span>{paper.year}</span>
                {paper.citations !== undefined && (
                    <>
                        <span className="opacity-30">•</span>
                        <span className="bg-slate-100 px-1.5 py-0.5 rounded text-xs font-medium">{paper.citations} citations</span>
                    </>
                )}
            </div>

            {/* Semantic Relevance Snippet - Explains the reasoning for the score */}
            {hasStrongMatch && (
                <div className="mt-4 p-3 bg-indigo-50/50 border border-indigo-100/50 rounded-lg animate-fade-in group-hover:bg-indigo-50/80 transition-colors">
                    <div className="flex items-center gap-1.5 mb-1.5">
                        <SparklesIcon className="w-3.5 h-3.5 text-indigo-600" />
                        <span className="text-[10px] font-black uppercase tracking-widest text-indigo-600">Relevance Context</span>
                    </div>
                    <p className="text-xs text-indigo-900 line-clamp-2 italic leading-relaxed">
                        "...<HighlightedText text={topHighlight.text} keywords={titleKeywords} />..."
                    </p>
                </div>
            )}

            <div className="mt-4 flex items-center justify-between gap-4">
                <div className="flex-grow">
                    <SemanticScoreIndicator score={paper.semanticScore} />
                </div>

                {!isInWorkspace && (
                    <button
                        onClick={(e) => {
                            e.stopPropagation();
                            onToggleWorkspace();
                        }}
                        className="flex-shrink-0 h-8 px-3 rounded-lg bg-slate-900 text-white text-[10px] font-black uppercase tracking-tighter opacity-0 group-hover:opacity-100 transition-all hover:bg-slate-800 flex items-center gap-1.5 shadow-sm active:scale-95"
                    >
                        <AddIcon className="w-3 h-3" />
                        Quick Save
                    </button>
                )}
            </div>
        </div>
    );
};

