                                    value={zoteroKey}
                                    onChange={(e) => setZoteroKey(e.target.value)}
                                    className="w-full h-10 px-4 rounded-md border bg-background text-sm focus:ring-2 focus:ring-indigo-500 transition-all font-mono"
                                    placeholder="Enter your Zotero API Key"
                                />
                            </div>
                        </div>
                    </div>

                    <hr className="border-border" />

                    {/* EZProxy Settings */}
                    <div className="space-y-4">
                        <h3 className="text-sm font-black uppercase tracking-[0.1em] text-blue-600">EZProxy Access</h3>
                        <div>
                            <label className="block text-[10px] font-black uppercase tracking-widest text-muted-foreground mb-1.5 ml-1">Proxy URL Prefix</label>
                            <input 
                                type="text"
                                value={proxyUrl}
                                onChange={(e) => setProxyUrl(e.target.value)}
                                className="w-full h-10 px-4 rounded-md border bg-background text-sm focus:ring-2 focus:ring-blue-500 transition-all"
                                placeholder="https://ezproxy.uni.edu/login?url="
                            />
                        </div>
                    </div>
                </main>

                <footer className="p-4 bg-muted/30 border-t border-border flex justify-end gap-3">
                    <button onClick={onClose} className="px-4 h-10 text-sm font-semibold text-muted-foreground hover:text-foreground">Cancel</button>
                    <button 
                        onClick={handleSave}
                        className="px-6 h-10 rounded-md bg-indigo-600 text-white font-bold text-sm hover:bg-indigo-700 shadow-md transition-all active:scale-95"
                    >
                        Save & Apply
                    </button>
                </footer>
            </div>
        </div>
    );
};

